import React, { useState, useRef, useEffect } from 'react';
import { Message, ProductionPhase } from '../types';
import { Loader2, Send, Image as ImageIcon, Camera } from 'lucide-react';

interface ChatInterfaceProps {
  messages: Message[];
  onSendMessage: (text: string) => void;
  isLoading: boolean;
  currentPhase: ProductionPhase;
  onGenerateGrid: () => void;
}

export const ChatInterface: React.FC<ChatInterfaceProps> = ({ 
  messages, 
  onSendMessage, 
  isLoading, 
  currentPhase,
  onGenerateGrid
}) => {
  const [input, setInput] = useState('');
  const scrollRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    if (scrollRef.current) {
      scrollRef.current.scrollTop = scrollRef.current.scrollHeight;
    }
  }, [messages, isLoading]);

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (!input.trim() || isLoading) return;
    onSendMessage(input);
    setInput('');
  };

  const showGridButton = [
    ProductionPhase.VISUAL_DEV, 
    ProductionPhase.CHARACTER_DEV, 
    ProductionPhase.STORYBOARD
  ].includes(currentPhase);

  return (
    <div className="flex flex-col h-full bg-neutral-900 border-x border-neutral-800 shadow-2xl overflow-hidden">
      {/* Messages area */}
      <div 
        ref={scrollRef}
        className="flex-1 overflow-y-auto p-4 space-y-6 scrollbar-thin scrollbar-thumb-amber-900"
      >
        {messages.map((msg, i) => (
          <div 
            key={i} 
            className={`flex ${msg.role === 'user' ? 'justify-end' : 'justify-start'}`}
          >
            <div className={`
              max-w-[85%] p-4 rounded-2xl shadow-lg
              ${msg.role === 'user' 
                ? 'bg-amber-700 text-white rounded-tr-none' 
                : 'bg-neutral-800 text-neutral-200 border border-neutral-700 rounded-tl-none'}
            `}>
              <div className="whitespace-pre-wrap leading-relaxed text-sm md:text-base">
                {msg.content}
              </div>
              {msg.images && msg.images.length > 0 && (
                <div className="mt-4 grid grid-cols-1 gap-2">
                   {msg.images.map((img, idx) => (
                     <img key={idx} src={img} alt="Generated" className="rounded-lg border border-neutral-600 w-full" />
                   ))}
                </div>
              )}
            </div>
          </div>
        ))}
        {isLoading && (
          <div className="flex justify-start">
            <div className="bg-neutral-800 p-4 rounded-2xl rounded-tl-none flex items-center gap-2">
              <Loader2 className="w-5 h-5 animate-spin text-amber-500" />
              <span className="text-neutral-400 italic">正在思考構思中...</span>
            </div>
          </div>
        )}
      </div>

      {/* Input area */}
      <div className="p-4 bg-neutral-900 border-t border-neutral-800">
        <div className="flex flex-wrap gap-2 mb-3">
          {showGridButton && (
            <button
              onClick={onGenerateGrid}
              disabled={isLoading}
              className="flex items-center gap-2 px-3 py-1.5 rounded-full bg-amber-900/30 border border-amber-800/50 text-amber-400 text-xs hover:bg-amber-900/50 transition-colors disabled:opacity-50"
            >
              <ImageIcon className="w-4 h-4" />
              生成概念九宮格
            </button>
          )}
          <button
            onClick={() => onSendMessage("好的，我們進行下一步。")}
            disabled={isLoading}
            className="flex items-center gap-2 px-3 py-1.5 rounded-full bg-neutral-800 border border-neutral-700 text-neutral-300 text-xs hover:bg-neutral-700 transition-colors disabled:opacity-50"
          >
            下一步
          </button>
        </div>
        <form onSubmit={handleSubmit} className="flex gap-2">
          <input
            type="text"
            value={input}
            onChange={(e) => setInput(e.target.value)}
            placeholder="輸入您的想法、修正或是指令..."
            className="flex-1 bg-neutral-800 border border-neutral-700 text-white px-4 py-3 rounded-xl focus:outline-none focus:ring-2 focus:ring-amber-500 placeholder:text-neutral-500"
          />
          <button
            type="submit"
            disabled={isLoading || !input.trim()}
            className="bg-amber-600 hover:bg-amber-500 text-white p-3 rounded-xl transition-all disabled:opacity-50 disabled:bg-neutral-700"
          >
            <Send className="w-5 h-5" />
          </button>
        </form>
      </div>
    </div>
  );
};

import React, { useState, useEffect, useCallback, useRef } from 'react';
import { ProductionPhase, Message, ProjectState } from './types';
import { PHASE_METADATA } from './constants';
import { GeminiService } from './services/geminiService';
import { ApiKeySelector } from './components/ApiKeySelector';
import { ChatInterface } from './components/ChatInterface';
import { Film, Info, User, Layers, Video, Palette } from 'lucide-react';

const App: React.FC = () => {
  const [hasKey, setHasKey] = useState(false);
  const [isLoading, setIsLoading] = useState(false);
  const [project, setProject] = useState<ProjectState>({
    currentPhase: ProductionPhase.PRE_PRODUCTION,
    dna: { format: '', style: '', genre: '', ratio: '16:9' },
    visualIDTags: {},
    history: [
      {
        role: 'assistant',
        content: '您好，我是您的頂尖編劇與 AI 導演助手。我們將展開一場電影級的創作旅程。\n\n**第一階段：創意錨定**\n請告訴我您的靈感碎片，或直接輸入任何關鍵字。我會為您提供 3 個不同的創意切入點。',
        phase: ProductionPhase.PRE_PRODUCTION
      }
    ]
  });

  const geminiRef = useRef<GeminiService | null>(null);

  useEffect(() => {
    const checkKey = async () => {
      // @ts-ignore
      const exists = await window.aistudio.hasSelectedApiKey();
      if (exists) {
        setHasKey(true);
        geminiRef.current = new GeminiService(process.env.API_KEY || '');
      }
    };
    checkKey();
  }, []);

  const handleSendMessage = useCallback(async (text: string) => {
    if (!geminiRef.current) return;

    setIsLoading(true);
    const newHistory = [...project.history, { role: 'user', content: text } as Message];
    setProject(prev => ({ ...prev, history: newHistory }));

    try {
      const responseText = await geminiRef.current.generateChatResponse(
        newHistory.map(h => ({ role: h.role, content: h.content })),
        project.currentPhase
      );

      // Detect phase transitions in AI text (simple heuristic)
      let nextPhase = project.currentPhase;
      if (responseText.includes('第二階段')) nextPhase = ProductionPhase.VISUAL_DEV;
      if (responseText.includes('第三階段')) nextPhase = ProductionPhase.CHARACTER_DEV;
      if (responseText.includes('第四階段')) nextPhase = ProductionPhase.STORY_ARCH;
      if (responseText.includes('第五階段')) nextPhase = ProductionPhase.STORYBOARD;
      if (responseText.includes('第六階段')) nextPhase = ProductionPhase.VIDEO_PROMPTING;

      setProject(prev => ({
        ...prev,
        currentPhase: nextPhase,
        history: [...newHistory, { role: 'assistant', content: responseText, phase: nextPhase } as Message]
      }));
    } catch (error) {
      console.error(error);
      if (error instanceof Error && error.message === 'KEY_NOT_FOUND') {
        setHasKey(false);
      }
    } finally {
      setIsLoading(false);
    }
  }, [project]);

  const handleGenerateGrid = useCallback(async () => {
    if (!geminiRef.current) return;

    setIsLoading(true);
    try {
      // First, get a descriptive prompt for the 3x3 grid from the AI context
      const promptQuery = `請根據目前的創作進度，為我生成一個適用於 ${project.currentPhase} 的 3x3 矩陣繪圖提示詞 (Grid Prompt)。
      如果是場景，請包含全景、特寫等9種視角；如果是角色，請包含全身、表情、特殊造型等。
      請直接回傳一段英文提示詞，格式為：A detailed 3x3 grid/matrix of [Description], cinematic, photorealistic, 8k.`;

      const gridPrompt = await geminiRef.current.generateChatResponse(
        [...project.history.map(h => ({ role: h.role, content: h.content })), { role: 'user', content: promptQuery }],
        project.currentPhase
      );

      const imageUrl = await geminiRef.current.generateImage(gridPrompt);

      if (imageUrl) {
        setProject(prev => ({
          ...prev,
          history: [...prev.history, { 
            role: 'assistant', 
            content: `🎬 導演筆記：[${PHASE_METADATA[project.currentPhase].title} 九宮格已生成]`,
            images: [imageUrl],
            isImageGrid: true
          } as Message]
        }));
      }
    } catch (error) {
      console.error(error);
    } finally {
      setIsLoading(false);
    }
  }, [project]);

  if (!hasKey) {
    return <ApiKeySelector onSelected={() => {
      setHasKey(true);
      geminiRef.current = new GeminiService(process.env.API_KEY || '');
    }} />;
  }

  return (
    <div className="flex h-screen bg-[#0a0a0a] text-neutral-200 overflow-hidden">
      {/* Sidebar - Phase Navigation */}
      <aside className="w-20 md:w-64 border-r border-neutral-800 flex flex-col bg-neutral-900/50">
        <div className="p-6 border-b border-neutral-800 flex items-center gap-3">
          <Film className="w-8 h-8 text-amber-500" />
          <h1 className="hidden md:block text-xl font-serif font-bold text-white tracking-wider">DIRECTOR</h1>
        </div>

        <nav className="flex-1 p-4 space-y-4">
          {Object.entries(PHASE_METADATA).map(([key, meta]) => {
            const isActive = project.currentPhase === key;
            return (
              <div 
                key={key}
                className={`flex items-center gap-3 p-3 rounded-xl transition-all ${
                  isActive ? 'bg-amber-600/20 border border-amber-600/50 text-amber-500' : 'text-neutral-500 grayscale opacity-50'
                }`}
              >
                <span className="text-xl">{meta.icon}</span>
                <span className="hidden md:block text-sm font-medium">{meta.title}</span>
              </div>
            );
          })}
        </nav>

        <div className="p-4 border-t border-neutral-800">
          <div className="hidden md:block text-[10px] uppercase tracking-widest text-neutral-500 mb-2">Project Stats</div>
          <div className="flex flex-col gap-2">
            <div className="flex items-center justify-between text-xs">
              <span className="text-neutral-400">進度</span>
              <span className="text-amber-500 font-bold">{Math.round((Object.keys(PHASE_METADATA).indexOf(project.currentPhase) + 1) / 6 * 100)}%</span>
            </div>
            <div className="w-full bg-neutral-800 h-1 rounded-full overflow-hidden">
              <div 
                className="bg-amber-600 h-full transition-all duration-500" 
                style={{ width: `${(Object.keys(PHASE_METADATA).indexOf(project.currentPhase) + 1) / 6 * 100}%` }}
              />
            </div>
          </div>
        </div>
      </aside>

      {/* Main Content Area */}
      <main className="flex-1 flex flex-col min-w-0">
        <header className="h-16 border-b border-neutral-800 flex items-center justify-between px-6 bg-neutral-900/30">
          <div className="flex items-center gap-2">
            <span className="text-xs text-neutral-500 uppercase font-bold tracking-widest">Active Phase:</span>
            <span className="text-sm text-amber-500 font-bold">{PHASE_METADATA[project.currentPhase].title}</span>
          </div>
          <div className="flex items-center gap-4">
             <button className="text-neutral-400 hover:text-white transition-colors">
                <Info className="w-5 h-5" />
             </button>
             <div className="h-8 w-8 rounded-full bg-neutral-800 border border-neutral-700 flex items-center justify-center text-xs font-bold text-amber-500">
               AD
             </div>
          </div>
        </header>

        <section className="flex-1 overflow-hidden">
          <ChatInterface 
            messages={project.history}
            onSendMessage={handleSendMessage}
            isLoading={isLoading}
            currentPhase={project.currentPhase}
            onGenerateGrid={handleGenerateGrid}
          />
        </section>
      </main>

      {/* Right Sidebar - Design Details / Tags */}
      <aside className="hidden lg:flex w-80 border-l border-neutral-800 flex-col bg-neutral-900/50 p-6 space-y-8 overflow-y-auto">
        <div>
          <h3 className="text-xs font-bold text-neutral-500 uppercase tracking-widest mb-4 flex items-center gap-2">
            <Palette className="w-4 h-4" /> 視覺標籤 (Visual IDs)
          </h3>
          {Object.keys(project.visualIDTags).length > 0 ? (
            <div className="space-y-3">
              {Object.entries(project.visualIDTags).map(([name, tag]) => (
                <div key={name} className="p-3 bg-neutral-800 rounded-lg border border-neutral-700">
                  <div className="text-amber-500 font-bold text-xs mb-1 uppercase">{name}</div>
                  <div className="text-xs text-neutral-400 italic">"{tag}"</div>
                </div>
              ))}
            </div>
          ) : (
            <div className="p-8 border border-dashed border-neutral-800 rounded-xl text-center">
              <User className="w-8 h-8 text-neutral-700 mx-auto mb-2" />
              <p className="text-xs text-neutral-600 italic">尚未定義角色標籤。進入第三階段後，這裡會顯示一致性標籤。</p>
            </div>
          )}
        </div>

        <div>
          <h3 className="text-xs font-bold text-neutral-500 uppercase tracking-widest mb-4 flex items-center gap-2">
            <Layers className="w-4 h-4" /> 場景摘要
          </h3>
          <div className="p-4 bg-neutral-800/50 rounded-xl border border-neutral-700 text-xs text-neutral-400 space-y-2">
             <div className="flex justify-between border-b border-neutral-700 pb-2">
               <span>影片比例</span>
               <span className="text-neutral-200">16:9</span>
             </div>
             <div className="flex justify-between border-b border-neutral-700 pb-2">
               <span>技術規格</span>
               <span className="text-neutral-200">4K / Highly Realistic</span>
             </div>
             <div className="flex justify-between">
               <span>推薦模型</span>
               <span className="text-amber-600">Runway Gen-3 / Luma</span>
             </div>
          </div>
        </div>

        <div className="mt-auto">
          <div className="p-4 bg-amber-900/20 rounded-xl border border-amber-800/30 flex items-start gap-3">
            <Video className="w-5 h-5 text-amber-500 shrink-0" />
            <div>
              <p className="text-[10px] text-amber-400 font-bold uppercase mb-1">Director's Tip</p>
              <p className="text-[11px] text-amber-200/80 leading-relaxed italic">
                「在 Phase 6 中生成的提示詞包含了動態縮放指令 (Motion Scale)，這對 AI 影片的穩定性至關重要。」
              </p>
            </div>
          </div>
        </div>
      </aside>
    </div>
  );
};

export default App;

import { GoogleGenAI, GenerateContentResponse, Type } from "@google/genai";
import { SYSTEM_INSTRUCTION } from "../constants";

export class GeminiService {
  private ai: GoogleGenAI;

  constructor(apiKey: string) {
    this.ai = new GoogleGenAI({ apiKey });
  }

  async generateChatResponse(messages: { role: string; content: string }[], phase: string) {
    const chat = this.ai.models.generateContent({
      model: 'gemini-3-pro-preview',
      contents: messages.map(m => ({ 
        role: m.role === 'assistant' ? 'model' : 'user', 
        parts: [{ text: m.content }] 
      })),
      config: {
        systemInstruction: `${SYSTEM_INSTRUCTION}\n\n目前階段：${phase}`,
        temperature: 0.8,
      }
    });

    const response = await chat;
    return response.text || "無法生成回應";
  }

  async generateImage(prompt: string): Promise<string | null> {
    try {
      const response = await this.ai.models.generateContent({
        model: 'gemini-3-pro-image-preview',
        contents: {
          parts: [{ text: prompt }]
        },
        config: {
          imageConfig: {
            aspectRatio: "16:9",
            imageSize: "1K"
          }
        }
      });

      for (const part of response.candidates?.[0]?.content?.parts || []) {
        if (part.inlineData) {
          return `data:image/png;base64,${part.inlineData.data}`;
        }
      }
      return null;
    } catch (error) {
      console.error("Image generation failed:", error);
      if (error instanceof Error && error.message.includes("Requested entity was not found")) {
         throw new Error("KEY_NOT_FOUND");
      }
      return null;
    }
  }

  async generateVideo(prompt: string, onProgress: (status: string) => void): Promise<string | null> {
    try {
      onProgress("正在初始化拍攝設備...");
      let operation = await this.ai.models.generateVideos({
        model: 'veo-3.1-fast-generate-preview',
        prompt: prompt,
        config: {
          numberOfVideos: 1,
          resolution: '720p',
          aspectRatio: '16:9'
        }
      });

      onProgress("影片渲染中 (約需 1 分鐘)...");
      while (!operation.done) {
        await new Promise(resolve => setTimeout(resolve, 10000));
        operation = await this.ai.operations.getVideosOperation({ operation: operation });
      }

      const downloadLink = operation.response?.generatedVideos?.[0]?.video?.uri;
      if (!downloadLink) return null;

      // Append API key for direct access
      return `${downloadLink}&key=${process.env.API_KEY}`;
    } catch (error) {
      console.error("Video generation failed:", error);
      return null;
    }
  }
}

export enum ProductionPhase {
  PRE_PRODUCTION = 'PRE_PRODUCTION',
  VISUAL_DEV = 'VISUAL_DEV',
  CHARACTER_DEV = 'CHARACTER_DEV',
  STORY_ARCH = 'STORY_ARCH',
  STORYBOARD = 'STORYBOARD',
  VIDEO_PROMPTING = 'VIDEO_PROMPTING'
}

export interface Message {
  role: 'user' | 'assistant';
  content: string;
  images?: string[]; 
  videoUrl?: string;
  phase?: ProductionPhase;
  isImageGrid?: boolean;
  isVideoGeneration?: boolean;
}

export interface GeneratedVideo {
  id: string;
  url: string;
  prompt: string;
  shotLabel: string;
}

export interface ProjectState {
  currentPhase: ProductionPhase;
  dna: {
    format: string;
    style: string;
    genre: string;
    ratio: string;
  };
  visualIDTags: Record<string, string>;
  history: Message[];
  generatedVideos: GeneratedVideo[];
}

import React, { useState, useRef, useEffect } from 'react';
import { Message, ProductionPhase } from '../types';
import { Loader2, Send, Image as ImageIcon, Video, Film, PlayCircle } from 'lucide-react';

interface ChatInterfaceProps {
  messages: Message[];
  onSendMessage: (text: string) => void;
  onGenerateVideo: (prompt: string, shotLabel: string) => void;
  isLoading: boolean;
  currentPhase: ProductionPhase;
  onGenerateGrid: () => void;
}

export const ChatInterface: React.FC<ChatInterfaceProps> = ({ 
  messages, 
  onSendMessage, 
  onGenerateVideo,
  isLoading, 
  currentPhase,
  onGenerateGrid
}) => {
  const [input, setInput] = useState('');
  const scrollRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    if (scrollRef.current) {
      scrollRef.current.scrollTop = scrollRef.current.scrollHeight;
    }
  }, [messages, isLoading]);

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (!input.trim() || isLoading) return;
    onSendMessage(input);
    setInput('');
  };

  const parseVideoPrompts = (content: string) => {
    // Regex to find AI Video Prompt blocks (from the specified format)
    const promptRegex = /AI 影片生成提示詞.*:.*"(.*)"/g;
    const matches = [...content.matchAll(promptRegex)];
    return matches.map(m => m[1]);
  };

  const showGridButton = [
    ProductionPhase.VISUAL_DEV, 
    ProductionPhase.CHARACTER_DEV, 
    ProductionPhase.STORYBOARD
  ].includes(currentPhase);

  return (
