    </div>
  );
};

import React, { useState, useEffect, useCallback, useRef } from 'react';
import { ProductionPhase, Message, ProjectState, GeneratedVideo } from './types';
import { PHASE_METADATA } from './constants';
import { GeminiService } from './services/geminiService';
import { ApiKeySelector } from './components/ApiKeySelector';
import { ChatInterface } from './components/ChatInterface';
import { Film, Info, User, Layers, Video, Palette, Clapperboard, Play, CheckCircle2 } from 'lucide-react';

const App: React.FC = () => {
  const [hasKey, setHasKey] = useState(false);
  const [isLoading, setIsLoading] = useState(false);
  const [productionStatus, setProductionStatus] = useState('');
  const [project, setProject] = useState<ProjectState>({
    currentPhase: ProductionPhase.PRE_PRODUCTION,
    dna: { format: '', style: '', genre: '', ratio: '16:9' },
    visualIDTags: {},
    history: [
      {
        role: 'assistant',
        content: '您好，我是您的頂尖編劇與 AI 導演助手。我們將展開一場電影級的創作旅程。\n\n**第一階段：創意錨定**\n請告訴我您的靈感碎片，或直接輸入任何關鍵字。我會為您提供 3 個不同的創意切入點。',
        phase: ProductionPhase.PRE_PRODUCTION
      }
    ],
    generatedVideos: []
  });

  const geminiRef = useRef<GeminiService | null>(null);

  useEffect(() => {
    const checkKey = async () => {
      // @ts-ignore
      const exists = await window.aistudio.hasSelectedApiKey();
      if (exists) {
        setHasKey(true);
        geminiRef.current = new GeminiService(process.env.API_KEY || '');
      }
    };
    checkKey();
  }, []);

  const handleSendMessage = useCallback(async (text: string) => {
    if (!geminiRef.current) return;

    setIsLoading(true);
    const newHistory = [...project.history, { role: 'user', content: text } as Message];
    setProject(prev => ({ ...prev, history: newHistory }));

    try {
      const responseText = await geminiRef.current.generateChatResponse(
        newHistory.map(h => ({ role: h.role, content: h.content })),
        project.currentPhase
      );

      let nextPhase = project.currentPhase;
      if (responseText.includes('第二階段')) nextPhase = ProductionPhase.VISUAL_DEV;
      if (responseText.includes('第三階段')) nextPhase = ProductionPhase.CHARACTER_DEV;
      if (responseText.includes('第四階段')) nextPhase = ProductionPhase.STORY_ARCH;
      if (responseText.includes('第五階段')) nextPhase = ProductionPhase.STORYBOARD;
      if (responseText.includes('第六階段')) nextPhase = ProductionPhase.VIDEO_PROMPTING;

      setProject(prev => ({
        ...prev,
        currentPhase: nextPhase,
        history: [...newHistory, { role: 'assistant', content: responseText, phase: nextPhase } as Message]
      }));
    } catch (error) {
      console.error(error);
      if (error instanceof Error && error.message === 'KEY_NOT_FOUND') {
        setHasKey(false);
      }
    } finally {
      setIsLoading(false);
    }
  }, [project]);

  const handleGenerateVideo = useCallback(async (prompt: string, shotLabel: string) => {
    if (!geminiRef.current) return;
    setIsLoading(true);
    setProductionStatus('正在初始化拍攝...');

    try {
      const videoUrl = await geminiRef.current.generateVideo(prompt, (status) => setProductionStatus(status));
      if (videoUrl) {
        const newVideo: GeneratedVideo = {
          id: Date.now().toString(),
          url: videoUrl,
          prompt: prompt,
          shotLabel: shotLabel
        };

        setProject(prev => ({
          ...prev,
          generatedVideos: [...prev.generatedVideos, newVideo],
          history: [...prev.history, { 
            role: 'assistant', 
            content: `🎬 影片生成完成：${shotLabel}`,
            videoUrl: videoUrl,
            isVideoGeneration: true
          } as Message]
        }));
      }
    } catch (error) {
      console.error(error);
    } finally {
      setIsLoading(false);
      setProductionStatus('');
    }
  }, [project]);

  const handleGenerateGrid = useCallback(async () => {
    if (!geminiRef.current) return;
    setIsLoading(true);
    try {
      const promptQuery = `請根據目前的創作進度，為我生成一個適用於 ${project.currentPhase} 的 3x3 矩陣繪圖提示詞 (Grid Prompt)。直接回傳一段英文提示詞，格式為：A detailed 3x3 grid/matrix of [Description], cinematic, photorealistic, 8k.`;
      const gridPrompt = await geminiRef.current.generateChatResponse(
        [...project.history.map(h => ({ role: h.role, content: h.content })), { role: 'user', content: promptQuery }],
        project.currentPhase
      );
      const imageUrl = await geminiRef.current.generateImage(gridPrompt);
      if (imageUrl) {
        setProject(prev => ({
          ...prev,
          history: [...prev.history, { role: 'assistant', content: `🎬 導演筆記：[${PHASE_METADATA[project.currentPhase].title} 九宮格已生成]`, images: [imageUrl], isImageGrid: true } as Message]
        }));
      }
    } catch (error) {
      console.error(error);
    } finally {
      setIsLoading(false);
    }
  }, [project]);

  if (!hasKey) {
    return <ApiKeySelector onSelected={() => { setHasKey(true); geminiRef.current = new GeminiService(process.env.API_KEY || ''); }} />;
  }

  return (
    <div className="flex h-screen bg-[#0a0a0a] text-neutral-200 overflow-hidden">
      {/* Sidebar - Phase Navigation */}
      <aside className="w-20 md:w-64 border-r border-neutral-800 flex flex-col bg-neutral-900/50">
        <div className="p-6 border-b border-neutral-800 flex items-center gap-3">
          <Film className="w-8 h-8 text-amber-500" />
          <h1 className="hidden md:block text-xl font-serif font-bold text-white tracking-wider">DIRECTOR</h1>
        </div>

        <nav className="flex-1 p-4 space-y-4">
          {Object.entries(PHASE_METADATA).map(([key, meta]) => {
            const isActive = project.currentPhase === key;
            const isCompleted = Object.keys(PHASE_METADATA).indexOf(project.currentPhase) > Object.keys(PHASE_METADATA).indexOf(key);
            return (
              <div 
                key={key}
                className={`flex items-center gap-3 p-3 rounded-xl transition-all ${
                  isActive ? 'bg-amber-600/20 border border-amber-600/50 text-amber-500' : 
                  isCompleted ? 'text-amber-700/80 grayscale-0' : 'text-neutral-500 grayscale opacity-50'
                }`}
              >
                <span className="text-xl">{isCompleted ? <CheckCircle2 className="w-5 h-5 text-amber-600" /> : meta.icon}</span>
                <span className="hidden md:block text-sm font-medium">{meta.title}</span>
              </div>
            );
          })}
        </nav>

        <div className="p-4 border-t border-neutral-800">
          <div className="hidden md:block text-[10px] uppercase tracking-widest text-neutral-500 mb-2">拍攝進度</div>
          <div className="flex flex-col gap-2">
            <div className="flex items-center justify-between text-xs">
              <span className="text-neutral-400">當前階段</span>
              <span className="text-amber-500 font-bold">{Math.round((Object.keys(PHASE_METADATA).indexOf(project.currentPhase) + 1) / 6 * 100)}%</span>
            </div>
            <div className="w-full bg-neutral-800 h-1 rounded-full overflow-hidden">
              <div className="bg-amber-600 h-full transition-all duration-500" style={{ width: `${(Object.keys(PHASE_METADATA).indexOf(project.currentPhase) + 1) / 6 * 100}%` }} />
            </div>
          </div>
        </div>
      </aside>

      {/* Main Content Area */}
      <main className="flex-1 flex flex-col min-w-0">
        <header className="h-16 border-b border-neutral-800 flex items-center justify-between px-6 bg-neutral-900/30">
          <div className="flex items-center gap-4">
            <div className="flex items-center gap-2">
              <span className="text-xs text-neutral-500 uppercase font-bold tracking-widest">Active Phase:</span>
              <span className="text-sm text-amber-500 font-bold">{PHASE_METADATA[project.currentPhase].title}</span>
            </div>
            {productionStatus && (
              <div className="flex items-center gap-2 bg-amber-900/30 px-3 py-1 rounded-full border border-amber-600/30 animate-pulse">
                <Loader2 className="w-3 h-3 text-amber-500 animate-spin" />
                <span className="text-[10px] text-amber-200 font-bold uppercase">{productionStatus}</span>
              </div>
            )}
          </div>
          <div className="flex items-center gap-4">
             <button className="text-neutral-400 hover:text-white transition-colors">
                <Info className="w-5 h-5" />
             </button>
             <div className="h-8 w-8 rounded-full bg-neutral-800 border border-neutral-700 flex items-center justify-center text-xs font-bold text-amber-500">
               AD
             </div>
          </div>
        </header>

        <section className="flex-1 overflow-hidden">
          <ChatInterface 
            messages={project.history}
            onSendMessage={handleSendMessage}
            onGenerateVideo={handleGenerateVideo}
            isLoading={isLoading}
            currentPhase={project.currentPhase}
            onGenerateGrid={handleGenerateGrid}
          />
        </section>
      </main>

      {/* Right Sidebar - Design Details & Video Assets */}
      <aside className="hidden lg:flex w-80 border-l border-neutral-800 flex-col bg-neutral-900/50 p-6 space-y-8 overflow-y-auto">
        <div>
          <h3 className="text-xs font-bold text-neutral-500 uppercase tracking-widest mb-4 flex items-center gap-2">
            <Clapperboard className="w-4 h-4" /> 數位剪輯室 (Production Studio)
          </h3>
          {project.generatedVideos.length > 0 ? (
            <div className="space-y-4">
              <div className="grid grid-cols-2 gap-2">
                {project.generatedVideos.map(video => (
                  <div key={video.id} className="group relative rounded-lg overflow-hidden border border-neutral-700 bg-black aspect-video">
                    <video src={video.url} className="w-full h-full object-cover opacity-60 group-hover:opacity-100 transition-opacity" muted loop onMouseOver={e => e.currentTarget.play()} onMouseOut={e => {e.currentTarget.pause(); e.currentTarget.currentTime = 0;}} />
                    <div className="absolute bottom-1 left-1 bg-black/60 px-1.5 py-0.5 rounded text-[8px] text-amber-500 font-bold">{video.shotLabel}</div>
                  </div>
                ))}
              </div>
              <button className="w-full flex items-center justify-center gap-2 py-2 bg-amber-600 hover:bg-amber-500 text-white rounded-lg font-bold text-xs transition-colors shadow-lg shadow-amber-900/20">
                <Play className="w-3 h-3 fill-current" /> 預覽完整長片拼接
