import { GoogleGenAI } from "@google/genai";
import { SYSTEM_INSTRUCTION } from "../constants";

export class GeminiService {
  // We keep the constructor for compatibility, but create fresh instances in methods
  // to comply with the requirement of using the latest key from the environment.
  constructor(apiKey: string) {}

  /**
   * Generates a text response for the chat.
   * Uses a fresh instance of GoogleGenAI to ensure the latest API key is used.
   */
  async generateChatResponse(messages: { role: string; content: string }[], phase: string) {
    // Create a new instance right before the call to ensure the latest API Key is used.
    const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
    const response = await ai.models.generateContent({
      model: 'gemini-3-pro-preview',
      contents: messages.map(m => ({ 
        role: m.role === 'assistant' ? 'model' : 'user', 
        parts: [{ text: m.content }] 
      })),
      config: {
        systemInstruction: `${SYSTEM_INSTRUCTION}\n\n目前階段：${phase}`,
        temperature: 0.8,
      }
    });

    return response.text || "無法生成回應";
  }

  /**
   * Generates an image using Gemini 3 Pro Image Preview (Nano Banana Pro).
   * Follows the rule to use a new instance for models requiring user-selected keys.
   */
  async generateImage(prompt: string): Promise<string | null> {
    const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
    try {
      const response = await ai.models.generateContent({
        model: 'gemini-3-pro-image-preview',
        contents: {
          parts: [{ text: prompt }]
        },
        config: {
          imageConfig: {
            aspectRatio: "16:9",
            imageSize: "1K"
          }
        }
      });

      for (const part of response.candidates?.[0]?.content?.parts || []) {
        if (part.inlineData) {
          return `data:image/png;base64,${part.inlineData.data}`;
        }
      }
      return null;
    } catch (error) {
      console.error("Image generation failed:", error);
      // Handle the case where the key might be invalid or from an unpaid project
      if (error instanceof Error && error.message.includes("Requested entity was not found")) {
         throw new Error("KEY_NOT_FOUND");
      }
      return null;
    }
  }

  /**
   * Generates a video using Veo 3.1 Fast.
   * Ensures gapless polling and uses a fresh client instance.
   */
  async generateVideo(prompt: string, onProgress: (status: string) => void): Promise<string | null> {
    const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
    try {
      onProgress("正在初始化拍攝設備...");
      let operation = await ai.models.generateVideos({
        model: 'veo-3.1-fast-generate-preview',
        prompt: prompt,
        config: {
          numberOfVideos: 1,
          resolution: '720p',
          aspectRatio: '16:9'
        }
      });

      onProgress("影片渲染中 (約需 1 分鐘)...");
      while (!operation.done) {
        // Wait for 10 seconds before polling again
        await new Promise(resolve => setTimeout(resolve, 10000));
        operation = await ai.operations.getVideosOperation({ operation: operation });
      }

      const downloadLink = operation.response?.generatedVideos?.[0]?.video?.uri;
      if (!downloadLink) return null;

      // The response.body contains the MP4 bytes. You must append an API key when fetching from the download link.
      return `${downloadLink}&key=${process.env.API_KEY}`;
    } catch (error) {
      console.error("Video generation failed:", error);
      return null;
    }
  }
}

