          </div>
        </div>
      </aside>

      {/* 主要工作區 */}
      <main className="flex-1 flex flex-col bg-[radial-gradient(circle_at_top_right,_rgba(217,119,6,0.05),_transparent)] relative">
        <header className="h-16 px-8 border-b border-white/5 flex items-center justify-between z-10">
          <div className="flex items-center gap-2">
            <span className="text-[10px] text-neutral-500 uppercase tracking-[0.2em]">當前任務</span>
            <ChevronRight className="w-3 h-3 text-neutral-600" />
            <span className="text-sm font-bold text-amber-500 tracking-wide">{PHASE_METADATA[project.currentPhase].title}</span>
