          <div className="flex gap-4">
             <button className="text-neutral-500 hover:text-white transition-colors" title="創作歷史"><History className="w-5 h-5" /></button>
             <button className="text-neutral-500 hover:text-white transition-colors" title="關於項目"><Info className="w-5 h-5" /></button>
          </div>
        </header>

        <section className="flex-1 flex flex-col items-center justify-center p-8 max-w-5xl mx-auto w-full">
          <div className="w-full max-w-2xl mb-12">
            <h2 className="text-3xl font-serif text-center mb-8 leading-relaxed">
              {project.history.length === 0 ? "輸入您的初步構想碎片，開始剪輯旅程" : "針對當前階段輸入您的修正或偏好"}
            </h2>
            <form onSubmit={handleSubmitIdea} className="relative group">
              <input 
                type="text" 
                value={input}
                onChange={(e) => setInput(e.target.value)}
