          {project.suggestions.length > 0 && (
            <div className="w-full animate-in fade-in slide-in-from-bottom-4 duration-700">
              <div className="grid grid-cols-1 md:grid-cols-3 gap-6 mb-12">
                {project.suggestions.map((s, i) => (
                  <button
                    key={i}
