                  </label>
                  <select 
                    value={tempDNA.style}
                    onChange={(e) => setTempDNA({...tempDNA, style: e.target.value})}
                    className="w-full bg-white/5 border border-white/10 rounded-xl p-3 text-sm focus:ring-1 focus:ring-amber-500 outline-none"
                  >
                    <option className="bg-[#1a1a1a]">寫實電影感 (Realistic Cinematic)</option>
                    <option className="bg-[#1a1a1a]">高對比黑色電影 (Film Noir)</option>
                    <option className="bg-[#1a1a1a]">賽博龐克 (Cyberpunk 2077 Style)</option>
                    <option className="bg-[#1a1a1a]">吉卜力手繪風 (Ghibli Inspired)</option>
                    <option className="bg-[#1a1a1a]">夢幻唯美 (Dreamy & Ethereal)</option>
                    <option className="bg-[#1a1a1a]">極簡現代 (Minimalist Modern)</option>
                  </select>
                </div>

                {/* 故事發展 */}
                <div className="space-y-2">
                  <label className="flex items-center gap-2 text-xs font-bold text-neutral-500 uppercase tracking-wider">
                    <BookOpen className="w-3 h-3" /> 敘事核心
                  </label>
                  <textarea 
                    value={tempDNA.story}
                    onChange={(e) => setTempDNA({...tempDNA, story: e.target.value})}
                    rows={4}
                    className="w-full bg-white/5 border border-white/10 rounded-xl p-4 text-sm focus:ring-1 focus:ring-amber-500 outline-none resize-none leading-relaxed"
                  />
                </div>
              </div>

              <footer className="p-6 border-t border-white/10 bg-white/5 flex gap-4">
                <button 
                  onClick={() => setShowConfig(false)}
                  className="flex-1 py-3 px-6 rounded-xl border border-white/10 text-sm font-bold hover:bg-white/5 transition-colors"
                >
                  返回修改
                </button>
                <button 
                  onClick={confirmConfig}
                  className="flex-1 py-3 px-6 rounded-xl bg-amber-600 text-sm font-bold hover:bg-amber-500 transition-all flex items-center justify-center gap-2 shadow-lg shadow-amber-900/20"
                >
                  <CheckCircle2 className="w-4 h-4" /> 確認並進入下一階段
                </button>
              </footer>
            </div>
          </div>
        )}
      </main>

      {/* 右側資訊面板 */}
      <aside className="w-80 border-l border-white/5 bg-black/40 p-6 flex flex-col gap-8 overflow-y-auto">
        <div>
          <h3 className="text-[10px] font-bold text-neutral-500 uppercase tracking-widest mb-4 flex items-center gap-2">
            <Layout className="w-4 h-4" /> 項目 DNA
          </h3>
          <div className="space-y-3">
             <div className="p-4 bg-white/5 rounded-xl border border-white/10">
                <div className="text-[10px] text-neutral-500 mb-1 flex items-center gap-1"><Layers className="w-3 h-3" /> 當前階段產出</div>
                <div className="text-xs text-amber-200">
                  {project.dna.format ? `${project.dna.format} | ${project.dna.ratio}` : "待選定方案"}
                </div>
             </div>
             <div className="p-4 bg-white/5 rounded-xl border border-white/10">
                <div className="text-[10px] text-neutral-500 mb-1 flex items-center gap-1"><Palette className="w-3 h-3" /> 選定風格</div>
                <div className="text-xs">
                  {project.dna.style || "未定義"}
                </div>
             </div>
             {project.dna.story && (
               <div className="p-4 bg-white/5 rounded-xl border border-white/10">
                  <div className="text-[10px] text-neutral-500 mb-1 flex items-center gap-1"><BookOpen className="w-3 h-3" /> 核心概念</div>
                  <div className="text-[10px] text-neutral-400 line-clamp-4 leading-relaxed">
                    {project.dna.story}
                  </div>
               </div>
             )}
          </div>
        </div>

        <div>
          <h3 className="text-[10px] font-bold text-neutral-500 uppercase tracking-widest mb-4 flex items-center gap-2">
            <Palette className="w-4 h-4" /> 蒙太奇剪輯庫
          </h3>
          {project.generatedVideos.length > 0 ? (
            <div className="grid grid-cols-2 gap-2">
              {project.generatedVideos.map(v => (
                <div key={v.id} className="aspect-video bg-neutral-900 rounded-lg overflow-hidden border border-white/10">
                   <video src={v.url} className="w-full h-full object-cover" muted loop />
                </div>
              ))}
            </div>
          ) : (
            <div className="p-8 border border-dashed border-white/5 rounded-2xl text-center">
              <Video className="w-6 h-6 text-neutral-800 mx-auto mb-2" />
              <p className="text-[10px] text-neutral-700 italic">尚未拍攝任何片段</p>
            </div>
          )}
        </div>
      </aside>
    </div>
  );
};

export default App;

