import React, { useState, useEffect, useCallback, useRef } from 'react';
import { ProductionPhase, Suggestion, ProjectState, GeneratedVideo, Message, ProjectDNA } from './types';
import { PHASE_METADATA } from './constants';
import { GeminiService } from './services/geminiService';
import { ApiKeySelector } from './components/ApiKeySelector';
import { 
  Film, Sparkles, Send, Loader2, ArrowRight, 
  Info, Clapperboard, Video, Layout, Palette, 
  ChevronRight, History, Save, Download, Upload,
  X, CheckCircle2, Monitor, BookOpen, Layers, Terminal
} from 'lucide-react';

const App: React.FC = () => {
  const [hasKey, setHasKey] = useState(false);
  const [isLoading, setIsLoading] = useState(false);
  const [input, setInput] = useState('');
  const [hoveredSuggestion, setHoveredSuggestion] = useState<Suggestion | null>(null);
  const [selectedSuggestion, setSelectedSuggestion] = useState<Suggestion | null>(null);
  const [showConfig, setShowConfig] = useState(false);
  const [showHistory, setShowHistory] = useState(false);

  const [tempDNA, setTempDNA] = useState<ProjectDNA>({
    format: '電影',
    style: '寫實電影感 (Realistic Cinematic)',
    story: '',
    ratio: '16:9'
  });

  const [project, setProject] = useState<ProjectState>({
    currentPhase: ProductionPhase.PRE_PRODUCTION,
    dna: { format: '', style: '', story: '', ratio: '16:9' },
    suggestions: [],
    history: [],
    generatedVideos: []
  });

  const fileInputRef = useRef<HTMLInputElement>(null);
  const geminiRef = useRef<GeminiService | null>(null);

  useEffect(() => {
    const checkKey = async () => {
      // @ts-ignore
      const exists = await window.aistudio.hasSelectedApiKey();
      if (exists) {
        setHasKey(true);
        geminiRef.current = new GeminiService(process.env.API_KEY || '');
      }
    };
    checkKey();
  }, []);

  const handleSubmitIdea = async (e?: React.FormEvent) => {
    if (e) e.preventDefault();
    if (!input.trim() || isLoading || !geminiRef.current) return;

    setIsLoading(true);
    try {
      const context = `項目DNA: ${JSON.stringify(project.dna)}\n歷史紀錄: ${project.history.map(h => h.content).slice(-5).join('\n')}`;
      const results = await geminiRef.current.generateSuggestions(input, project.currentPhase, context);
      setProject(prev => ({ ...prev, suggestions: results }));
      setHoveredSuggestion(null);
    } catch (error) {
      console.error(error);
    } finally {
      setIsLoading(false);
    }
  };

  const handleSuggestionClick = (s: Suggestion) => {
    setSelectedSuggestion(s);
    // 第一階段才自動推算 DNA，後續階段繼承舊 DNA
    if (project.currentPhase === ProductionPhase.PRE_PRODUCTION) {
      setTempDNA({
        format: s.tags.includes('廣告') ? '商業廣告' : s.tags.includes('動畫') ? '動畫短片' : '電影短片',
        style: '寫實電影感 (Realistic Cinematic)',
        story: s.description,
        ratio: '16:9'
      });
    } else {
      setTempDNA({ ...project.dna, story: s.description });
    }
    setShowConfig(true);
  };

  const confirmConfig = () => {
    if (!selectedSuggestion) return;

    const selectedContent = `【確認 [${PHASE_METADATA[project.currentPhase].title}] 方案：${selectedSuggestion.title}】\n${selectedSuggestion.description}`;

    const nextPhases = Object.values(ProductionPhase);
    const currentIndex = nextPhases.indexOf(project.currentPhase);
    const nextPhase = currentIndex < nextPhases.length - 1 ? nextPhases[currentIndex + 1] : project.currentPhase;

    setProject(prev => ({
      ...prev,
      currentPhase: nextPhase,
      dna: { ...tempDNA },
      suggestions: [],
      history: [...prev.history, { 
        role: 'assistant', 
        content: selectedContent, 
        phase: project.currentPhase 
      }]
    }));

    setShowConfig(false);
    setSelectedSuggestion(null);
    setInput('');
  };

  const saveProject = () => {
    const projectToSave = { ...project, generatedVideos: [], history: project.history.map(h => ({ ...h, videoUrl: undefined })) };
    const blob = new Blob([JSON.stringify(projectToSave, null, 2)], { type: 'application/json' });
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url;
    a.download = `電影蒙太奇_專案_${new Date().toLocaleDateString().replace(/\//g, '-')}.json`;
    a.click();
    URL.revokeObjectURL(url);
  };

  const loadProject = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;
    const reader = new FileReader();
    reader.onload = (event) => {
      try {
        const data = JSON.parse(event.target?.result as string) as ProjectState;
        if (data.currentPhase && data.history) setProject(data);
      } catch (err) { alert('讀取檔案出錯'); }
    };
    reader.readAsText(file);
    if (fileInputRef.current) fileInputRef.current.value = '';
  };

  if (!hasKey) return <ApiKeySelector onSelected={() => { setHasKey(true); geminiRef.current = new GeminiService(process.env.API_KEY || ''); }} />;

  return (
    <div className="flex h-screen bg-[#050505] text-white overflow-hidden">
      {/* 側邊導航 */}
      <aside className="w-64 border-r border-white/5 flex flex-col bg-black/40 p-6">
        <div className="flex items-center gap-3 mb-12">
          <div className="bg-amber-600 p-2 rounded-lg shadow-[0_0_15px_rgba(217,119,6,0.3)]">
            <Film className="w-6 h-6 text-white" />
          </div>
          <h1 className="text-lg font-serif font-bold tracking-widest">電影蒙太奇 AI</h1>
        </div>

        <nav className="flex-1 space-y-2">
          {Object.entries(PHASE_METADATA).map(([key, meta], idx) => {
            const isActive = project.currentPhase === key;
            const isCompleted = Object.keys(PHASE_METADATA).indexOf(project.currentPhase) > idx;
            return (
              <div key={key} className={`relative flex items-center gap-4 p-3 rounded-lg transition-all ${isActive ? 'bg-white/10 text-amber-500 shadow-inner' : 'text-neutral-600 opacity-60'}`}>
                {isActive && <div className="absolute left-0 w-1 h-6 bg-amber-600 rounded-full" />}
                <span className="text-xl">{meta.icon}</span>
                <div className="flex flex-col">
                  <span className="text-[10px] uppercase tracking-tighter opacity-50">Step 0{idx+1}</span>
                  <span className="text-sm font-medium">{meta.title}</span>
                </div>
              </div>
            );
          })}
        </nav>

        <div className="mt-8 space-y-2 border-t border-white/5 pt-6">
          <button onClick={saveProject} className="w-full flex items-center gap-3 px-3 py-2.5 rounded-lg bg-neutral-900/50 hover:bg-neutral-800 border border-white/5 text-xs text-neutral-300 transition-all group">
            <Download className="w-4 h-4 text-amber-600 group-hover:scale-110 transition-transform" />
            <span>匯出專案</span>
          </button>
          <button onClick={() => fileInputRef.current?.click()} className="w-full flex items-center gap-3 px-3 py-2.5 rounded-lg bg-neutral-900/50 hover:bg-neutral-800 border border-white/5 text-xs text-neutral-300 transition-all group">
            <Upload className="w-4 h-4 text-amber-600 group-hover:scale-110 transition-transform" />
            <span>載入專案</span>
          </button>
          <input type="file" ref={fileInputRef} onChange={loadProject} className="hidden" accept=".json" />
        </div>
      </aside>

      {/* 主要工作區 */}
      <main className="flex-1 flex flex-col bg-[radial-gradient(circle_at_top_right,_rgba(217,119,6,0.05),_transparent)] relative">
        <header className="h-16 px-8 border-b border-white/5 flex items-center justify-between z-10">
          <div className="flex items-center gap-2">
            <Terminal className="w-4 h-4 text-amber-600" />
            <span className="text-[10px] text-neutral-500 uppercase tracking-[0.2em]">DIRECTOR'S TERMINAL</span>
            <ChevronRight className="w-3 h-3 text-neutral-600" />
            <span className="text-sm font-bold text-amber-500 tracking-wide">{PHASE_METADATA[project.currentPhase].title}</span>
          </div>
