  Info, Clapperboard, Video, Layout, Palette, 
  ChevronRight, History, Save, Download, Upload,
  X, CheckCircle2, Monitor, BookOpen, Layers, Terminal, MapPin, Users, Target
} from 'lucide-react';

const App: React.FC = () => {
  const [hasKey, setHasKey] = useState(false);
  const [isLoading, setIsLoading] = useState(false);
  const [input, setInput] = useState('');
  const [hoveredSuggestion, setHoveredSuggestion] = useState<Suggestion | null>(null);
  const [selectedSuggestion, setSelectedSuggestion] = useState<Suggestion | null>(null);
  const [showConfig, setShowConfig] = useState(false);
  const [showHistory, setShowHistory] = useState(false);

  const [tempDNA, setTempDNA] = useState<ProjectDNA>({
    format: '電影',
    style: '寫實電影感 (Realistic Cinematic)',
    story: '',
    ratio: '16:9',
    environment: '',
    socialBackground: '',
    coreSetting: ''
  });

  const [project, setProject] = useState<ProjectState>({
    currentPhase: ProductionPhase.PRE_PRODUCTION,
    dna: { format: '', style: '', story: '', ratio: '16:9', environment: '', socialBackground: '', coreSetting: '' },
    suggestions: [],
    history: [],
    generatedVideos: []
  });

  const fileInputRef = useRef<HTMLInputElement>(null);
  const geminiRef = useRef<GeminiService | null>(null);

  useEffect(() => {
    const checkKey = async () => {
      // @ts-ignore
      const exists = await window.aistudio.hasSelectedApiKey();
      if (exists) {
        setHasKey(true);
        geminiRef.current = new GeminiService(process.env.API_KEY || '');
      }
    };
    checkKey();
  }, []);

  const handleSubmitIdea = async (e?: React.FormEvent) => {
    if (e) e.preventDefault();
    if (!input.trim() || isLoading || !geminiRef.current) return;

    setIsLoading(true);
    try {
      const context = `項目DNA: ${JSON.stringify(project.dna)}\n歷史紀錄: ${project.history.map(h => h.content).slice(-5).join('\n')}`;
      const results = await geminiRef.current.generateSuggestions(input, project.currentPhase, context);
      setProject(prev => ({ ...prev, suggestions: results }));
      setHoveredSuggestion(null);
    } catch (error) {
      console.error(error);
    } finally {
      setIsLoading(false);
    }
  };

  const handleSuggestionClick = (s: Suggestion) => {
    setSelectedSuggestion(s);
    // AI 自動推論填充
    const inferredFormat = s.tags.includes('廣告') ? '商業廣告' : s.tags.includes('動畫') ? '動畫短片' : '電影短片';

    setTempDNA({
      ...project.dna,
      format: project.currentPhase === ProductionPhase.PRE_PRODUCTION ? inferredFormat : project.dna.format,
      style: project.currentPhase === ProductionPhase.PRE_PRODUCTION ? '寫實電影感 (Realistic Cinematic)' : project.dna.style,
      story: s.description,
      environment: s.environment || project.dna.environment,
      socialBackground: s.socialBackground || project.dna.socialBackground,
      coreSetting: s.coreSetting || project.dna.coreSetting,
    });
    setShowConfig(true);
  };

  const confirmConfig = () => {
    if (!selectedSuggestion) return;

    const selectedContent = `【確認 [${PHASE_METADATA[project.currentPhase].title}] 方案：${selectedSuggestion.title}】\n${selectedSuggestion.description}\n\n[AI 預設環境]：${tempDNA.environment}\n[AI 預設背景]：${tempDNA.socialBackground}\n[AI 預設設定]：${tempDNA.coreSetting}`;

    const nextPhases = Object.values(ProductionPhase);
    const currentIndex = nextPhases.indexOf(project.currentPhase);
    const nextPhase = currentIndex < nextPhases.length - 1 ? nextPhases[currentIndex + 1] : project.currentPhase;

    setProject(prev => ({
      ...prev,
      currentPhase: nextPhase,
      dna: { ...tempDNA },
      suggestions: [],
      history: [...prev.history, { 
        role: 'assistant', 
        content: selectedContent, 
        phase: project.currentPhase 
      }]
    }));

    setShowConfig(false);
    setSelectedSuggestion(null);
    setInput('');
  };

  const saveProject = () => {
    const projectToSave = { ...project, generatedVideos: [], history: project.history.map(h => ({ ...h, videoUrl: undefined })) };
    const blob = new Blob([JSON.stringify(projectToSave, null, 2)], { type: 'application/json' });
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url;
    a.download = `電影蒙太奇_專案_${new Date().toLocaleDateString().replace(/\//g, '-')}.json`;
    a.click();
    URL.revokeObjectURL(url);
  };

  const loadProject = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;
    const reader = new FileReader();
    reader.onload = (event) => {
      try {
        const data = JSON.parse(event.target?.result as string) as ProjectState;
        if (data.currentPhase && data.history) setProject(data);
      } catch (err) { alert('讀取檔案出錯'); }
    };
    reader.readAsText(file);
    if (fileInputRef.current) fileInputRef.current.value = '';
  };

  if (!hasKey) return <ApiKeySelector onSelected={() => { setHasKey(true); geminiRef.current = new GeminiService(process.env.API_KEY || ''); }} />;

  return (
    <div className="flex h-screen bg-[#050505] text-white overflow-hidden">
      {/* 側邊導航 */}
      <aside className="w-64 border-r border-white/5 flex flex-col bg-black/40 p-6">
        <div className="flex items-center gap-3 mb-12">
          <div className="bg-amber-600 p-2 rounded-lg shadow-[0_0_15px_rgba(217,119,6,0.3)]">
            <Film className="w-6 h-6 text-white" />
          </div>
          <h1 className="text-lg font-serif font-bold tracking-widest text-white/90">電影蒙太奇 AI</h1>
        </div>

        <nav className="flex-1 space-y-2">
          {Object.entries(PHASE_METADATA).map(([key, meta], idx) => {
            const isActive = project.currentPhase === key;
            return (
              <div key={key} className={`relative flex items-center gap-4 p-3 rounded-lg transition-all ${isActive ? 'bg-white/10 text-amber-500 shadow-inner' : 'text-neutral-600 opacity-60'}`}>
                {isActive && <div className="absolute left-0 w-1 h-6 bg-amber-600 rounded-full" />}
                <span className="text-xl">{meta.icon}</span>
                <div className="flex flex-col">
                  <span className="text-[10px] uppercase tracking-tighter opacity-50">Step 0{idx+1}</span>
                  <span className="text-sm font-medium">{meta.title}</span>
                </div>
              </div>
            );
          })}
        </nav>

        <div className="mt-8 space-y-2 border-t border-white/5 pt-6">
          <button onClick={saveProject} className="w-full flex items-center gap-3 px-3 py-2.5 rounded-lg bg-neutral-900/50 hover:bg-neutral-800 border border-white/5 text-xs text-neutral-300 transition-all group">
            <Download className="w-4 h-4 text-amber-600 group-hover:scale-110 transition-transform" />
            <span>匯出專案</span>
          </button>
          <button onClick={() => fileInputRef.current?.click()} className="w-full flex items-center gap-3 px-3 py-2.5 rounded-lg bg-neutral-900/50 hover:bg-neutral-800 border border-white/5 text-xs text-neutral-300 transition-all group">
            <Upload className="w-4 h-4 text-amber-600 group-hover:scale-110 transition-transform" />
            <span>載入專案</span>
          </button>
          <input type="file" ref={fileInputRef} onChange={loadProject} className="hidden" accept=".json" />
        </div>
      </aside>

      {/* 主要工作區 */}
      <main className="flex-1 flex flex-col bg-[radial-gradient(circle_at_top_right,_rgba(217,119,6,0.05),_transparent)] relative">
        <header className="h-16 px-8 border-b border-white/5 flex items-center justify-between z-10">
          <div className="flex items-center gap-2">
            <Terminal className="w-4 h-4 text-amber-600" />
            <span className="text-[10px] text-neutral-500 uppercase tracking-[0.2em]">DIRECTOR'S TERMINAL</span>
            <ChevronRight className="w-3 h-3 text-neutral-600" />
            <span className="text-sm font-bold text-amber-500 tracking-wide">{PHASE_METADATA[project.currentPhase].title}</span>
          </div>
          <div className="flex gap-4">
             <button onClick={() => setShowHistory(true)} className="text-neutral-500 hover:text-white transition-colors" title="查看DNA紀錄"><History className="w-5 h-5" /></button>
          </div>
        </header>

        <section className="flex-1 flex flex-col items-center justify-center p-8 max-w-5xl mx-auto w-full">
          <div className="w-full max-w-2xl mb-12 animate-in fade-in zoom-in-95 duration-500">
            <div className="flex flex-col items-center text-center space-y-4 mb-8">
              <div className="px-3 py-1 bg-amber-900/20 rounded-full border border-amber-600/30 text-[10px] text-amber-500 font-bold uppercase tracking-widest">
                拍攝靈感/導演指令
              </div>
              <h2 className="text-2xl md:text-3xl font-serif leading-relaxed text-neutral-100">
                {PHASE_METADATA[project.currentPhase].guide}
              </h2>
            </div>

            <form onSubmit={handleSubmitIdea} className="relative group">
              <input 
                type="text" 
                value={input}
                onChange={(e) => setInput(e.target.value)}
                placeholder="例如：五色鳥觀察日記..."
                className="w-full bg-white/5 border border-white/10 p-5 pr-16 rounded-2xl focus:outline-none focus:ring-2 focus:ring-amber-600/50 transition-all text-lg placeholder:text-neutral-700 shadow-2xl"
              />
              <button 
                type="submit"
                disabled={isLoading || !input.trim()}
                className="absolute right-3 top-3 bg-amber-600 hover:bg-amber-500 p-3 rounded-xl transition-all disabled:opacity-30 disabled:grayscale"
              >
                {isLoading ? <Loader2 className="w-6 h-6 animate-spin text-white" /> : <Sparkles className="w-6 h-6 text-white" />}
              </button>
            </form>
          </div>

          {project.suggestions.length > 0 && (
            <div className="w-full animate-in fade-in slide-in-from-bottom-8 duration-1000">
              <div className="grid grid-cols-1 md:grid-cols-3 gap-6 mb-12">
                {project.suggestions.map((s, i) => (
                  <button
                    key={i}
                    onMouseEnter={() => setHoveredSuggestion(s)}
                    onClick={() => handleSuggestionClick(s)}
                    className="btn-montage glass p-8 rounded-2xl text-center group border-white/5 hover:border-amber-600/50"
                  >
                    <div className="text-[10px] text-amber-500 font-bold mb-4 tracking-widest opacity-0 group-hover:opacity-100 transition-opacity uppercase">提案 Proposal {i+1}</div>
                    <h3 className="text-lg font-serif font-bold mb-4 line-clamp-2 h-14 flex items-center justify-center">{s.title}</h3>
                    <div className="flex flex-wrap justify-center gap-1.5 mt-2">
                      {s.tags.map(t => <span key={t} className="text-[9px] bg-amber-900/30 px-2 py-0.5 rounded text-amber-200/60 border border-amber-600/10">#{t}</span>)}
                    </div>
                  </button>
                ))}
              </div>

              <div className="h-44 relative">
                {hoveredSuggestion ? (
                  <div className="glass p-8 rounded-2xl border-amber-600/30 animate-in fade-in slide-in-from-bottom-4 duration-300 shadow-2xl bg-black/40">
                    <div className="flex items-start gap-6">
                      <div className="bg-amber-600/20 p-3 rounded-xl border border-amber-600/30 shrink-0">
                        <Clapperboard className="w-6 h-6 text-amber-500" />
                      </div>
                      <div className="space-y-2 text-left">
                        <h4 className="text-amber-500 text-[10px] font-bold uppercase tracking-[0.3em]">導演階段摘要</h4>
                        <p className="text-base text-neutral-200 leading-relaxed italic font-serif">「{hoveredSuggestion.description}」</p>
                        {hoveredSuggestion.environment && (
                          <div className="flex items-center gap-2 mt-2 text-xs text-neutral-500">
                            <MapPin className="w-3 h-3 text-amber-600" /> {hoveredSuggestion.environment}
                          </div>
                        )}
                      </div>
                    </div>
                  </div>
                ) : (
                  <div className="flex flex-col items-center justify-center h-full text-neutral-600 space-y-3 opacity-40">
                    <ArrowRight className="w-5 h-5 animate-bounce" />
                    <p className="text-sm italic font-light tracking-wide">選擇一個方案，或懸停查看 AI 推理細節</p>
                  </div>
                )}
              </div>
            </div>
          )}
        </section>

        {/* 方案確認對話框：AI 設計展示 */}
        {showConfig && (
          <div className="fixed inset-0 bg-black/95 backdrop-blur-md flex items-center justify-center z-50 p-6">
            <div className="glass w-full max-w-4xl rounded-3xl overflow-hidden shadow-[0_0_50px_rgba(217,119,6,0.15)] border border-amber-600/20 flex flex-col max-h-[90vh]">
              <header className="p-8 border-b border-white/5 flex justify-between items-center bg-white/5">
                <div>
                  <h3 className="text-2xl font-serif font-bold text-white tracking-wide">AI 導演企劃書 (項目 DNA)</h3>
                  <p className="text-[10px] text-amber-500/60 mt-2 uppercase tracking-[0.3em]">AI 已根據靈感自動生成世界觀設定，請檢閱確認</p>
                </div>
                <button onClick={() => setShowConfig(false)} className="text-neutral-500 hover:text-white transition-colors">
                  <X className="w-6 h-6" />
                </button>
              </header>

              <div className="p-10 grid grid-cols-1 md:grid-cols-2 gap-10 overflow-y-auto">
                <div className="space-y-8">
                  {/* 核心設定 */}
                  <div className="space-y-3">
                    <label className="flex items-center gap-2 text-[10px] font-bold text-neutral-500 uppercase tracking-widest">
                      <Target className="w-3 h-3 text-amber-600" /> 核心設定 (Core Setting)
                    </label>
                    <textarea 
                      value={tempDNA.coreSetting}
                      onChange={(e) => setTempDNA({...tempDNA, coreSetting: e.target.value})}
                      rows={3}
                      className="w-full bg-white/5 border border-white/10 rounded-xl p-4 text-sm text-amber-200/80 outline-none focus:ring-1 focus:ring-amber-500"
                    />
                  </div>

                  {/* 社會背景 */}
                  <div className="space-y-3">
                    <label className="flex items-center gap-2 text-[10px] font-bold text-neutral-500 uppercase tracking-widest">
                      <Users className="w-3 h-3 text-amber-600" /> 社會背景 (Background)
                    </label>
                    <textarea 
                      value={tempDNA.socialBackground}
                      onChange={(e) => setTempDNA({...tempDNA, socialBackground: e.target.value})}
                      rows={3}
                      className="w-full bg-white/5 border border-white/10 rounded-xl p-4 text-sm text-neutral-300 outline-none focus:ring-1 focus:ring-amber-500"
                    />
                  </div>

                  {/* 地理環境 */}
                  <div className="space-y-3">
                    <label className="flex items-center gap-2 text-[10px] font-bold text-neutral-500 uppercase tracking-widest">
                      <MapPin className="w-3 h-3 text-amber-600" /> 地理環境 (Environment)
                    </label>
                    <textarea 
                      value={tempDNA.environment}
                      onChange={(e) => setTempDNA({...tempDNA, environment: e.target.value})}
                      rows={3}
                      className="w-full bg-white/5 border border-white/10 rounded-xl p-4 text-sm text-neutral-300 outline-none focus:ring-1 focus:ring-amber-500"
                    />
                  </div>
                </div>

                <div className="space-y-8">
                   <div className="grid grid-cols-2 gap-4">
                      <div className="space-y-2">
                         <label className="text-[10px] font-bold text-neutral-500 uppercase tracking-widest">影片類型</label>
                         <select value={tempDNA.format} onChange={(e) => setTempDNA({...tempDNA, format: e.target.value})} className="w-full bg-white/5 border border-white/10 rounded-lg p-3 text-xs outline-none appearance-none">
                            <option className="bg-black">電影短片</option><option className="bg-black">商業廣告</option><option className="bg-black">動畫短片</option><option className="bg-black">紀錄片</option>
                         </select>
                      </div>
                      <div className="space-y-2">
                         <label className="text-[10px] font-bold text-neutral-500 uppercase tracking-widest">視覺風格</label>
                         <select value={tempDNA.style} onChange={(e) => setTempDNA({...tempDNA, style: e.target.value})} className="w-full bg-white/5 border border-white/10 rounded-lg p-3 text-xs outline-none appearance-none">
                            <option className="bg-black">寫實電影感</option><option className="bg-black">黑色電影</option><option className="bg-black">賽博龐克</option><option className="bg-black">吉卜力風</option>
                         </select>
                      </div>
                   </div>

                   <div className="space-y-3">
                    <label className="flex items-center gap-2 text-[10px] font-bold text-neutral-500 uppercase tracking-widest">
                      <BookOpen className="w-3 h-3 text-amber-600" /> 敘事摘要
                    </label>
                    <textarea 
                      value={tempDNA.story}
                      onChange={(e) => setTempDNA({...tempDNA, story: e.target.value})}
                      rows={8}
                      className="w-full bg-white/5 border border-white/10 rounded-2xl p-6 text-sm focus:ring-1 focus:ring-amber-500 outline-none resize-none leading-relaxed font-serif text-neutral-300"
                    />
                  </div>
                </div>
              </div>

              <footer className="p-8 border-t border-white/5 bg-white/5 flex gap-6">
                <button onClick={() => setShowConfig(false)} className="px-10 py-4 rounded-2xl border border-white/10 text-sm font-bold hover:bg-white/5 transition-all text-neutral-400">
                  取消
                </button>
                <button onClick={confirmConfig} className="flex-1 py-4 px-6 rounded-2xl bg-amber-600 text-sm font-bold hover:bg-amber-500 transition-all flex items-center justify-center gap-3 shadow-xl shadow-amber-900/40">
                  <CheckCircle2 className="w-5 h-5" /> 確認 AI 設計並推進下一階段
                </button>
              </footer>
            </div>
          </div>
        )}

        {/* 歷史紀錄對話框 */}
        {showHistory && (
          <div className="fixed inset-0 bg-black/90 backdrop-blur-xl z-[60] p-12 overflow-y-auto">
             <div className="max-w-4xl mx-auto space-y-12 pb-24">
                <div className="flex justify-between items-center border-b border-white/10 pb-8">
                   <h2 className="text-4xl font-serif">項目製作歷程</h2>
                   <button onClick={() => setShowHistory(false)} className="p-3 bg-white/5 rounded-full hover:bg-amber-600 transition-all"><X className="w-6 h-6" /></button>
                </div>

                <div className="grid grid-cols-1 md:grid-cols-2 gap-8">
                   <div className="glass p-8 rounded-3xl space-y-6">
                      <h3 className="text-amber-500 text-xs font-bold uppercase tracking-widest">當前項目 DNA</h3>
                      <div className="space-y-4">
                         <div className="flex justify-between border-b border-white/5 pb-2"><span className="text-neutral-500 text-sm">影片形式</span><span className="text-sm">{project.dna.format || "未定"}</span></div>
                         <div className="flex justify-between border-b border-white/5 pb-2"><span className="text-neutral-500 text-sm">視覺風格</span><span className="text-sm">{project.dna.style || "未定"}</span></div>
                         <div className="flex justify-between border-b border-white/5 pb-2"><span className="text-neutral-500 text-sm">環境設定</span><span className="text-sm text-right max-w-[200px] truncate">{project.dna.environment || "未定"}</span></div>
                      </div>
                   </div>
                   <div className="glass p-8 rounded-3xl">
                      <h3 className="text-amber-500 text-xs font-bold uppercase tracking-widest mb-4">核心設定摘要</h3>
                      <p className="text-sm text-neutral-400 leading-relaxed italic">「{project.dna.coreSetting || "尚未生成世界觀"}」</p>
                   </div>
                </div>

                <div className="space-y-6">
                   <h3 className="text-amber-500 text-xs font-bold uppercase tracking-widest">階段產出紀錄</h3>
                   {project.history.map((h, i) => (
                      <div key={i} className="glass p-6 rounded-2xl border-white/5 hover:border-amber-600/30 transition-all">
                         <div className="text-[10px] text-neutral-500 mb-2 font-mono">{h.phase ? PHASE_METADATA[h.phase].title : "系統訊息"}</div>
                         <div className="text-sm text-neutral-200 whitespace-pre-wrap">{h.content}</div>
                      </div>
                   ))}
                </div>
             </div>
          </div>
        )}
      </main>

      {/* 右側資訊面板 */}
      <aside className="w-80 border-l border-white/5 bg-black/40 p-6 flex flex-col gap-8 overflow-y-auto">
        <div className="space-y-6">
          <h3 className="text-[10px] font-bold text-neutral-500 uppercase tracking-widest flex items-center gap-2">
            <Layout className="w-4 h-4 text-amber-600" /> 項目活躍 DNA
          </h3>
          <div className="space-y-4">
             <div className="p-5 bg-white/5 rounded-2xl border border-white/10 group hover:border-amber-600/30 transition-all">
                <div className="text-[10px] text-neutral-500 mb-2 flex items-center gap-2"><Layers className="w-3 h-3" /> 進度節點</div>
                <div className="text-xs text-amber-500 font-bold uppercase tracking-wider">
                  {PHASE_METADATA[project.currentPhase].title}
                </div>
             </div>
             {project.dna.environment && (
               <div className="p-5 bg-white/5 rounded-2xl border border-white/10">
                  <div className="text-[10px] text-neutral-500 mb-2 flex items-center gap-2"><MapPin className="w-3 h-3" /> 地理空間</div>
                  <div className="text-xs text-neutral-300 leading-relaxed truncate">{project.dna.environment}</div>
               </div>
             )}
             {project.dna.coreSetting && (
               <div className="p-5 bg-white/5 rounded-2xl border border-white/10">
                  <div className="text-[10px] text-neutral-500 mb-2 flex items-center gap-2"><Target className="w-3 h-3" /> 核心使命</div>
                  <div className="text-[10px] text-neutral-400 line-clamp-3 leading-relaxed italic">{project.dna.coreSetting}</div>
               </div>
             )}
          </div>
        </div>

        <div className="space-y-6 flex-1">
          <h3 className="text-[10px] font-bold text-neutral-500 uppercase tracking-widest flex items-center gap-2">
            <Video className="w-4 h-4 text-amber-600" /> 蒙太奇剪輯庫
          </h3>
          {project.generatedVideos.length > 0 ? (
            <div className="grid grid-cols-1 gap-4">
              {project.generatedVideos.map(v => (
                <div key={v.id} className="aspect-video bg-black rounded-2xl overflow-hidden border border-white/10 group relative">
                   <video src={v.url} className="w-full h-full object-cover" muted loop onMouseEnter={(e) => e.currentTarget.play()} onMouseLeave={(e) => e.currentTarget.pause()} />
                </div>
              ))}
            </div>
          ) : (
            <div className="py-12 px-6 border border-dashed border-white/10 rounded-3xl text-center space-y-4 opacity-50">
              <div className="bg-white/5 w-10 h-10 rounded-full flex items-center justify-center mx-auto">
                <Video className="w-5 h-5 text-neutral-700" />
              </div>
              <p className="text-[10px] text-neutral-600 italic tracking-wide">尚未產出影片</p>
            </div>
          )}
        </div>
      </aside>
    </div>
  );
};

export default App;

export enum ProductionPhase {
  PRE_PRODUCTION = 'PRE_PRODUCTION',
  VISUAL_DEV = 'VISUAL_DEV',
  CHARACTER_DEV = 'CHARACTER_DEV',
  STORY_ARCH = 'STORY_ARCH',
  STORYBOARD = 'STORYBOARD',
  VIDEO_PROMPTING = 'VIDEO_PROMPTING'
}

export interface Suggestion {
  title: string;
  description: string;
  tags: string[];
  // AI Inferred fields
  environment?: string;
  socialBackground?: string;
  coreSetting?: string;
}

export interface Message {
  role: 'user' | 'assistant';
  content: string;
  images?: string[]; 
  videoUrl?: string;
  phase?: ProductionPhase;
  isImageGrid?: boolean;
}

export interface GeneratedVideo {
  id: string;
  url: string;
  prompt: string;
  shotLabel: string;
}

export interface ProjectDNA {
  format: string;
  style: string;
  story: string;
  ratio: string;
  // New inferred metadata
  environment: string;
  socialBackground: string;
  coreSetting: string;
}

export interface ProjectState {
  currentPhase: ProductionPhase;
  initialInput?: string; // The "Original Spark"
  dna: ProjectDNA;
  suggestions: Suggestion[];
  history: Message[];
  generatedVideos: GeneratedVideo[];
}

import React, { useState, useEffect, useCallback, useRef } from 'react';
import { ProductionPhase, Suggestion, ProjectState, GeneratedVideo, Message, ProjectDNA } from './types';
import { PHASE_METADATA } from './constants';
import { GeminiService } from './services/geminiService';
import { ApiKeySelector } from './components/ApiKeySelector';
import { 
  Film, Sparkles, Send, Loader2, ArrowRight, 
  Info, Clapperboard, Video, Layout, Palette, 
  ChevronRight, History, Save, Download, Upload,
  X, CheckCircle2, Monitor, BookOpen, Layers, Terminal, MapPin, Users, Target, Lightbulb
} from 'lucide-react';

const App: React.FC = () => {
  const [hasKey, setHasKey] = useState(false);
  const [isLoading, setIsLoading] = useState(false);
  const [input, setInput] = useState('');
  const [hoveredSuggestion, setHoveredSuggestion] = useState<Suggestion | null>(null);
  const [selectedSuggestion, setSelectedSuggestion] = useState<Suggestion | null>(null);
  const [showConfig, setShowConfig] = useState(false);
  const [showHistory, setShowHistory] = useState(false);

  const [tempDNA, setTempDNA] = useState<ProjectDNA>({
    format: '電影',
    style: '寫實電影感 (Realistic Cinematic)',
    story: '',
    ratio: '16:9',
    environment: '',
    socialBackground: '',
    coreSetting: ''
  });

  const [project, setProject] = useState<ProjectState>({
    currentPhase: ProductionPhase.PRE_PRODUCTION,
    initialInput: '',
    dna: { format: '', style: '', story: '', ratio: '16:9', environment: '', socialBackground: '', coreSetting: '' },
    suggestions: [],
    history: [],
    generatedVideos: []
  });

  const fileInputRef = useRef<HTMLInputElement>(null);
  const geminiRef = useRef<GeminiService | null>(null);

  useEffect(() => {
    const checkKey = async () => {
      // @ts-ignore
      const exists = await window.aistudio.hasSelectedApiKey();
      if (exists) {
        setHasKey(true);
        geminiRef.current = new GeminiService(process.env.API_KEY || '');
      }
    };
    checkKey();
  }, []);

  const handleSubmitIdea = async (e?: React.FormEvent) => {
    if (e) e.preventDefault();
    if (!input.trim() || isLoading || !geminiRef.current) return;

    // 如果是第一次輸入，紀錄為初心
    const isFirstInput = project.history.length === 0;

    setIsLoading(true);
    try {
      const context = `
        原始靈感初心: ${project.initialInput || input}
        項目DNA: ${JSON.stringify(project.dna)}
        歷史紀錄摘要: ${project.history.map(h => h.content).slice(-3).join('\n')}
      `;

      const results = await geminiRef.current.generateSuggestions(input, project.currentPhase, context);

      setProject(prev => ({ 
        ...prev, 
        suggestions: results,
        initialInput: isFirstInput ? input : prev.initialInput // 永久記錄第一次輸入
      }));

      setHoveredSuggestion(null);
    } catch (error) {
      console.error(error);
    } finally {
      setIsLoading(false);
    }
  };

  const handleSuggestionClick = (s: Suggestion) => {
    setSelectedSuggestion(s);
    const inferredFormat = s.tags.includes('廣告') ? '商業廣告' : s.tags.includes('動畫') ? '動畫短片' : '電影短片';

    setTempDNA({
      ...project.dna,
      format: project.currentPhase === ProductionPhase.PRE_PRODUCTION ? inferredFormat : project.dna.format,
      style: project.currentPhase === ProductionPhase.PRE_PRODUCTION ? '寫實電影感 (Realistic Cinematic)' : project.dna.style,
      story: s.description,
      environment: s.environment || project.dna.environment,
      socialBackground: s.socialBackground || project.dna.socialBackground,
      coreSetting: s.coreSetting || project.dna.coreSetting,
    });
    setShowConfig(true);
  };

  const confirmConfig = () => {
    if (!selectedSuggestion) return;

    const selectedContent = `【確認 [${PHASE_METADATA[project.currentPhase].title}] 方案：${selectedSuggestion.title}】\n${selectedSuggestion.description}`;

    const nextPhases = Object.values(ProductionPhase);
    const currentIndex = nextPhases.indexOf(project.currentPhase);
    const nextPhase = currentIndex < nextPhases.length - 1 ? nextPhases[currentIndex + 1] : project.currentPhase;

    setProject(prev => ({
      ...prev,
      currentPhase: nextPhase,
      dna: { ...tempDNA },
      suggestions: [],
      history: [...prev.history, { 
        role: 'assistant', 
        content: selectedContent, 
        phase: project.currentPhase 
      }]
    }));

    setShowConfig(false);
    setSelectedSuggestion(null);
    setInput('');
  };

  const saveProject = () => {
    const projectToSave = { ...project, generatedVideos: [], history: project.history.map(h => ({ ...h, videoUrl: undefined })) };
    const blob = new Blob([JSON.stringify(projectToSave, null, 2)], { type: 'application/json' });
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url;
    a.download = `電影蒙太奇_專案_${new Date().toLocaleDateString().replace(/\//g, '-')}.json`;
    a.click();
    URL.revokeObjectURL(url);
  };

  const loadProject = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;
    const reader = new FileReader();
    reader.onload = (event) => {
      try {
        const data = JSON.parse(event.target?.result as string) as ProjectState;
        if (data.currentPhase && data.history) setProject(data);
      } catch (err) { alert('讀取檔案出錯'); }
    };
    reader.readAsText(file);
    if (fileInputRef.current) fileInputRef.current.value = '';
  };

  if (!hasKey) return <ApiKeySelector onSelected={() => { setHasKey(true); geminiRef.current = new GeminiService(process.env.API_KEY || ''); }} />;

  return (
    <div className="flex h-screen bg-[#050505] text-white overflow-hidden">
      {/* 側邊導航 */}
      <aside className="w-64 border-r border-white/5 flex flex-col bg-black/40 p-6">
        <div className="flex items-center gap-3 mb-12">
          <div className="bg-amber-600 p-2 rounded-lg shadow-[0_0_15px_rgba(217,119,6,0.3)]">
            <Film className="w-6 h-6 text-white" />
          </div>
          <h1 className="text-lg font-serif font-bold tracking-widest text-white/90">電影蒙太奇 AI</h1>
        </div>

        <nav className="flex-1 space-y-2">
          {Object.entries(PHASE_METADATA).map(([key, meta], idx) => {
            const isActive = project.currentPhase === key;
            return (
              <div key={key} className={`relative flex items-center gap-4 p-3 rounded-lg transition-all ${isActive ? 'bg-white/10 text-amber-500 shadow-inner' : 'text-neutral-600 opacity-60'}`}>
                {isActive && <div className="absolute left-0 w-1 h-6 bg-amber-600 rounded-full" />}
                <span className="text-xl">{meta.icon}</span>
                <div className="flex flex-col">
                  <span className="text-[10px] uppercase tracking-tighter opacity-50">Step 0{idx+1}</span>
                  <span className="text-sm font-medium">{meta.title}</span>
                </div>
              </div>
            );
          })}
        </nav>

        <div className="mt-8 space-y-2 border-t border-white/5 pt-6">
          <button onClick={saveProject} className="w-full flex items-center gap-3 px-3 py-2.5 rounded-lg bg-neutral-900/50 hover:bg-neutral-800 border border-white/5 text-xs text-neutral-300 transition-all group">
            <Download className="w-4 h-4 text-amber-600 group-hover:scale-110 transition-transform" />
            <span>匯出專案</span>
          </button>
          <button onClick={() => fileInputRef.current?.click()} className="w-full flex items-center gap-3 px-3 py-2.5 rounded-lg bg-neutral-900/50 hover:bg-neutral-800 border border-white/5 text-xs text-neutral-300 transition-all group">
            <Upload className="w-4 h-4 text-amber-600 group-hover:scale-110 transition-transform" />
            <span>載入專案</span>
          </button>
          <input type="file" ref={fileInputRef} onChange={loadProject} className="hidden" accept=".json" />
        </div>
      </aside>

      {/* 主要工作區 */}
      <main className="flex-1 flex flex-col bg-[radial-gradient(circle_at_top_right,_rgba(217,119,6,0.05),_transparent)] relative">
        <header className="h-16 px-8 border-b border-white/5 flex items-center justify-between z-10">
          <div className="flex items-center gap-2">
            <Terminal className="w-4 h-4 text-amber-600" />
            <span className="text-[10px] text-neutral-500 uppercase tracking-[0.2em]">DIRECTOR'S TERMINAL</span>
            <ChevronRight className="w-3 h-3 text-neutral-600" />
            <span className="text-sm font-bold text-amber-500 tracking-wide">{PHASE_METADATA[project.currentPhase].title}</span>
          </div>
          <div className="flex gap-4">
             <button onClick={() => setShowHistory(true)} className="text-neutral-500 hover:text-white transition-colors" title="查看專案全貌"><History className="w-5 h-5" /></button>
          </div>
        </header>

        <section className="flex-1 flex flex-col items-center justify-center p-8 max-w-5xl mx-auto w-full">
          {/* 初心回溯指引 */}
          {project.initialInput && (
            <div className="mb-6 flex items-center gap-3 px-4 py-2 bg-amber-900/10 border border-amber-600/20 rounded-full animate-in fade-in slide-in-from-top-2 duration-500">
              <Lightbulb className="w-3 h-3 text-amber-500" />
              <span className="text-[10px] text-amber-500/70 uppercase tracking-widest font-bold">原始靈感初心者：</span>
              <span className="text-[11px] text-neutral-400 italic font-medium truncate max-w-[300px]">"{project.initialInput}"</span>
            </div>
          )}

          <div className="w-full max-w-2xl mb-12 animate-in fade-in zoom-in-95 duration-500">
            <div className="flex flex-col items-center text-center space-y-4 mb-8">
              <div className="px-3 py-1 bg-amber-900/20 rounded-full border border-amber-600/30 text-[10px] text-amber-500 font-bold uppercase tracking-widest">
                拍攝靈感/導演指令
              </div>
              <h2 className="text-2xl md:text-3xl font-serif leading-relaxed text-neutral-100">
                {PHASE_METADATA[project.currentPhase].guide}
              </h2>
            </div>

            <form onSubmit={handleSubmitIdea} className="relative group">
              <input 
                type="text" 
                value={input}
                onChange={(e) => setInput(e.target.value)}
                placeholder="在此輸入您的創意指令..."
                className="w-full bg-white/5 border border-white/10 p-5 pr-16 rounded-2xl focus:outline-none focus:ring-2 focus:ring-amber-600/50 transition-all text-lg placeholder:text-neutral-700 shadow-2xl"
              />
              <button 
                type="submit"
                disabled={isLoading || !input.trim()}
                className="absolute right-3 top-3 bg-amber-600 hover:bg-amber-500 p-3 rounded-xl transition-all disabled:opacity-30 disabled:grayscale"
              >
                {isLoading ? <Loader2 className="w-6 h-6 animate-spin text-white" /> : <Sparkles className="w-6 h-6 text-white" />}
              </button>
            </form>
          </div>

          {project.suggestions.length > 0 && (
            <div className="w-full animate-in fade-in slide-in-from-bottom-8 duration-1000">
              <div className="grid grid-cols-1 md:grid-cols-3 gap-6 mb-12">
                {project.suggestions.map((s, i) => (
                  <button
                    key={i}
                    onMouseEnter={() => setHoveredSuggestion(s)}
                    onClick={() => handleSuggestionClick(s)}
                    className="btn-montage glass p-8 rounded-2xl text-center group border-white/5 hover:border-amber-600/50"
                  >
                    <div className="text-[10px] text-amber-500 font-bold mb-4 tracking-widest opacity-0 group-hover:opacity-100 transition-opacity uppercase">提案 Proposal {i+1}</div>
                    <h3 className="text-lg font-serif font-bold mb-4 line-clamp-2 h-14 flex items-center justify-center">{s.title}</h3>
                    <div className="flex flex-wrap justify-center gap-1.5 mt-2">
                      {s.tags.map(t => <span key={t} className="text-[9px] bg-amber-900/30 px-2 py-0.5 rounded text-amber-200/60 border border-amber-600/10">#{t}</span>)}
                    </div>
                  </button>
                ))}
              </div>

              <div className="h-44 relative">
                {hoveredSuggestion ? (
                  <div className="glass p-8 rounded-2xl border-amber-600/30 animate-in fade-in slide-in-from-bottom-4 duration-300 shadow-2xl bg-black/40">
                    <div className="flex items-start gap-6">
                      <div className="bg-amber-600/20 p-3 rounded-xl border border-amber-600/30 shrink-0">
                        <Clapperboard className="w-6 h-6 text-amber-500" />
                      </div>
                      <div className="space-y-2 text-left">
                        <h4 className="text-amber-500 text-[10px] font-bold uppercase tracking-[0.3em]">導演階段摘要</h4>
                        <p className="text-base text-neutral-200 leading-relaxed italic font-serif">「{hoveredSuggestion.description}」</p>
                        {hoveredSuggestion.environment && (
                          <div className="flex items-center gap-2 mt-2 text-xs text-neutral-500">
                            <MapPin className="w-3 h-3 text-amber-600" /> {hoveredSuggestion.environment}
                          </div>
                        )}
                      </div>
                    </div>
                  </div>
                ) : (
                  <div className="flex flex-col items-center justify-center h-full text-neutral-600 space-y-3 opacity-40">
                    <ArrowRight className="w-5 h-5 animate-bounce" />
                    <p className="text-sm italic font-light tracking-wide">選擇一個方案，或懸停查看 AI 推理細節</p>
                  </div>
                )}
              </div>
            </div>
          )}
        </section>

        {/* 方案確認對話框 */}
        {showConfig && (
          <div className="fixed inset-0 bg-black/95 backdrop-blur-md flex items-center justify-center z-50 p-6">
            <div className="glass w-full max-w-4xl rounded-3xl overflow-hidden shadow-[0_0_50px_rgba(217,119,6,0.15)] border border-amber-600/20 flex flex-col max-h-[90vh]">
              <header className="p-8 border-b border-white/5 flex justify-between items-center bg-white/5">
                <div>
                  <h3 className="text-2xl font-serif font-bold text-white tracking-wide">AI 導演企劃書 (項目 DNA)</h3>
                  <p className="text-[10px] text-amber-500/60 mt-2 uppercase tracking-[0.3em]">AI 已根據靈感自動生成世界觀設定，請檢閱確認</p>
                </div>
                <button onClick={() => setShowConfig(false)} className="text-neutral-500 hover:text-white transition-colors">
                  <X className="w-6 h-6" />
                </button>
              </header>

              <div className="p-10 grid grid-cols-1 md:grid-cols-2 gap-10 overflow-y-auto">
                <div className="space-y-8">
                  <div className="space-y-3">
                    <label className="flex items-center gap-2 text-[10px] font-bold text-neutral-500 uppercase tracking-widest">
                      <Target className="w-3 h-3 text-amber-600" /> 核心設定 (Core Setting)
                    </label>
                    <textarea 
                      value={tempDNA.coreSetting}
                      onChange={(e) => setTempDNA({...tempDNA, coreSetting: e.target.value})}
                      rows={3}
                      className="w-full bg-white/5 border border-white/10 rounded-xl p-4 text-sm text-amber-200/80 outline-none focus:ring-1 focus:ring-amber-500"
                    />
                  </div>
                  <div className="space-y-3">
                    <label className="flex items-center gap-2 text-[10px] font-bold text-neutral-500 uppercase tracking-widest">
                      <Users className="w-3 h-3 text-amber-600" /> 社會背景 (Background)
                    </label>
                    <textarea 
                      value={tempDNA.socialBackground}
                      onChange={(e) => setTempDNA({...tempDNA, socialBackground: e.target.value})}
                      rows={3}
                      className="w-full bg-white/5 border border-white/10 rounded-xl p-4 text-sm text-neutral-300 outline-none focus:ring-1 focus:ring-amber-500"
                    />
                  </div>
                  <div className="space-y-3">
                    <label className="flex items-center gap-2 text-[10px] font-bold text-neutral-500 uppercase tracking-widest">
                      <MapPin className="w-3 h-3 text-amber-600" /> 地理環境 (Environment)
                    </label>
                    <textarea 
                      value={tempDNA.environment}
                      onChange={(e) => setTempDNA({...tempDNA, environment: e.target.value})}
                      rows={3}
                      className="w-full bg-white/5 border border-white/10 rounded-xl p-4 text-sm text-neutral-300 outline-none focus:ring-1 focus:ring-amber-500"
                    />
                  </div>
                </div>

                <div className="space-y-8">
                   <div className="grid grid-cols-2 gap-4">
                      <div className="space-y-2">
                         <label className="text-[10px] font-bold text-neutral-500 uppercase tracking-widest">影片類型</label>
                         <select value={tempDNA.format} onChange={(e) => setTempDNA({...tempDNA, format: e.target.value})} className="w-full bg-white/5 border border-white/10 rounded-lg p-3 text-xs outline-none appearance-none">
                            <option className="bg-black">電影短片</option><option className="bg-black">商業廣告</option><option className="bg-black">動畫短片</option><option className="bg-black">紀錄片</option>
                         </select>
                      </div>
                      <div className="space-y-2">
                         <label className="text-[10px] font-bold text-neutral-500 uppercase tracking-widest">視覺風格</label>
                         <select value={tempDNA.style} onChange={(e) => setTempDNA({...tempDNA, style: e.target.value})} className="w-full bg-white/5 border border-white/10 rounded-lg p-3 text-xs outline-none appearance-none">
                            <option className="bg-black">寫實電影感</option><option className="bg-black">黑色電影</option><option className="bg-black">賽博龐克</option><option className="bg-black">吉卜力風</option>
                         </select>
                      </div>
                   </div>
                   <div className="space-y-3">
                    <label className="flex items-center gap-2 text-[10px] font-bold text-neutral-500 uppercase tracking-widest">
                      <BookOpen className="w-3 h-3 text-amber-600" /> 該階段產出摘要
                    </label>
                    <textarea 
                      value={tempDNA.story}
                      onChange={(e) => setTempDNA({...tempDNA, story: e.target.value})}
                      rows={8}
                      className="w-full bg-white/5 border border-white/10 rounded-2xl p-6 text-sm focus:ring-1 focus:ring-amber-500 outline-none resize-none leading-relaxed font-serif text-neutral-300"
                    />
                  </div>
                </div>
              </div>

              <footer className="p-8 border-t border-white/5 bg-white/5 flex gap-6">
                <button onClick={() => setShowConfig(false)} className="px-10 py-4 rounded-2xl border border-white/10 text-sm font-bold hover:bg-white/5 transition-all text-neutral-400">
                  取消
                </button>
                <button onClick={confirmConfig} className="flex-1 py-4 px-6 rounded-2xl bg-amber-600 text-sm font-bold hover:bg-amber-500 transition-all flex items-center justify-center gap-3 shadow-xl shadow-amber-900/40">
                  <CheckCircle2 className="w-5 h-5" /> 確認 AI 設計並推進下一階段
                </button>
              </footer>
            </div>
          </div>
        )}

        {/* 歷史與初心回溯對話框 */}
        {showHistory && (
          <div className="fixed inset-0 bg-black/95 backdrop-blur-2xl z-[60] p-12 overflow-y-auto">
             <div className="max-w-4xl mx-auto space-y-12 pb-24">
                <div className="flex justify-between items-center border-b border-white/10 pb-8">
                   <div>
                     <h2 className="text-4xl font-serif">項目製作全貌</h2>
                     <p className="text-xs text-amber-500/60 mt-2 uppercase tracking-widest">追溯您的初心靈感與製作歷程</p>
                   </div>
                   <button onClick={() => setShowHistory(false)} className="p-3 bg-white/5 rounded-full hover:bg-amber-600 transition-all"><X className="w-6 h-6" /></button>
                </div>

                {/* 原始靈感展示 */}
                <div className="p-8 bg-amber-600/5 border border-amber-600/20 rounded-3xl relative overflow-hidden group">
                   <Lightbulb className="absolute -right-4 -top-4 w-32 h-32 text-amber-600/10 rotate-12 group-hover:scale-110 transition-transform duration-1000" />
                   <h3 className="text-amber-500 text-xs font-bold uppercase tracking-widest mb-4 flex items-center gap-2">
                     <Sparkles className="w-4 h-4" /> 專案靈感初心 (Original Spark)
                   </h3>
                   <p className="text-2xl font-serif text-neutral-100 leading-relaxed italic relative z-10">
                     「{project.initialInput || "尚未開始製作"}」
                   </p>
                </div>

                <div className="grid grid-cols-1 md:grid-cols-2 gap-8">
                   <div className="glass p-8 rounded-3xl space-y-6">
                      <h3 className="text-amber-500 text-xs font-bold uppercase tracking-widest">當前項目 DNA</h3>
                      <div className="space-y-4">
                         <div className="flex justify-between border-b border-white/5 pb-2"><span className="text-neutral-500 text-sm">影片形式</span><span className="text-sm">{project.dna.format || "未定"}</span></div>
                         <div className="flex justify-between border-b border-white/5 pb-2"><span className="text-neutral-500 text-sm">視覺風格</span><span className="text-sm">{project.dna.style || "未定"}</span></div>
                         <div className="flex justify-between border-b border-white/5 pb-2"><span className="text-neutral-500 text-sm">環境設定</span><span className="text-sm text-right max-w-[200px] truncate">{project.dna.environment || "未定"}</span></div>
                      </div>
                   </div>
                   <div className="glass p-8 rounded-3xl">
                      <h3 className="text-amber-500 text-xs font-bold uppercase tracking-widest mb-4">核心設定摘要</h3>
                      <p className="text-sm text-neutral-400 leading-relaxed italic">「{project.dna.coreSetting || "尚未生成世界觀"}」</p>
                   </div>
                </div>

                <div className="space-y-6">
                   <h3 className="text-amber-500 text-xs font-bold uppercase tracking-widest">製作決策歷史</h3>
                   {project.history.map((h, i) => (
                      <div key={i} className="glass p-6 rounded-2xl border-white/5 hover:border-amber-600/30 transition-all flex gap-6">
                         <div className="text-[10px] text-amber-600 font-mono font-bold pt-1">#0{i+1}</div>
                         <div>
                            <div className="text-[10px] text-neutral-500 mb-2 font-mono">{h.phase ? PHASE_METADATA[h.phase].title : "系統訊息"}</div>
                            <div className="text-sm text-neutral-200 whitespace-pre-wrap">{h.content}</div>
                         </div>
                      </div>
                   ))}
                </div>
             </div>
          </div>
        )}
      </main>

      {/* 右側資訊面板 */}
      <aside className="w-80 border-l border-white/5 bg-black/40 p-6 flex flex-col gap-8 overflow-y-auto">
        <div className="space-y-6">
          <h3 className="text-[10px] font-bold text-neutral-500 uppercase tracking-widest flex items-center gap-2">
            <Layout className="w-4 h-4 text-amber-600" /> 項目活躍 DNA
          </h3>
          <div className="space-y-4">
             <div className="p-5 bg-white/5 rounded-2xl border border-white/10 group hover:border-amber-600/30 transition-all">
                <div className="text-[10px] text-neutral-500 mb-2 flex items-center gap-2"><Layers className="w-3 h-3" /> 進度節點</div>
                <div className="text-xs text-amber-500 font-bold uppercase tracking-wider">
                  {PHASE_METADATA[project.currentPhase].title}
                </div>
             </div>
             {project.dna.environment && (
               <div className="p-5 bg-white/5 rounded-2xl border border-white/10">
                  <div className="text-[10px] text-neutral-500 mb-2 flex items-center gap-2"><MapPin className="w-3 h-3" /> 地理空間</div>
                  <div className="text-xs text-neutral-300 leading-relaxed truncate">{project.dna.environment}</div>
               </div>
             )}
             {project.dna.coreSetting && (
               <div className="p-5 bg-white/5 rounded-2xl border border-white/10">
                  <div className="text-[10px] text-neutral-500 mb-2 flex items-center gap-2"><Target className="w-3 h-3" /> 核心使命</div>
                  <div className="text-[10px] text-neutral-400 line-clamp-3 leading-relaxed italic">{project.dna.coreSetting}</div>
               </div>
             )}
          </div>
        </div>

        <div className="space-y-6 flex-1">
          <h3 className="text-[10px] font-bold text-neutral-500 uppercase tracking-widest flex items-center gap-2">
            <Video className="w-4 h-4 text-amber-600" /> 蒙太奇剪輯庫
          </h3>
          {project.generatedVideos.length > 0 ? (
            <div className="grid grid-cols-1 gap-4">
              {project.generatedVideos.map(v => (
                <div key={v.id} className="aspect-video bg-black rounded-2xl overflow-hidden border border-white/10 group relative">
                   <video src={v.url} className="w-full h-full object-cover" muted loop onMouseEnter={(e) => e.currentTarget.play()} onMouseLeave={(e) => e.currentTarget.pause()} />
                </div>
              ))}
            </div>
          ) : (
            <div className="py-12 px-6 border border-dashed border-white/10 rounded-3xl text-center space-y-4 opacity-50">
              <div className="bg-white/5 w-10 h-10 rounded-full flex items-center justify-center mx-auto">
                <Video className="w-5 h-5 text-neutral-700" />
              </div>
              <p className="text-[10px] text-neutral-600 italic tracking-wide">尚未產出影片</p>
            </div>
          )}
        </div>
      </aside>
    </div>
  );
};

export default App;

export enum ProductionPhase {
  PRE_PRODUCTION = 'PRE_PRODUCTION',
  VISUAL_DEV = 'VISUAL_DEV',
  CHARACTER_DEV = 'CHARACTER_DEV',
  STORY_ARCH = 'STORY_ARCH',
  STORYBOARD = 'STORYBOARD',
  VIDEO_PROMPTING = 'VIDEO_PROMPTING'
}

export interface Suggestion {
  title: string;
  description: string;
  tags: string[];
  environment?: string;
  socialBackground?: string;
  coreSetting?: string;
}

export interface Message {
  role: 'user' | 'assistant';
  content: string;
  images?: string[]; 
  videoUrl?: string;
  phase?: ProductionPhase;
}

export interface GeneratedVideo {
  id: string;
  url: string;
  prompt: string;
  shotLabel: string;
}

export interface ProjectDNA {
  format: string;
  style: string;
  story: string;
  ratio: string;
  environment: string;
  socialBackground: string;
  coreSetting: string;
}

export interface ProjectState {
  currentPhase: ProductionPhase;
  initialInput?: string;
  dna: ProjectDNA;
  suggestions: Suggestion[];
  history: Message[];
  generatedVideos: GeneratedVideo[];
  sceneGrid: string[]; // 儲存九宮格圖片 Base64 或 URL
  coreSceneImage?: string; // 核心場景圖
}

import { GoogleGenAI, Type } from "@google/genai";
import { SYSTEM_INSTRUCTION } from "../constants";
import { Suggestion } from "../types";

export class GeminiService {
  constructor(apiKey: string) {}

  async generateSuggestions(input: string, phase: string, context: string): Promise<Suggestion[]> {
    const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
    const prompt = `目前的靈感/指令： "${input}"。
    請根據目前的製作階段 [${phase}]，提供三個具體的創意導向。

    【關鍵任務】如果是 PRE_PRODUCTION 階段，請發揮頂尖導演聯想力，自動推論出：
    1. 地理環境 (environment)
    2. 社會背景 (socialBackground)
    3. 核心設定 (coreSetting)

    請回傳 JSON 陣列，包含 title, description, tags, environment, socialBackground, coreSetting。`;

    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: [{ role: 'user', parts: [{ text: prompt }] }],
      config: {
        systemInstruction: SYSTEM_INSTRUCTION,
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.ARRAY,
          items: {
            type: Type.OBJECT,
            properties: {
              title: { type: Type.STRING },
              description: { type: Type.STRING },
              tags: { type: Type.ARRAY, items: { type: Type.STRING } },
              environment: { type: Type.STRING },
              socialBackground: { type: Type.STRING },
              coreSetting: { type: Type.STRING }
            },
            required: ["title", "description", "tags"]
          }
        }
      }
    });
    return JSON.parse(response.text || "[]");
  }

  async polishText(text: string, type: string): Promise<string> {
    const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: `你是專業編劇。請將以下內容進行電影化的專業潤色，強調視覺張力與敘事內核。類型：${type}。內容：${text}`,
    });
    return response.text || text;
  }

  async generateImage(prompt: string): Promise<string | null> {
    const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
    try {
      const response = await ai.models.generateContent({
        model: 'gemini-3-pro-image-preview',
        contents: { parts: [{ text: prompt }] },
        config: { imageConfig: { aspectRatio: "16:9", imageSize: "1K" } }
      });
      for (const part of response.candidates?.[0]?.content?.parts || []) {
        if (part.inlineData) return `data:image/png;base64,${part.inlineData.data}`;
      }
      return null;
    } catch (error) { return null; }
  }

  async generateSceneGrid(prompt: string): Promise<string[]> {
    const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
    try {
      const response = await ai.models.generateImages({
        model: 'imagen-4.0-generate-001',
        prompt: `9 different cinematic concept art shots for: ${prompt}. Diverse angles, lighting variations, high cinematic quality.`,
        config: { numberOfImages: 9, aspectRatio: '16:9' },
      });
      return response.generatedImages.map(img => `data:image/png;base64,${img.image.imageBytes}`);
    } catch (error) {
      console.error(error);
      return [];
    }
  }

  async generateVideo(prompt: string, onProgress: (status: string) => void): Promise<string | null> {
    const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
    try {
      onProgress("正在初始化拍攝設備...");
      let operation = await ai.models.generateVideos({
        model: 'veo-3.1-fast-generate-preview',
        prompt: prompt,
        config: { numberOfVideos: 1, resolution: '720p', aspectRatio: '16:9' }
      });
      while (!operation.done) {
        await new Promise(resolve => setTimeout(resolve, 10000));
        operation = await ai.operations.getVideosOperation({ operation: operation });
      }
      const downloadLink = operation.response?.generatedVideos?.[0]?.video?.uri;
      return downloadLink ? `${downloadLink}&key=${process.env.API_KEY}` : null;
    } catch (error) { return null; }
  }
}

import React, { useState, useEffect, useCallback, useRef } from 'react';
import { ProductionPhase, Suggestion, ProjectState, GeneratedVideo, Message, ProjectDNA } from './types';
import { PHASE_METADATA } from './constants';
import { GeminiService } from './services/geminiService';
import { ApiKeySelector } from './components/ApiKeySelector';
import { 
  Film, Sparkles, Send, Loader2, ArrowRight, 
  Info, Clapperboard, Video, Layout, Palette, 
  ChevronRight, History, Save, Download, Upload,
  X, CheckCircle2, Monitor, BookOpen, Layers, Terminal, MapPin, Users, Target, Lightbulb,
  Undo2, Redo2, Wand2, Eye, Grid
} from 'lucide-react';

const App: React.FC = () => {
  const [hasKey, setHasKey] = useState(false);
  const [isLoading, setIsLoading] = useState(false);
  const [input, setInput] = useState('');
  const [hoveredSuggestion, setHoveredSuggestion] = useState<Suggestion | null>(null);
  const [selectedSuggestion, setSelectedSuggestion] = useState<Suggestion | null>(null);
  const [showConfig, setShowConfig] = useState(false);
  const [showHistory, setShowHistory] = useState(false);
  const [activeStep, setActiveStep] = useState<ProductionPhase>(ProductionPhase.PRE_PRODUCTION);

  // Undo/Redo Stack
  const [historyStack, setHistoryStack] = useState<ProjectDNA[]>([]);
  const [redoStack, setRedoStack] = useState<ProjectDNA[]>([]);

  const [tempDNA, setTempDNA] = useState<ProjectDNA>({
    format: '電影', style: '寫實電影感 (Realistic Cinematic)', story: '', ratio: '16:9',
    environment: '', socialBackground: '', coreSetting: ''
  });

  const [project, setProject] = useState<ProjectState>({
    currentPhase: ProductionPhase.PRE_PRODUCTION,
    initialInput: '',
    dna: { format: '', style: '', story: '', ratio: '16:9', environment: '', socialBackground: '', coreSetting: '' },
    suggestions: [], history: [], generatedVideos: [], sceneGrid: []
  });

  const fileInputRef = useRef<HTMLInputElement>(null);
  const geminiRef = useRef<GeminiService | null>(null);

  useEffect(() => {
    const checkKey = async () => {
      // @ts-ignore
      const exists = await window.aistudio.hasSelectedApiKey();
      if (exists) {
        setHasKey(true);
        geminiRef.current = new GeminiService(process.env.API_KEY || '');
      }
    };
    checkKey();
  }, []);

  const handleSubmitIdea = async (e?: React.FormEvent) => {
    if (e) e.preventDefault();
    if (!input.trim() || isLoading || !geminiRef.current) return;

    setIsLoading(true);
    try {
      const results = await geminiRef.current.generateSuggestions(input, activeStep, JSON.stringify(project.dna));
      setProject(prev => ({ 
        ...prev, suggestions: results, 
        initialInput: prev.history.length === 0 ? input : prev.initialInput 
      }));
    } catch (error) { console.error(error); }
    finally { setIsLoading(false); }
  };

  const handleSuggestionClick = (s: Suggestion) => {
    setSelectedSuggestion(s);
    const inferredDNA = {
      ...project.dna,
      format: s.tags.includes('廣告') ? '商業廣告' : s.tags.includes('動畫') ? '動畫短片' : '電影短片',
      story: s.description,
      environment: s.environment || project.dna.environment,
      socialBackground: s.socialBackground || project.dna.socialBackground,
      coreSetting: s.coreSetting || project.dna.coreSetting,
    };
    setTempDNA(inferredDNA);
    setHistoryStack([inferredDNA]);
    setRedoStack([]);
    setShowConfig(true);
  };

  const pushToUndo = (newDNA: ProjectDNA) => {
    setHistoryStack(prev => [...prev, newDNA]);
    setRedoStack([]);
  };

  const handleUndo = () => {
    if (historyStack.length <= 1) return;
    const current = historyStack[historyStack.length - 1];
    const prev = historyStack[historyStack.length - 2];
    setRedoStack(r => [current, ...r]);
    setHistoryStack(h => h.slice(0, -1));
    setTempDNA(prev);
  };

  const handleRedo = () => {
    if (redoStack.length === 0) return;
    const next = redoStack[0];
    setRedoStack(r => r.slice(1));
    setHistoryStack(h => [...h, next]);
    setTempDNA(next);
  };

  const handlePolish = async (field: keyof ProjectDNA, type: string) => {
    if (!geminiRef.current || isLoading) return;
    setIsLoading(true);
    try {
      const polished = await geminiRef.current.polishText(tempDNA[field] as string, type);
      const updated = { ...tempDNA, [field]: polished };
      setTempDNA(updated);
      pushToUndo(updated);
    } finally { setIsLoading(false); }
  };

  const confirmConfig = async () => {
    if (!selectedSuggestion || !geminiRef.current) return;
    setIsLoading(true);

    try {
      let coreImage = project.coreSceneImage;
      let grid = project.sceneGrid;

      // 如果是第一階段，生成核心場景
      if (activeStep === ProductionPhase.PRE_PRODUCTION) {
        coreImage = await geminiRef.current.generateImage(`${tempDNA.story}. ${tempDNA.style}. Cinematic, 8k.`) || undefined;
        // 同時生成九宮格
        grid = await geminiRef.current.generateSceneGrid(tempDNA.story);
      }

      const nextPhases = Object.values(ProductionPhase);
      const currentIndex = nextPhases.indexOf(activeStep);
      const nextPhase = currentIndex < nextPhases.length - 1 ? nextPhases[currentIndex + 1] : activeStep;

      setProject(prev => ({
        ...prev,
        currentPhase: nextPhase,
        dna: { ...tempDNA },
        suggestions: [],
        history: [...prev.history, { role: 'assistant', content: `【確認階段：${PHASE_METADATA[activeStep].title}】\n已確認 DNA 與視覺基調。`, phase: activeStep }],
        coreSceneImage: coreImage,
        sceneGrid: grid
      }));

      setActiveStep(nextPhase);
      setShowConfig(false);
      setSelectedSuggestion(null);
      setInput('');
    } finally { setIsLoading(false); }
  };

  if (!hasKey) return <ApiKeySelector onSelected={() => { setHasKey(true); geminiRef.current = new GeminiService(process.env.API_KEY || ''); }} />;

  return (
    <div className="flex h-screen bg-[#050505] text-white overflow-hidden">
      {/* 側邊導航：改為切換按鈕 */}
      <aside className="w-64 border-r border-white/5 flex flex-col bg-black/40 p-6">
        <div className="flex items-center gap-3 mb-12">
          <div className="bg-amber-600 p-2 rounded-lg shadow-[0_0_15px_rgba(217,119,6,0.3)]"><Film className="w-6 h-6 text-white" /></div>
          <h1 className="text-lg font-serif font-bold tracking-widest text-white/90">電影蒙太奇</h1>
        </div>

        <nav className="flex-1 space-y-2">
          {Object.entries(PHASE_METADATA).map(([key, meta], idx) => {
            const phaseKey = key as ProductionPhase;
            const isActive = activeStep === phaseKey;
            const isAccessible = Object.values(ProductionPhase).indexOf(phaseKey) <= Object.values(ProductionPhase).indexOf(project.currentPhase);

            return (
              <button 
                key={key} 
                disabled={!isAccessible}
                onClick={() => setActiveStep(phaseKey)}
                className={`w-full relative flex items-center gap-4 p-3 rounded-lg transition-all text-left group
                  ${isActive ? 'bg-amber-600/20 text-amber-500 ring-1 ring-amber-600/30' : 'text-neutral-600 hover:text-neutral-400'}
                  ${!isAccessible ? 'opacity-30 grayscale cursor-not-allowed' : 'cursor-pointer'}
                `}
              >
                {isActive && <div className="absolute left-0 w-1 h-6 bg-amber-600 rounded-full" />}
                <span className="text-xl">{meta.icon}</span>
                <div className="flex flex-col">
                  <span className="text-[9px] uppercase tracking-tighter opacity-50">Step 0{idx+1}</span>
                  <span className="text-sm font-bold">{meta.title}</span>
                </div>
              </button>
            );
          })}
        </nav>

        <div className="mt-8 space-y-2 border-t border-white/5 pt-6">
          <button onClick={() => setShowHistory(true)} className="w-full flex items-center gap-3 px-3 py-2 text-xs text-neutral-400 hover:text-white transition-colors group">
            <History className="w-4 h-4 text-amber-600 group-hover:rotate-[-45deg] transition-transform" />
            <span>製作歷史</span>
          </button>
          <button onClick={saveProject} className="w-full flex items-center gap-3 px-3 py-2 text-xs text-neutral-400 hover:text-white transition-colors"><Download className="w-4 h-4" /> 匯出專案</button>
        </div>
      </aside>

      {/* 主要工作區 */}
      <main className="flex-1 flex flex-col relative overflow-hidden">
        <header className="h-16 px-8 border-b border-white/5 flex items-center justify-between z-10 bg-black/50 backdrop-blur-md">
          <div className="flex items-center gap-2">
            <Terminal className="w-4 h-4 text-amber-600" />
            <span className="text-[10px] text-neutral-500 uppercase tracking-[0.2em]">TERMINAL</span>
            <ChevronRight className="w-3 h-3 text-neutral-600" />
            <span className="text-sm font-bold text-amber-500 uppercase">{PHASE_METADATA[activeStep].title}</span>
          </div>
        </header>

        <section className="flex-1 flex flex-col items-center justify-center p-8 max-w-5xl mx-auto w-full overflow-y-auto">
          {/* 初心 */}
          {project.initialInput && (
            <div className="mb-8 flex items-center gap-3 px-5 py-2.5 bg-amber-900/10 border border-amber-600/20 rounded-full">
              <Lightbulb className="w-3.5 h-3.5 text-amber-500" />
              <span className="text-[10px] text-amber-500 font-bold tracking-widest">初心：</span>
              <span className="text-[11px] text-neutral-300 italic truncate max-w-[400px]">"{project.initialInput}"</span>
            </div>
          )}

          <div className="w-full max-w-2xl mb-12">
            <div className="flex flex-col items-center text-center space-y-4 mb-8">
              <h2 className="text-3xl font-serif leading-relaxed text-neutral-100">{PHASE_METADATA[activeStep].guide}</h2>
            </div>

            <form onSubmit={handleSubmitIdea} className="relative group">
              <input 
                type="text" value={input} onChange={(e) => setInput(e.target.value)}
                placeholder="在此輸入您的創意指令..."
                className="w-full bg-white/5 border border-white/10 p-5 pr-16 rounded-2xl focus:outline-none focus:ring-2 focus:ring-amber-600/50 text-lg shadow-2xl"
              />
              <button 
                type="submit" disabled={isLoading || !input.trim()}
                className="absolute right-3 top-3 bg-amber-600 hover:bg-amber-500 p-3 rounded-xl transition-all"
              >
                {isLoading ? <Loader2 className="w-6 h-6 animate-spin" /> : <Sparkles className="w-6 h-6" />}
              </button>
            </form>
          </div>

          {project.suggestions.length > 0 && (
            <div className="w-full grid grid-cols-1 md:grid-cols-3 gap-6 mb-12 animate-in fade-in slide-in-from-bottom-8">
              {project.suggestions.map((s, i) => (
                <button
                  key={i} onMouseEnter={() => setHoveredSuggestion(s)} onClick={() => handleSuggestionClick(s)}
                  className="btn-montage glass p-8 rounded-2xl text-center border-white/5 hover:border-amber-600/50 group"
                >
                  <div className="text-[10px] text-amber-500 font-bold mb-4 opacity-0 group-hover:opacity-100 uppercase tracking-widest">提案 Proposal {i+1}</div>
                  <h3 className="text-lg font-serif font-bold mb-4 line-clamp-2 h-14 flex items-center justify-center">{s.title}</h3>
                  <div className="flex flex-wrap justify-center gap-1.5 mt-2">
                    {s.tags.map(t => <span key={t} className="text-[9px] bg-amber-900/30 px-2 py-0.5 rounded text-amber-200/60 border border-amber-600/10">#{t}</span>)}
                  </div>
                </button>
              ))}
            </div>
          )}

          {/* 九宮格展示區域 */}
          {project.sceneGrid.length > 0 && activeStep === ProductionPhase.VISUAL_DEV && (
            <div className="w-full space-y-6 mt-12 animate-in fade-in zoom-in-95">
              <h3 className="text-xs font-bold text-amber-500 uppercase tracking-[0.4em] flex items-center gap-3">
                <Grid className="w-4 h-4" /> 專案場景九宮格
              </h3>
              <div className="grid grid-cols-3 gap-3">
                {project.sceneGrid.map((img, i) => (
                  <div key={i} className="aspect-video rounded-xl overflow-hidden border border-white/5 hover:scale-105 transition-transform cursor-zoom-in">
                    <img src={img} className="w-full h-full object-cover" />
                  </div>
                ))}
              </div>
            </div>
          )}
        </section>

        {/* AI 配置對話框：新增潤色、Undo、Redo */}
        {showConfig && (
          <div className="fixed inset-0 bg-black/95 backdrop-blur-md flex items-center justify-center z-50 p-6 overflow-y-auto">
            <div className="glass w-full max-w-5xl rounded-3xl overflow-hidden border border-amber-600/20 flex flex-col max-h-[90vh]">
              <header className="p-8 border-b border-white/5 flex justify-between items-center bg-white/5">
                <div>
                  <h3 className="text-2xl font-serif font-bold tracking-wide">AI 導演企劃書</h3>
                  <div className="flex gap-4 mt-3">
                    <button onClick={handleUndo} disabled={historyStack.length <= 1} className="p-2 bg-white/5 rounded-lg hover:bg-amber-600 disabled:opacity-20"><Undo2 className="w-4 h-4" /></button>
                    <button onClick={handleRedo} disabled={redoStack.length === 0} className="p-2 bg-white/5 rounded-lg hover:bg-amber-600 disabled:opacity-20"><Redo2 className="w-4 h-4" /></button>
                  </div>
                </div>
                <button onClick={() => setShowConfig(false)} className="text-neutral-500 hover:text-white"><X className="w-8 h-8" /></button>
              </header>

              <div className="p-10 grid grid-cols-1 lg:grid-cols-2 gap-12 overflow-y-auto">
                <div className="space-y-8">
                  {/* 可潤色的欄位 */}
                  {[
                    { id: 'coreSetting', label: '核心設定', icon: <Target className="w-3 h-3" /> },
                    { id: 'socialBackground', label: '社會背景', icon: <Users className="w-3 h-3" /> },
                    { id: 'environment', label: '地理環境', icon: <MapPin className="w-3 h-3" /> }
                  ].map(field => (
                    <div key={field.id} className="group relative">
                      <div className="flex justify-between items-center mb-3">
                        <label className="flex items-center gap-2 text-[10px] font-bold text-neutral-500 uppercase tracking-widest">
                          {field.icon} {field.label}
                        </label>
                        <button 
                          onClick={() => handlePolish(field.id as keyof ProjectDNA, field.label)}
                          className="flex items-center gap-1.5 text-[9px] bg-amber-600/10 hover:bg-amber-600 text-amber-500 hover:text-white px-2 py-1 rounded-md transition-all opacity-0 group-hover:opacity-100"
                        >
                          <Wand2 className="w-3 h-3" /> AI 潤色
                        </button>
                      </div>
                      <textarea 
                        value={tempDNA[field.id as keyof ProjectDNA]}
                        onChange={(e) => {
                          const updated = { ...tempDNA, [field.id]: e.target.value };
                          setTempDNA(updated);
                          pushToUndo(updated);
                        }}
                        rows={3}
                        className="w-full bg-white/5 border border-white/10 rounded-xl p-4 text-sm text-neutral-200 outline-none focus:ring-1 focus:ring-amber-500"
                      />
                    </div>
                  ))}
                </div>

                <div className="space-y-8">
                   <div className="space-y-3 group">
                    <div className="flex justify-between items-center">
                      <label className="flex items-center gap-2 text-[10px] font-bold text-neutral-500 uppercase tracking-widest"><BookOpen className="w-3 h-3" /> 敘事摘要</label>
                      <button onClick={() => handlePolish('story', '敘事摘要')} className="flex items-center gap-1.5 text-[9px] bg-amber-600/10 hover:bg-amber-600 text-amber-500 hover:text-white px-2 py-1 rounded-md opacity-0 group-hover:opacity-100 transition-all"><Wand2 className="w-3 h-3" /> AI 潤色</button>
                    </div>
                    <textarea 
                      value={tempDNA.story}
                      onChange={(e) => {
                        const updated = { ...tempDNA, story: e.target.value };
                        setTempDNA(updated);
                        pushToUndo(updated);
                      }}
                      rows={10}
                      className="w-full bg-white/5 border border-white/10 rounded-2xl p-6 text-sm focus:ring-1 focus:ring-amber-500 outline-none leading-relaxed font-serif text-neutral-300"
                    />
                  </div>
                </div>
              </div>

              <footer className="p-8 border-t border-white/5 bg-white/5 flex gap-6">
                <button onClick={confirmConfig} disabled={isLoading} className="flex-1 py-5 rounded-2xl bg-amber-600 hover:bg-amber-500 text-sm font-bold flex items-center justify-center gap-4 shadow-xl disabled:opacity-50">
                  {isLoading ? <Loader2 className="w-6 h-6 animate-spin" /> : <><CheckCircle2 className="w-6 h-6" /> 確認 AI 設計並生成核心場景</>}
                </button>
              </footer>
            </div>
          </div>
        )}

        {showHistory && (
          <div className="fixed inset-0 bg-black/95 backdrop-blur-3xl z-[60] p-12 overflow-y-auto">
             <div className="max-w-5xl mx-auto space-y-16 pb-24">
                <div className="flex justify-between items-center border-b border-white/10 pb-8">
                   <h2 className="text-4xl font-serif tracking-widest">項目檔案庫</h2>
                   <button onClick={() => setShowHistory(false)} className="p-4 bg-white/5 rounded-full hover:bg-amber-600"><X className="w-8 h-8" /></button>
                </div>

                {project.coreSceneImage && (
                  <div className="space-y-6">
                    <h3 className="text-xs font-bold text-amber-500 uppercase tracking-[0.4em] flex items-center gap-2"><Eye className="w-4 h-4" /> 核心視覺定義</h3>
                    <div className="aspect-[21/9] rounded-3xl overflow-hidden border border-white/10 shadow-2xl">
                       <img src={project.coreSceneImage} className="w-full h-full object-cover" />
                    </div>
                  </div>
                )}

                <div className="grid grid-cols-1 md:grid-cols-2 gap-12">
                   <div className="space-y-6">
                      <h3 className="text-amber-500 text-xs font-bold uppercase tracking-widest">當前 DNA</h3>
                      <div className="glass p-8 rounded-3xl space-y-4">
                         {Object.entries(project.dna).filter(([k]) => k !== 'story').map(([k, v]) => (
                           <div key={k} className="flex justify-between border-b border-white/5 pb-2">
                             <span className="text-neutral-500 text-xs capitalize">{k}</span>
                             <span className="text-xs text-neutral-200">{v}</span>
                           </div>
                         ))}
                      </div>
                   </div>
                   <div className="space-y-6">
                      <h3 className="text-amber-500 text-xs font-bold uppercase tracking-widest">劇本核心</h3>
                      <div className="glass p-8 rounded-3xl">
                        <p className="text-sm text-neutral-400 leading-relaxed italic">{project.dna.story}</p>
                      </div>
                   </div>
                </div>
             </div>
          </div>
        )}
      </main>

      {/* 右側資訊面板：展示核心場景與九宮格 */}
      <aside className="w-80 border-l border-white/5 bg-black/40 p-6 flex flex-col gap-8 overflow-y-auto">
        <div className="space-y-6">
          <h3 className="text-[10px] font-bold text-neutral-500 uppercase tracking-widest">視覺檔案 (Asset)</h3>
          {project.coreSceneImage ? (
            <div className="space-y-6 animate-in fade-in duration-700">
              <div className="aspect-video rounded-2xl overflow-hidden border border-white/10 shadow-lg group relative">
                <img src={project.coreSceneImage} className="w-full h-full object-cover" />
                <div className="absolute inset-0 bg-black/60 opacity-0 group-hover:opacity-100 transition-opacity flex items-center justify-center p-4">
                  <p className="text-[10px] text-center italic leading-relaxed text-amber-500">「這是本片的視覺基調」</p>
                </div>
              </div>

              {project.sceneGrid.length > 0 && (
                <div className="grid grid-cols-3 gap-2">
                  {project.sceneGrid.slice(0, 9).map((img, i) => (
                    <div key={i} className="aspect-square rounded-lg overflow-hidden border border-white/5 opacity-60 hover:opacity-100 transition-opacity">
                      <img src={img} className="w-full h-full object-cover" />
                    </div>
                  ))}
                </div>
              )}
            </div>
          ) : (
            <div className="py-12 border border-dashed border-white/10 rounded-3xl text-center opacity-30">
              <Eye className="w-8 h-8 mx-auto mb-3 text-neutral-700" />
              <p className="text-[10px] uppercase tracking-widest">等待視覺生成</p>
            </div>
          )}
        </div>

        <div className="mt-auto pt-6 border-t border-white/5">
           <div className="flex items-center justify-between text-[10px] text-neutral-600 mb-2 font-mono">
              <span>PROJECT QUALITY</span>
              <span className="text-amber-600">MASTER GRADE</span>
           </div>
           <div className="h-1 bg-white/5 rounded-full overflow-hidden">
              <div className="h-full bg-amber-600/50 w-full animate-pulse"></div>
           </div>
        </div>
      </aside>
    </div>
  );
};

export default App;

import React, { useState, useEffect, useCallback, useRef } from 'react';
import { ProductionPhase, Suggestion, ProjectState, GeneratedVideo, Message, ProjectDNA } from './types';
import { PHASE_METADATA } from './constants';
import { GeminiService } from './services/geminiService';
import { ApiKeySelector } from './components/ApiKeySelector';
import { 
  Film, Sparkles, Send, Loader2, ArrowRight, 
  Info, Clapperboard, Video, Layout, Palette, 
  ChevronRight, History, Save, Download, Upload,
  X, CheckCircle2, Monitor, BookOpen, Layers, Terminal, MapPin, Users, Target, Lightbulb,
  Undo2, Redo2, Wand2, Eye, Grid
} from 'lucide-react';

const App: React.FC = () => {
  const [hasKey, setHasKey] = useState(false);
  const [isLoading, setIsLoading] = useState(false);
  const [input, setInput] = useState('');
  const [hoveredSuggestion, setHoveredSuggestion] = useState<Suggestion | null>(null);
  const [selectedSuggestion, setSelectedSuggestion] = useState<Suggestion | null>(null);
  const [showConfig, setShowConfig] = useState(false);
  const [showHistory, setShowHistory] = useState(false);
  const [activeStep, setActiveStep] = useState<ProductionPhase>(ProductionPhase.PRE_PRODUCTION);

  // Undo/Redo Stack
  const [historyStack, setHistoryStack] = useState<ProjectDNA[]>([]);
  const [redoStack, setRedoStack] = useState<ProjectDNA[]>([]);

  const [tempDNA, setTempDNA] = useState<ProjectDNA>({
    format: '電影', style: '寫實電影感 (Realistic Cinematic)', story: '', ratio: '16:9',
    environment: '', socialBackground: '', coreSetting: ''
  });

  const [project, setProject] = useState<ProjectState>({
    currentPhase: ProductionPhase.PRE_PRODUCTION,
    initialInput: '',
    dna: { format: '', style: '', story: '', ratio: '16:9', environment: '', socialBackground: '', coreSetting: '' },
    suggestions: [], history: [], generatedVideos: [], sceneGrid: []
  });

  const fileInputRef = useRef<HTMLInputElement>(null);
  const geminiRef = useRef<GeminiService | null>(null);

  useEffect(() => {
    const checkKey = async () => {
      // @ts-ignore
      const exists = await window.aistudio.hasSelectedApiKey();
      if (exists) {
        setHasKey(true);
        geminiRef.current = new GeminiService(process.env.API_KEY || '');
      }
    };
    checkKey();
  }, []);

  // Implementation for saveProject to fix undefined error
  const saveProject = () => {
    const data = JSON.stringify(project, null, 2);
    const blob = new Blob([data], { type: 'application/json' });
    const url = URL.createObjectURL(blob);
    const link = document.createElement('a');
    link.href = url;
    link.download = `montage-project-${new Date().toISOString().slice(0, 10)}.json`;
    link.click();
    URL.revokeObjectURL(url);
  };

  const handleSubmitIdea = async (e?: React.FormEvent) => {
    if (e) e.preventDefault();
    if (!input.trim() || isLoading || !geminiRef.current) return;

    setIsLoading(true);
    try {
      const results = await geminiRef.current.generateSuggestions(input, activeStep, JSON.stringify(project.dna));
      setProject(prev => ({ 
        ...prev, suggestions: results, 
        initialInput: prev.history.length === 0 ? input : prev.initialInput 
      }));
    } catch (error) { console.error(error); }
    finally { setIsLoading(false); }
  };

  const handleSuggestionClick = (s: Suggestion) => {
    setSelectedSuggestion(s);
    const inferredDNA = {
      ...project.dna,
      format: s.tags.includes('廣告') ? '商業廣告' : s.tags.includes('動畫') ? '動畫短片' : '電影短片',
      story: s.description,
      environment: s.environment || project.dna.environment,
      socialBackground: s.socialBackground || project.dna.socialBackground,
      coreSetting: s.coreSetting || project.dna.coreSetting,
    };
    setTempDNA(inferredDNA);
    setHistoryStack([inferredDNA]);
    setRedoStack([]);
    setShowConfig(true);
  };

  const pushToUndo = (newDNA: ProjectDNA) => {
    setHistoryStack(prev => [...prev, newDNA]);
    setRedoStack([]);
  };

  const handleUndo = () => {
    if (historyStack.length <= 1) return;
    const current = historyStack[historyStack.length - 1];
    const prev = historyStack[historyStack.length - 2];
    setRedoStack(r => [current, ...r]);
    setHistoryStack(h => h.slice(0, -1));
    setTempDNA(prev);
  };

  const handleRedo = () => {
    if (redoStack.length === 0) return;
    const next = redoStack[0];
    setRedoStack(r => r.slice(1));
    setHistoryStack(h => [...h, next]);
    setTempDNA(next);
  };

  const handlePolish = async (field: keyof ProjectDNA, type: string) => {
    if (!geminiRef.current || isLoading) return;
    setIsLoading(true);
    try {
      const polished = await geminiRef.current.polishText(tempDNA[field] as string, type);
      const updated = { ...tempDNA, [field]: polished };
      setTempDNA(updated);
      pushToUndo(updated);
    } finally { setIsLoading(false); }
  };

  const confirmConfig = async () => {
    if (!selectedSuggestion || !geminiRef.current) return;
    setIsLoading(true);

    try {
      let coreImage = project.coreSceneImage;
      let grid = project.sceneGrid;

      // 如果是第一階段，生成核心場景
      if (activeStep === ProductionPhase.PRE_PRODUCTION) {
        coreImage = await geminiRef.current.generateImage(`${tempDNA.story}. ${tempDNA.style}. Cinematic, 8k.`) || undefined;
        // 同時生成九宮格
        grid = await geminiRef.current.generateSceneGrid(tempDNA.story);
      }

      const nextPhases = Object.values(ProductionPhase);
      const currentIndex = nextPhases.indexOf(activeStep);
      const nextPhase = currentIndex < nextPhases.length - 1 ? nextPhases[currentIndex + 1] : activeStep;

      setProject(prev => ({
        ...prev,
        currentPhase: nextPhase,
        dna: { ...tempDNA },
        suggestions: [],
        history: [...prev.history, { role: 'assistant', content: `【確認階段：${PHASE_METADATA[activeStep].title}】\n已確認 DNA 與視覺基調。`, phase: activeStep }],
        coreSceneImage: coreImage,
        sceneGrid: grid
      }));

      setActiveStep(nextPhase);
      setShowConfig(false);
      setSelectedSuggestion(null);
      setInput('');
    } finally { setIsLoading(false); }
  };

  if (!hasKey) return <ApiKeySelector onSelected={() => { setHasKey(true); geminiRef.current = new GeminiService(process.env.API_KEY || ''); }} />;

  return (
    <div className="flex h-screen bg-[#050505] text-white overflow-hidden">
      {/* 側邊導航：改為切換按鈕 */}
      <aside className="w-64 border-r border-white/5 flex flex-col bg-black/40 p-6">
        <div className="flex items-center gap-3 mb-12">
          <div className="bg-amber-600 p-2 rounded-lg shadow-[0_0_15px_rgba(217,119,6,0.3)]"><Film className="w-6 h-6 text-white" /></div>
          <h1 className="text-lg font-serif font-bold tracking-widest text-white/90">電影蒙太奇</h1>
        </div>

        <nav className="flex-1 space-y-2">
          {Object.entries(PHASE_METADATA).map(([key, meta], idx) => {
            const phaseKey = key as ProductionPhase;
            const isActive = activeStep === phaseKey;
            const isAccessible = Object.values(ProductionPhase).indexOf(phaseKey) <= Object.values(ProductionPhase).indexOf(project.currentPhase);

            return (
              <button 
                key={key} 
                disabled={!isAccessible}
                onClick={() => setActiveStep(phaseKey)}
                className={`w-full relative flex items-center gap-4 p-3 rounded-lg transition-all text-left group
                  ${isActive ? 'bg-amber-600/20 text-amber-500 ring-1 ring-amber-600/30' : 'text-neutral-600 hover:text-neutral-400'}
                  ${!isAccessible ? 'opacity-30 grayscale cursor-not-allowed' : 'cursor-pointer'}
                `}
              >
                {isActive && <div className="absolute left-0 w-1 h-6 bg-amber-600 rounded-full" />}
                <span className="text-xl">{meta.icon}</span>
                <div className="flex flex-col">
                  <span className="text-[9px] uppercase tracking-tighter opacity-50">Step 0{idx+1}</span>
                  <span className="text-sm font-bold">{meta.title}</span>
                </div>
              </button>
            );
          })}
        </nav>

        <div className="mt-8 space-y-2 border-t border-white/5 pt-6">
          <button onClick={() => setShowHistory(true)} className="w-full flex items-center gap-3 px-3 py-2 text-xs text-neutral-400 hover:text-white transition-colors group">
            <History className="w-4 h-4 text-amber-600 group-hover:rotate-[-45deg] transition-transform" />
            <span>製作歷史</span>
          </button>
          <button onClick={saveProject} className="w-full flex items-center gap-3 px-3 py-2 text-xs text-neutral-400 hover:text-white transition-colors"><Download className="w-4 h-4" /> 匯出專案</button>
        </div>
      </aside>

      {/* 主要工作區 */}
      <main className="flex-1 flex flex-col relative overflow-hidden">
        <header className="h-16 px-8 border-b border-white/5 flex items-center justify-between z-10 bg-black/50 backdrop-blur-md">
          <div className="flex items-center gap-2">
            <Terminal className="w-4 h-4 text-amber-600" />
            <span className="text-[10px] text-neutral-500 uppercase tracking-[0.2em]">TERMINAL</span>
            <ChevronRight className="w-3 h-3 text-neutral-600" />
            <span className="text-sm font-bold text-amber-500 uppercase">{PHASE_METADATA[activeStep].title}</span>
          </div>
        </header>

        <section className="flex-1 flex flex-col items-center justify-center p-8 max-w-5xl mx-auto w-full overflow-y-auto">
          {/* 初心 */}
          {project.initialInput && (
            <div className="mb-8 flex items-center gap-3 px-5 py-2.5 bg-amber-900/10 border border-amber-600/20 rounded-full">
              <Lightbulb className="w-3.5 h-3.5 text-amber-500" />
              <span className="text-[10px] text-amber-500 font-bold tracking-widest">初心：</span>
              <span className="text-[11px] text-neutral-300 italic truncate max-w-[400px]">"{project.initialInput}"</span>
            </div>
          )}

          <div className="w-full max-w-2xl mb-12">
            <div className="flex flex-col items-center text-center space-y-4 mb-8">
              <h2 className="text-3xl font-serif leading-relaxed text-neutral-100">{PHASE_METADATA[activeStep].guide}</h2>
            </div>

            <form onSubmit={handleSubmitIdea} className="relative group">
              <input 
                type="text" value={input} onChange={(e) => setInput(e.target.value)}
                placeholder="在此輸入您的創意指令..."
                className="w-full bg-white/5 border border-white/10 p-5 pr-16 rounded-2xl focus:outline-none focus:ring-2 focus:ring-amber-600/50 text-lg shadow-2xl"
              />
              <button 
                type="submit" disabled={isLoading || !input.trim()}
                className="absolute right-3 top-3 bg-amber-600 hover:bg-amber-500 p-3 rounded-xl transition-all"
              >
                {isLoading ? <Loader2 className="w-6 h-6 animate-spin" /> : <Sparkles className="w-6 h-6" />}
              </button>
            </form>
          </div>

          {project.suggestions.length > 0 && (
            <div className="w-full grid grid-cols-1 md:grid-cols-3 gap-6 mb-12 animate-in fade-in slide-in-from-bottom-8">
              {project.suggestions.map((s, i) => (
                <button
                  key={i} onMouseEnter={() => setHoveredSuggestion(s)} onClick={() => handleSuggestionClick(s)}
                  className="btn-montage glass p-8 rounded-2xl text-center border-white/5 hover:border-amber-600/50 group"
                >
                  <div className="text-[10px] text-amber-500 font-bold mb-4 opacity-0 group-hover:opacity-100 uppercase tracking-widest">提案 Proposal {i+1}</div>
                  <h3 className="text-lg font-serif font-bold mb-4 line-clamp-2 h-14 flex items-center justify-center">{s.title}</h3>
                  <div className="flex flex-wrap justify-center gap-1.5 mt-2">
                    {s.tags.map(t => <span key={t} className="text-[9px] bg-amber-900/30 px-2 py-0.5 rounded text-amber-200/60 border border-amber-600/10">#{t}</span>)}
                  </div>
                </button>
              ))}
            </div>
          )}

          {/* 九宮格展示區域 */}
          {project.sceneGrid.length > 0 && activeStep === ProductionPhase.VISUAL_DEV && (
            <div className="w-full space-y-6 mt-12 animate-in fade-in zoom-in-95">
              <h3 className="text-xs font-bold text-amber-500 uppercase tracking-[0.4em] flex items-center gap-3">
                <Grid className="w-4 h-4" /> 專案場景九宮格
              </h3>
              <div className="grid grid-cols-3 gap-3">
                {project.sceneGrid.map((img, i) => (
                  <div key={i} className="aspect-video rounded-xl overflow-hidden border border-white/5 hover:scale-105 transition-transform cursor-zoom-in">
                    <img src={img} className="w-full h-full object-cover" />
                  </div>
                ))}
              </div>
            </div>
          )}
        </section>

        {/* AI 配置對話框：新增潤色、Undo、Redo */}
        {showConfig && (
          <div className="fixed inset-0 bg-black/95 backdrop-blur-md flex items-center justify-center z-50 p-6 overflow-y-auto">
            <div className="glass w-full max-w-5xl rounded-3xl overflow-hidden border border-amber-600/20 flex flex-col max-h-[90vh]">
              <header className="p-8 border-b border-white/5 flex justify-between items-center bg-white/5">
                <div>
                  <h3 className="text-2xl font-serif font-bold tracking-wide">AI 導演企劃書</h3>
                  <div className="flex gap-4 mt-3">
                    <button onClick={handleUndo} disabled={historyStack.length <= 1} className="p-2 bg-white/5 rounded-lg hover:bg-amber-600 disabled:opacity-20"><Undo2 className="w-4 h-4" /></button>
                    <button onClick={handleRedo} disabled={redoStack.length === 0} className="p-2 bg-white/5 rounded-lg hover:bg-amber-600 disabled:opacity-20"><Redo2 className="w-4 h-4" /></button>
                  </div>
                </div>
                <button onClick={() => setShowConfig(false)} className="text-neutral-500 hover:text-white"><X className="w-8 h-8" /></button>
              </header>

              <div className="p-10 grid grid-cols-1 lg:grid-cols-2 gap-12 overflow-y-auto">
                <div className="space-y-8">
                  {/* 可潤色的欄位 */}
                  {[
                    { id: 'coreSetting', label: '核心設定', icon: <Target className="w-3 h-3" /> },
                    { id: 'socialBackground', label: '社會背景', icon: <Users className="w-3 h-3" /> },
                    { id: 'environment', label: '地理環境', icon: <MapPin className="w-3 h-3" /> }
                  ].map(field => (
                    <div key={field.id} className="group relative">
                      <div className="flex justify-between items-center mb-3">
                        <label className="flex items-center gap-2 text-[10px] font-bold text-neutral-500 uppercase tracking-widest">
                          {field.icon} {field.label}
                        </label>
                        <button 
                          onClick={() => handlePolish(field.id as keyof ProjectDNA, field.label)}
                          className="flex items-center gap-1.5 text-[9px] bg-amber-600/10 hover:bg-amber-600 text-amber-500 hover:text-white px-2 py-1 rounded-md transition-all opacity-0 group-hover:opacity-100"
                        >
                          <Wand2 className="w-3 h-3" /> AI 潤色
                        </button>
                      </div>
                      <textarea 
                        value={tempDNA[field.id as keyof ProjectDNA]}
                        onChange={(e) => {
                          const updated = { ...tempDNA, [field.id]: e.target.value };
                          setTempDNA(updated);
                          pushToUndo(updated);
                        }}
                        rows={3}
                        className="w-full bg-white/5 border border-white/10 rounded-xl p-4 text-sm text-neutral-200 outline-none focus:ring-1 focus:ring-amber-500"
                      />
                    </div>
                  ))}
                </div>

                <div className="space-y-8">
                   <div className="space-y-3 group">
                    <div className="flex justify-between items-center">
                      <label className="flex items-center gap-2 text-[10px] font-bold text-neutral-500 uppercase tracking-widest"><BookOpen className="w-3 h-3" /> 敘事摘要</label>
                      <button onClick={() => handlePolish('story', '敘事摘要')} className="flex items-center gap-1.5 text-[9px] bg-amber-600/10 hover:bg-amber-600 text-amber-500 hover:text-white px-2 py-1 rounded-md opacity-0 group-hover:opacity-100 transition-all"><Wand2 className="w-3 h-3" /> AI 潤色</button>
                    </div>
                    <textarea 
                      value={tempDNA.story}
                      onChange={(e) => {
                        const updated = { ...tempDNA, story: e.target.value };
                        setTempDNA(updated);
                        pushToUndo(updated);
                      }}
                      rows={10}
                      className="w-full bg-white/5 border border-white/10 rounded-2xl p-6 text-sm focus:ring-1 focus:ring-amber-500 outline-none leading-relaxed font-serif text-neutral-300"
                    />
                  </div>
                </div>
              </div>

              <footer className="p-8 border-t border-white/5 bg-white/5 flex gap-6">
                <button onClick={confirmConfig} disabled={isLoading} className="flex-1 py-5 rounded-2xl bg-amber-600 hover:bg-amber-500 text-sm font-bold flex items-center justify-center gap-4 shadow-xl disabled:opacity-50">
                  {isLoading ? <Loader2 className="w-6 h-6 animate-spin" /> : <><CheckCircle2 className="w-6 h-6" /> 確認 AI 設計並生成核心場景</>}
                </button>
              </footer>
            </div>
          </div>
        )}

        {showHistory && (
          <div className="fixed inset-0 bg-black/95 backdrop-blur-3xl z-[60] p-12 overflow-y-auto">
             <div className="max-w-5xl mx-auto space-y-16 pb-24">
                <div className="flex justify-between items-center border-b border-white/10 pb-8">
                   <h2 className="text-4xl font-serif tracking-widest">項目檔案庫</h2>
                   <button onClick={() => setShowHistory(false)} className="p-4 bg-white/5 rounded-full hover:bg-amber-600"><X className="w-8 h-8" /></button>
                </div>

                {project.coreSceneImage && (
                  <div className="space-y-6">
                    <h3 className="text-xs font-bold text-amber-500 uppercase tracking-[0.4em] flex items-center gap-2"><Eye className="w-4 h-4" /> 核心視覺定義</h3>
                    <div className="aspect-[21/9] rounded-3xl overflow-hidden border border-white/10 shadow-2xl">
                       <img src={project.coreSceneImage} className="w-full h-full object-cover" />
                    </div>
                  </div>
                )}

                <div className="grid grid-cols-1 md:grid-cols-2 gap-12">
                   <div className="space-y-6">
                      <h3 className="text-amber-500 text-xs font-bold uppercase tracking-widest">當前 DNA</h3>
                      <div className="glass p-8 rounded-3xl space-y-4">
                         {Object.entries(project.dna).filter(([k]) => k !== 'story').map(([k, v]) => (
                           <div key={k} className="flex justify-between border-b border-white/5 pb-2">
                             <span className="text-neutral-500 text-xs capitalize">{k}</span>
                             <span className="text-xs text-neutral-200">{v}</span>
                           </div>
                         ))}
                      </div>
                   </div>
                   <div className="space-y-6">
                      <h3 className="text-amber-500 text-xs font-bold uppercase tracking-widest">劇本核心</h3>
                      <div className="glass p-8 rounded-3xl">
                        <p className="text-sm text-neutral-400 leading-relaxed italic">{project.dna.story}</p>
                      </div>
                   </div>
                </div>
             </div>
          </div>
        )}
      </main>

      {/* 右側資訊面板：展示核心場景與九宮格 */}
      <aside className="w-80 border-l border-white/5 bg-black/40 p-6 flex flex-col gap-8 overflow-y-auto">
        <div className="space-y-6">
          <h3 className="text-[10px] font-bold text-neutral-500 uppercase tracking-widest">視覺檔案 (Asset)</h3>
          {project.coreSceneImage ? (
            <div className="space-y-6 animate-in fade-in duration-700">
              <div className="aspect-video rounded-2xl overflow-hidden border border-white/10 shadow-lg group relative">
                <img src={project.coreSceneImage} className="w-full h-full object-cover" />
                <div className="absolute inset-0 bg-black/60 opacity-0 group-hover:opacity-100 transition-opacity flex items-center justify-center p-4">
                  <p className="text-[10px] text-center italic leading-relaxed text-amber-500">「這是本片的視覺基調」</p>
                </div>
              </div>

              {project.sceneGrid.length > 0 && (
                <div className="grid grid-cols-3 gap-2">
                  {project.sceneGrid.slice(0, 9).map((img, i) => (
                    <div key={i} className="aspect-square rounded-lg overflow-hidden border border-white/5 opacity-60 hover:opacity-100 transition-opacity">
                      <img src={img} className="w-full h-full object-cover" />
                    </div>
                  ))}
                </div>
              )}
            </div>
          ) : (
            <div className="py-12 border border-dashed border-white/10 rounded-3xl text-center opacity-30">
              <Eye className="w-8 h-8 mx-auto mb-3 text-neutral-700" />
              <p className="text-[10px] uppercase tracking-widest">等待視覺生成</p>
            </div>
          )}
        </div>

        <div className="mt-auto pt-6 border-t border-white/5">
           <div className="flex items-center justify-between text-[10px] text-neutral-600 mb-2 font-mono">
              <span>PROJECT QUALITY</span>
              <span className="text-amber-600">MASTER GRADE</span>
           </div>
           <div className="h-1 bg-white/5 rounded-full overflow-hidden">
              <div className="h-full bg-amber-600/50 w-full animate-pulse"></div>
           </div>
        </div>
      </aside>
    </div>
  );
};

export default App;

import React, { useState, useEffect, useCallback, useRef } from 'react';
import { ProductionPhase, Suggestion, ProjectState, GeneratedVideo, Message, ProjectDNA } from './types';
