                          pushToUndo(updated);
                        }}
                        rows={3}
                        className="w-full bg-white/5 border border-white/10 rounded-xl p-4 text-sm text-neutral-200 outline-none focus:ring-1 focus:ring-amber-500"
                      />
                    </div>
                  ))}
                </div>

                <div className="space-y-8">
                   <div className="space-y-3 group">
                    <div className="flex justify-between items-center">
                      <label className="flex items-center gap-2 text-[10px] font-bold text-neutral-500 uppercase tracking-widest"><BookOpen className="w-3 h-3" /> 敘事摘要</label>
                      <button onClick={() => handlePolish('story', '敘事摘要')} className="flex items-center gap-1.5 text-[9px] bg-amber-600/10 hover:bg-amber-600 text-amber-500 hover:text-white px-2 py-1 rounded-md opacity-0 group-hover:opacity-100 transition-all"><Wand2 className="w-3 h-3" /> AI 潤色</button>
                    </div>
                    <textarea 
                      value={tempDNA.story || ''}
                      onChange={(e) => {
                        const updated = { ...tempDNA, story: e.target.value };
                        setTempDNA(updated);
                        pushToUndo(updated);
                      }}
                      rows={10}
                      className="w-full bg-white/5 border border-white/10 rounded-2xl p-6 text-sm focus:ring-1 focus:ring-amber-500 outline-none leading-relaxed font-serif text-neutral-300"
                    />
                  </div>
                </div>
              </div>

              <footer className="p-8 border-t border-white/5 bg-white/5 flex gap-6">
                <button onClick={confirmConfig} disabled={isLoading} className="flex-1 py-5 rounded-2xl bg-amber-600 hover:bg-amber-500 text-sm font-bold flex items-center justify-center gap-4 shadow-xl disabled:opacity-50">
                  {isLoading ? <Loader2 className="w-6 h-6 animate-spin" /> : <><CheckCircle2 className="w-6 h-6" /> 確認 AI 設計並生成核心場景</>}
                </button>
              </footer>
            </div>
          </div>
