                       <img src={project.coreSceneImage} className="w-full h-full object-cover" />
                    </div>
                  </div>
                )}

                <div className="grid grid-cols-1 md:grid-cols-2 gap-12">
                   <div className="space-y-6">
                      <h3 className="text-amber-500 text-xs font-bold uppercase tracking-widest">當前 DNA</h3>
                      <div className="glass p-8 rounded-3xl space-y-4">
                         {Object.entries(project.dna || {}).filter(([k]) => k !== 'story').map(([k, v]) => (
                           <div key={k} className="flex justify-between border-b border-white/5 pb-2">
                             <span className="text-neutral-500 text-xs capitalize">{k}</span>
                             <span className="text-xs text-neutral-200">{String(v || '未定')}</span>
