import React, { useState, useEffect, useCallback, useRef } from 'react';
import { ProductionPhase, Suggestion, ProjectState, GeneratedVideo, Message, ProjectDNA, SceneDesign } from './types';
import { PHASE_METADATA } from './constants';
import { GeminiService } from './services/geminiService';
import { ApiKeySelector } from './components/ApiKeySelector';
import { 
  Film, Sparkles, Send, Loader2, ArrowRight, 
  Info, Clapperboard, Video, Layout, Palette, 
  ChevronRight, History, Save, Download, Upload,
  X, CheckCircle2, Monitor, BookOpen, Layers, Terminal, MapPin, Users, Target, Lightbulb,
  Undo2, Redo2, Wand2, Eye, Grid, Edit3, Image as ImageIcon
} from 'lucide-react';

const App: React.FC = () => {
  const [hasKey, setHasKey] = useState(false);
  const [isLoading, setIsLoading] = useState(false);
  const [isAnalyzing, setIsAnalyzing] = useState(false);
  const [input, setInput] = useState('');
  const [hoveredSuggestion, setHoveredSuggestion] = useState<Suggestion | null>(null);
  const [selectedSuggestion, setSelectedSuggestion] = useState<Suggestion | null>(null);
  const [showConfig, setShowConfig] = useState(false);
  const [showHistory, setShowHistory] = useState(false);
  const [activeStep, setActiveStep] = useState<ProductionPhase>(ProductionPhase.PRE_PRODUCTION);

  const [historyStack, setHistoryStack] = useState<ProjectDNA[]>([]);
  const [redoStack, setRedoStack] = useState<ProjectDNA[]>([]);

  // Scene History for Visual Dev
  const [sceneHistoryStack, setSceneHistoryStack] = useState<SceneDesign[][]>([]);
  const [sceneRedoStack, setSceneRedoStack] = useState<SceneDesign[][]>([]);

  const [tempDNA, setTempDNA] = useState<ProjectDNA>({
    format: '電影', style: '寫實電影感 (Realistic Cinematic)', story: '', ratio: '16:9',
    environment: '', socialBackground: '', coreSetting: ''
  });

  const [project, setProject] = useState<ProjectState>({
    currentPhase: ProductionPhase.PRE_PRODUCTION,
    initialInput: '',
    dna: { format: '', style: '', story: '', ratio: '16:9', environment: '', socialBackground: '', coreSetting: '' },
    suggestions: [], proposedScenes: [], history: [], generatedVideos: [], sceneGrid: []
  });

  const fileInputRef = useRef<HTMLInputElement>(null);
  const geminiRef = useRef<GeminiService | null>(null);

  useEffect(() => {
    const checkKey = async () => {
      // @ts-ignore
      const exists = await window.aistudio.hasSelectedApiKey();
      if (exists) {
        setHasKey(true);
        geminiRef.current = new GeminiService(process.env.API_KEY || '');
      }
    };
    checkKey();
  }, []);

  useEffect(() => {
    if (activeStep === ProductionPhase.VISUAL_DEV && project.proposedScenes.length === 0 && !isAnalyzing && geminiRef.current) {
      handleAnalyzeScenes();
    }
  }, [activeStep, project.proposedScenes.length]);

  const handleAnalyzeScenes = async () => {
    if (!geminiRef.current) return;
    setIsAnalyzing(true);
    try {
      const scenes = await geminiRef.current.analyzeScenes(project.dna);
      setProject(prev => ({ ...prev, proposedScenes: scenes }));
      setSceneHistoryStack([scenes]);
      setSceneRedoStack([]);
    } catch (err) {
      console.error(err);
    } finally {
      setIsAnalyzing(false);
    }
  };

  const pushToSceneUndo = (newScenes: SceneDesign[]) => {
    setSceneHistoryStack(prev => [...prev, newScenes]);
    setSceneRedoStack([]);
  };

  const handleUndoScene = () => {
    if (sceneHistoryStack.length <= 1) return;
    const current = sceneHistoryStack[sceneHistoryStack.length - 1];
    const prev = sceneHistoryStack[sceneHistoryStack.length - 2];
    setSceneRedoStack(r => [current, ...r]);
    setSceneHistoryStack(h => h.slice(0, -1));
    setProject(p => ({ ...p, proposedScenes: prev }));
  };

  const handleRedoScene = () => {
    if (sceneRedoStack.length === 0) return;
    const next = sceneRedoStack[0];
    setSceneRedoStack(r => r.slice(1));
    setSceneHistoryStack(h => [...h, next]);
    setProject(p => ({ ...p, proposedScenes: next }));
  };

  const handleRenderGrid = async () => {
    if (!geminiRef.current || project.proposedScenes.length === 0) return;
    setIsLoading(true);
    try {
      const grid = await geminiRef.current.generateSceneGrid(project.dna.story, project.proposedScenes);
      setProject(prev => ({ ...prev, sceneGrid: grid }));
    } catch (err) {
      console.error(err);
    } finally {
      setIsLoading(false);
    }
  };

  const updateScene = (idx: number, field: keyof SceneDesign, value: string) => {
    const newScenes = [...project.proposedScenes];
    newScenes[idx] = { ...newScenes[idx], [field]: value };
    setProject(prev => ({ ...prev, proposedScenes: newScenes }));
    // We only push to undo stack after some delay or on blur to avoid excessive snapshots
    // But for simplicity here, we'll push when needed. 
  };

  // Dedicated push function for input changes (manual edits)
  const finalizeSceneUpdate = () => {
    pushToSceneUndo(project.proposedScenes);
  };

  const handlePolishScene = async (idx: number) => {
    if (!geminiRef.current || isLoading) return;
    setIsLoading(true);
    try {
      const scene = project.proposedScenes[idx];
      const polished = await geminiRef.current.polishText(scene.visualDescription, `場景視覺設計：${scene.title}`);
      const newScenes = [...project.proposedScenes];
      newScenes[idx] = { ...scene, visualDescription: polished };
      setProject(prev => ({ ...prev, proposedScenes: newScenes }));
      pushToSceneUndo(newScenes);
    } finally {
      setIsLoading(false);
    }
  };

  const saveProject = () => {
    const data = JSON.stringify(project, null, 2);
    const blob = new Blob([data], { type: 'application/json' });
    const url = URL.createObjectURL(blob);
    const link = document.createElement('a');
    link.href = url;
    link.download = `montage-project-${new Date().toISOString().slice(0, 10)}.json`;
    link.click();
    URL.revokeObjectURL(url);
  };

  const loadProject = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;
    const reader = new FileReader();
    reader.onload = (event) => {
      try {
        const data = JSON.parse(event.target?.result as string) as ProjectState;
        if (data.currentPhase && data.dna) {
          setProject({
            ...data,
            suggestions: data.suggestions || [],
            proposedScenes: data.proposedScenes || [],
            history: data.history || [],
            generatedVideos: data.generatedVideos || [],
            sceneGrid: data.sceneGrid || []
          });
          setActiveStep(data.currentPhase);
          if (data.currentPhase === ProductionPhase.PRE_PRODUCTION) {
            setInput(data.initialInput || '');
          }
        }
      } catch (err) {
        alert('檔案格式錯誤，請確保上傳正確的專案檔。');
      }
    };
    reader.readAsText(file);
    if (fileInputRef.current) fileInputRef.current.value = '';
  };

  const handleStepSwitch = (phase: ProductionPhase) => {
    setActiveStep(phase);
    if (phase === ProductionPhase.PRE_PRODUCTION) {
      setInput(project.initialInput || '');
    } else {
      const lastUserMsgForPhase = [...project.history].reverse().find(m => m.role === 'user' && m.phase === phase);
      if (lastUserMsgForPhase) {
        setInput(lastUserMsgForPhase.content);
      } else {
        setInput('');
      }
    }
    setProject(prev => ({ ...prev, suggestions: [] }));
  };

  const handleSubmitIdea = async (e?: React.FormEvent) => {
    if (e) e.preventDefault();
    if (!input.trim() || isLoading || !geminiRef.current) return;

    setIsLoading(true);
    try {
      const results = await geminiRef.current.generateSuggestions(input, activeStep, JSON.stringify(project.dna));
      setProject(prev => ({ 
        ...prev, 
        suggestions: results || [], 
        initialInput: activeStep === ProductionPhase.PRE_PRODUCTION ? input : prev.initialInput,
        history: [...(prev.history || []), { role: 'user', content: input, phase: activeStep }]
      }));
    } catch (error) { 
      console.error(error); 
    } finally { 
      setIsLoading(false); 
    }
  };

  const handleSuggestionClick = (s: Suggestion) => {
    setSelectedSuggestion(s);
    const inferredDNA = {
      ...project.dna,
      format: s.tags?.includes('廣告') ? '商業廣告' : s.tags?.includes('動畫') ? '動畫短片' : '電影短片',
      story: s.description,
      environment: s.environment || project.dna.environment,
      socialBackground: s.socialBackground || project.dna.socialBackground,
      coreSetting: s.coreSetting || project.dna.coreSetting,
    };
    setTempDNA(inferredDNA);
    setHistoryStack([inferredDNA]);
    setRedoStack([]);
    setShowConfig(true);
  };

  const pushToUndo = (newDNA: ProjectDNA) => {
    setHistoryStack(prev => [...prev, newDNA]);
    setRedoStack([]);
  };

  const handleUndo = () => {
    if (historyStack.length <= 1) return;
    const current = historyStack[historyStack.length - 1];
    const prev = historyStack[historyStack.length - 2];
    setRedoStack(r => [current, ...r]);
    setHistoryStack(h => h.slice(0, -1));
    setTempDNA(prev);
  };

  const handleRedo = () => {
    if (redoStack.length === 0) return;
    const next = redoStack[0];
    setRedoStack(r => r.slice(1));
    setHistoryStack(h => [...h, next]);
    setTempDNA(next);
  };

  const handlePolish = async (field: keyof ProjectDNA, type: string) => {
    if (!geminiRef.current || isLoading) return;
    setIsLoading(true);
    try {
      const polished = await geminiRef.current.polishText(tempDNA[field] as string, type);
      const updated = { ...tempDNA, [field]: polished };
      setTempDNA(updated);
      pushToUndo(updated);
    } finally { 
      setIsLoading(false); 
    }
  };

  const confirmConfig = async () => {
    if (!selectedSuggestion || !geminiRef.current) return;
    setIsLoading(true);

    try {
      let coreImage = project.coreSceneImage;
      if (activeStep === ProductionPhase.PRE_PRODUCTION) {
        coreImage = await geminiRef.current.generateImage(`${tempDNA.story}. ${tempDNA.style}. Cinematic, 8k.`) || undefined;
      }

      const nextPhases = Object.values(ProductionPhase);
      const currentIndex = nextPhases.indexOf(activeStep);
      const nextPhase = currentIndex < nextPhases.length - 1 ? nextPhases[currentIndex + 1] : activeStep;

      setProject(prev => ({
        ...prev,
        currentPhase: nextPhase,
        dna: { ...tempDNA },
        suggestions: [],
        history: [...(prev.history || []), { 
          role: 'assistant', 
          content: `【確認階段：${PHASE_METADATA[activeStep].title}】\n已確認 DNA 並推進至下一階段。`, 
          phase: activeStep 
        }],
        coreSceneImage: coreImage
      }));

      setActiveStep(nextPhase);
      setShowConfig(false);
      setSelectedSuggestion(null);
      setInput('');
    } catch (error) {
      console.error(error);
    } finally { 
      setIsLoading(false); 
    }
  };

  if (!hasKey) return <ApiKeySelector onSelected={() => { setHasKey(true); geminiRef.current = new GeminiService(process.env.API_KEY || ''); }} />;

  return (
    <div className="flex h-screen bg-[#050505] text-white overflow-hidden font-sans">
      <aside className="w-64 border-r border-white/5 flex flex-col bg-black/40 p-6">
        <div className="flex items-center gap-3 mb-12">
          <div className="bg-amber-600 p-2 rounded-lg shadow-[0_0_15px_rgba(217,119,6,0.3)]"><Film className="w-6 h-6 text-white" /></div>
          <h1 className="text-lg font-serif font-bold tracking-widest text-white/90">電影蒙太奇</h1>
        </div>

        <nav className="flex-1 space-y-2">
          {Object.entries(PHASE_METADATA).map(([key, meta], idx) => {
            const phaseKey = key as ProductionPhase;
            const isActive = activeStep === phaseKey;
            const isAccessible = Object.values(ProductionPhase).indexOf(phaseKey) <= Object.values(ProductionPhase).indexOf(project.currentPhase);

            return (
              <button 
                key={key} 
                disabled={!isAccessible}
                onClick={() => handleStepSwitch(phaseKey)}
                className={`w-full relative flex items-center gap-4 p-3 rounded-lg transition-all text-left group
                  ${isActive ? 'bg-amber-600/20 text-amber-500 ring-1 ring-amber-600/30' : 'text-neutral-600 hover:text-neutral-400'}
                  ${!isAccessible ? 'opacity-30 grayscale cursor-not-allowed' : 'cursor-pointer'}
                `}
              >
                {isActive && <div className="absolute left-0 w-1 h-6 bg-amber-600 rounded-full" />}
                <span className="text-xl">{meta.icon}</span>
                <div className="flex flex-col">
                  <span className="text-[9px] uppercase tracking-tighter opacity-50">Step 0{idx+1}</span>
                  <span className="text-sm font-bold">{meta.title}</span>
                </div>
              </button>
            );
          })}
        </nav>

        <div className="mt-8 space-y-2 border-t border-white/5 pt-6">
          <button onClick={() => setShowHistory(true)} className="w-full flex items-center gap-3 px-3 py-2 text-xs text-neutral-400 hover:text-white transition-colors group">
            <History className="w-4 h-4 text-amber-600 group-hover:rotate-[-45deg] transition-transform" />
            <span>製作歷史</span>
          </button>
          <button onClick={saveProject} className="w-full flex items-center gap-3 px-3 py-2 text-xs text-neutral-400 hover:text-white transition-colors"><Download className="w-4 h-4" /> 匯出專案</button>
          <button onClick={() => fileInputRef.current?.click()} className="w-full flex items-center gap-3 px-3 py-2 text-xs text-neutral-400 hover:text-white transition-colors"><Upload className="w-4 h-4" /> 載入專案</button>
          <input type="file" ref={fileInputRef} onChange={loadProject} className="hidden" accept=".json" />
        </div>
      </aside>

      <main className="flex-1 flex flex-col relative overflow-hidden">
        <header className="h-16 px-8 border-b border-white/5 flex items-center justify-between z-10 bg-black/50 backdrop-blur-md">
          <div className="flex items-center gap-2">
            <Terminal className="w-4 h-4 text-amber-600" />
            <span className="text-[10px] text-neutral-500 uppercase tracking-[0.2em]">TERMINAL</span>
            <ChevronRight className="w-3 h-3 text-neutral-600" />
            <span className="text-sm font-bold text-amber-500 uppercase">{PHASE_METADATA[activeStep]?.title}</span>
          </div>
          <div className="flex items-center gap-4">
            {activeStep === ProductionPhase.VISUAL_DEV && project.proposedScenes.length > 0 && (
              <>
                <div className="flex items-center gap-2 mr-4 bg-white/5 p-1 rounded-full px-2 border border-white/5">
                  <button 
                    onClick={handleUndoScene} 
                    disabled={sceneHistoryStack.length <= 1}
                    className="p-2 hover:bg-amber-600 rounded-full disabled:opacity-20 transition-all"
                    title="復原"
                  >
                    <Undo2 className="w-3.5 h-3.5" />
                  </button>
                  <button 
                    onClick={handleRedoScene} 
                    disabled={sceneRedoStack.length === 0}
                    className="p-2 hover:bg-amber-600 rounded-full disabled:opacity-20 transition-all"
                    title="重做"
                  >
                    <Redo2 className="w-3.5 h-3.5" />
                  </button>
                </div>
                <button 
                  onClick={handleRenderGrid} 
                  disabled={isLoading}
                  className="bg-amber-600 hover:bg-amber-500 px-4 py-2 rounded-full text-[11px] font-bold flex items-center gap-2 shadow-lg transition-all"
                >
                  {isLoading ? <Loader2 className="w-3.5 h-3.5 animate-spin" /> : <ImageIcon className="w-3.5 h-3.5" />}
                  渲染視覺九宮格
                </button>
              </>
            )}
          </div>
        </header>

        <section className="flex-1 flex flex-col items-center justify-start p-8 max-w-5xl mx-auto w-full overflow-y-auto">
          {project.initialInput && activeStep === ProductionPhase.PRE_PRODUCTION && (
            <div className="mb-8 flex items-center gap-3 px-5 py-2.5 bg-amber-900/10 border border-amber-600/20 rounded-full">
              <Lightbulb className="w-3.5 h-3.5 text-amber-500" />
              <span className="text-[10px] text-amber-500 font-bold tracking-widest">初心：</span>
              <span className="text-[11px] text-neutral-300 italic truncate max-w-[400px]">"{project.initialInput}"</span>
            </div>
          )}

          {activeStep === ProductionPhase.VISUAL_DEV ? (
            <div className="w-full space-y-12 animate-in fade-in slide-in-from-top-4 duration-700 pb-20">
              <div className="text-center space-y-4">
                <h2 className="text-3xl font-serif leading-relaxed text-neutral-100">{PHASE_METADATA[activeStep]?.guide}</h2>
                <p className="text-sm text-neutral-500 max-w-xl mx-auto">AI 已自動為您拆解關鍵場景，您可以微調視覺描述，然後一鍵生成視覺概念圖。</p>
              </div>

              {isAnalyzing ? (
                <div className="py-20 flex flex-col items-center gap-6">
                  <div className="relative">
                    <Loader2 className="w-12 h-12 text-amber-600 animate-spin" />
                    <Sparkles className="absolute -top-2 -right-2 w-6 h-6 text-amber-400 animate-pulse" />
                  </div>
                  <p className="text-amber-500 text-xs font-bold uppercase tracking-[0.3em]">AI 正在深度分析劇本 DNA 並設計場景視覺...</p>
                </div>
              ) : (
                <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
                  {project.proposedScenes.map((scene, idx) => (
                    <div key={idx} className="glass p-6 rounded-2xl border-white/5 hover:border-amber-600/30 transition-all group flex flex-col">
                      <div className="flex items-center justify-between mb-4">
                        <span className="text-[10px] font-bold text-amber-600/70 uppercase font-mono">SCENE 0{idx+1}</span>
                        <div className="flex items-center gap-2">
                           <button 
                             onClick={() => handlePolishScene(idx)}
                             disabled={isLoading}
                             className="flex items-center gap-1 text-[9px] bg-amber-600/10 hover:bg-amber-600 text-amber-500 hover:text-white px-2 py-1 rounded transition-all opacity-0 group-hover:opacity-100"
                           >
                             <Wand2 className="w-3 h-3" /> AI 潤色
                           </button>
                           <Edit3 className="w-3.5 h-3.5 text-neutral-600" />
                        </div>
                      </div>
                      <input 
                        className="bg-transparent border-none text-neutral-100 font-serif font-bold text-lg mb-2 focus:ring-0 w-full"
                        value={scene.title}
                        onChange={(e) => updateScene(idx, 'title', e.target.value)}
                        onBlur={finalizeSceneUpdate}
                        placeholder="場景標題"
                      />
                      <textarea 
                        className="w-full bg-white/5 border border-white/5 rounded-xl p-3 text-[11px] text-neutral-400 focus:text-neutral-200 outline-none focus:ring-1 focus:ring-amber-500/50 resize-none leading-relaxed flex-1"
                        rows={6}
                        value={scene.visualDescription}
                        onChange={(e) => updateScene(idx, 'visualDescription', e.target.value)}
                        onBlur={finalizeSceneUpdate}
                        placeholder="視覺設計細節..."
                      />
                    </div>
                  ))}
                </div>
              )}

              {project.sceneGrid.length > 0 && (
                <div className="space-y-6 pt-12 border-t border-white/5 animate-in fade-in zoom-in-95">
                  <h3 className="text-xs font-bold text-amber-500 uppercase tracking-[0.4em] flex items-center gap-3">
                    <Grid className="w-4 h-4" /> 視覺開發九宮格成果
                  </h3>
                  <div className="grid grid-cols-3 gap-3">
                    {project.sceneGrid.map((img, i) => (
                      <div key={i} className="aspect-video rounded-xl overflow-hidden border border-white/5 hover:scale-105 transition-transform cursor-zoom-in group relative">
                        <img src={img} className="w-full h-full object-cover" />
                        <div className="absolute inset-0 bg-black/40 opacity-0 group-hover:opacity-100 transition-opacity p-4 flex items-end">
                           <span className="text-[9px] text-white/80 font-mono">SHOT_{i+1}</span>
                        </div>
                      </div>
                    ))}
                  </div>
                </div>
              )}
            </div>
          ) : (
            <div className="w-full max-w-2xl mb-12 py-12">
              <div className="flex flex-col items-center text-center space-y-4 mb-8">
                <h2 className="text-xl md:text-2xl font-serif leading-relaxed text-neutral-100 whitespace-nowrap">{PHASE_METADATA[activeStep]?.guide}</h2>
              </div>

              <form onSubmit={handleSubmitIdea} className="relative group">
                <input 
                  type="text" value={input} onChange={(e) => setInput(e.target.value)}
                  placeholder="在此輸入您的創意指令..."
                  className="w-full bg-white/5 border border-white/10 p-5 pr-16 rounded-2xl focus:outline-none focus:ring-2 focus:ring-amber-600/50 text-lg shadow-2xl transition-all"
                />
                <button 
                  type="submit" disabled={isLoading || !input.trim()}
                  className="absolute right-3 top-3 bg-amber-600 hover:bg-amber-500 p-3 rounded-xl transition-all shadow-lg"
                >
                  {isLoading ? <Loader2 className="w-6 h-6 animate-spin" /> : <Sparkles className="w-6 h-6" />}
                </button>
              </form>
            </div>
          )}

          {activeStep !== ProductionPhase.VISUAL_DEV && (project.suggestions?.length || 0) > 0 && (
            <div className="w-full grid grid-cols-1 md:grid-cols-3 gap-6 mb-12 animate-in fade-in slide-in-from-bottom-8">
              {project.suggestions.map((s, i) => (
                <button
                  key={i} onMouseEnter={() => setHoveredSuggestion(s)} onClick={() => handleSuggestionClick(s)}
                  className="btn-montage glass p-8 rounded-2xl text-center border-white/5 hover:border-amber-600/50 group"
                >
                  <div className="text-[10px] text-amber-500 font-bold mb-4 opacity-0 group-hover:opacity-100 uppercase tracking-widest">提案 Proposal {i+1}</div>
                  <h3 className="text-lg font-serif font-bold mb-4 line-clamp-2 h-14 flex items-center justify-center">{s.title}</h3>
                  <div className="flex flex-wrap justify-center gap-1.5 mt-2">
                    {s.tags?.map(t => <span key={t} className="text-[9px] bg-amber-900/30 px-2 py-0.5 rounded text-amber-200/60 border border-amber-600/10">#{t}</span>)}
                  </div>
                </button>
              ))}
            </div>
          )}
        </section>

        {showConfig && (
          <div className="fixed inset-0 bg-black/95 backdrop-blur-md flex items-center justify-center z-50 p-6 overflow-y-auto">
            <div className="glass w-full max-w-5xl rounded-3xl overflow-hidden border border-amber-600/20 flex flex-col max-h-[90vh]">
              <header className="p-8 border-b border-white/5 flex justify-between items-center bg-white/5">
                <div>
                  <h3 className="text-2xl font-serif font-bold tracking-wide">AI 導演企劃書</h3>
                  <div className="flex gap-4 mt-3">
                    <button onClick={handleUndo} disabled={historyStack.length <= 1} className="p-2 bg-white/5 rounded-lg hover:bg-amber-600 disabled:opacity-20 transition-all"><Undo2 className="w-4 h-4" /></button>
                    <button onClick={handleRedo} disabled={redoStack.length === 0} className="p-2 bg-white/5 rounded-lg hover:bg-amber-600 disabled:opacity-20 transition-all"><Redo2 className="w-4 h-4" /></button>
                  </div>
                </div>
                <button onClick={() => setShowConfig(false)} className="text-neutral-500 hover:text-white transition-colors"><X className="w-8 h-8" /></button>
              </header>

              <div className="p-10 grid grid-cols-1 lg:grid-cols-2 gap-12 overflow-y-auto">
                <div className="space-y-8">
                  {[
                    { id: 'coreSetting', label: '核心設定', icon: <Target className="w-3 h-3" /> },
                    { id: 'socialBackground', label: '社會背景', icon: <Users className="w-3 h-3" /> },
                    { id: 'environment', label: '地理環境', icon: <MapPin className="w-3 h-3" /> }
                  ].map(field => (
                    <div key={field.id} className="group relative">
                      <div className="flex justify-between items-center mb-3">
                        <label className="flex items-center gap-2 text-[10px] font-bold text-neutral-500 uppercase tracking-widest">
                          {field.icon} {field.label}
                        </label>
                        <button 
                          onClick={() => handlePolish(field.id as keyof ProjectDNA, field.label)}
                          className="flex items-center gap-1.5 text-[9px] bg-amber-600/10 hover:bg-amber-600 text-amber-500 hover:text-white px-2 py-1 rounded-md transition-all opacity-0 group-hover:opacity-100"
                        >
                          <Wand2 className="w-3 h-3" /> AI 潤色
                        </button>
                      </div>
                      <textarea 
                        value={tempDNA[field.id as keyof ProjectDNA] || ''}
                        onChange={(e) => {
                          const updated = { ...tempDNA, [field.id]: e.target.value };
                          setTempDNA(updated);
                          pushToUndo(updated);
                        }}
                        rows={3}
                        className="w-full bg-white/5 border border-white/10 rounded-xl p-4 text-sm text-neutral-200 outline-none focus:ring-1 focus:ring-amber-500 transition-all"
                      />
                    </div>
                  ))}
                </div>

                <div className="space-y-8">
                   <div className="space-y-3 group">
                    <div className="flex justify-between items-center">
                      <label className="flex items-center gap-2 text-[10px] font-bold text-neutral-500 uppercase tracking-widest"><BookOpen className="w-3 h-3" /> 敘事摘要</label>
                      <button onClick={() => handlePolish('story', '敘事摘要')} className="flex items-center gap-1.5 text-[9px] bg-amber-600/10 hover:bg-amber-600 text-amber-500 hover:text-white px-2 py-1 rounded-md opacity-0 group-hover:opacity-100 transition-all"><Wand2 className="w-3 h-3" /> AI 潤色</button>
                    </div>
                    <textarea 
                      value={tempDNA.story || ''}
                      onChange={(e) => {
                        const updated = { ...tempDNA, story: e.target.value };
                        setTempDNA(updated);
                        pushToUndo(updated);
                      }}
                      rows={10}
                      className="w-full bg-white/5 border border-white/10 rounded-2xl p-6 text-sm focus:ring-1 focus:ring-amber-500 outline-none leading-relaxed font-serif text-neutral-300 transition-all"
                    />
                  </div>
                </div>
              </div>

              <footer className="p-8 border-t border-white/5 bg-white/5 flex gap-6">
                <button onClick={confirmConfig} disabled={isLoading} className="flex-1 py-5 rounded-2xl bg-amber-600 hover:bg-amber-500 text-sm font-bold flex items-center justify-center gap-4 shadow-xl disabled:opacity-50 transition-all">
                  {isLoading ? <Loader2 className="w-6 h-6 animate-spin" /> : <><CheckCircle2 className="w-6 h-6" /> 確認 AI 設計並展開製作</>}
                </button>
              </footer>
            </div>
          </div>
        )}

        {showHistory && (
          <div className="fixed inset-0 bg-black/95 backdrop-blur-3xl z-[60] p-12 overflow-y-auto">
             <div className="max-w-5xl mx-auto space-y-16 pb-24">
                <div className="flex justify-between items-center border-b border-white/10 pb-8">
                   <h2 className="text-4xl font-serif tracking-widest">項目檔案庫</h2>
                   <button onClick={() => setShowHistory(false)} className="p-4 bg-white/5 rounded-full hover:bg-amber-600 transition-colors"><X className="w-8 h-8" /></button>
                </div>

                {project.coreSceneImage && (
                  <div className="space-y-6">
                    <h3 className="text-xs font-bold text-amber-500 uppercase tracking-[0.4em] flex items-center gap-2"><Eye className="w-4 h-4" /> 核心視覺定義</h3>
                    <div className="aspect-[21/9] rounded-3xl overflow-hidden border border-white/10 shadow-2xl">
                       <img src={project.coreSceneImage} className="w-full h-full object-cover" />
                    </div>
                  </div>
                )}

                <div className="grid grid-cols-1 md:grid-cols-2 gap-12">
                   <div className="space-y-6">
                      <h3 className="text-amber-500 text-xs font-bold uppercase tracking-widest">當前 DNA</h3>
                      <div className="glass p-8 rounded-3xl space-y-4">
                         {Object.entries(project.dna || {}).filter(([k]) => k !== 'story').map(([k, v]) => (
                           <div key={k} className="flex justify-between border-b border-white/5 pb-2">
                             <span className="text-neutral-500 text-xs capitalize">{k}</span>
                             <span className="text-xs text-neutral-200">{String(v || '未定')}</span>
                           </div>
                         ))}
                      </div>
                   </div>
                   <div className="space-y-6">
                      <h3 className="text-amber-500 text-xs font-bold uppercase tracking-widest">劇本核心</h3>
                      <div className="glass p-8 rounded-3xl">
                        <p className="text-sm text-neutral-400 leading-relaxed italic">{project.dna?.story || '尚無內容'}</p>
                      </div>
                   </div>
                </div>

                <div className="space-y-6">
                  <h3 className="text-xs font-bold text-amber-500 uppercase tracking-widest">操作歷史</h3>
                  <div className="space-y-4">
                    {(project.history || []).map((msg, idx) => (
                      <div key={idx} className={`p-4 rounded-xl border text-sm ${msg.role === 'user' ? 'bg-amber-600/5 border-amber-600/20' : 'bg-white/5 border-white/10'}`}>
                        <div className={`text-[10px] mb-1 font-mono ${msg.role === 'user' ? 'text-amber-500' : 'text-neutral-500'}`}>
                          {msg.role.toUpperCase()} | {msg.phase ? PHASE_METADATA[msg.phase]?.title : 'SYSTEM'}
                        </div>
                        <div className="text-neutral-300">{msg.content}</div>
                      </div>
                    ))}
                  </div>
                </div>
             </div>
          </div>
        )}
      </main>

      <aside className="w-80 border-l border-white/5 bg-black/40 p-6 flex flex-col gap-8 overflow-y-auto">
        <div className="space-y-6">
          <h3 className="text-[10px] font-bold text-neutral-500 uppercase tracking-widest">視覺檔案 (Asset)</h3>
          {project.coreSceneImage ? (
            <div className="space-y-6 animate-in fade-in duration-700">
              <div className="aspect-video rounded-2xl overflow-hidden border border-white/10 shadow-lg group relative">
                <img src={project.coreSceneImage} className="w-full h-full object-cover" />
                <div className="absolute inset-0 bg-black/60 opacity-0 group-hover:opacity-100 transition-opacity flex items-center justify-center p-4">
                  <p className="text-[10px] text-center italic leading-relaxed text-amber-500">「這是本片的視覺基調」</p>
                </div>
              </div>

              {(project.sceneGrid?.length || 0) > 0 && (
                <div className="grid grid-cols-3 gap-2">
                  {project.sceneGrid.slice(0, 9).map((img, i) => (
                    <div key={i} className="aspect-square rounded-lg overflow-hidden border border-white/5 opacity-60 hover:opacity-100 transition-opacity">
                      <img src={img} className="w-full h-full object-cover" />
                    </div>
                  ))}
                </div>
              )}
            </div>
          ) : (
            <div className="py-12 border border-dashed border-white/10 rounded-3xl text-center opacity-30">
              <Eye className="w-8 h-8 mx-auto mb-3 text-neutral-700" />
              <p className="text-[10px] uppercase tracking-widest">等待視覺生成</p>
            </div>
          )}
        </div>

        <div className="mt-auto pt-6 border-t border-white/5">
           <div className="flex items-center justify-between text-[10px] text-neutral-600 mb-2 font-mono">
              <span>PROJECT QUALITY</span>
              <span className="text-amber-600">MASTER GRADE</span>
           </div>
           <div className="h-1 bg-white/5 rounded-full overflow-hidden">
              <div className="h-full bg-amber-600/50 w-full animate-pulse"></div>
           </div>
        </div>
      </aside>
    </div>
  );
};

