import { GoogleGenAI, Type } from "@google/genai";
import { SYSTEM_INSTRUCTION } from "../constants";
import { Suggestion, SceneDesign, ProjectDNA, ProductionPhase } from "../types";

export class GeminiService {
  constructor(apiKey: string) {}

  async generateSuggestions(input: string, phase: ProductionPhase, context: string): Promise<Suggestion[]> {
    const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
    const prompt = `目前的靈感/指令： "${input}"。
    請根據目前的製作階段 [${phase}]，提供三個具體的創意導向。

    【關鍵任務】如果是 INSPIRATION 階段，請發揮頂尖導演聯想力，自動推論出：
    1. 地理環境 (environment)
    2. 社會背景 (socialBackground)
    3. 核心敘事 (coreNarrative)

    請回傳 JSON 陣列，包含 title, description, tags, environment, socialBackground, coreNarrative。`;

    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: [{ role: 'user', parts: [{ text: prompt }] }],
      config: {
        systemInstruction: SYSTEM_INSTRUCTION,
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.ARRAY,
          items: {
            type: Type.OBJECT,
            properties: {
              title: { type: Type.STRING },
              description: { type: Type.STRING },
              tags: { type: Type.ARRAY, items: { type: Type.STRING } },
              environment: { type: Type.STRING },
              socialBackground: { type: Type.STRING },
              coreNarrative: { type: Type.STRING }
            },
            required: ["title", "description", "tags"]
          }
        }
      }
    });
    return JSON.parse(response.text || "[]");
  }

  async analyzeScenes(dna: ProjectDNA): Promise<SceneDesign[]> {
    const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
    const prompt = `你是一位頂尖視覺藝術總監。請根據以下劇本 DNA，拆解並設計出 9 個最具視覺張力、代表性的關鍵場景。

    劇本摘要：${dna.story}
    風格：${dna.style}
    核心敘事：${dna.coreNarrative}
    環境：${dna.environment}

    請為每個場景提供：
    1. 場景名稱 (title)
    2. 視覺設計描述 (visualDescription) - 包含精確的構圖、光影性質、主要色彩、材質細節與鏡頭語言。

    請回傳 JSON 陣列。`;

    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: [{ role: 'user', parts: [{ text: prompt }] }],
      config: {
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.ARRAY,
          items: {
            type: Type.OBJECT,
            properties: {
              title: { type: Type.STRING },
              visualDescription: { type: Type.STRING }
            },
            required: ["title", "visualDescription"]
          }
        }
      }
    });
    return JSON.parse(response.text || "[]");
  }

  async polishText(text: string, type: string): Promise<string> {
    const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: `你是專業編劇。請將以下內容進行電影化的專業潤色，強調視覺張力與敘事內核。類型：${type}。內容：${text}`,
    });
    return response.text || text;
  }

  async generateImage(prompt: string): Promise<string | null> {
    const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
    try {
      const response = await ai.models.generateContent({
        model: 'gemini-3-pro-image-preview',
        contents: { parts: [{ text: prompt }] },
        config: { imageConfig: { aspectRatio: "16:9", imageSize: "1K" } }
      });
      for (const part of response.candidates?.[0]?.content?.parts || []) {
        if (part.inlineData) return `data:image/png;base64,${part.inlineData.data}`;
      }
      return null;
    } catch (error) { return null; }
  }

  async generateSceneGrid(prompt: string, specificScenes?: SceneDesign[]): Promise<string[]> {
    const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
    try {
      if (specificScenes && specificScenes.length > 0) {
        const renderPrompts = specificScenes.slice(0, 9).map(s => `${s.title}: ${s.visualDescription}. Cinematic style, high quality, 8k.`);
        const combinedPrompt = `A 3x3 cinematic storyboard grid showcasing: ${renderPrompts.join('; ')}. Each panel should be a distinct professional concept art piece. High detail, masterwork.`;

        const response = await ai.models.generateImages({
          model: 'imagen-4.0-generate-001',
          prompt: combinedPrompt,
          config: { numberOfImages: 9, aspectRatio: '16:9' },
        });

        if (!response.generatedImages) return [];
        return response.generatedImages.map(img => `data:image/png;base64,${img.image.imageBytes}`);
      } else {
        const response = await ai.models.generateImages({
          model: 'imagen-4.0-generate-001',
          prompt: `9 different cinematic concept art shots for: ${prompt}. Diverse angles, lighting variations, high cinematic quality.`,
          config: { numberOfImages: 9, aspectRatio: '16:9' },
        });
        if (!response.generatedImages) return [];
        return response.generatedImages.map(img => `data:image/png;base64,${img.image.imageBytes}`);
      }
    } catch (error) {
      console.error(error);
      return [];
    }
  }

  async generateVideo(prompt: string, onProgress: (status: string) => void): Promise<string | null> {
    const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
    try {
      onProgress("正在初始化拍攝設備...");
      let operation = await ai.models.generateVideos({
        model: 'veo-3.1-fast-generate-preview',
        prompt: prompt,
        config: { numberOfVideos: 1, resolution: '720p', aspectRatio: '16:9' }
      });
      while (!operation.done) {
        await new Promise(resolve => setTimeout(resolve, 10000));
        operation = await ai.operations.getVideosOperation({ operation: operation });
      }
      const downloadLink = operation.response?.generatedVideos?.[0]?.video?.uri;
      return downloadLink ? `${downloadLink}&key=${process.env.API_KEY}` : null;
    } catch (error) { return null; }
  }
}

import React, { useState, useEffect, useCallback, useRef } from 'react';
import { ProductionPhase, Suggestion, ProjectState, GeneratedVideo, Message, ProjectDNA, SceneDesign } from './types';
import { PHASE_METADATA } from './constants';
import { GeminiService } from './services/geminiService';
import { ApiKeySelector } from './components/ApiKeySelector';
import { 
  Film, Sparkles, Send, Loader2, ArrowRight, 
  Info, Clapperboard, Video, Layout, Palette, 
  ChevronRight, History, Save, Download, Upload,
  X, CheckCircle2, Monitor, BookOpen, Layers, Terminal, MapPin, Users, Target, Lightbulb,
  Undo2, Redo2, Wand2, Eye, Grid, Edit3, Image as ImageIcon, Briefcase
} from 'lucide-react';

const App: React.FC = () => {
  const [hasKey, setHasKey] = useState(false);
  const [isLoading, setIsLoading] = useState(false);
  const [isAnalyzing, setIsAnalyzing] = useState(false);
  const [input, setInput] = useState('');
  const [hoveredSuggestion, setHoveredSuggestion] = useState<Suggestion | null>(null);
  const [selectedSuggestion, setSelectedSuggestion] = useState<Suggestion | null>(null);
  const [showHistory, setShowHistory] = useState(false);
  const [activeStep, setActiveStep] = useState<ProductionPhase>(ProductionPhase.INSPIRATION);

  const [historyStack, setHistoryStack] = useState<ProjectDNA[]>([]);
  const [redoStack, setRedoStack] = useState<ProjectDNA[]>([]);

  const [sceneHistoryStack, setSceneHistoryStack] = useState<SceneDesign[][]>([]);
  const [sceneRedoStack, setSceneRedoStack] = useState<SceneDesign[][]>([]);

  const [tempDNA, setTempDNA] = useState<ProjectDNA>({
    format: '電影', style: '寫實電影感 (Realistic Cinematic)', story: '', ratio: '16:9',
    environment: '', socialBackground: '', coreNarrative: ''
  });

  const [project, setProject] = useState<ProjectState>({
    currentPhase: ProductionPhase.INSPIRATION,
    initialInput: '',
    dna: { format: '', style: '', story: '', ratio: '16:9', environment: '', socialBackground: '', coreNarrative: '' },
    suggestions: [], proposedScenes: [], history: [], generatedVideos: [], sceneGrid: []
  });

  const fileInputRef = useRef<HTMLInputElement>(null);
  const geminiRef = useRef<GeminiService | null>(null);

  useEffect(() => {
    const checkKey = async () => {
      // @ts-ignore
      const exists = await window.aistudio.hasSelectedApiKey();
      if (exists) {
        setHasKey(true);
        geminiRef.current = new GeminiService(process.env.API_KEY || '');
      }
    };
    checkKey();
  }, []);

  useEffect(() => {
    if (activeStep === ProductionPhase.VISUAL_DEV && project.proposedScenes.length === 0 && !isAnalyzing && geminiRef.current) {
      handleAnalyzeScenes();
    }
  }, [activeStep, project.proposedScenes.length]);

  const handleAnalyzeScenes = async () => {
    if (!geminiRef.current) return;
    setIsAnalyzing(true);
    try {
      const scenes = await geminiRef.current.analyzeScenes(project.dna);
      setProject(prev => ({ ...prev, proposedScenes: scenes }));
      setSceneHistoryStack([scenes]);
      setSceneRedoStack([]);
    } catch (err) {
      console.error(err);
    } finally {
      setIsAnalyzing(false);
    }
  };

  const pushToSceneUndo = (newScenes: SceneDesign[]) => {
    setSceneHistoryStack(prev => [...prev, newScenes]);
    setSceneRedoStack([]);
  };

  const handleUndoScene = () => {
    if (sceneHistoryStack.length <= 1) return;
    const current = sceneHistoryStack[sceneHistoryStack.length - 1];
    const prev = sceneHistoryStack[sceneHistoryStack.length - 2];
    setSceneRedoStack(r => [current, ...r]);
    setSceneHistoryStack(h => h.slice(0, -1));
    setProject(p => ({ ...p, proposedScenes: prev }));
  };

  const handleRedoScene = () => {
    if (sceneRedoStack.length === 0) return;
    const next = sceneRedoStack[0];
    setSceneRedoStack(r => r.slice(1));
    setSceneHistoryStack(h => [...h, next]);
    setProject(p => ({ ...p, proposedScenes: next }));
  };

  const handleRenderGrid = async () => {
    if (!geminiRef.current || project.proposedScenes.length === 0) return;
    setIsLoading(true);
    try {
      const grid = await geminiRef.current.generateSceneGrid(project.dna.story, project.proposedScenes);
      setProject(prev => ({ ...prev, sceneGrid: grid }));
    } catch (err) {
      console.error(err);
    } finally {
      setIsLoading(false);
    }
  };

  const updateScene = (idx: number, field: keyof SceneDesign, value: string) => {
    const newScenes = [...project.proposedScenes];
    newScenes[idx] = { ...newScenes[idx], [field]: value };
    setProject(prev => ({ ...prev, proposedScenes: newScenes }));
  };

  const finalizeSceneUpdate = () => {
    pushToSceneUndo(project.proposedScenes);
  };

  const handlePolishScene = async (idx: number) => {
    if (!geminiRef.current || isLoading) return;
    setIsLoading(true);
    try {
      const scene = project.proposedScenes[idx];
      const polished = await geminiRef.current.polishText(scene.visualDescription, `場景視覺設計：${scene.title}`);
      const newScenes = [...project.proposedScenes];
      newScenes[idx] = { ...scene, visualDescription: polished };
      setProject(prev => ({ ...prev, proposedScenes: newScenes }));
      pushToSceneUndo(newScenes);
    } finally {
      setIsLoading(false);
    }
  };

  const saveProject = () => {
    const data = JSON.stringify(project, null, 2);
    const blob = new Blob([data], { type: 'application/json' });
    const url = URL.createObjectURL(blob);
    const link = document.createElement('a');
    link.href = url;
    link.download = `montage-project-${new Date().toISOString().slice(0, 10)}.json`;
    link.click();
    URL.revokeObjectURL(url);
  };

  const loadProject = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;
    const reader = new FileReader();
    reader.onload = (event) => {
      try {
        const data = JSON.parse(event.target?.result as string) as ProjectState;
        if (data.currentPhase && data.dna) {
          setProject({
            ...data,
            suggestions: data.suggestions || [],
            proposedScenes: data.proposedScenes || [],
            history: data.history || [],
            generatedVideos: data.generatedVideos || [],
            sceneGrid: data.sceneGrid || []
          });
          setActiveStep(data.currentPhase);
          if (data.currentPhase === ProductionPhase.INSPIRATION) {
            setInput(data.initialInput || '');
          }
        }
      } catch (err) {
        alert('檔案格式錯誤，請確保上傳正確的專案檔。');
      }
    };
    reader.readAsText(file);
    if (fileInputRef.current) fileInputRef.current.value = '';
  };

  const handleStepSwitch = (phase: ProductionPhase) => {
    setActiveStep(phase);
    if (phase === ProductionPhase.INSPIRATION) {
      setInput(project.initialInput || '');
    } else {
      const lastUserMsgForPhase = [...project.history].reverse().find(m => m.role === 'user' && m.phase === phase);
      if (lastUserMsgForPhase) {
        setInput(lastUserMsgForPhase.content);
      } else {
        setInput('');
      }
    }
    setProject(prev => ({ ...prev, suggestions: [] }));
  };

  const handleSubmitIdea = async (e?: React.FormEvent) => {
    if (e) e.preventDefault();
    if (!input.trim() || isLoading || !geminiRef.current) return;

    setIsLoading(true);
    try {
      const results = await geminiRef.current.generateSuggestions(input, activeStep, JSON.stringify(project.dna));
      setProject(prev => ({ 
        ...prev, 
        suggestions: results || [], 
        initialInput: activeStep === ProductionPhase.INSPIRATION ? input : prev.initialInput,
        history: [...(prev.history || []), { role: 'user', content: input, phase: activeStep }]
      }));
    } catch (error) { 
      console.error(error); 
    } finally { 
      setIsLoading(false); 
    }
  };

  const handleSuggestionClick = (s: Suggestion) => {
    const inferredDNA = {
      ...project.dna,
      format: s.tags?.includes('廣告') ? '商業廣告' : s.tags?.includes('動畫') ? '動畫短片' : '電影短片',
      story: s.description,
      environment: s.environment || project.dna.environment,
      socialBackground: s.socialBackground || project.dna.socialBackground,
      coreNarrative: s.coreNarrative || project.dna.coreNarrative,
    };
    setTempDNA(inferredDNA);
    setHistoryStack([inferredDNA]);
    setRedoStack([]);

    // 選中後直接推進到「拍攝方案」階段進行編輯
    setProject(prev => ({
      ...prev,
      dna: inferredDNA,
      currentPhase: ProductionPhase.PRODUCTION_PLAN,
      suggestions: []
    }));
    setActiveStep(ProductionPhase.PRODUCTION_PLAN);
  };

  const pushToUndo = (newDNA: ProjectDNA) => {
    setHistoryStack(prev => [...prev, newDNA]);
    setRedoStack([]);
  };

  const handleUndo = () => {
    if (historyStack.length <= 1) return;
    const current = historyStack[historyStack.length - 1];
    const prev = historyStack[historyStack.length - 2];
    setRedoStack(r => [current, ...r]);
    setHistoryStack(h => h.slice(0, -1));
    setTempDNA(prev);
    setProject(p => ({ ...p, dna: prev }));
  };

  const handleRedo = () => {
    if (redoStack.length === 0) return;
    const next = redoStack[0];
    setRedoStack(r => r.slice(1));
    setHistoryStack(h => [...h, next]);
    setTempDNA(next);
    setProject(p => ({ ...p, dna: next }));
  };

  const handlePolish = async (field: keyof ProjectDNA, type: string) => {
    if (!geminiRef.current || isLoading) return;
    setIsLoading(true);
    try {
      const polished = await geminiRef.current.polishText(tempDNA[field] as string, type);
      const updated = { ...tempDNA, [field]: polished };
      setTempDNA(updated);
      pushToUndo(updated);
      setProject(p => ({ ...p, dna: updated }));
    } finally { 
      setIsLoading(false); 
    }
  };

  const confirmProductionPlan = async () => {
    if (!geminiRef.current) return;
    setIsLoading(true);

    try {
      let coreImage = project.coreSceneImage;
      // 只有從此階段推進到視覺開發時，才生成核心視覺
      coreImage = await geminiRef.current.generateImage(`${tempDNA.story}. ${tempDNA.style}. Cinematic, 8k.`) || undefined;

      const nextPhase = ProductionPhase.VISUAL_DEV;

      setProject(prev => ({
        ...prev,
        currentPhase: nextPhase,
        dna: { ...tempDNA },
        history: [...(prev.history || []), { 
          role: 'assistant', 
          content: `【確認拍攝方案】\n已完成拍攝 DNA 的優化，核心視覺基調已確立。`, 
          phase: ProductionPhase.PRODUCTION_PLAN 
        }],
        coreSceneImage: coreImage
      }));

      setActiveStep(nextPhase);
    } catch (error) {
      console.error(error);
    } finally { 
      setIsLoading(false); 
    }
  };

  if (!hasKey) return <ApiKeySelector onSelected={() => { setHasKey(true); geminiRef.current = new GeminiService(process.env.API_KEY || ''); }} />;

  return (
    <div className="flex h-screen bg-[#050505] text-white overflow-hidden font-sans">
      <aside className="w-64 border-r border-white/5 flex flex-col bg-black/40 p-6">
        <div className="flex items-center gap-3 mb-12">
          <div className="bg-amber-600 p-2 rounded-lg shadow-[0_0_15px_rgba(217,119,6,0.3)]"><Film className="w-6 h-6 text-white" /></div>
          <h1 className="text-lg font-serif font-bold tracking-widest text-white/90">電影蒙太奇</h1>
        </div>

        <nav className="flex-1 space-y-2">
          {Object.entries(PHASE_METADATA).map(([key, meta], idx) => {
