              {isAnalyzing ? (
                <div className="py-20 flex flex-col items-center gap-6">
                  <div className="relative"><Loader2 className="w-12 h-12 text-amber-600 animate-spin" /><Sparkles className="absolute -top-2 -right-2 w-6 h-6 text-amber-400 animate-pulse" /></div>
