                        </div>
                        <div className="flex items-center gap-2">
                           <button onClick={() => handlePolishStage(idx)} disabled={isLoading} className="flex items-center gap-1 text-[9px] bg-amber-600/10 hover:bg-amber-600 text-amber-500 hover:text-white px-2 py-1 rounded transition-all opacity-0 group-hover:opacity-100"><Wand2 className="w-3 h-3" /> AI 潤色</button>
                           <button onClick={() => removeStage(idx)} className="text-neutral-600 hover:text-red-500 transition-colors opacity-0 group-hover:opacity-100"><Trash2 className="w-3.5 h-3.5" /></button>
                           <Edit3 className="w-3.5 h-3.5 text-neutral-600" />
                        </div>
                      </div>
                      <input className="bg-transparent border-none text-neutral-100 font-serif font-bold text-lg mb-2 focus:ring-0 w-full" value={stage.name} onChange={(e) => updateStage(idx, 'name', e.target.value)} onBlur={finalizeStageUpdate} placeholder="舞台地點名稱" />
                      <textarea className="w-full bg-white/5 border border-white/5 rounded-xl p-3 text-[11px] text-neutral-400 focus:text-neutral-200 outline-none focus:ring-1 focus:ring-amber-500/50 resize-none leading-relaxed flex-1 mb-4" rows={6} value={stage.description} onChange={(e) => updateStage(idx, 'description', e.target.value)} onBlur={finalizeStageUpdate} placeholder="地理集群與空間描述..." />
                      <button 
                        onClick={() => handleRenderStageGrid(idx)}
                        disabled={isLoading}
                        className="w-full py-2 bg-amber-600/10 hover:bg-amber-600 text-amber-500 hover:text-white rounded-lg text-[11px] font-bold flex items-center justify-center gap-2 transition-all"
                      >
                        {isLoading && project.selectedStageIndex === idx ? <Loader2 className="w-3.5 h-3.5 animate-spin" /> : <Grid className="w-3.5 h-3.5" />}
