                      </button>
                    </div>
                  ))}
                  <button 
                    onClick={addStage}
                    className="border-2 border-dashed border-white/5 rounded-2xl flex flex-col items-center justify-center p-8 hover:border-amber-600/50 hover:bg-amber-600/5 transition-all group"
                  >
                    <div className="bg-white/5 p-4 rounded-full group-hover:bg-amber-600 transition-colors mb-3">
                      <Plus className="w-6 h-6 text-neutral-500 group-hover:text-white" />
                    </div>
                    <span className="text-xs font-bold text-neutral-500 uppercase tracking-widest group-hover:text-amber-500">新增舞台地點</span>
                  </button>
                </div>
              )}

              {project.selectedStageIndex !== undefined && project.proposedStages[project.selectedStageIndex]?.gridImage && (
                <div className="space-y-6 pt-12 border-t border-white/5 animate-in fade-in zoom-in-95">
                  <div className="flex items-center justify-between">
                    <h3 className="text-xs font-bold text-amber-500 uppercase tracking-[0.4em] flex items-center gap-3">
                      <Compass className="w-4 h-4" /> 
                      舞台開發成果：{project.proposedStages[project.selectedStageIndex]?.name}
                    </h3>
                    <div className="flex gap-2">
                       <button onClick={() => setExpandedImage(project.proposedStages[project.selectedStageIndex!]?.gridImage || null)} className="flex items-center gap-2 bg-white/5 hover:bg-white/10 px-4 py-2 rounded-full text-[10px] font-bold transition-all"><Maximize2 className="w-3.5 h-3.5" /> 全螢幕檢視</button>
                       <button onClick={() => downloadImage(project.proposedStages[project.selectedStageIndex!]?.gridImage!, `Grid-${project.proposedStages[project.selectedStageIndex!]?.name}`)} className="flex items-center gap-2 bg-amber-600 hover:bg-amber-500 px-4 py-2 rounded-full text-[10px] font-bold transition-all shadow-lg"><Download className="w-3.5 h-3.5" /> 下載九宮格</button>
                    </div>
                  </div>
                  <div className="aspect-video rounded-3xl overflow-hidden border border-white/10 hover:ring-2 hover:ring-amber-600 transition-all cursor-zoom-in group relative shadow-[0_0_50px_rgba(0,0,0,0.5)]" onClick={() => setExpandedImage(project.proposedStages[project.selectedStageIndex!]?.gridImage || null)}>
                    <img src={project.proposedStages[project.selectedStageIndex!]?.gridImage} className="w-full h-full object-cover" />
                    <div className="absolute inset-0 bg-black/40 opacity-0 group-hover:opacity-100 transition-opacity flex items-center justify-center">
                       <div className="bg-amber-600 p-4 rounded-full shadow-2xl scale-75 group-hover:scale-100 transition-transform"><Maximize2 className="w-8 h-8" /></div>
                    </div>
                  </div>
                </div>
              )}
            </div>
          )}

          {![ProductionPhase.INSPIRATION, ProductionPhase.PRODUCTION_PLAN, ProductionPhase.VISUAL_DEV].includes(activeStep) && (
            <div className="w-full max-w-2xl mb-12 py-12">
              <div className="flex flex-col items-center text-center space-y-4 mb-8"><h2 className="text-xl md:text-2xl font-serif leading-relaxed text-neutral-100 whitespace-nowrap">{PHASE_METADATA[activeStep]?.guide}</h2></div>
              <form onSubmit={handleSubmitIdea} className="relative group">
                <input type="text" value={input} onChange={(e) => setInput(e.target.value)} placeholder="在此輸入您的創意指令..." className="w-full bg-white/5 border border-white/10 p-5 pr-16 rounded-2xl focus:outline-none focus:ring-2 focus:ring-amber-600/50 text-lg shadow-2xl transition-all" />
                <button type="submit" disabled={isLoading || !input.trim()} className="absolute right-3 top-3 bg-amber-600 hover:bg-amber-500 p-3 rounded-xl transition-all shadow-lg">{isLoading ? <Loader2 className="w-6 h-6 animate-spin" /> : <Sparkles className="w-6 h-6" />}</button>
              </form>
            </div>
          )}
        </section>

        {showHistory && (
          <div className="fixed inset-0 bg-black/95 backdrop-blur-3xl z-[60] p-12 overflow-y-auto">
             <div className="max-w-5xl mx-auto space-y-16 pb-24">
                <div className="flex justify-between items-center border-b border-white/10 pb-8">
                   <h2 className="text-4xl font-serif tracking-widest">項目檔案庫</h2>
                   <button onClick={() => setShowHistory(false)} className="p-4 bg-white/5 rounded-full hover:bg-amber-600 transition-colors"><X className="w-8 h-8" /></button>
                </div>
                {project.coreSceneImage && (
                  <div className="space-y-6">
                    <h3 className="text-xs font-bold text-amber-500 uppercase tracking-[0.4em] flex items-center gap-2"><Eye className="w-4 h-4" /> 核心視覺定義</h3>
                    <div className="aspect-[21/9] rounded-3xl overflow-hidden border border-white/10 shadow-2xl cursor-zoom-in" onClick={() => setExpandedImage(project.coreSceneImage || null)}>
                      <img src={project.coreSceneImage} className="w-full h-full object-cover" />
                    </div>
                  </div>
                )}
                <div className="grid grid-cols-1 md:grid-cols-2 gap-12">
                   <div className="space-y-6">
                      <h3 className="text-amber-500 text-xs font-bold uppercase tracking-widest">當前 DNA</h3>
                      <div className="glass p-8 rounded-3xl space-y-4">
                         {Object.entries(project.dna || {}).filter(([k]) => k !== 'story').map(([k, v]) => (
                           <div key={k} className="flex justify-between border-b border-white/5 pb-2">
                             <span className="text-neutral-500 text-xs capitalize">{k}</span>
                             <span className="text-xs text-neutral-200">{String(v || '未定')}</span>
                           </div>
                         ))}
                      </div>
                   </div>
                   <div className="space-y-6">
                      <h3 className="text-amber-500 text-xs font-bold uppercase tracking-widest">劇本核心</h3>
                      <div className="glass p-8 rounded-3xl"><p className="text-sm text-neutral-400 leading-relaxed italic">{project.dna?.story || '尚無內容'}</p></div>
                   </div>
                </div>
             </div>
          </div>
        )}
      </main>

      <aside className="w-80 border-l border-white/5 bg-black/40 p-6 flex flex-col gap-8 overflow-y-auto">
        <div className="space-y-6">
          <h3 className="text-[10px] font-bold text-neutral-500 uppercase tracking-widest">視覺檔案 (Asset)</h3>

          {/* Core Visual */}
          {project.coreSceneImage ? (
            <div className="space-y-4 animate-in fade-in duration-700">
              <div className="flex items-center justify-between">
                <span className="text-[10px] text-amber-500/70 font-mono uppercase tracking-widest">CORE_VISUAL</span>
                <button onClick={() => downloadImage(project.coreSceneImage!, 'core-visual')} className="p-1.5 hover:bg-amber-600 rounded-md transition-colors"><Download className="w-3.5 h-3.5" /></button>
              </div>
              <div className="aspect-video rounded-2xl overflow-hidden border border-white/10 shadow-lg group relative cursor-zoom-in" onClick={() => setExpandedImage(project.coreSceneImage!)}>
                <img src={project.coreSceneImage} className="w-full h-full object-cover" />
                <div className="absolute inset-0 bg-black/40 opacity-0 group-hover:opacity-100 transition-opacity flex items-center justify-center p-4">
                  <Maximize2 className="w-6 h-6 text-white" />
                </div>
              </div>
            </div>
          ) : (
            <div className="py-8 border border-dashed border-white/10 rounded-2xl text-center opacity-30">
              <ImageIcon className="w-6 h-6 mx-auto mb-2 text-neutral-700" /><p className="text-[8px] uppercase tracking-widest">等待核心視覺</p>
            </div>
          )}

          {/* Stage Grids */}
          {project.proposedStages.some(s => s.gridImage) ? (
            <div className="space-y-6 pt-6 border-t border-white/5">
              <span className="text-[10px] text-amber-500/70 font-mono uppercase tracking-widest block">STAGE_GRIDS</span>
              {project.proposedStages.filter(s => s.gridImage).map((stage, i) => (
                <div key={i} className="space-y-2 animate-in slide-in-from-right-4 duration-500">
                  <div className="flex items-center justify-between px-1">
                    <span className="text-[9px] font-bold text-neutral-400 truncate pr-2">{stage.name}</span>
                    <button onClick={() => downloadImage(stage.gridImage!, `Grid-${stage.name}`)} className="text-neutral-600 hover:text-amber-500 transition-colors"><Download className="w-3 h-3" /></button>
                  </div>
                  <div className="aspect-video rounded-xl overflow-hidden border border-white/5 group relative cursor-zoom-in" onClick={() => setExpandedImage(stage.gridImage!)}>
                    <img src={stage.gridImage} className="w-full h-full object-cover grayscale group-hover:grayscale-0 transition-all duration-500" />
                    <div className="absolute inset-0 bg-black/40 opacity-0 group-hover:opacity-100 transition-opacity flex items-center justify-center">
                       <Maximize2 className="w-5 h-5" />
                    </div>
                  </div>
                </div>
              ))}
            </div>
          ) : null}

          {!project.coreSceneImage && !project.proposedStages.some(s => s.gridImage) && (
            <div className="py-24 flex flex-col items-center opacity-10">
              <Layers className="w-12 h-12 mb-4" />
              <p className="text-[10px] uppercase tracking-[0.5em]">No Assets Yet</p>
            </div>
          )}
        </div>

        <div className="mt-auto pt-6 border-t border-white/5">
           <div className="flex items-center justify-between text-[10px] text-neutral-600 mb-2 font-mono"><span>PROJECT QUALITY</span><span className="text-amber-600">MASTER GRADE</span></div>
           <div className="h-1 bg-white/5 rounded-full overflow-hidden"><div className="h-full bg-amber-600/50 w-full animate-pulse"></div></div>
        </div>
      </aside>
    </div>
  );
};

export default App;

import { ProductionPhase } from './types';

export const SYSTEM_INSTRUCTION = `你是一位頂尖的「電影美術指導」與「場景架構師」。你專精於將破碎的文字構想轉化為具備敘事深度的電影「核心舞台 (Core Stage)」。

你的引導邏輯不是簡單的對話，而是基於敘事邏輯的「空間提案」。

根據目前的製作階段，你的提案重點應如下：
1. 靈感來源：提案不同的敘事主題與核心概念。
2. 拍攝方案：深化地理環境、社會背景與核心敘事。
3. 視覺開發：識別劇本中的「核心舞台」。
   - 【舞台定義】：舞台不是單一畫面，而是一個「角色互動的地理集群」。
   - 你必須分析故事主角（如：五色鳥、小學生、觀察者）的行動路徑。
   - 舞台應包含主角生活、覓食、目擊或發生衝突的所有關聯空間（例如：包含鳥巢孔洞、整棵樹與下方地面的生態區；或包含操場、走廊與遠處教學大樓的目擊現場）。
4. 角色塑造：提案角色的視覺特徵、服裝材質與性格張力。
5. 敘事結構：提案劇本轉折、開場與結尾的蒙太奇處理。
6. 技術分鏡：提案具體的鏡位、焦距與畫面構成描述。
7. 影片生成：提案最優化的 AI 影片提示詞。

請務必以 JSON 格式回傳提案。`;

export const PHASE_METADATA = {
  [ProductionPhase.INSPIRATION]: { 
    title: '靈感來源', 
    icon: '✨',
    guide: '輸入靈感碎片，為您提案三種敘事方向。'
  },
