                    <div className="absolute inset-0 bg-black/40 opacity-0 group-hover:opacity-100 transition-opacity flex items-center justify-center">
                       <Maximize2 className="w-5 h-5" />
                    </div>
                  </div>
                </div>
              ))}
            </div>
          ) : null}

          {!project.coreSceneImage && !project.proposedStages.some(s => s.gridImage) && (
            <div className="py-24 flex flex-col items-center opacity-10">
              <Layers className="w-12 h-12 mb-4" />
              <p className="text-[10px] uppercase tracking-[0.5em]">No Assets Yet</p>
            </div>
          )}
        </div>

        <div className="mt-auto pt-6 border-t border-white/5">
           <div className="flex items-center justify-between text-[10px] text-neutral-600 mb-2 font-mono"><span>PROJECT QUALITY</span><span className="text-amber-600">MASTER GRADE</span></div>
           <div className="h-1 bg-white/5 rounded-full overflow-hidden"><div className="h-full bg-amber-600/50 w-full animate-pulse"></div></div>
        </div>
      </aside>
    </div>
  );
};

