  async elaboratePlan(suggestion: Suggestion): Promise<ProjectDNA> {
    const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
    const prompt = `你是一位資深編劇與導演。請根據以下初步提案，擴充為完整的電影拍攝 DNA。

    提案標題：${suggestion.title}
    提案描述：${suggestion.description}

    【生成要求】
    1. 地理環境 (environment)：細膩描述空間、光影與材質感。字數約 150 字。
    2. 社會背景 (socialBackground)：描述世界觀、階級、文化或時代張力。字數約 150 字。
    3. 核心敘事 (coreNarrative)：描述本片的精神內核、哲學探討或情感主軸。字數約 150 字。
    4. 劇本摘要 (story)：完整的電影短片敘事結構（開頭、發展、轉折、結尾）。字數 200-300 字。

    請回傳 JSON 物件。`;

    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: [{ role: 'user', parts: [{ text: prompt }] }],
      config: {
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.OBJECT,
          properties: {
            format: { type: Type.STRING },
            style: { type: Type.STRING },
            story: { type: Type.STRING },
            ratio: { type: Type.STRING },
            environment: { type: Type.STRING },
            socialBackground: { type: Type.STRING },
            coreNarrative: { type: Type.STRING }
          },
          required: ["format", "style", "story", "environment", "socialBackground", "coreNarrative"]
        }
      }
    });

    const data = JSON.parse(response.text || "{}");
    return {
      ...data,
      ratio: data.ratio || '16:9',
      style: data.style || '寫實電影感 (Realistic Cinematic)',
      format: data.format || '電影短片'
    };
  }

  async polishText(text: string, type: string): Promise<string> {
    const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: `你是專業美術指導。請將以下內容進行電影場景化的專業潤色，強調空間敘事邏輯、角色間的視覺連線與地理集群的完整性。類型：${type}。內容：${text}`,
    });
    return response.text || text;
  }

  async generateImage(prompt: string): Promise<string | null> {
    const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
    try {
      const response = await ai.models.generateContent({
        model: 'gemini-3-pro-image-preview',
        contents: { parts: [{ text: prompt }] },
        config: { imageConfig: { aspectRatio: "16:9", imageSize: "1K" } }
      });
      for (const part of response.candidates?.[0]?.content?.parts || []) {
        if (part.inlineData) return `data:image/png;base64,${part.inlineData.data}`;
      }
      return null;
    } catch (error) { return null; }
  }

  private async mergeImagesToGrid(images: string[]): Promise<string> {
    return new Promise((resolve) => {
      const canvas = document.createElement('canvas');
      const ctx = canvas.getContext('2d');
      if (!ctx) return resolve(images[0]);

      const imgObjs = images.map(src => {
        const img = new Image();
        img.src = src;
        return img;
      });

      const checkLoaded = () => {
        if (imgObjs.every(img => img.complete)) {
          const singleW = imgObjs[0].naturalWidth || 1024;
          const singleH = imgObjs[0].naturalHeight || 576;
          canvas.width = singleW * 3;
          canvas.height = singleH * 3;

          imgObjs.forEach((img, i) => {
            const row = Math.floor(i / 3);
            const col = i % 3;
            ctx.drawImage(img, col * singleW, row * singleH, singleW, singleH);
          });
          resolve(canvas.toDataURL('image/png'));
        }
      };

      imgObjs.forEach(img => {
        img.onload = checkLoaded;
        if (img.complete) checkLoaded();
      });
    });
  }

  async generateSceneGrid(dna: ProjectDNA, stage: StageDesign): Promise<string> {
    const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
    const base64Images: string[] = [];

    const angles = [
      "1. 全景俯瞰 (High-angle master shot showing the entire geographic cluster layout)",
      "2. 敘事全景 (Wide shot showing the primary character's perspective within the cluster)",
      "3. 側面全景 (Profile shot showing spatial depth and relationships between key zones)",
      "4. 入口視角 (Character's arrival perspective into this stage)",
      "5. 核心物件特寫 (Close-up of the narrative focus element within the stage)",
      "6. 氛圍細節 A (Detail on lighting and texture that anchors the mood)",
      "7. 氛圍細節 B (Secondary atmospheric detail showing spatial context)",
      "8. 關鍵道具特寫 (Macro shot of a significant narrative anchor)",
      "9. 角色主觀 POV (Subjective point of view from a character's eye level)"
    ];

    try {
      for (let i = 0; i < 9; i++) {
        const currentAngle = angles[i];
        const prompt = `Stage: ${stage.name}. Perspective: ${currentAngle}. Context: ${stage.description}. Style: ${dna.style}. Professional cinematic concept art, 8k, extreme detail, consistent spatial logic.`;

        const response = await ai.models.generateImages({
          model: 'imagen-4.0-generate-001',
          prompt: prompt,
          config: {
            numberOfImages: 1,
            aspectRatio: '16:9',
          },
        });

        if (response.generatedImages?.[0]) {
          base64Images.push(`data:image/png;base64,${response.generatedImages[0].image.imageBytes}`);
        }
      }

      if (base64Images.length === 9) {
        return await this.mergeImagesToGrid(base64Images);
      }
    } catch (error) {
      console.error("Stage grid generation failed:", error);
    }

    return base64Images[0] || "";
  }

  async generateVideo(prompt: string, onProgress: (status: string) => void): Promise<string | null> {
    const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
    try {
      onProgress("正在初始化拍攝設備...");
      let operation = await ai.models.generateVideos({
        model: 'veo-3.1-fast-generate-preview',
        prompt: prompt,
        config: { numberOfVideos: 1, resolution: '720p', aspectRatio: '16:9' }
      });
      while (!operation.done) {
        await new Promise(resolve => setTimeout(resolve, 10000));
        operation = await ai.operations.getVideosOperation({ operation: operation });
      }
      const downloadLink = operation.response?.generatedVideos?.[0]?.video?.uri;
      return downloadLink ? `${downloadLink}&key=${process.env.API_KEY}` : null;
    } catch (error) { return null; }
  }
}

import React, { useState, useEffect, useCallback, useRef } from 'react';
import { ProductionPhase, Suggestion, ProjectState, GeneratedVideo, Message, ProjectDNA, StageDesign } from './types';
import { PHASE_METADATA } from './constants';
import { GeminiService } from './services/geminiService';
import { ApiKeySelector } from './components/ApiKeySelector';
import { 
  Film, Sparkles, Send, Loader2, ArrowRight, 
  Info, Clapperboard, Video, Layout, Palette, 
  ChevronRight, History, Save, Download, Upload,
  X, CheckCircle2, Monitor, BookOpen, Layers, Terminal, MapPin, Users, Target, Lightbulb,
  Undo2, Redo2, Wand2, Eye, Grid, Edit3, Image as ImageIcon, Briefcase, Trash2, Plus, 
  Compass, Map, Maximize2, DownloadCloud, RefreshCw
} from 'lucide-react';

const App: React.FC = () => {
  const [hasKey, setHasKey] = useState(false);
  const [isLoading, setIsLoading] = useState(false);
  const [isAnalyzing, setIsAnalyzing] = useState(false);
  const [isElaborating, setIsElaborating] = useState(false);
  const [input, setInput] = useState('');
  const [showHistory, setShowHistory] = useState(false);
  const [activeStep, setActiveStep] = useState<ProductionPhase>(ProductionPhase.INSPIRATION);
  const [expandedImage, setExpandedImage] = useState<string | null>(null);

  const [historyStack, setHistoryStack] = useState<ProjectDNA[]>([]);
  const [redoStack, setRedoStack] = useState<ProjectDNA[]>([]);

  const [stageHistoryStack, setStageHistoryStack] = useState<StageDesign[][]>([]);
  const [stageRedoStack, setStageRedoStack] = useState<StageDesign[][]>([]);

  const [tempDNA, setTempDNA] = useState<ProjectDNA>({
    format: '電影', style: '寫實電影感 (Realistic Cinematic)', story: '', ratio: '16:9',
    environment: '', socialBackground: '', coreNarrative: ''
  });

  const [project, setProject] = useState<ProjectState>({
    currentPhase: ProductionPhase.INSPIRATION,
    initialInput: '',
    dna: { format: '電影', style: '寫實電影感 (Realistic Cinematic)', story: '', ratio: '16:9', environment: '', socialBackground: '', coreNarrative: '' },
    suggestions: [], proposedStages: [], history: [], generatedVideos: [], sceneGrid: []
  });

  const fileInputRef = useRef<HTMLInputElement>(null);
  const geminiRef = useRef<GeminiService | null>(null);

  useEffect(() => {
    const checkKey = async () => {
      // @ts-ignore
      const exists = await window.aistudio.hasSelectedApiKey();
      if (exists) {
        setHasKey(true);
        geminiRef.current = new GeminiService(process.env.API_KEY || '');
      }
    };
    checkKey();
  }, []);

  useEffect(() => {
    if (activeStep === ProductionPhase.VISUAL_DEV && project.proposedStages.length === 0 && !isAnalyzing && geminiRef.current) {
      handleIdentifyStages();
    }
  }, [activeStep, project.proposedStages.length]);

  const handleIdentifyStages = async () => {
    if (!geminiRef.current || isAnalyzing) return;

    // 如果已經有資料，詢問是否重置（這能在手動點擊「重新分析」時觸發）
    if (project.proposedStages.length > 0 && !confirm("這將會清除目前所有已開發的舞台設計與視覺九宮格，確定要重新分析嗎？")) {
      return;
    }

    setIsAnalyzing(true);
    // 重置開發狀態，避免舊資料干擾
    setProject(prev => ({ 
      ...prev, 
      proposedStages: [], 
      selectedStageIndex: undefined, 
      sceneGrid: [] 
    }));

    try {
      const stages = await geminiRef.current.identifyCoreStages(project.dna);
      setProject(prev => ({ ...prev, proposedStages: stages }));
      setStageHistoryStack([stages]);
      setStageRedoStack([]);
    } catch (err) {
      console.error(err);
    } finally {
      setIsAnalyzing(false);
    }
  };

  const pushToStageUndo = (newStages: StageDesign[]) => {
    setStageHistoryStack(prev => [...prev, newStages]);
    setStageRedoStack([]);
  };

  const handleUndoStage = () => {
    if (stageHistoryStack.length <= 1) return;
    const current = stageHistoryStack[stageHistoryStack.length - 1];
    const prev = stageHistoryStack[stageHistoryStack.length - 2];
    setStageRedoStack(r => [current, ...r]);
    setStageHistoryStack(h => h.slice(0, -1));
    setProject(p => ({ ...p, proposedStages: prev }));
  };

  const handleRedoStage = () => {
    if (stageRedoStack.length === 0) return;
    const next = stageRedoStack[0];
    setStageRedoStack(r => r.slice(1));
    setStageHistoryStack(h => [...h, next]);
    setProject(p => ({ ...p, proposedStages: next }));
  };

  const handleRenderStageGrid = async (idx: number) => {
    if (!geminiRef.current) return;
    const stage = project.proposedStages[idx];
    setIsLoading(true);
    setProject(prev => ({ ...prev, selectedStageIndex: idx }));
    try {
      const mergedGrid = await geminiRef.current.generateSceneGrid(project.dna, stage);
      const newStages = [...project.proposedStages];
      newStages[idx] = { ...stage, gridImage: mergedGrid };
      setProject(prev => ({ ...prev, proposedStages: newStages }));
      pushToStageUndo(newStages);
    } catch (err) {
      console.error(err);
    } finally {
      setIsLoading(false);
    }
  };

  const updateStage = (idx: number, field: keyof StageDesign, value: string) => {
    const newStages = [...project.proposedStages];
    newStages[idx] = { ...newStages[idx], [field]: value };
    setProject(prev => ({ ...prev, proposedStages: newStages }));
  };

  const addStage = () => {
    const newStages = [...project.proposedStages, { name: '新舞台地點', description: '描述該舞台的地理集群、核心角色路徑與空間關係...' }];
    setProject(prev => ({ ...prev, proposedStages: newStages }));
    pushToStageUndo(newStages);
  };

  const removeStage = (idx: number) => {
    const newStages = project.proposedStages.filter((_, i) => i !== idx);
    setProject(prev => ({ ...prev, proposedStages: newStages }));
    pushToStageUndo(newStages);
  };

  const finalizeStageUpdate = () => {
    pushToStageUndo(project.proposedStages);
  };

  const handlePolishStage = async (idx: number) => {
    if (!geminiRef.current || isLoading) return;
    setIsLoading(true);
    try {
      const stage = project.proposedStages[idx];
      const polished = await geminiRef.current.polishText(stage.description, `舞台空間設計：${stage.name}`);
      const newStages = [...project.proposedStages];
      newStages[idx] = { ...stage, description: polished };
      setProject(prev => ({ ...prev, proposedStages: newStages }));
      pushToStageUndo(newStages);
    } finally {
      setIsLoading(false);
    }
  };

  const saveProject = () => {
    const data = JSON.stringify(project, null, 2);
    const blob = new Blob([data], { type: 'application/json' });
    const url = URL.createObjectURL(blob);
    const link = document.createElement('a');
    link.href = url;
    link.download = `montage-project-${new Date().toISOString().slice(0, 10)}.json`;
    link.click();
    URL.revokeObjectURL(url);
  };

  const loadProject = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;
    const reader = new FileReader();
    reader.onload = (event) => {
      try {
        const data = JSON.parse(event.target?.result as string) as ProjectState;
        if (data.currentPhase && data.dna) {
          setProject({
            ...data,
            suggestions: data.suggestions || [],
            proposedStages: data.proposedStages || [],
            history: data.history || [],
            generatedVideos: data.generatedVideos || [],
            sceneGrid: data.sceneGrid || []
          });
          setActiveStep(data.currentPhase);
          setTempDNA(data.dna);
          if (data.currentPhase === ProductionPhase.INSPIRATION) {
            setInput(data.initialInput || '');
          }
        }
      } catch (err) {
        alert('檔案格式錯誤，請確保上傳正確的專案檔。');
      }
    };
    reader.readAsText(file);
    if (fileInputRef.current) fileInputRef.current.value = '';
  };

  const handleStepSwitch = (phase: ProductionPhase) => {
    setActiveStep(phase);
    if (phase === ProductionPhase.INSPIRATION) {
      setInput(project.initialInput || '');
    } else {
      const lastUserMsgForPhase = [...project.history].reverse().find(m => m.role === 'user' && m.phase === phase);
      if (lastUserMsgForPhase) {
        setInput(lastUserMsgForPhase.content);
      } else {
        setInput('');
      }
    }

    if (phase === ProductionPhase.PRODUCTION_PLAN) {
      setTempDNA(project.dna);
      setHistoryStack([project.dna]);
      setRedoStack([]);
    }

    setProject(prev => ({ ...prev, suggestions: [] }));
  };

  const handleSubmitIdea = async (e?: React.FormEvent) => {
    if (e) e.preventDefault();
    if (!input.trim() || isLoading || !geminiRef.current) return;

    setIsLoading(true);
    try {
      const results = await geminiRef.current.generateSuggestions(input, activeStep, JSON.stringify(project.dna));
      setProject(prev => ({ 
        ...prev, 
        suggestions: results || [], 
        initialInput: activeStep === ProductionPhase.INSPIRATION ? input : prev.initialInput,
        history: [...(prev.history || []), { role: 'user', content: input, phase: activeStep }]
      }));
    } catch (error) { 
      console.error(error); 
    } finally { 
      setIsLoading(false); 
    }
  };

  const handleSuggestionClick = async (s: Suggestion) => {
    if (!geminiRef.current) return;
    setIsElaborating(true);
    try {
      const detailedDNA = await geminiRef.current.elaboratePlan(s);

      setTempDNA(detailedDNA);
      setHistoryStack([detailedDNA]);
      setRedoStack([]);

      setProject(prev => ({
        ...prev,
        dna: detailedDNA,
        currentPhase: ProductionPhase.PRODUCTION_PLAN,
        suggestions: []
      }));
      setActiveStep(ProductionPhase.PRODUCTION_PLAN);
    } catch (error) {
      console.error(error);
    } finally {
      setIsElaborating(false);
    }
  };

  const pushToUndo = (newDNA: ProjectDNA) => {
    setHistoryStack(prev => [...prev, newDNA]);
    setRedoStack([]);
  };

  const handleUndo = () => {
    if (historyStack.length <= 1) return;
    const current = historyStack[historyStack.length - 1];
    const prev = historyStack[historyStack.length - 2];
    setRedoStack(r => [current, ...r]);
    setHistoryStack(h => h.slice(0, -1));
    setTempDNA(prev);
    setProject(p => ({ ...p, dna: prev }));
  };

  const handleRedo = () => {
    if (redoStack.length === 0) return;
    const next = redoStack[0];
    setRedoStack(r => r.slice(1));
    setHistoryStack(h => [...h, next]);
    setTempDNA(next);
    setProject(p => ({ ...p, dna: next }));
  };

  const handlePolish = async (field: keyof ProjectDNA, type: string) => {
    if (!geminiRef.current || isLoading) return;
    setIsLoading(true);
    try {
      const polished = await geminiRef.current.polishText(tempDNA[field] as string, type);
      const updated = { ...tempDNA, [field]: polished };
      setTempDNA(updated);
      pushToUndo(updated);
      setProject(p => ({ ...p, dna: updated }));
    } finally { 
      setIsLoading(false); 
    }
  };

  const confirmProductionPlan = async () => {
    if (!geminiRef.current) return;
    setIsLoading(true);

    try {
      let coreImage = project.coreSceneImage;
      coreImage = await geminiRef.current.generateImage(`${tempDNA.story}. ${tempDNA.style}. Cinematic, 8k.`) || undefined;

      const nextPhase = ProductionPhase.VISUAL_DEV;

      setProject(prev => ({
        ...prev,
        currentPhase: nextPhase,
        dna: { ...tempDNA },
        history: [...(prev.history || []), { 
          role: 'assistant', 
          content: `【確認拍攝方案】\n已完成拍攝 DNA 的優化，核心視覺基調已確立。`, 
          phase: ProductionPhase.PRODUCTION_PLAN 
        }],
        coreSceneImage: coreImage,
        // 確保切換到視覺開發時重新出發
        proposedStages: [],
        selectedStageIndex: undefined,
        sceneGrid: []
      }));

      setActiveStep(nextPhase);
    } catch (error) {
      console.error(error);
    } finally { 
      setIsLoading(false); 
    }
  };

  const downloadImage = (base64: string, name: string) => {
