                      </div>
                      <input className="bg-transparent border-none text-neutral-100 font-serif font-bold text-lg mb-2 focus:ring-0 w-full" value={stage.name} onChange={(e) => updateStage(idx, 'name', e.target.value)} onBlur={finalizeStageUpdate} placeholder="舞台地點名稱" />
                      <textarea className="w-full bg-white/5 border border-white/5 rounded-xl p-3 text-[11px] text-neutral-400 focus:text-neutral-200 outline-none focus:ring-1 focus:ring-amber-500/50 resize-none leading-relaxed flex-1 mb-4" rows={6} value={stage.description} onChange={(e) => updateStage(idx, 'description', e.target.value)} onBlur={finalizeStageUpdate} placeholder="主角路徑、地理集群與空間關係描述..." />
