            required: ["title", "description", "tags"]
          }
        }
      }
    });
    return JSON.parse(response.text || "[]");
  }

  async identifyCoreStages(dna: ProjectDNA): Promise<StageDesign[]> {
    const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
    const prompt = `你是一位資深電影美術指導。請針對劇本內容進行「角色—路徑—交匯點」的空間邏輯分析，識別出 1-3 個核心舞台。

    【分析核心】
    1. 主角基點：他在哪裡開始行動或尋求避風港？
    2. 行動路徑：他在空間中如何觀察或追逐目標？
    3. 敘事交匯：重要的互動或衝突發生在哪個地理集群？

    舞台必須是一個具備連貫邏輯的物理空間。

    劇本摘要：${dna.story}
    風格：${dna.style}
