  async elaboratePlan(suggestion: Suggestion): Promise<ProjectDNA> {
    const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
    const prompt = `你是一位資深編劇與導演。請根據以下初步提案，擴充為完整的電影拍攝 DNA。

    提案標題：${suggestion.title}
    提案描述：${suggestion.description}

    【生成要求】
    1. 地理環境 (environment)：細膩描述空間、光影與材質感。字數約 150 字。
    2. 社會背景 (socialBackground)：描述世界觀、階級、文化或時代張力。字數約 150 字。
    3. 核心敘事 (coreNarrative)：描述本片的精神內核、哲學探討或情感主軸。字數約 150 字。
    4. 劇本摘要 (story)：完整的電影短片敘事結構（開頭、發展、轉折、結尾）。字數 200-300 字。

    請回傳 JSON 物件。`;

    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: [{ role: 'user', parts: [{ text: prompt }] }],
      config: {
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.OBJECT,
          properties: {
            format: { type: Type.STRING },
            style: { type: Type.STRING },
            story: { type: Type.STRING },
            ratio: { type: Type.STRING },
            environment: { type: Type.STRING },
            socialBackground: { type: Type.STRING },
            coreNarrative: { type: Type.STRING }
          },
          required: ["format", "style", "story", "environment", "socialBackground", "coreNarrative"]
        }
      }
    });

    const data = JSON.parse(response.text || "{}");
    return {
      ...data,
      ratio: data.ratio || '16:9',
      style: data.style || '寫實電影感 (Realistic Cinematic)',
      format: data.format || '電影短片'
    };
  }

  async polishText(text: string, type: string): Promise<string> {
    const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: `你是專業美術指導。請進行場景化的專業潤色，強調主角視角下的空間層次感與地理集群的完整性。類型：${type}。內容：${text}`,
    });
    return response.text || text;
  }

  async generateImage(prompt: string): Promise<string | null> {
    const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
    try {
      const response = await ai.models.generateContent({
        model: 'gemini-3-pro-image-preview',
        contents: { parts: [{ text: prompt }] },
        config: { imageConfig: { aspectRatio: "16:9", imageSize: "1K" } }
      });
      for (const part of response.candidates?.[0]?.content?.parts || []) {
        if (part.inlineData) return `data:image/png;base64,${part.inlineData.data}`;
      }
      return null;
    } catch (error) { return null; }
  }

  async generateSceneGrid(dna: ProjectDNA, stage: StageDesign): Promise<string> {
    const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

    // 使用 gemini-3-pro-image-preview 以獲得更好的指令遵循度（Layout Adherence）
    // 解決 3x5 佈局錯誤，強調嚴格的 3x3 九宮格結構
    const gridPrompt = `
      A professional 3x3 cinematic concept art storyboard for the movie stage: "${stage.name}".
      Spatial Context: ${stage.description}.
      Visual Style: ${dna.style}.

      CRITICAL LAYOUT INSTRUCTION: 
      Generate a single 1:1 square image strictly divided into a 3x3 grid containing exactly NINE equal-sized panels. 
      DO NOT add extra rows or columns.

      Grid Content Mapping:
      - Top-Left: Wide bird's-eye overhead master shot.
      - Top-Center: Frontal wide establishing shot.
      - Top-Right: Side profile perspective shot.
      - Mid-Left: Entry point perspective, character arrival.
      - Center: Narrative core - Extreme close-up of the interaction focus.
      - Mid-Right: Material texture and environmental detail A.
      - Bottom-Left: Atmospheric lighting and mood detail B.
      - Bottom-Center: Macro shot of a key narrative prop.
      - Bottom-Right: Subjective Character POV (eye-level).

      Consistency: All 9 panels must share the exact same lighting, color palette, and architectural style. Cinematic 8k, professional concept design.
    `;

    try {
      // 切換至 generateContent 並使用 gemini-3-pro-image-preview 以確保更精準的佈局控制
      const response = await ai.models.generateContent({
        model: 'gemini-3-pro-image-preview',
        contents: { parts: [{ text: gridPrompt }] },
        config: { 
          imageConfig: { 
            aspectRatio: "1:1", 
            imageSize: "1K" 
          } 
        }
      });

      for (const part of response.candidates?.[0]?.content?.parts || []) {
        if (part.inlineData) {
          return `data:image/png;base64,${part.inlineData.data}`;
        }
      }
    } catch (error) {
      console.error("Grid generation failed:", error);
    }

    return "";
  }

  async generateVideo(prompt: string, onProgress: (status: string) => void): Promise<string | null> {
    const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
    try {
      onProgress("正在初始化拍攝設備...");
      let operation = await ai.models.generateVideos({
        model: 'veo-3.1-fast-generate-preview',
        prompt: prompt,
        config: { numberOfVideos: 1, resolution: '720p', aspectRatio: '16:9' }
      });
      while (!operation.done) {
        await new Promise(resolve => setTimeout(resolve, 10000));
        operation = await ai.operations.getVideosOperation({ operation: operation });
      }
      const downloadLink = operation.response?.generatedVideos?.[0]?.video?.uri;
      return downloadLink ? `${downloadLink}&key=${process.env.API_KEY}` : null;
    } catch (error) { return null; }
  }
}

