import React, { useState, useEffect, useCallback, useRef } from 'react';
import { ProductionPhase, Suggestion, ProjectState, GeneratedVideo, Message, ProjectDNA, StageDesign } from './types';
import { PHASE_METADATA } from './constants';
import { GeminiService } from './services/geminiService';
import { ApiKeySelector } from './components/ApiKeySelector';
import { 
  Film, Sparkles, Send, Loader2, ArrowRight, 
  Info, Clapperboard, Video, Layout, Palette, 
  ChevronRight, History, Save, Download, Upload,
  X, CheckCircle2, Monitor, BookOpen, Layers, Terminal, MapPin, Users, Target, Lightbulb,
  Undo2, Redo2, Wand2, Eye, Grid, Edit3, Image as ImageIcon, Briefcase, Trash2, Plus, 
  Compass, Map, Maximize2, DownloadCloud, RefreshCw, UserPlus
} from 'lucide-react';

const App: React.FC = () => {
  const [hasKey, setHasKey] = useState(false);
  const [isLoading, setIsLoading] = useState(false);
  const [isAnalyzing, setIsAnalyzing] = useState(false);
  const [isElaborating, setIsElaborating] = useState(false);
  const [input, setInput] = useState('');
  const [showHistory, setShowHistory] = useState(false);
  const [activeStep, setActiveStep] = useState<ProductionPhase>(ProductionPhase.INSPIRATION);
  const [expandedImage, setExpandedImage] = useState<string | null>(null);

  const [historyStack, setHistoryStack] = useState<ProjectDNA[]>([]);
  const [redoStack, setRedoStack] = useState<ProjectDNA[]>([]);

  const [stageHistoryStack, setStageHistoryStack] = useState<StageDesign[][]>([]);
  const [stageRedoStack, setStageRedoStack] = useState<StageDesign[][]>([]);

  const [tempDNA, setTempDNA] = useState<ProjectDNA>({
    format: '電影', style: '寫實電影感 (Realistic Cinematic)', story: '', ratio: '16:9',
    environment: '', socialBackground: '', coreNarrative: ''
  });

  const [project, setProject] = useState<ProjectState>({
    currentPhase: ProductionPhase.INSPIRATION,
    initialInput: '',
    dna: { format: '電影', style: '寫實電影感 (Realistic Cinematic)', story: '', ratio: '16:9', environment: '', socialBackground: '', coreNarrative: '' },
    suggestions: [], proposedStages: [], history: [], generatedVideos: [], sceneGrid: []
  });

  const fileInputRef = useRef<HTMLInputElement>(null);
  const geminiRef = useRef<GeminiService | null>(null);

  useEffect(() => {
    const checkKey = async () => {
      // @ts-ignore
      const exists = await window.aistudio.hasSelectedApiKey();
      if (exists) {
        setHasKey(true);
        geminiRef.current = new GeminiService(process.env.API_KEY || '');
      }
    };
    checkKey();
  }, []);

  useEffect(() => {
    if (activeStep === ProductionPhase.VISUAL_DEV && project.proposedStages.length === 0 && !isAnalyzing && geminiRef.current) {
      handleIdentifyStages(true); // 自動觸發時不詢問
    }
  }, [activeStep, project.proposedStages.length]);

  const handleIdentifyStages = async (isAuto = false) => {
    if (!geminiRef.current || isAnalyzing) return;

    if (!isAuto && project.proposedStages.length > 0 && !confirm("重新分析將清除目前所有的舞台塑造數據與視覺資產，確定嗎？")) {
      return;
    }

    setIsAnalyzing(true);
    setProject(prev => ({ 
      ...prev, 
      proposedStages: [], 
      selectedStageIndex: undefined, 
      sceneGrid: []
    }));

    try {
      const stages = await geminiRef.current.identifyCoreStages(project.dna);
      setProject(prev => ({ ...prev, proposedStages: stages }));
      setStageHistoryStack([stages]);
      setStageRedoStack([]);
    } catch (err) {
      console.error(err);
    } finally {
      setIsAnalyzing(false);
    }
  };

  const pushToStageUndo = (newStages: StageDesign[]) => {
    setStageHistoryStack(prev => [...prev, newStages]);
    setStageRedoStack([]);
  };

  const handleUndoStage = () => {
    if (stageHistoryStack.length <= 1) return;
    const current = stageHistoryStack[stageHistoryStack.length - 1];
    const prev = stageHistoryStack[stageHistoryStack.length - 2];
    setStageRedoStack(r => [current, ...r]);
    setStageHistoryStack(h => h.slice(0, -1));
    setProject(p => ({ ...p, proposedStages: prev }));
  };

  const handleRedoStage = () => {
    if (stageRedoStack.length === 0) return;
    const next = stageRedoStack[0];
    setStageRedoStack(r => r.slice(1));
    setStageHistoryStack(h => [...h, next]);
    setProject(p => ({ ...p, proposedStages: next }));
  };

  const handleRenderStageGrid = async (idx: number) => {
    if (!geminiRef.current) return;
    const stage = project.proposedStages[idx];
    setIsLoading(true);
    setProject(prev => ({ ...prev, selectedStageIndex: idx }));
    try {
      const gridResult = await geminiRef.current.generateSceneGrid(project.dna, stage);
      if (gridResult) {
        setProject(prev => {
          const newStages = [...prev.proposedStages];
          newStages[idx] = { ...newStages[idx], gridImage: gridResult };
          pushToStageUndo(newStages);
          return { ...prev, proposedStages: newStages };
        });
      }
    } catch (err) {
      console.error(err);
    } finally {
      setIsLoading(false);
    }
  };

  const updateStage = (idx: number, field: keyof StageDesign, value: string) => {
    const newStages = [...project.proposedStages];
    newStages[idx] = { ...newStages[idx], [field]: value };
    setProject(prev => ({ ...prev, proposedStages: newStages }));
  };

  const addStage = () => {
    const newStages = [...project.proposedStages, { name: '新舞台地點', description: '描述該舞台的角色基點、行動路徑與交匯邏輯...' }];
    setProject(prev => ({ ...prev, proposedStages: newStages }));
    pushToStageUndo(newStages);
  };

  const removeStage = (idx: number) => {
    const newStages = project.proposedStages.filter((_, i) => i !== idx);
    setProject(prev => ({ ...prev, proposedStages: newStages, selectedStageIndex: undefined }));
    pushToStageUndo(newStages);
  };

  const finalizeStageUpdate = () => {
    pushToStageUndo(project.proposedStages);
  };

  const handlePolishStage = async (idx: number) => {
    if (!geminiRef.current || isLoading) return;
    setIsLoading(true);
    try {
      const stage = project.proposedStages[idx];
      const polished = await geminiRef.current.polishText(stage.description, `舞台塑造：${stage.name}`);
      const newStages = [...project.proposedStages];
      newStages[idx] = { ...stage, description: polished };
      setProject(prev => ({ ...prev, proposedStages: newStages }));
      pushToStageUndo(newStages);
    } finally {
      setIsLoading(false);
    }
  };

  const saveProject = () => {
    const data = JSON.stringify(project, null, 2);
    const blob = new Blob([data], { type: 'application/json' });
    const url = URL.createObjectURL(blob);
    const link = document.createElement('a');
    link.href = url;
    link.download = `montage-project-${new Date().toISOString().slice(0, 10)}.json`;
    link.click();
    URL.revokeObjectURL(url);
  };

  const loadProject = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;
    const reader = new FileReader();
    reader.onload = (event) => {
      try {
        const data = JSON.parse(event.target?.result as string) as ProjectState;
        if (data.currentPhase && data.dna) {
          setProject({
            ...data,
            suggestions: data.suggestions || [],
            proposedStages: data.proposedStages || [],
            history: data.history || [],
            generatedVideos: data.generatedVideos || [],
            sceneGrid: data.sceneGrid || []
          });
          setActiveStep(data.currentPhase);
          setTempDNA(data.dna);
          if (data.currentPhase === ProductionPhase.INSPIRATION) {
            setInput(data.initialInput || '');
          }
        }
      } catch (err) {
        alert('檔案格式錯誤，請確保上傳正確的專案檔。');
      }
    };
    reader.readAsText(file);
    if (fileInputRef.current) fileInputRef.current.value = '';
  };

  const handleStepSwitch = (phase: ProductionPhase) => {
    setActiveStep(phase);
    if (phase === ProductionPhase.INSPIRATION) {
      setInput(project.initialInput || '');
    } else {
      const lastUserMsgForPhase = [...project.history].reverse().find(m => m.role === 'user' && m.phase === phase);
      if (lastUserMsgForPhase) {
        setInput(lastUserMsgForPhase.content);
      } else {
        setInput('');
      }
    }

    if (phase === ProductionPhase.PRODUCTION_PLAN) {
      setTempDNA(project.dna);
      setHistoryStack([project.dna]);
      setRedoStack([]);
    }

    setProject(prev => ({ ...prev, suggestions: [] }));
  };

  const handleSubmitIdea = async (e?: React.FormEvent) => {
    if (e) e.preventDefault();
    if (!input.trim() || isLoading || !geminiRef.current) return;

    setIsLoading(true);
    try {
      const results = await geminiRef.current.generateSuggestions(input, activeStep, JSON.stringify(project.dna));
      setProject(prev => ({ 
        ...prev, 
        suggestions: results || [], 
        initialInput: activeStep === ProductionPhase.INSPIRATION ? input : prev.initialInput,
        history: [...(prev.history || []), { role: 'user', content: input, phase: activeStep }]
      }));
    } catch (error) { 
      console.error(error); 
    } finally { 
      setIsLoading(false); 
    }
  };

  const handleSuggestionClick = async (s: Suggestion) => {
    if (!geminiRef.current) return;
    setIsElaborating(true);
    try {
      const detailedDNA = await geminiRef.current.elaboratePlan(s);
      setTempDNA(detailedDNA);
      setHistoryStack([detailedDNA]);
      setRedoStack([]);
      setProject(prev => ({
        ...prev,
        dna: detailedDNA,
        currentPhase: ProductionPhase.PRODUCTION_PLAN,
        suggestions: []
      }));
      setActiveStep(ProductionPhase.PRODUCTION_PLAN);
    } catch (error) {
      console.error(error);
    } finally {
      setIsElaborating(false);
    }
  };

  const pushToUndo = (newDNA: ProjectDNA) => {
    setHistoryStack(prev => [...prev, newDNA]);
    setRedoStack([]);
  };

  const handleUndo = () => {
    if (historyStack.length <= 1) return;
    const current = historyStack[historyStack.length - 1];
    const prev = historyStack[historyStack.length - 2];
    setRedoStack(r => [current, ...r]);
    setHistoryStack(h => h.slice(0, -1));
    setTempDNA(prev);
    setProject(p => ({ ...p, dna: prev }));
  };

  const handleRedo = () => {
    if (redoStack.length === 0) return;
    const next = redoStack[0];
    setRedoStack(r => r.slice(1));
    setHistoryStack(h => [...h, next]);
    setTempDNA(next);
    setProject(p => ({ ...p, dna: next }));
  };

  const handlePolish = async (field: keyof ProjectDNA, type: string) => {
    if (!geminiRef.current || isLoading) return;
    setIsLoading(true);
    try {
      const polished = await geminiRef.current.polishText(tempDNA[field] as string, type);
      const updated = { ...tempDNA, [field]: polished };
      setTempDNA(updated);
      pushToUndo(updated);
      setProject(p => ({ ...p, dna: updated }));
    } finally { 
      setIsLoading(false); 
    }
  };

  const confirmProductionPlan = async () => {
    if (!geminiRef.current) return;
    setIsLoading(true);

    try {
      const coreImage = await geminiRef.current.generateImage(`${tempDNA.story}. ${tempDNA.style}. Cinematic, 8k.`) || undefined;
      const nextPhase = ProductionPhase.VISUAL_DEV;

      setProject(prev => ({
        ...prev,
        currentPhase: nextPhase,
        dna: { ...tempDNA },
        history: [...(prev.history || []), { 
          role: 'assistant', 
          content: `【確認拍攝方案】\n已完成拍攝 DNA 的優化，核心視覺基調已確立。進入舞台塑造階段。`, 
          phase: ProductionPhase.PRODUCTION_PLAN 
        }],
        coreSceneImage: coreImage,
        proposedStages: [],
        selectedStageIndex: undefined,
        sceneGrid: []
      }));

      setActiveStep(nextPhase);
    } catch (error) {
      console.error(error);
    } finally { 
      setIsLoading(false); 
    }
  };

  const goToCharacterDev = () => {
    const nextPhase = ProductionPhase.CHARACTER_DEV;
    setProject(prev => ({
      ...prev,
      currentPhase: nextPhase,
      history: [...(prev.history || []), { 
        role: 'assistant', 
        content: `【舞台塑造完成】\n所有核心舞台視覺九宮格已開發完畢。接下來進入角色塑造階段，請描述您的主要角色特徵。`, 
        phase: ProductionPhase.VISUAL_DEV 
      }]
    }));
    setActiveStep(nextPhase);
  };

  const downloadImage = (base64: string, name: string) => {
    const link = document.createElement('a');
    link.href = base64;
    link.download = `${name}.png`;
    link.click();
  };

  const isAllGridsGenerated = project.proposedStages.length > 0 && project.proposedStages.every(s => !!s.gridImage);

  if (!hasKey) return <ApiKeySelector onSelected={() => { setHasKey(true); geminiRef.current = new GeminiService(process.env.API_KEY || ''); }} />;

  return (
    <div className="flex h-screen bg-[#050505] text-white overflow-hidden font-sans">
      {/* Expanded Image Modal */}
      {expandedImage && (
        <div className="fixed inset-0 bg-black/95 z-[100] flex flex-col items-center justify-center p-8 animate-in fade-in duration-300">
          <button onClick={() => setExpandedImage(null)} className="absolute top-8 right-8 p-3 bg-white/5 hover:bg-amber-600 rounded-full transition-all group">
            <X className="w-8 h-8 text-white group-hover:scale-110 transition-transform" />
          </button>
          <div className="relative max-w-7xl w-full max-h-full">
            <img src={expandedImage} className="w-full h-full object-contain shadow-2xl rounded-lg border border-white/10" />
            <button 
              onClick={() => downloadImage(expandedImage, 'montage-asset')}
              className="absolute bottom-4 right-4 flex items-center gap-2 bg-amber-600 hover:bg-amber-500 px-6 py-3 rounded-full font-bold shadow-xl transition-all"
            >
              <DownloadCloud className="w-5 h-5" />
              下載原始圖片
            </button>
          </div>
        </div>
      )}

      <aside className="w-64 border-r border-white/5 flex flex-col bg-black/40 p-6">
        <div className="flex items-center gap-3 mb-12">
          <div className="bg-amber-600 p-2 rounded-lg shadow-[0_0_15px_rgba(217,119,6,0.3)]"><Film className="w-6 h-6 text-white" /></div>
          <h1 className="text-lg font-serif font-bold tracking-widest text-white/90">電影蒙太奇</h1>
        </div>

        <nav className="flex-1 space-y-2">
          {Object.entries(PHASE_METADATA).map(([key, meta], idx) => {
            const phaseKey = key as ProductionPhase;
            const isActive = activeStep === phaseKey;
            const isAccessible = Object.values(ProductionPhase).indexOf(phaseKey) <= Object.values(ProductionPhase).indexOf(project.currentPhase);

            return (
              <button 
                key={key} 
                disabled={!isAccessible}
                onClick={() => handleStepSwitch(phaseKey)}
                className={`w-full relative flex items-center gap-4 p-3 rounded-lg transition-all text-left group
                  ${isActive ? 'bg-amber-600/20 text-amber-500 ring-1 ring-amber-600/30' : 'text-neutral-600 hover:text-neutral-400'}
                  ${!isAccessible ? 'opacity-30 grayscale cursor-not-allowed' : 'cursor-pointer'}
                `}
              >
                {isActive && <div className="absolute left-0 w-1 h-6 bg-amber-600 rounded-full" />}
                <span className="text-xl">{meta.icon}</span>
                <div className="flex flex-col">
                  <span className="text-[9px] uppercase tracking-tighter opacity-50">Step 0{idx+1}</span>
                  <span className="text-sm font-bold">{meta.title}</span>
                </div>
              </button>
            );
          })}
        </nav>

        <div className="mt-8 space-y-2 border-t border-white/5 pt-6">
          <button onClick={() => setShowHistory(true)} className="w-full flex items-center gap-3 px-3 py-2 text-xs text-neutral-400 hover:text-white transition-colors group">
            <History className="w-4 h-4 text-amber-600 group-hover:rotate-[-45deg] transition-transform" />
            <span>製作歷史</span>
          </button>
          <button onClick={saveProject} className="w-full flex items-center gap-3 px-3 py-2 text-xs text-neutral-400 hover:text-white transition-colors"><Download className="w-4 h-4" /> 匯出專案</button>
          <button onClick={() => fileInputRef.current?.click()} className="w-full flex items-center gap-3 px-3 py-2 text-xs text-neutral-400 hover:text-white transition-colors"><Upload className="w-4 h-4" /> 載入專案</button>
          <input type="file" ref={fileInputRef} onChange={loadProject} className="hidden" accept=".json" />
        </div>
      </aside>

      <main className="flex-1 flex flex-col relative overflow-hidden">
        <header className="h-16 px-8 border-b border-white/5 flex items-center justify-between z-10 bg-black/50 backdrop-blur-md">
          <div className="flex items-center gap-2">
            <Terminal className="w-4 h-4 text-amber-600" />
            <span className="text-[10px] text-neutral-500 uppercase tracking-[0.2em]">TERMINAL</span>
            <ChevronRight className="w-3 h-3 text-neutral-600" />
            <span className="text-sm font-bold text-amber-500 uppercase">{PHASE_METADATA[activeStep]?.title}</span>
          </div>
          <div className="flex items-center gap-4">
            {activeStep === ProductionPhase.VISUAL_DEV && (
              <div className="flex items-center gap-4">
                <div className="flex items-center gap-2 bg-white/5 p-1 rounded-full px-2 border border-white/5">
                  <button 
                    onClick={() => handleIdentifyStages(false)} 
                    disabled={isAnalyzing} 
                    className="p-2 hover:bg-amber-600 rounded-full disabled:opacity-20 transition-all text-neutral-400 hover:text-white" 
                    title="重新分析舞台"
                  >
                    <RefreshCw className={`w-3.5 h-3.5 ${isAnalyzing ? 'animate-spin text-amber-500' : ''}`} />
                  </button>
                  <div className="w-px h-4 bg-white/10 mx-1" />
                  <button onClick={handleUndoStage} disabled={stageHistoryStack.length <= 1} className="p-2 hover:bg-amber-600 rounded-full disabled:opacity-20 transition-all" title="復原"><Undo2 className="w-3.5 h-3.5" /></button>
                  <button onClick={handleRedoStage} disabled={stageRedoStack.length === 0} className="p-2 hover:bg-amber-600 rounded-full disabled:opacity-20 transition-all" title="重做"><Redo2 className="w-3.5 h-3.5" /></button>
                </div>
                <button 
                  onClick={goToCharacterDev}
                  disabled={!isAllGridsGenerated || isLoading}
                  className={`px-6 py-2 rounded-full text-[11px] font-bold flex items-center gap-2 shadow-lg transition-all ${
                    isAllGridsGenerated 
                    ? 'bg-amber-600 hover:bg-amber-500 text-white' 
                    : 'bg-neutral-800 text-neutral-500 cursor-not-allowed opacity-50'
                  }`}
                >
                  <UserPlus className="w-3.5 h-3.5" />
                  進行角色塑造
                </button>
              </div>
            )}
            {activeStep === ProductionPhase.PRODUCTION_PLAN && !isElaborating && (
              <button onClick={confirmProductionPlan} disabled={isLoading} className="bg-amber-600 hover:bg-amber-500 px-6 py-2 rounded-full text-[11px] font-bold flex items-center gap-2 shadow-lg transition-all">
                {isLoading ? <Loader2 className="w-3.5 h-3.5 animate-spin" /> : <CheckCircle2 className="w-3.5 h-3.5" />}
                確認方案並塑造舞台
              </button>
            )}
          </div>
        </header>

        <section className="flex-1 flex flex-col items-center justify-start p-8 max-w-5xl mx-auto w-full overflow-y-auto">
          {activeStep === ProductionPhase.INSPIRATION && (
            <div className="w-full max-w-2xl mt-20 mb-12">
              <div className="flex flex-col items-center text-center space-y-4 mb-8">
                <h2 className="text-xl md:text-2xl font-serif leading-relaxed text-neutral-100 whitespace-nowrap">{PHASE_METADATA[activeStep]?.guide}</h2>
              </div>
              <form onSubmit={handleSubmitIdea} className="relative group">
                <textarea 
                  value={input} onChange={(e) => setInput(e.target.value)}
                  placeholder="在此輸入您的創意指令..."
                  rows={3}
                  className="w-full bg-white/5 border border-white/10 p-5 pr-16 rounded-2xl focus:outline-none focus:ring-2 focus:ring-amber-600/50 text-lg shadow-2xl transition-all resize-none"
                />
                <button type="submit" disabled={isLoading || !input.trim()} className="absolute right-3 top-3 bg-amber-600 hover:bg-amber-500 p-3 rounded-xl transition-all shadow-lg">
                  {isLoading ? <Loader2 className="w-6 h-6 animate-spin" /> : <Sparkles className="w-6 h-6" />}
                </button>
              </form>

              {isElaborating && (
                <div className="mt-20 flex flex-col items-center gap-4 animate-pulse">
                   <Loader2 className="w-10 h-10 text-amber-600 animate-spin" />
                   <p className="text-amber-500 text-[11px] font-bold uppercase tracking-[0.4em]">正在為您構建完整的電影拍攝 DNA...</p>
                </div>
              )}

              {!isElaborating && (project.suggestions?.length || 0) > 0 && (
                <div className="w-full grid grid-cols-1 md:grid-cols-3 gap-6 mt-16 animate-in fade-in slide-in-from-bottom-8">
                  {project.suggestions.map((s, i) => (
                    <button key={i} onClick={() => handleSuggestionClick(s)} className="btn-montage glass p-8 rounded-2xl text-center border-white/5 hover:border-amber-600/50 group">
                      <div className="text-[10px] text-amber-500 font-bold mb-4 opacity-0 group-hover:opacity-100 uppercase tracking-widest">提案 Proposal {i+1}</div>
                      <h3 className="text-lg font-serif font-bold mb-4 line-clamp-2 h-14 flex items-center justify-center">{s.title}</h3>
                      <div className="flex flex-wrap justify-center gap-1.5 mt-2">
                        {s.tags?.map(t => <span key={t} className="text-[9px] bg-amber-900/30 px-2 py-0.5 rounded text-amber-200/60 border border-amber-600/10">#{t}</span>)}
                      </div>
                    </button>
                  ))}
                </div>
              )}
            </div>
          )}

          {activeStep === ProductionPhase.PRODUCTION_PLAN && (
            <div className="w-full space-y-12 animate-in fade-in slide-in-from-top-4 duration-700 pb-20">
              <div className="text-center space-y-4">
                <h2 className="text-3xl font-serif leading-relaxed text-neutral-100">優化拍攝 DNA</h2>
                <div className="flex justify-center gap-4">
                  <button onClick={handleUndo} disabled={historyStack.length <= 1} className="p-2 bg-white/5 rounded-lg hover:bg-amber-600 disabled:opacity-20 transition-all"><Undo2 className="w-4 h-4" /></button>
                  <button onClick={handleRedo} disabled={redoStack.length === 0} className="p-2 bg-white/5 rounded-lg hover:bg-amber-600 disabled:opacity-20 transition-all"><Redo2 className="w-4 h-4" /></button>
                </div>
              </div>

              <div className="grid grid-cols-1 lg:grid-cols-2 gap-12">
                <div className="space-y-8">
                  {[
                    { id: 'coreNarrative', label: '核心敘事', icon: <Target className="w-3 h-3" /> },
                    { id: 'socialBackground', label: '社會背景', icon: <Users className="w-3 h-3" /> },
                    { id: 'environment', label: '地理環境', icon: <MapPin className="w-3 h-3" /> }
                  ].map(field => (
                    <div key={field.id} className="group relative">
                      <div className="flex justify-between items-center mb-3">
                        <label className="flex items-center gap-2 text-[10px] font-bold text-neutral-500 uppercase tracking-widest">{field.icon} {field.label}</label>
                        <button onClick={() => handlePolish(field.id as keyof ProjectDNA, field.label)} className="flex items-center gap-1.5 text-[9px] bg-amber-600/10 hover:bg-amber-600 text-amber-500 hover:text-white px-2 py-1 rounded-md transition-all opacity-0 group-hover:opacity-100"><Wand2 className="w-3 h-3" /> AI 潤色</button>
                      </div>
                      <textarea 
                        value={tempDNA[field.id as keyof ProjectDNA] || ''}
                        onChange={(e) => {
                          const updated = { ...tempDNA, [field.id]: e.target.value };
                          setTempDNA(updated);
                          pushToUndo(updated);
                          setProject(p => ({ ...p, dna: updated }));
                        }}
                        rows={6}
                        className="w-full bg-white/5 border border-white/10 rounded-xl p-4 text-sm text-neutral-300 outline-none focus:ring-1 focus:ring-amber-500 transition-all leading-relaxed"
                      />
                    </div>
                  ))}
                </div>
                <div className="space-y-8">
                  <div className="space-y-3 group">
                    <div className="flex justify-between items-center">
                      <label className="flex items-center gap-2 text-[10px] font-bold text-neutral-500 uppercase tracking-widest"><BookOpen className="w-3 h-3" /> 劇本摘要</label>
                      <button onClick={() => handlePolish('story', '劇本摘要')} className="flex items-center gap-1.5 text-[9px] bg-amber-600/10 hover:bg-amber-600 text-amber-500 hover:text-white px-2 py-1 rounded-md opacity-0 group-hover:opacity-100 transition-all"><Wand2 className="w-3 h-3" /> AI 潤色</button>
                    </div>
                    <textarea 
                      value={tempDNA.story || ''}
                      onChange={(e) => {
                        const updated = { ...tempDNA, story: e.target.value };
                        setTempDNA(updated);
                        pushToUndo(updated);
                        setProject(p => ({ ...p, dna: updated }));
                      }}
                      rows={22}
                      className="w-full bg-white/5 border border-white/10 rounded-2xl p-6 text-sm focus:ring-1 focus:ring-amber-500 outline-none leading-relaxed font-serif text-neutral-300 transition-all"
                    />
                  </div>
                </div>
              </div>
            </div>
          )}

          {activeStep === ProductionPhase.VISUAL_DEV && (
            <div className="w-full space-y-12 animate-in fade-in slide-in-from-top-4 duration-700 pb-20">
              <div className="text-center space-y-4">
                <h2 className="text-3xl font-serif leading-relaxed text-neutral-100">{PHASE_METADATA[activeStep]?.guide}</h2>
                <p className="text-sm text-neutral-500 max-w-xl mx-auto">AI 已識別故事中的主角活動集群與路徑邏輯，請針對核心舞台進行九宮格視覺開發。</p>
              </div>
              {isAnalyzing ? (
                <div className="py-20 flex flex-col items-center gap-6">
                  <div className="relative"><Loader2 className="w-12 h-12 text-amber-600 animate-spin" /><Sparkles className="absolute -top-2 -right-2 w-6 h-6 text-amber-400 animate-pulse" /></div>
                  <p className="text-amber-500 text-xs font-bold uppercase tracking-[0.3em]">AI 正在識別核心舞台集群並同步開發數據...</p>
                </div>
              ) : (
                <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
                  {project.proposedStages.map((stage, idx) => (
                    <div key={idx} className={`glass p-6 rounded-2xl border-white/5 transition-all group flex flex-col relative hover:border-amber-600/30 ${project.selectedStageIndex === idx ? 'ring-2 ring-amber-600 border-transparent shadow-[0_0_20px_rgba(217,119,6,0.15)]' : ''}`}>
                      <div className="flex items-center justify-between mb-4">
                        <div className="flex items-center gap-2">
                           <MapPin className="w-3.5 h-3.5 text-amber-600" />
                           <span className="text-[10px] font-bold text-neutral-500 uppercase font-mono">STAGE 0{idx+1}</span>
                        </div>
                        <div className="flex items-center gap-2">
                           <button onClick={() => handlePolishStage(idx)} disabled={isLoading} className="flex items-center gap-1 text-[9px] bg-amber-600/10 hover:bg-amber-600 text-amber-500 hover:text-white px-2 py-1 rounded transition-all opacity-0 group-hover:opacity-100"><Wand2 className="w-3 h-3" /> AI 潤色</button>
                           <button onClick={() => removeStage(idx)} className="text-neutral-600 hover:text-red-500 transition-colors opacity-0 group-hover:opacity-100"><Trash2 className="w-3.5 h-3.5" /></button>
                           <Edit3 className="w-3.5 h-3.5 text-neutral-600" />
                        </div>
                      </div>
                      <input className="bg-transparent border-none text-neutral-100 font-serif font-bold text-lg mb-2 focus:ring-0 w-full" value={stage.name} onChange={(e) => updateStage(idx, 'name', e.target.value)} onBlur={finalizeStageUpdate} placeholder="舞台地點名稱" />
