  const [historyStack, setHistoryStack] = useState<ProjectDNA[]>([]);
  const [redoStack, setRedoStack] = useState<ProjectDNA[]>([]);

  const [stageHistoryStack, setStageHistoryStack] = useState<StageDesign[][]>([]);
  const [charHistoryStack, setCharHistoryStack] = useState<CharacterDesign[][]>([]);

  const [tempDNA, setTempDNA] = useState<ProjectDNA>({
    format: '電影', style: '寫實電影感 (Realistic Cinematic)', story: '', ratio: '16:9',
    environment: '', socialBackground: '', coreNarrative: ''
  });

  const [project, setProject] = useState<ProjectState>({
    currentPhase: ProductionPhase.INSPIRATION,
    initialInput: '',
    dna: { format: '電影', style: '寫實電影感 (Realistic Cinematic)', story: '', ratio: '16:9', environment: '', socialBackground: '', coreNarrative: '' },
    suggestions: [], proposedStages: [], proposedCharacters: [], history: [], generatedVideos: [], sceneGrid: []
  });

  const fileInputRef = useRef<HTMLInputElement>(null);
  const geminiRef = useRef<GeminiService | null>(null);

  useEffect(() => {
    const checkKey = async () => {
      // @ts-ignore
      const exists = await window.aistudio.hasSelectedApiKey();
      if (exists) {
        setHasKey(true);
        geminiRef.current = new GeminiService(process.env.API_KEY || '');
      }
    };
    checkKey();
  }, []);

  useEffect(() => {
    if (activeStep === ProductionPhase.VISUAL_DEV && project.proposedStages.length === 0 && !isAnalyzing && geminiRef.current) {
      handleIdentifyStages(true);
    }
    if (activeStep === ProductionPhase.CHARACTER_DEV && project.proposedCharacters.length === 0 && !isAnalyzing && geminiRef.current) {
      handleAutoAnalyzeCharacters();
    }
  }, [activeStep, project.proposedStages.length, project.proposedCharacters.length]);

  const handleIdentifyStages = async (isAuto = false) => {
    if (!geminiRef.current || isAnalyzing) return;
    if (!isAuto && project.proposedStages.length > 0 && !confirm("重新分析將清除目前所有的舞台資產，確定嗎？")) return;

    setIsAnalyzing(true);
    setProject(prev => ({ ...prev, proposedStages: [], selectedStageIndex: undefined }));
    try {
      const stages = await geminiRef.current.identifyCoreStages(project.dna);
      setProject(prev => ({ ...prev, proposedStages: stages }));
      setStageHistoryStack([stages]);
    } catch (err) { console.error(err); } finally { setIsAnalyzing(false); }
  };

  const handleAutoAnalyzeCharacters = async () => {
    if (!geminiRef.current || isAnalyzing) return;
    setIsAnalyzing(true);
    setProject(prev => ({ ...prev, proposedCharacters: [], selectedCharacterIndex: undefined }));
    try {
      const chars = await geminiRef.current.analyzeCharacters(project.dna);
      setProject(prev => ({ ...prev, proposedCharacters: chars }));
      setCharHistoryStack([chars]);
    } catch (err) { console.error(err); } finally { setIsAnalyzing(false); }
  };

  const handleRenderStageGrid = async (idx: number) => {
    if (!geminiRef.current) return;
    const stage = project.proposedStages[idx];
    setIsLoading(true);
    setProject(prev => ({ ...prev, selectedStageIndex: idx }));
    try {
      const gridResult = await geminiRef.current.generateSceneGrid(project.dna, stage);
      if (gridResult) {
        setProject(prev => {
          const newStages = [...prev.proposedStages];
          newStages[idx] = { ...newStages[idx], gridImage: gridResult };
          return { ...prev, proposedStages: newStages };
        });
      }
    } finally { setIsLoading(false); }
  };

  const handleRenderCharacterGrid = async (idx: number) => {
    if (!geminiRef.current) return;
    const character = project.proposedCharacters[idx];
    setIsLoading(true);
    setProject(prev => ({ ...prev, selectedCharacterIndex: idx }));
    try {
      const gridResult = await geminiRef.current.generateCharacterGrid(project.dna, character);
      if (gridResult) {
        setProject(prev => {
          const newChars = [...prev.proposedCharacters];
          newChars[idx] = { ...newChars[idx], gridImage: gridResult };
          return { ...prev, proposedCharacters: newChars };
        });
      }
    } finally { setIsLoading(false); }
  };

  const updateStage = (idx: number, field: keyof StageDesign, value: string) => {
    const newStages = [...project.proposedStages];
    newStages[idx] = { ...newStages[idx], [field]: value };
    setProject(prev => ({ ...prev, proposedStages: newStages }));
  };

  const updateCharacter = (idx: number, field: keyof CharacterDesign, value: string) => {
    const newChars = [...project.proposedCharacters];
    newChars[idx] = { ...newChars[idx], [field]: value };
    setProject(prev => ({ ...prev, proposedCharacters: newChars }));
  };

  const handlePolishChar = async (idx: number, field: keyof CharacterDesign, label: string) => {
    if (!geminiRef.current || isLoading) return;
    setIsLoading(true);
    try {
      const char = project.proposedCharacters[idx];
      const polished = await geminiRef.current.polishText(char[field] as string, `角色塑造（${char.name}）之${label}`);
      updateCharacter(idx, field, polished);
    } finally { setIsLoading(false); }
  };

  const saveProject = () => {
    const data = JSON.stringify(project, null, 2);
    const blob = new Blob([data], { type: 'application/json' });
    const url = URL.createObjectURL(blob);
    const link = document.createElement('a');
    link.href = url;
    link.download = `montage-project-${new Date().toISOString().slice(0, 10)}.json`;
    link.click();
  };

  const handleStepSwitch = (phase: ProductionPhase) => {
    setActiveStep(phase);
    if (phase === ProductionPhase.PRODUCTION_PLAN) setTempDNA(project.dna);
    setProject(prev => ({ ...prev, suggestions: [] }));
  };

  const handleSubmitIdea = async (e?: React.FormEvent) => {
    if (e) e.preventDefault();
    if (!input.trim() || isLoading || !geminiRef.current) return;
    setIsLoading(true);
    try {
      const results = await geminiRef.current.generateSuggestions(input, activeStep, JSON.stringify(project.dna));
      setProject(prev => ({ 
        ...prev, suggestions: results || [], 
        initialInput: activeStep === ProductionPhase.INSPIRATION ? input : prev.initialInput,
        history: [...(prev.history || []), { role: 'user', content: input, phase: activeStep }]
      }));
    } finally { setIsLoading(false); }
  };

  const handleSuggestionClick = async (s: Suggestion) => {
    if (!geminiRef.current) return;
    setIsElaborating(true);
    try {
      const detailedDNA = await geminiRef.current.elaboratePlan(s);
      setTempDNA(detailedDNA);
      setProject(prev => ({
        ...prev, dna: detailedDNA, currentPhase: ProductionPhase.PRODUCTION_PLAN, suggestions: []
      }));
      setActiveStep(ProductionPhase.PRODUCTION_PLAN);
    } finally { setIsElaborating(false); }
  };

  const confirmProductionPlan = async () => {
    if (!geminiRef.current) return;
    setIsLoading(true);
    try {
      const coreImage = await geminiRef.current.generateImage(`${tempDNA.story}. ${tempDNA.style}. Cinematic, 8k.`) || undefined;
      setProject(prev => ({
        ...prev, currentPhase: ProductionPhase.VISUAL_DEV, dna: { ...tempDNA }, coreSceneImage: coreImage,
        proposedStages: [], sceneGrid: []
      }));
      setActiveStep(ProductionPhase.VISUAL_DEV);
    } finally { setIsLoading(false); }
  };

  const goToCharacterDev = () => {
    setProject(prev => ({ ...prev, currentPhase: ProductionPhase.CHARACTER_DEV }));
    setActiveStep(ProductionPhase.CHARACTER_DEV);
  };

  const goToStoryArch = () => {
    setProject(prev => ({ ...prev, currentPhase: ProductionPhase.STORY_ARCH }));
    setActiveStep(ProductionPhase.STORY_ARCH);
  };

  const downloadImage = (base64: string, name: string) => {
    const link = document.createElement('a');
    link.href = base64;
    link.download = `${name}.png`;
    link.click();
  };

  const isAllStageGridsGenerated = project.proposedStages.length > 0 && project.proposedStages.every(s => !!s.gridImage);
  const isAllCharGridsGenerated = project.proposedCharacters.length > 0 && project.proposedCharacters.every(c => !!c.gridImage);

  if (!hasKey) return <ApiKeySelector onSelected={() => setHasKey(true)} />;

  return (
    <div className="flex h-screen bg-[#050505] text-white overflow-hidden font-sans">
      {expandedImage && (
        <div className="fixed inset-0 bg-black/95 z-[100] flex flex-col items-center justify-center p-8 animate-in fade-in duration-300">
          <button onClick={() => setExpandedImage(null)} className="absolute top-8 right-8 p-3 bg-white/5 hover:bg-amber-600 rounded-full transition-all group">
            <X className="w-8 h-8 text-white group-hover:scale-110" />
          </button>
          <div className="relative max-w-7xl w-full max-h-full">
            <img src={expandedImage} className="w-full h-full object-contain shadow-2xl rounded-lg border border-white/10" />
            <button onClick={() => downloadImage(expandedImage, 'montage-asset')} className="absolute bottom-4 right-4 flex items-center gap-2 bg-amber-600 hover:bg-amber-500 px-6 py-3 rounded-full font-bold">
              <DownloadCloud className="w-5 h-5" /> 下載原始圖片
            </button>
          </div>
        </div>
      )}

      <aside className="w-64 border-r border-white/5 flex flex-col bg-black/40 p-6">
        <div className="flex items-center gap-3 mb-12">
          <div className="bg-amber-600 p-2 rounded-lg shadow-[0_0_15px_rgba(217,119,6,0.3)]"><Film className="w-6 h-6 text-white" /></div>
          <h1 className="text-lg font-serif font-bold tracking-widest text-white/90">電影蒙太奇</h1>
        </div>
        <nav className="flex-1 space-y-2">
          {Object.entries(PHASE_METADATA).map(([key, meta], idx) => {
            const phaseKey = key as ProductionPhase;
            const isActive = activeStep === phaseKey;
            const isAccessible = Object.values(ProductionPhase).indexOf(phaseKey) <= Object.values(ProductionPhase).indexOf(project.currentPhase);
            return (
              <button key={key} disabled={!isAccessible} onClick={() => handleStepSwitch(phaseKey)} className={`w-full relative flex items-center gap-4 p-3 rounded-lg transition-all text-left ${isActive ? 'bg-amber-600/20 text-amber-500 ring-1 ring-amber-600/30' : 'text-neutral-600 hover:text-neutral-400'} ${!isAccessible ? 'opacity-30 grayscale cursor-not-allowed' : 'cursor-pointer'}`}>
                {isActive && <div className="absolute left-0 w-1 h-6 bg-amber-600 rounded-full" />}
                <span className="text-xl">{meta.icon}</span>
                <div className="flex flex-col"><span className="text-[9px] uppercase tracking-tighter opacity-50">Step 0{idx+1}</span><span className="text-sm font-bold">{meta.title}</span></div>
              </button>
            );
          })}
        </nav>
        <div className="mt-8 space-y-2 border-t border-white/5 pt-6">
          <button onClick={() => setShowHistory(true)} className="w-full flex items-center gap-3 px-3 py-2 text-xs text-neutral-400 hover:text-white group"><History className="w-4 h-4 text-amber-600" /><span>製作歷史</span></button>
          <button onClick={saveProject} className="w-full flex items-center gap-3 px-3 py-2 text-xs text-neutral-400 hover:text-white"><Download className="w-4 h-4" /> 匯出專案</button>
        </div>
      </aside>

      <main className="flex-1 flex flex-col relative overflow-hidden">
        <header className="h-16 px-8 border-b border-white/5 flex items-center justify-between z-10 bg-black/50 backdrop-blur-md">
          <div className="flex items-center gap-2"><Terminal className="w-4 h-4 text-amber-600" /><span className="text-[10px] text-neutral-500 uppercase tracking-[0.2em]">TERMINAL</span><ChevronRight className="w-3 h-3 text-neutral-600" /><span className="text-sm font-bold text-amber-500 uppercase">{PHASE_METADATA[activeStep]?.title}</span></div>
          <div className="flex items-center gap-4">
            {activeStep === ProductionPhase.VISUAL_DEV && (
              <button onClick={goToCharacterDev} disabled={!isAllStageGridsGenerated || isLoading} className={`px-6 py-2 rounded-full text-[11px] font-bold flex items-center gap-2 shadow-lg transition-all ${isAllStageGridsGenerated ? 'bg-amber-600 hover:bg-amber-500 text-white' : 'bg-neutral-800 text-neutral-500 opacity-50'}`}>
                <UserPlus className="w-3.5 h-3.5" /> 進行角色塑造
              </button>
            )}
            {activeStep === ProductionPhase.CHARACTER_DEV && (
              <button onClick={goToStoryArch} disabled={!isAllCharGridsGenerated || isLoading} className={`px-6 py-2 rounded-full text-[11px] font-bold flex items-center gap-2 shadow-lg transition-all ${isAllCharGridsGenerated ? 'bg-amber-600 hover:bg-amber-500 text-white' : 'bg-neutral-800 text-neutral-500 opacity-50'}`}>
                <ArrowRight className="w-3.5 h-3.5" /> 蒙太奇敘事結構
              </button>
            )}
            {activeStep === ProductionPhase.PRODUCTION_PLAN && !isElaborating && (
              <button onClick={confirmProductionPlan} disabled={isLoading} className="bg-amber-600 hover:bg-amber-500 px-6 py-2 rounded-full text-[11px] font-bold flex items-center gap-2 shadow-lg transition-all">
                {isLoading ? <Loader2 className="w-3.5 h-3.5 animate-spin" /> : <CheckCircle2 className="w-3.5 h-3.5" />} 確認方案並塑造舞台
              </button>
            )}
          </div>
        </header>

        <section className="flex-1 flex flex-col items-center justify-start p-8 max-w-5xl mx-auto w-full overflow-y-auto">
          {activeStep === ProductionPhase.INSPIRATION && (
            <div className="w-full max-w-2xl mt-20 mb-12">
              <h2 className="text-xl md:text-2xl font-serif text-center mb-8">{PHASE_METADATA[activeStep]?.guide}</h2>
              <form onSubmit={handleSubmitIdea} className="relative group">
                <textarea value={input} onChange={(e) => setInput(e.target.value)} placeholder="在此輸入您的創意指令..." rows={3} className="w-full bg-white/5 border border-white/10 p-5 rounded-2xl text-lg resize-none" />
                <button type="submit" disabled={isLoading || !input.trim()} className="absolute right-3 top-3 bg-amber-600 p-3 rounded-xl shadow-lg">
                  {isLoading ? <Loader2 className="w-6 h-6 animate-spin" /> : <Sparkles className="w-6 h-6" />}
                </button>
              </form>
              {!isElaborating && project.suggestions?.length > 0 && (
                <div className="w-full grid grid-cols-1 md:grid-cols-3 gap-6 mt-16 animate-in slide-in-from-bottom-8">
                  {project.suggestions.map((s, i) => (
                    <button key={i} onClick={() => handleSuggestionClick(s)} className="glass p-8 rounded-2xl text-center border-white/5 hover:border-amber-600 group">
                      <h3 className="text-lg font-serif font-bold mb-4 line-clamp-2 h-14 flex items-center justify-center">{s.title}</h3>
                      <div className="flex flex-wrap justify-center gap-1.5">{s.tags?.map(t => <span key={t} className="text-[9px] bg-amber-900/30 px-2 py-0.5 rounded text-amber-200/60 border border-amber-600/10">#{t}</span>)}</div>
                    </button>
                  ))}
                </div>
              )}
            </div>
          )}

          {activeStep === ProductionPhase.VISUAL_DEV && (
            <div className="w-full space-y-12 pb-20">
              <div className="text-center space-y-4">
                <h2 className="text-3xl font-serif">{PHASE_METADATA[activeStep]?.guide}</h2>
                <p className="text-sm text-neutral-500">AI 已識別故事中的主角活動地理集群，請渲染舞台視覺九宮格。</p>
              </div>
              {isAnalyzing ? (
                <div className="py-20 flex flex-col items-center gap-6"><Loader2 className="w-12 h-12 text-amber-600 animate-spin" /><p className="text-amber-500 text-xs font-bold uppercase tracking-[0.3em]">AI 正在識別核心舞台...</p></div>
              ) : (
                <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
                  {project.proposedStages.map((stage, idx) => (
                    <div key={idx} className={`glass p-6 rounded-2xl transition-all group border-white/5 flex flex-col ${project.selectedStageIndex === idx ? 'ring-2 ring-amber-600' : ''}`}>
                      <div className="flex items-center justify-between mb-4"><div className="flex items-center gap-2"><MapPin className="w-3.5 h-3.5 text-amber-600" /><span className="text-[10px] font-bold text-neutral-500 uppercase">STAGE 0{idx+1}</span></div></div>
                      <input className="bg-transparent border-none text-neutral-100 font-serif font-bold text-lg mb-2 focus:ring-0 w-full" value={stage.name} onChange={(e) => updateStage(idx, 'name', e.target.value)} />
                      <textarea className="w-full bg-white/5 rounded-xl p-3 text-[11px] text-neutral-400 focus:text-neutral-200 outline-none resize-none flex-1 mb-4" rows={6} value={stage.description} onChange={(e) => updateStage(idx, 'description', e.target.value)} />
                      <button onClick={() => handleRenderStageGrid(idx)} disabled={isLoading} className="w-full py-2 bg-amber-600/10 hover:bg-amber-600 text-amber-500 hover:text-white rounded-lg text-[11px] font-bold flex items-center justify-center gap-2">
                        {isLoading && project.selectedStageIndex === idx ? <Loader2 className="w-3.5 h-3.5 animate-spin" /> : <Grid className="w-3.5 h-3.5" />} 渲染舞台九宮格
                      </button>
                    </div>
                  ))}
                </div>
              )}
              {project.selectedStageIndex !== undefined && project.proposedStages[project.selectedStageIndex]?.gridImage && (
                <div className="space-y-6 pt-12 border-t border-white/5 animate-in zoom-in-95">
                  <div className="flex items-center justify-between"><h3 className="text-xs font-bold text-amber-500 uppercase tracking-widest">{project.proposedStages[project.selectedStageIndex]?.name} 九宮格資產</h3></div>
                  <div className="aspect-square max-w-2xl mx-auto rounded-3xl overflow-hidden border border-white/10 shadow-2xl cursor-zoom-in" onClick={() => setExpandedImage(project.proposedStages[project.selectedStageIndex!]?.gridImage || null)}>
                    <img src={project.proposedStages[project.selectedStageIndex!]?.gridImage} className="w-full h-full object-cover" />
                  </div>
                </div>
              )}
            </div>
          )}

          {activeStep === ProductionPhase.CHARACTER_DEV && (
            <div className="w-full space-y-12 pb-20">
              <div className="text-center space-y-4">
                <h2 className="text-3xl font-serif">塑造核心角色形象</h2>
                <p className="text-sm text-neutral-500">AI 已根據劇本提取關鍵角色，請優化他們的外貌、材質與動作特徵。</p>
              </div>
              {isAnalyzing ? (
                <div className="py-20 flex flex-col items-center gap-6"><Loader2 className="w-12 h-12 text-amber-600 animate-spin" /><p className="text-amber-500 text-xs font-bold uppercase tracking-[0.3em]">AI 正在設計角色原型...</p></div>
              ) : (
                <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-8">
                  {project.proposedCharacters.map((char, idx) => (
                    <div key={idx} className={`glass p-8 rounded-3xl transition-all border-white/5 flex flex-col relative ${project.selectedCharacterIndex === idx ? 'ring-2 ring-amber-600' : ''}`}>
                      <div className="flex items-center justify-between mb-6">
                        <div className="flex items-center gap-2"><Users className="w-4 h-4 text-amber-600" /><span className="text-[10px] font-bold text-neutral-500 uppercase tracking-widest">{char.role}</span></div>
                        <PersonStanding className="w-5 h-5 text-neutral-700" />
                      </div>
                      <input className="bg-transparent border-none text-neutral-100 font-serif font-bold text-2xl mb-6 focus:ring-0 w-full" value={char.name} onChange={(e) => updateCharacter(idx, 'name', e.target.value)} placeholder="角色姓名" />

                      <div className="space-y-6 mb-8 flex-1">
                        {[
                          { id: 'physicalTraits', label: '外貌特徵', icon: <Eye className="w-3 h-3" /> },
                          { id: 'visualTone', label: '外觀材質色調', icon: <Palette className="w-3 h-3" /> },
                          { id: 'motivation', label: '內在動機與表情動作', icon: <Target className="w-3 h-3" /> }
                        ].map(f => (
                          <div key={f.id} className="group/field">
                            <div className="flex justify-between items-center mb-2">
                              <label className="text-[9px] font-bold text-neutral-500 uppercase flex items-center gap-1.5">{f.icon} {f.label}</label>
                              <button onClick={() => handlePolishChar(idx, f.id as keyof CharacterDesign, f.label)} className="opacity-0 group-hover/field:opacity-100 text-amber-500 hover:text-white transition-all"><Wand2 className="w-3 h-3" /></button>
                            </div>
                            <textarea value={char[f.id as keyof CharacterDesign] || ''} onChange={(e) => updateCharacter(idx, f.id as keyof CharacterDesign, e.target.value)} rows={4} className="w-full bg-white/5 rounded-xl p-3 text-xs text-neutral-400 focus:text-neutral-200 outline-none resize-none leading-relaxed" />
                          </div>
                        ))}
                      </div>

                      <button onClick={() => handleRenderCharacterGrid(idx)} disabled={isLoading} className="w-full py-3 bg-amber-600/10 hover:bg-amber-600 text-amber-500 hover:text-white rounded-xl text-xs font-bold flex items-center justify-center gap-2 transition-all">
                        {isLoading && project.selectedCharacterIndex === idx ? <Loader2 className="w-4 h-4 animate-spin" /> : <Grid className="w-4 h-4" />} 渲染角色形象九宮格
                      </button>
                    </div>
                  ))}
                </div>
              )}

              {project.selectedCharacterIndex !== undefined && project.proposedCharacters[project.selectedCharacterIndex]?.gridImage && (
                <div className="space-y-6 pt-12 border-t border-white/5 animate-in zoom-in-95">
                  <div className="flex items-center justify-between"><h3 className="text-xs font-bold text-amber-500 uppercase tracking-widest">{project.proposedCharacters[project.selectedCharacterIndex]?.name} 的視覺原型九宮格</h3></div>
                  <div className="aspect-square max-w-2xl mx-auto rounded-3xl overflow-hidden border border-white/10 shadow-2xl cursor-zoom-in" onClick={() => setExpandedImage(project.proposedCharacters[project.selectedCharacterIndex!]?.gridImage || null)}>
                    <img src={project.proposedCharacters[project.selectedCharacterIndex!]?.gridImage} className="w-full h-full object-cover" />
                  </div>
                </div>
              )}
            </div>
          )}

          {activeStep === ProductionPhase.PRODUCTION_PLAN && (
            <div className="w-full space-y-12 pb-20 animate-in fade-in duration-700">
              <div className="text-center space-y-4">
                <h2 className="text-3xl font-serif">優化拍攝 DNA</h2>
                <p className="text-sm text-neutral-500">確立影片風格、核心敘事與劇本細節。</p>
              </div>
              <div className="grid grid-cols-1 lg:grid-cols-2 gap-12">
                <div className="space-y-8">
                  {['coreNarrative', 'socialBackground', 'environment'].map(f => (
                    <div key={f} className="group relative">
                      <div className="flex justify-between items-center mb-3"><label className="text-[10px] font-bold text-neutral-500 uppercase tracking-widest">{f}</label></div>
                      <textarea value={tempDNA[f as keyof ProjectDNA] || ''} onChange={(e) => setTempDNA({ ...tempDNA, [f]: e.target.value })} rows={6} className="w-full bg-white/5 border border-white/10 rounded-xl p-4 text-sm outline-none focus:ring-1 focus:ring-amber-500" />
                    </div>
                  ))}
                </div>
                <div className="space-y-3 group">
                   <label className="text-[10px] font-bold text-neutral-500 uppercase tracking-widest">劇本摘要</label>
                   <textarea value={tempDNA.story || ''} onChange={(e) => setTempDNA({ ...tempDNA, story: e.target.value })} rows={22} className="w-full bg-white/5 border border-white/10 rounded-2xl p-6 text-sm focus:ring-1 focus:ring-amber-500 outline-none leading-relaxed font-serif text-neutral-300" />
                </div>
              </div>
            </div>
          )}
        </section>

        {showHistory && (
          <div className="fixed inset-0 bg-black/95 backdrop-blur-3xl z-[60] p-12 overflow-y-auto">
             <div className="max-w-5xl mx-auto space-y-16 pb-24">
                <div className="flex justify-between items-center border-b border-white/10 pb-8"><h2 className="text-4xl font-serif tracking-widest">項目檔案庫</h2><button onClick={() => setShowHistory(false)} className="p-4 bg-white/5 rounded-full hover:bg-amber-600 transition-colors"><X className="w-8 h-8" /></button></div>
                {project.coreSceneImage && (
