                    <div className="aspect-[21/9] rounded-3xl overflow-hidden border border-white/10 shadow-2xl cursor-zoom-in" onClick={() => setExpandedImage(project.coreSceneImage || null)}><img src={project.coreSceneImage} className="w-full h-full object-cover" /></div>
                  </div>
                )}
             </div>
          </div>
        )}
      </main>

      <aside className="w-80 border-l border-white/5 bg-black/40 p-6 flex flex-col gap-8 overflow-y-auto">
        <div className="space-y-6">
          <h3 className="text-[10px] font-bold text-neutral-500 uppercase tracking-widest">視覺檔案 (Asset)</h3>
          {project.coreSceneImage ? (
            <div className="space-y-4 animate-in fade-in duration-700">
              <span className="text-[10px] text-amber-500/70 font-mono uppercase tracking-widest">CORE_VISUAL</span>
              <div className="aspect-video rounded-2xl overflow-hidden border border-white/10 shadow-lg group relative cursor-zoom-in" onClick={() => setExpandedImage(project.coreSceneImage!)}><img src={project.coreSceneImage} className="w-full h-full object-cover" /></div>
            </div>
          ) : <div className="py-8 border border-dashed border-white/10 rounded-2xl text-center opacity-30"><ImageIcon className="w-6 h-6 mx-auto mb-2 text-neutral-700" /><p className="text-[8px] uppercase tracking-widest">等待核心視覺</p></div>}

          {project.proposedStages.some(s => s.gridImage) && (
            <div className="space-y-6 pt-6 border-t border-white/5">
              <span className="text-[10px] text-amber-500/70 font-mono uppercase tracking-widest block">STAGE_GRIDS</span>
              {project.proposedStages.filter(s => s.gridImage).map((stage, i) => (
                <div key={i} className="space-y-2 animate-in slide-in-from-right-4 duration-500">
                  <span className="text-[9px] font-bold text-neutral-400 truncate block px-1">{stage.name}</span>
                  <div className="aspect-square rounded-xl overflow-hidden border border-white/5 cursor-zoom-in" onClick={() => setExpandedImage(stage.gridImage!)}><img src={stage.gridImage} className="w-full h-full object-cover grayscale hover:grayscale-0 transition-all duration-500" /></div>
                </div>
              ))}
            </div>
          )}

          {project.proposedCharacters.some(c => c.gridImage) && (
            <div className="space-y-6 pt-6 border-t border-white/5">
              <span className="text-[10px] text-amber-500/70 font-mono uppercase tracking-widest block">CHARACTER_GRIDS</span>
