          <h3 className="text-[10px] font-bold text-neutral-500 uppercase tracking-widest border-b border-white/5 pb-2">視覺檔案 (Asset)</h3>
          {project.coreSceneImage ? (
            <div className="space-y-4 animate-in fade-in duration-700">
              <div className="flex items-center justify-between">
                <span className="text-[10px] text-amber-500/70 font-mono uppercase tracking-widest">CORE_VISUAL</span>
                <button onClick={() => downloadImage(project.coreSceneImage!, 'core-visual')} className="p-1 hover:bg-amber-600 rounded transition-colors"><Download className="w-3.5 h-3.5" /></button>
              </div>
              <div className="aspect-video rounded-2xl overflow-hidden border border-white/10 shadow-lg group relative cursor-zoom-in" onClick={() => setExpandedImage(project.coreSceneImage!)}>
                <img src={project.coreSceneImage} className="w-full h-full object-cover" />
                <div className="absolute inset-0 bg-black/40 opacity-0 group-hover:opacity-100 transition-opacity flex items-center justify-center p-4">
                  <Maximize2 className="w-6 h-6 text-white" />
                </div>
              </div>
            </div>
          ) : <div className="py-8 border border-dashed border-white/10 rounded-2xl text-center opacity-30"><ImageIcon className="w-6 h-6 mx-auto mb-2 text-neutral-700" /><p className="text-[8px] uppercase tracking-widest">等待核心視覺</p></div>}

          {project.proposedStages.some(s => s.gridImage) && (
            <div className="space-y-6 pt-6 border-t border-white/5">
              <span className="text-[10px] text-amber-500/70 font-mono uppercase tracking-widest block mb-4">STAGE_GRIDS</span>
              {project.proposedStages.filter(s => s.gridImage).map((stage, i) => (
                <div key={i} className="space-y-2 animate-in slide-in-from-right-4 duration-500 group">
                  <div className="flex items-center justify-between px-1">
                    <span className="text-[9px] font-bold text-neutral-400 truncate block">{stage.name}</span>
                    <Download className="w-3 h-3 text-neutral-600 group-hover:text-amber-500 transition-colors cursor-pointer" onClick={() => downloadImage(stage.gridImage!, `Grid-${stage.name}`)} />
                  </div>
                  <div className="aspect-square rounded-xl overflow-hidden border border-white/5 cursor-zoom-in relative" onClick={() => setExpandedImage(stage.gridImage!)}>
                    <img src={stage.gridImage} className="w-full h-full object-cover grayscale hover:grayscale-0 transition-all duration-500" />
                  </div>
                </div>
              ))}
            </div>
          )}

          {project.proposedCharacters.some(c => c.gridImage) && (
            <div className="space-y-6 pt-6 border-t border-white/5">
              <span className="text-[10px] text-amber-500/70 font-mono uppercase tracking-widest block mb-4">CHARACTER_GRIDS</span>
              {project.proposedCharacters.filter(c => c.gridImage).map((char, i) => (
                <div key={i} className="space-y-2 animate-in slide-in-from-right-4 duration-500 group">
                  <div className="flex items-center justify-between px-1">
                    <span className="text-[9px] font-bold text-neutral-400 truncate block">{char.name}</span>
                    <Download className="w-3 h-3 text-neutral-600 group-hover:text-amber-500 transition-colors cursor-pointer" onClick={() => downloadImage(char.gridImage!, `Char-${char.name}`)} />
                  </div>
                  <div className="aspect-square rounded-xl overflow-hidden border border-white/5 cursor-zoom-in relative" onClick={() => setExpandedImage(char.gridImage!)}>
                    <img src={char.gridImage} className="w-full h-full object-cover" />
                  </div>
                </div>
              ))}
            </div>
          )}
        </div>
      </aside>
    </div>
  );
};

export default App;

