export class GeminiService {
  constructor(apiKey: string) { }

  async generateSuggestions(input: string, phase: ProductionPhase, context: string): Promise<Suggestion[]> {
    const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
    const prompt = `目前的靈感/指令： "${input}"。
    請根據目前的製作階段 [${phase}]，提供三個具體的創意導向（高層次提案）。

    【關鍵任務】如果是 INSPIRATION 階段，請發揮頂尖導演聯想力，自動推論出初步的：
    1. 地理環境 (environment)
    2. 社會背景 (socialBackground)
    3. 核心敘事 (coreNarrative)

    請回傳 JSON 陣列，包含 title, description, tags, environment, socialBackground, coreNarrative。`;

    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: [{ role: 'user', parts: [{ text: prompt }] }],
      config: {
        systemInstruction: SYSTEM_INSTRUCTION,
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.ARRAY,
          items: {
            type: Type.OBJECT,
            properties: {
              title: { type: Type.STRING },
              description: { type: Type.STRING },
              tags: { type: Type.ARRAY, items: { type: Type.STRING } },
              environment: { type: Type.STRING },
              socialBackground: { type: Type.STRING },
              coreNarrative: { type: Type.STRING }
            },
            required: ["title", "description", "tags"]
          }
        }
      }
    });
    return JSON.parse(response.text || "[]");
  }

  async identifyCoreStages(dna: ProjectDNA): Promise<StageDesign[]> {
    const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
    const prompt = `你是一位頂尖電影美術指導與空間設計師。請針對提供的劇本內容進行核心舞台 (Core Stage) 的識別與視覺設計。

【執行步驟】
1. 歸納主要地點：深入閱讀「劇本摘要」，從中找出故事主要發生的物理地點，並歸納為 1-3 個最具敘事代表性的核心舞台。
2. 宏觀審視與篩選：對於每個初步選定的地點，請進行專業審視：「這是否為角色的核心活動區？」或「這是否為角色之間關鍵的互動空間？」。若兩者皆為否，請剔除該地點並尋找更具空間敘事張力的地點。
3. 詳細空間設計：為選定的舞台產出具備工業標準的描述，內容必須包含：
    - 場地大小與空間格局 (Scale & Layout)
    - 位置、方位與方向感 (Position & Orientation)
    - 關鍵物件、道具與美術陳設 (Key Props & Dressing)
    - 光影質調、色調色標與材質細節 (Lighting, Color & Textures)
    - 敘事氛圍與心理空間感 (Atmosphere)

劇本摘要：${dna.story}
視覺風格定義：${dna.style}
環境背景：${dna.environment}

請回傳 JSON 陣列，包含 name 與詳盡的 description。`;

    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: [{ role: 'user', parts: [{ text: prompt }] }],
      config: {
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.ARRAY,
          items: {
            type: Type.OBJECT,
            properties: {
              name: { type: Type.STRING },
              description: { type: Type.STRING }
            },
            required: ["name", "description"]
          }
        }
      }
    });
    return JSON.parse(response.text || "[]");
  }

  async analyzeCharacters(dna: ProjectDNA): Promise<CharacterDesign[]> {
    const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
    const prompt = `你是一位頂尖電影選角指導與角色造型設計師。請針對劇本內容，識別出「主角」、「反派」與「關鍵配角」，並為這 1-3 個核心角色設計深度視覺原型。

    劇本摘要：${dna.story}
    視覺風格：${dna.style}

    【深度要求】每個角色的總描述量應在 150-200 字之間，內容必須具備工業級的細節。

    【設計維度】
    1. 外貌特徵 (physicalTraits)：具體的五官輪廓、身形比例、標誌性傷疤或裝飾、服裝的剪裁與時代感。
    2. 外觀材質色調 (visualTone)：定義角色的「視覺 DNA」。包含服裝面料細節（粗糙皮革、絲綢光澤等）、專屬配色方案、以及光影如何在其臉部產生戲劇效果。
    3. 內在動機與表情動作 (motivation)：核心欲望如何轉化為習慣性表情（如：焦慮的眨眼、冷酷的嘴角下撇）與典型的動態行為。

    請回傳 JSON 陣列。`;

    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: [{ role: 'user', parts: [{ text: prompt }] }],
      config: {
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.ARRAY,
          items: {
            type: Type.OBJECT,
            properties: {
              name: { type: Type.STRING },
              role: { type: Type.STRING, description: '角色定位，如主角、反派、關鍵配角' },
              physicalTraits: { type: Type.STRING },
              visualTone: { type: Type.STRING },
              motivation: { type: Type.STRING }
            },
            required: ["name", "role", "physicalTraits", "visualTone", "motivation"]
          }
        }
      }
    });
    return JSON.parse(response.text || "[]");
  }

  async elaboratePlan(suggestion: Suggestion): Promise<ProjectDNA> {
    const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
    const prompt = `將以下提案擴充為完整的電影拍攝 DNA：${suggestion.title}。內容包含地理環境、社會背景、核心敘事與劇本摘要。`;
    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: [{ role: 'user', parts: [{ text: prompt }] }],
      config: {
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.OBJECT,
          properties: {
            format: { type: Type.STRING },
            style: { type: Type.STRING },
            story: { type: Type.STRING },
            ratio: { type: Type.STRING },
            environment: { type: Type.STRING },
            socialBackground: { type: Type.STRING },
            coreNarrative: { type: Type.STRING }
          },
          required: ["format", "style", "story", "environment", "socialBackground", "coreNarrative"]
        }
      }
    });
    return JSON.parse(response.text || "{}");
  }

  async polishText(text: string, type: string): Promise<string> {
    const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: `你是專業電影視覺指導。請進行場景化潤色，強調視覺細節與專業術語。類型：${type}。內容：${text}`,
    });
    return response.text || text;
  }

  async generateImage(prompt: string): Promise<string | null> {
    const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
    try {
      const response = await ai.models.generateContent({
        model: 'gemini-3-pro-image-preview',
        contents: { parts: [{ text: prompt }] },
        config: { imageConfig: { aspectRatio: "16:9", imageSize: "1K" } }
      });
      for (const part of response.candidates?.[0]?.content?.parts || []) {
        if (part.inlineData) return `data:image/png;base64,${part.inlineData.data}`;
      }
      return null;
    } catch (error) { return null; }
  }

  async generateSceneGrid(dna: ProjectDNA, stage: StageDesign): Promise<string> {
    const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
    const gridPrompt = `
      Professional 3x3 cinematic concept art storyboard for stage: "${stage.name}".
      Spatial Context: ${stage.description}. Style: ${dna.style}.
      STRICT LAYOUT REQUIREMENT: Single 1:1 square image strictly divided into a 3x3 grid with EXACTLY NINE equal rectangular panels. 
      Consistent lighting, texture, and color grading across all 9 panels. 8k resolution, cinematic concept design.
    `;
    try {
      const response = await ai.models.generateContent({
        model: 'gemini-3-pro-image-preview',
        contents: { parts: [{ text: gridPrompt }] },
        config: { imageConfig: { aspectRatio: "1:1", imageSize: "1K" } }
      });
      for (const part of response.candidates?.[0]?.content?.parts || []) {
        if (part.inlineData) return `data:image/png;base64,${part.inlineData.data}`;
      }
    } catch (error) { console.error(error); }
    return "";
  }

  async generateCharacterGrid(dna: ProjectDNA, character: CharacterDesign): Promise<string> {
    const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
    const gridPrompt = `
      A professional 3x3 cinematic character concept art sheet for: "${character.name}" (${character.role}).
      Traits: ${character.physicalTraits}. 
      Visual Tone & Material: ${character.visualTone}. 
      Motivation & Expressions: ${character.motivation}.
      Film Style: ${dna.style}.

      CRITICAL LAYOUT REQUIREMENT: 
      Generate a single 1:1 square image strictly divided into a 3x3 grid containing exactly NINE distinct equal-sized panels. 
      DO NOT GENERATE EXTRA ROWS OR COLUMNS. THE GRID MUST BE EXACTLY 3x3.

      Grid Content Mapping:
      - (1,1) Top-Left: Full-body heroic/villainous standing pose.
      - (1,2) Top-Center: Extreme close-up of the eyes and emotional expression.
      - (1,3) Top-Right: Profile view (side silhouette) showing costume depth.
      - (2,1) Mid-Left: Macro detail of costume fabric, armor, or material texture.
      - (2,2) CENTER: Main narrative action pose - showing the character's dynamic core.
      - (2,3) Mid-Right: Close-up of a signature accessory, weapon, or tool.
      - (3,1) Bottom-Left: Dramatic lighting study - shadows and highlights on face.
      - (3,2) Bottom-Center: Hand detail or character-specific gesture.
      - (3,3) Bottom-Right: Environmental interaction - how character fits in the world.

      Visual Consistency: The character's face, clothing, and the overall color palette MUST be identical across all nine panels. High-end cinematic concept art, 8k.
    `;
    try {
      const response = await ai.models.generateContent({
        model: 'gemini-3-pro-image-preview',
        contents: { parts: [{ text: gridPrompt }] },
        config: { imageConfig: { aspectRatio: "1:1", imageSize: "1K" } }
      });
      for (const part of response.candidates?.[0]?.content?.parts || []) {
        if (part.inlineData) return `data:image/png;base64,${part.inlineData.data}`;
      }
    } catch (error) { console.error("Character grid generation failed:", error); }
    return "";
  }

  async generateVideo(prompt: string, onProgress: (status: string) => void): Promise<string | null> {
    const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
    try {
      onProgress("正在初始化拍攝設備...");
      let operation = await ai.models.generateVideos({
        model: 'veo-3.1-fast-generate-preview',
        prompt: prompt,
        config: { numberOfVideos: 1, resolution: '720p', aspectRatio: '16:9' }
      });
      while (!operation.done) {
        await new Promise(resolve => setTimeout(resolve, 10000));
        operation = await ai.operations.getVideosOperation({ operation: operation });
      }
      const downloadLink = operation.response?.generatedVideos?.[0]?.video?.uri;
      return downloadLink ? `${downloadLink}&key=${process.env.API_KEY}` : null;
    } catch (error) { return null; }
  }
}

import React, { useState, useEffect, useCallback, useRef } from 'react';
import { ProductionPhase, Suggestion, ProjectState, GeneratedVideo, Message, ProjectDNA, StageDesign, CharacterDesign } from './types';
import { PHASE_METADATA } from './constants';
import { GeminiService } from './services/geminiService';
import { ApiKeySelector } from './components/ApiKeySelector';
import { 
  Film, Sparkles, Send, Loader2, ArrowRight, 
  Info, Clapperboard, Video, Layout, Palette, 
  ChevronRight, Save, Download, Upload,
  X, CheckCircle2, Monitor, BookOpen, Layers, Terminal, MapPin, Users, Target, Lightbulb,
  Undo2, Redo2, Wand2, Eye, Grid, Edit3, Image as ImageIcon, Briefcase, Trash2, Plus, 
  Compass, Map, Maximize2, DownloadCloud, RefreshCw, UserPlus, UserCheck, PersonStanding
} from 'lucide-react';

const App: React.FC = () => {
  const [hasKey, setHasKey] = useState(false);
  const [isLoading, setIsLoading] = useState(false);
  const [isAnalyzing, setIsAnalyzing] = useState(false);
  const [isElaborating, setIsElaborating] = useState(false);
  const [input, setInput] = useState('');
  const [activeStep, setActiveStep] = useState<ProductionPhase>(ProductionPhase.INSPIRATION);
  const [expandedImage, setExpandedImage] = useState<string | null>(null);

  const [tempDNA, setTempDNA] = useState<ProjectDNA>({
    format: '電影', style: '寫實電影感 (Realistic Cinematic)', story: '', ratio: '16:9',
    environment: '', socialBackground: '', coreNarrative: ''
  });

  const [project, setProject] = useState<ProjectState>({
    currentPhase: ProductionPhase.INSPIRATION,
    initialInput: '',
    dna: { format: '電影', style: '寫實電影感 (Realistic Cinematic)', story: '', ratio: '16:9', environment: '', socialBackground: '', coreNarrative: '' },
    suggestions: [], proposedStages: [], proposedCharacters: [], history: [], generatedVideos: [], sceneGrid: []
  });

  const fileInputRef = useRef<HTMLInputElement>(null);
  const geminiRef = useRef<GeminiService | null>(null);

  useEffect(() => {
    const checkKey = async () => {
      // @ts-ignore
      const exists = await window.aistudio.hasSelectedApiKey();
      if (exists) {
        setHasKey(true);
        geminiRef.current = new GeminiService(process.env.API_KEY || '');
      }
    };
    checkKey();
  }, []);

  useEffect(() => {
    if (activeStep === ProductionPhase.VISUAL_DEV && project.proposedStages.length === 0 && !isAnalyzing && geminiRef.current) {
      handleIdentifyStages(true);
    }
    if (activeStep === ProductionPhase.CHARACTER_DEV && project.proposedCharacters.length === 0 && !isAnalyzing && geminiRef.current) {
      handleAutoAnalyzeCharacters();
    }
  }, [activeStep, project.proposedStages.length, project.proposedCharacters.length]);

  const handleIdentifyStages = async (isAuto = false) => {
    if (!geminiRef.current || isAnalyzing) return;
    if (!isAuto && project.proposedStages.length > 0 && !confirm("重新分析將清除目前所有的舞台資產，確定嗎？")) return;

    setIsAnalyzing(true);
    setProject(prev => ({ ...prev, proposedStages: [], selectedStageIndex: undefined }));
    try {
      const stages = await geminiRef.current.identifyCoreStages(project.dna);
      setProject(prev => ({ ...prev, proposedStages: stages }));
    } catch (err) { console.error(err); } finally { setIsAnalyzing(false); }
  };

  const handleAutoAnalyzeCharacters = async () => {
    if (!geminiRef.current || isAnalyzing) return;
    setIsAnalyzing(true);
    setProject(prev => ({ ...prev, proposedCharacters: [], selectedCharacterIndex: undefined }));
    try {
      const chars = await geminiRef.current.analyzeCharacters(project.dna);
      setProject(prev => ({ ...prev, proposedCharacters: chars }));
    } catch (err) { console.error(err); } finally { setIsAnalyzing(false); }
  };

  const handleRenderStageGrid = async (idx: number) => {
    if (!geminiRef.current) return;
    const stage = project.proposedStages[idx];
    setIsLoading(true);
    setProject(prev => ({ ...prev, selectedStageIndex: idx }));
    try {
      const gridResult = await geminiRef.current.generateSceneGrid(project.dna, stage);
      if (gridResult) {
        setProject(prev => {
          const newStages = [...prev.proposedStages];
          newStages[idx] = { ...newStages[idx], gridImage: gridResult };
          return { ...prev, proposedStages: newStages };
        });
      }
    } finally { setIsLoading(false); }
  };

  const handleRenderCharacterGrid = async (idx: number) => {
    if (!geminiRef.current) return;
    const character = project.proposedCharacters[idx];
    setIsLoading(true);
    setProject(prev => ({ ...prev, selectedCharacterIndex: idx }));
    try {
      const gridResult = await geminiRef.current.generateCharacterGrid(project.dna, character);
      if (gridResult) {
        setProject(prev => {
          const newChars = [...prev.proposedCharacters];
          newChars[idx] = { ...newChars[idx], gridImage: gridResult };
          return { ...prev, proposedCharacters: newChars };
        });
      }
    } finally { setIsLoading(false); }
  };

  const updateStage = (idx: number, field: keyof StageDesign, value: string) => {
    const newStages = [...project.proposedStages];
    newStages[idx] = { ...newStages[idx], [field]: value };
    setProject(prev => ({ ...prev, proposedStages: newStages }));
  };

  const updateCharacter = (idx: number, field: keyof CharacterDesign, value: string) => {
    const newChars = [...project.proposedCharacters];
    newChars[idx] = { ...newChars[idx], [field]: value };
    setProject(prev => ({ ...prev, proposedCharacters: newChars }));
  };

  const handlePolishChar = async (idx: number, field: keyof CharacterDesign, label: string) => {
    if (!geminiRef.current || isLoading) return;
    setIsLoading(true);
    try {
      const char = project.proposedCharacters[idx];
      const polished = await geminiRef.current.polishText(char[field] as string, `角色塑造（${char.name}）之${label}`);
      updateCharacter(idx, field, polished);
    } finally { setIsLoading(false); }
  };

  const saveProject = () => {
    const data = JSON.stringify(project, null, 2);
    const blob = new Blob([data], { type: 'application/json' });
    const url = URL.createObjectURL(blob);
    const link = document.createElement('a');
    link.href = url;
    link.download = `montage-project-${new Date().toISOString().slice(0, 10)}.json`;
    link.click();
  };

  const loadProject = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;
    const reader = new FileReader();
    reader.onload = (event) => {
      try {
        const data = JSON.parse(event.target?.result as string) as ProjectState;
        if (data.currentPhase && data.dna) {
          setProject({
            ...data,
            suggestions: data.suggestions || [],
            proposedStages: data.proposedStages || [],
            proposedCharacters: data.proposedCharacters || [],
            history: data.history || [],
            generatedVideos: data.generatedVideos || [],
            sceneGrid: data.sceneGrid || []
          });
          setActiveStep(data.currentPhase);
          setTempDNA(data.dna);
          if (data.currentPhase === ProductionPhase.INSPIRATION) {
            setInput(data.initialInput || '');
          }
        }
      } catch (err) {
        alert('檔案格式錯誤，請確保上傳正確的專案檔。');
      }
    };
    reader.readAsText(file);
    if (fileInputRef.current) fileInputRef.current.value = '';
  };

  const handleStepSwitch = (phase: ProductionPhase) => {
    setActiveStep(phase);
    if (phase === ProductionPhase.PRODUCTION_PLAN) setTempDNA(project.dna);
    setProject(prev => ({ ...prev, suggestions: [] }));
  };

  const handleSubmitIdea = async (e?: React.FormEvent) => {
    if (e) e.preventDefault();
    if (!input.trim() || isLoading || !geminiRef.current) return;
    setIsLoading(true);
    try {
      const results = await geminiRef.current.generateSuggestions(input, activeStep, JSON.stringify(project.dna));
      setProject(prev => ({ 
        ...prev, suggestions: results || [], 
        initialInput: activeStep === ProductionPhase.INSPIRATION ? input : prev.initialInput,
        history: [...(prev.history || []), { role: 'user', content: input, phase: activeStep }]
      }));
    } finally { setIsLoading(false); }
  };

  const handleSuggestionClick = async (s: Suggestion) => {
    if (!geminiRef.current) return;
    setIsElaborating(true);
    try {
      const detailedDNA = await geminiRef.current.elaboratePlan(s);
      setTempDNA(detailedDNA);
      setProject(prev => ({
        ...prev, dna: detailedDNA, currentPhase: ProductionPhase.PRODUCTION_PLAN, suggestions: []
      }));
      setActiveStep(ProductionPhase.PRODUCTION_PLAN);
    } finally { setIsElaborating(false); }
  };

  const confirmProductionPlan = async () => {
    if (!geminiRef.current) return;
    setIsLoading(true);
    try {
      const coreImage = await geminiRef.current.generateImage(`${tempDNA.story}. ${tempDNA.style}. Cinematic, 8k.`) || undefined;
      setProject(prev => ({
        ...prev, currentPhase: ProductionPhase.VISUAL_DEV, dna: { ...tempDNA }, coreSceneImage: coreImage,
        proposedStages: [], sceneGrid: []
      }));
      setActiveStep(ProductionPhase.VISUAL_DEV);
    } finally { setIsLoading(false); }
  };

  const goToCharacterDev = () => {
    setProject(prev => ({ ...prev, currentPhase: ProductionPhase.CHARACTER_DEV }));
    setActiveStep(ProductionPhase.CHARACTER_DEV);
  };

  const goToStoryArch = () => {
    setProject(prev => ({ ...prev, currentPhase: ProductionPhase.STORY_ARCH }));
    setActiveStep(ProductionPhase.STORY_ARCH);
  };

  const downloadImage = (base64: string, name: string) => {
    const link = document.createElement('a');
    link.href = base64;
    link.download = `${name}.png`;
    link.click();
  };

  const isAllStageGridsGenerated = project.proposedStages.length > 0 && project.proposedStages.every(s => !!s.gridImage);
  const isAllCharGridsGenerated = project.proposedCharacters.length > 0 && project.proposedCharacters.every(c => !!c.gridImage);

  if (!hasKey) return <ApiKeySelector onSelected={() => setHasKey(true)} />;

  return (
    <div className="flex h-screen bg-[#050505] text-white overflow-hidden font-sans">
      {/* Expanded Image Modal */}
      {expandedImage && (
        <div className="fixed inset-0 bg-black/95 z-[100] flex flex-col items-center justify-center p-8 animate-in fade-in duration-300">
          <button onClick={() => setExpandedImage(null)} className="absolute top-8 right-8 p-3 bg-white/5 hover:bg-amber-600 rounded-full transition-all group">
            <X className="w-8 h-8 text-white group-hover:scale-110" />
          </button>
          <div className="relative max-w-7xl w-full max-h-full">
            <img src={expandedImage} className="w-full h-full object-contain shadow-2xl rounded-lg border border-white/10" />
            <button onClick={() => downloadImage(expandedImage, 'montage-asset')} className="absolute bottom-4 right-4 flex items-center gap-2 bg-amber-600 hover:bg-amber-500 px-6 py-3 rounded-full font-bold shadow-xl transition-all">
              <DownloadCloud className="w-5 h-5" /> 下載原始圖片
            </button>
          </div>
        </div>
      )}

      <aside className="w-64 border-r border-white/5 flex flex-col bg-black/40 p-6">
        <div className="flex items-center gap-3 mb-12">
          <div className="bg-amber-600 p-2 rounded-lg shadow-[0_0_15px_rgba(217,119,6,0.3)]"><Film className="w-6 h-6 text-white" /></div>
          <h1 className="text-lg font-serif font-bold tracking-widest text-white/90">電影蒙太奇</h1>
        </div>
        <nav className="flex-1 space-y-2">
          {Object.entries(PHASE_METADATA).map(([key, meta], idx) => {
            const phaseKey = key as ProductionPhase;
            const isActive = activeStep === phaseKey;
            const isAccessible = Object.values(ProductionPhase).indexOf(phaseKey) <= Object.values(ProductionPhase).indexOf(project.currentPhase);
            return (
