              </div>
            )}
          </div>

          {/* 舞台與角色九宮格 */}
          {project.proposedStages.some(s => s.gridImage) && (
            <div className="space-y-6 pt-6 border-t border-white/5">
              <span className="text-[10px] text-amber-500/70 font-mono uppercase tracking-widest block mb-4">STAGE_GRIDS</span>
              {project.proposedStages.filter(s => s.gridImage).map((stage, i) => (
                <div key={i} className="space-y-2 animate-in slide-in-from-right-4 duration-500 group">
                  <div className="flex items-center justify-between px-1">
                    <span className="text-[9px] font-bold text-neutral-400 truncate block">{stage.name}</span>
                    <Download className="w-3 h-3 text-neutral-600 group-hover:text-amber-500 transition-colors cursor-pointer" onClick={() => downloadImage(stage.gridImage!, `Grid-${stage.name}`)} />
                  </div>
                  <div className="aspect-square rounded-xl overflow-hidden border border-white/5 cursor-zoom-in relative" onClick={() => setExpandedImage(stage.gridImage!)}>
                    <img src={stage.gridImage} className="w-full h-full object-cover grayscale hover:grayscale-0 transition-all duration-500" />
                  </div>
                </div>
              ))}
            </div>
          )}

          {project.proposedCharacters.some(c => c.gridImage) && (
            <div className="space-y-6 pt-6 border-t border-white/5">
              <span className="text-[10px] text-amber-500/70 font-mono uppercase tracking-widest block mb-4">CHARACTER_GRIDS</span>
              {project.proposedCharacters.filter(c => c.gridImage).map((char, i) => (
                <div key={i} className="space-y-2 animate-in slide-in-from-right-4 duration-500 group">
