  input: string;
  setInput: (val: string) => void;
  isLoading: boolean;
  isElaborating: boolean;
  suggestions: Suggestion[];
  onSubmit: (e: React.FormEvent) => void;
  onSuggestionClick: (s: Suggestion) => void;
  guideText: string;
}

