  input, setInput, isLoading, isElaborating, suggestions, onSubmit, onSuggestionClick, guideText
}) => {
  return (
    <div className="w-full max-w-2xl mt-20 mb-12 animate-in fade-in slide-in-from-top-4 duration-700">
