import { ProjectState, CharacterDesign } from '../types';

interface CharacterDevPhaseProps {
  project: ProjectState;
  isAnalyzing: boolean;
  isLoading: boolean;
  onUpdateCharacter: (idx: number, field: keyof CharacterDesign, value: string) => void;
  onPolishCharacter: (idx: number, field: keyof CharacterDesign, label: string) => void;
  onRenderGrid: (idx: number) => void;
  guideText: string;
}

export const CharacterDevPhase: React.FC<CharacterDevPhaseProps> = ({
  project, isAnalyzing, isLoading, onUpdateCharacter, onPolishCharacter, onRenderGrid, guideText
}) => {
  return (
    <div className="w-full space-y-12 pb-20 animate-in fade-in duration-1000">
      <div className="text-center space-y-4">
        <h2 className="text-3xl font-serif text-neutral-100">{guideText}</h2>
        <p className="text-sm text-neutral-500 max-w-xl mx-auto">AI 已根據劇本建立角色視覺原型，請優化他們的外貌細節與材質色調。</p>
      </div>

      {isAnalyzing ? (
        <div className="py-20 flex flex-col items-center gap-6 animate-pulse">
          <Loader2 className="w-12 h-12 text-amber-600 animate-spin" />
          <p className="text-amber-500 text-xs font-bold uppercase tracking-[0.3em]">AI 正在設計角色視覺原型...</p>
        </div>
      ) : (
        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-8">
          {project.proposedCharacters.map((char, idx) => (
            <div key={idx} className={`glass p-8 rounded-3xl transition-all border-white/5 flex flex-col shadow-2xl ${project.selectedCharacterIndex === idx ? 'ring-2 ring-amber-600 bg-amber-600/5' : ''}`}>
              <div className="flex items-center justify-between mb-6">
                <div className="flex items-center gap-2">
                  <Users className="w-4 h-4 text-amber-600" />
                  <span className="text-[10px] font-bold text-neutral-500 uppercase tracking-widest">{char.role}</span>
                </div>
                <PersonStanding className="w-5 h-5 text-neutral-700" />
              </div>

              <input 
                className="bg-transparent border-none text-neutral-100 font-serif font-bold text-2xl mb-6 focus:ring-0 w-full outline-none" 
                value={char.name} 
                onChange={(e) => onUpdateCharacter(idx, 'name', e.target.value)} 
                placeholder="角色姓名" 
              />

              <div className="space-y-6 mb-8 flex-1">
                {[
                  { id: 'physicalTraits', label: '外貌特徵', icon: <Eye className="w-3 h-3" /> },
                  { id: 'visualTone', label: '外觀材質色調', icon: <Palette className="w-3 h-3" /> },
                  { id: 'motivation', label: '內在動機', icon: <Target className="w-3 h-3" /> }
                ].map(f => (
                  <div key={f.id} className="group/field">
                    <div className="flex justify-between items-center mb-2">
                      <label className="text-[9px] font-bold text-neutral-500 uppercase flex items-center gap-1.5">{f.icon} {f.label}</label>
                      <button onClick={() => onPolishCharacter(idx, f.id as keyof CharacterDesign, f.label)} className="opacity-0 group-hover/field:opacity-100 text-amber-500 hover:text-white transition-all bg-amber-600/10 p-1 rounded-md"><Wand2 className="w-3 h-3" /></button>
                    </div>
                    <textarea 
                      value={char[f.id as keyof CharacterDesign] as string || ''} 
                      onChange={(e) => onUpdateCharacter(idx, f.id as keyof CharacterDesign, e.target.value)} 
                      rows={3} 
                      className="w-full bg-white/5 rounded-xl p-3 text-xs text-neutral-400 focus:text-neutral-200 outline-none resize-none leading-relaxed transition-colors border border-transparent focus:border-amber-600/30" 
                    />
                  </div>
                ))}
              </div>

              <button 
                onClick={() => onRenderGrid(idx)} 
                disabled={isLoading} 
                className="w-full py-3.5 bg-amber-600/10 hover:bg-amber-600 text-amber-500 hover:text-white rounded-xl text-xs font-bold flex items-center justify-center gap-2 transition-all"
              >
                {isLoading && project.selectedCharacterIndex === idx ? <Loader2 className="w-4 h-4 animate-spin" /> : <Grid className="w-4 h-4" />} 渲染形象九宮格
              </button>
            </div>
          ))}
        </div>
      )}
    </div>
  );
};

import React, { useState, useEffect, useRef } from 'react';
import { ProductionPhase, Suggestion, ProjectState, ProjectDNA, StageDesign, CharacterDesign } from './types';
import { PHASE_METADATA } from './constants';
import { GeminiService } from './services/geminiService';
import { ApiKeySelector } from './components/ApiKeySelector';
import { InspirationPhase } from './components/InspirationPhase';
import { ProductionPlanPhase } from './components/ProductionPlanPhase';
import { VisualDevPhase } from './components/VisualDevPhase';
import { CharacterDevPhase } from './components/CharacterDevPhase';
import { 
  Film, Loader2, ArrowRight, 
  ChevronRight, Download, Upload,
  X, CheckCircle2, Terminal, MapPin, Users, Target,
  Grid, Image as ImageIcon, Maximize2, DownloadCloud, UserPlus
} from 'lucide-react';

const App: React.FC = () => {
  const [hasKey, setHasKey] = useState(false);
  const [isLoading, setIsLoading] = useState(false);
  const [isAnalyzing, setIsAnalyzing] = useState(false);
  const [isElaborating, setIsElaborating] = useState(false);
  const [input, setInput] = useState('');
  const [activeStep, setActiveStep] = useState<ProductionPhase>(ProductionPhase.INSPIRATION);
  const [expandedImage, setExpandedImage] = useState<string | null>(null);

  const [project, setProject] = useState<ProjectState>({
    currentPhase: ProductionPhase.INSPIRATION,
    initialInput: '',
    dna: { format: '電影', style: '寫實電影感 (Realistic Cinematic)', story: '', ratio: '16:9', environment: '', socialBackground: '', coreNarrative: '' },
    suggestions: [], proposedStages: [], proposedCharacters: [], history: [], generatedVideos: [], sceneGrid: []
  });

  const [tempDNA, setTempDNA] = useState<ProjectDNA>(project.dna);
  const fileInputRef = useRef<HTMLInputElement>(null);
  const geminiRef = useRef<GeminiService | null>(null);

  useEffect(() => {
    const checkKey = async () => {
      // @ts-ignore
      const exists = await window.aistudio.hasSelectedApiKey();
      if (exists) {
        setHasKey(true);
        geminiRef.current = new GeminiService(process.env.API_KEY || '');
      }
    };
    checkKey();
  }, []);

  useEffect(() => {
    if (activeStep === ProductionPhase.INSPIRATION && project.initialInput) {
      setInput(project.initialInput);
    }
  }, [project.initialInput, activeStep]);

  useEffect(() => {
    if (activeStep === ProductionPhase.VISUAL_DEV && project.proposedStages.length === 0 && !isAnalyzing && geminiRef.current) {
      handleIdentifyStages();
    }
    if (activeStep === ProductionPhase.CHARACTER_DEV && project.proposedCharacters.length === 0 && !isAnalyzing && geminiRef.current) {
      handleAutoAnalyzeCharacters();
    }
  }, [activeStep, project.proposedStages.length, project.proposedCharacters.length]);

  const handleIdentifyStages = async () => {
    if (!geminiRef.current || isAnalyzing) return;
    setIsAnalyzing(true);
    try {
      const stages = await geminiRef.current.identifyCoreStages(project.dna);
      setProject(prev => ({ ...prev, proposedStages: stages }));
    } catch (err) { console.error(err); } finally { setIsAnalyzing(false); }
  };

  const handleAutoAnalyzeCharacters = async () => {
    if (!geminiRef.current || isAnalyzing) return;
    setIsAnalyzing(true);
    try {
      const chars = await geminiRef.current.analyzeCharacters(project.dna);
      setProject(prev => ({ ...prev, proposedCharacters: chars }));
    } catch (err) { console.error(err); } finally { setIsAnalyzing(false); }
  };

  const handleSubmitIdea = async (e?: React.FormEvent) => {
    if (e) e.preventDefault();
    if (!input.trim() || isLoading || !geminiRef.current) return;
    setIsLoading(true);
    try {
      const results = await geminiRef.current.generateSuggestions(input, activeStep, JSON.stringify(project.dna));
      setProject(prev => ({ 
        ...prev, 
        suggestions: results || [], 
        initialInput: activeStep === ProductionPhase.INSPIRATION ? input : prev.initialInput
      }));
    } finally { setIsLoading(false); }
  };

  const handleSuggestionClick = async (s: Suggestion) => {
    if (!geminiRef.current) return;
    setIsElaborating(true);
    try {
      const detailedDNA = await geminiRef.current.elaboratePlan(s);
      setTempDNA(detailedDNA);
      setProject(prev => ({
        ...prev, dna: detailedDNA, currentPhase: ProductionPhase.PRODUCTION_PLAN, suggestions: []
      }));
      setActiveStep(ProductionPhase.PRODUCTION_PLAN);
    } finally { setIsElaborating(false); }
  };

  const confirmProductionPlan = async () => {
    if (!geminiRef.current) return;
    setIsLoading(true);
    try {
      const coreImage = await geminiRef.current.generateCoreStyleVisual(tempDNA) || undefined;
      setProject(prev => ({
        ...prev, currentPhase: ProductionPhase.VISUAL_DEV, dna: { ...tempDNA }, coreSceneImage: coreImage,
        proposedStages: [], proposedCharacters: []
      }));
      setActiveStep(ProductionPhase.VISUAL_DEV);
    } finally { setIsLoading(false); }
  };

  const saveProject = () => {
    const dataToSave = { ...project, initialInput: input };
    const data = JSON.stringify(dataToSave, null, 2);
    const blob = new Blob([data], { type: 'application/json' });
    const url = URL.createObjectURL(blob);
    const link = document.createElement('a');
    link.href = url;
    link.download = `montage-project-${new Date().toISOString().slice(0, 10)}.json`;
    link.click();
  };

  const loadProject = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;
    const reader = new FileReader();
    reader.onload = (event) => {
      try {
        const data = JSON.parse(event.target?.result as string) as ProjectState;
        if (data.currentPhase && data.dna) {
          setProject(data);
          setActiveStep(data.currentPhase);
          setTempDNA(data.dna);
          if (data.initialInput) setInput(data.initialInput);
        }
      } catch (err) { alert('檔案格式錯誤。'); }
    };
    reader.readAsText(file);
    if (fileInputRef.current) fileInputRef.current.value = '';
  };

  const handleRenderStageGrid = async (idx: number) => {
    if (!geminiRef.current) return;
    setIsLoading(true);
    setProject(prev => ({ ...prev, selectedStageIndex: idx }));
    try {
      const gridResult = await geminiRef.current.generateSceneGrid(project.dna, project.proposedStages[idx]);
      if (gridResult) {
        setProject(prev => {
          const newStages = [...prev.proposedStages];
          newStages[idx] = { ...newStages[idx], gridImage: gridResult };
          return { ...prev, proposedStages: newStages };
        });
      }
    } finally { setIsLoading(false); }
  };

  const handleRenderCharacterGrid = async (idx: number) => {
    if (!geminiRef.current) return;
    setIsLoading(true);
    setProject(prev => ({ ...prev, selectedCharacterIndex: idx }));
    try {
      const gridResult = await geminiRef.current.generateCharacterGrid(project.dna, project.proposedCharacters[idx]);
      if (gridResult) {
        setProject(prev => {
          const newChars = [...prev.proposedCharacters];
          newChars[idx] = { ...newChars[idx], gridImage: gridResult };
          return { ...prev, proposedCharacters: newChars };
        });
      }
    } finally { setIsLoading(false); }
  };

  const updateStage = (idx: number, field: keyof StageDesign, value: string) => {
    setProject(prev => {
      const newStages = [...prev.proposedStages];
      newStages[idx] = { ...newStages[idx], [field]: value };
      return { ...prev, proposedStages: newStages };
    });
  };

  const updateCharacter = (idx: number, field: keyof CharacterDesign, value: string) => {
    setProject(prev => {
      const newChars = [...prev.proposedCharacters];
      newChars[idx] = { ...newChars[idx], [field]: value };
      return { ...prev, proposedCharacters: newChars };
    });
  };

  const handlePolishCharacter = async (idx: number, field: keyof CharacterDesign, label: string) => {
    if (!geminiRef.current || isLoading) return;
    setIsLoading(true);
    try {
      const char = project.proposedCharacters[idx];
      const polished = await geminiRef.current.polishText(char[field] as string, `角色塑造之${label}`);
      updateCharacter(idx, field, polished);
    } finally { setIsLoading(false); }
  };

  const downloadImage = (base64: string, name: string) => {
    const link = document.createElement('a');
    link.href = base64;
    link.download = `${name}.png`;
    link.click();
  };

  if (!hasKey) return <ApiKeySelector onSelected={() => setHasKey(true)} />;

  return (
    <div className="flex h-screen bg-[#050505] text-white overflow-hidden font-sans">
      {expandedImage && (
        <div className="fixed inset-0 bg-black/95 z-[100] flex flex-col items-center justify-center p-8 animate-in fade-in duration-300" onClick={() => setExpandedImage(null)}>
          <button className="absolute top-8 right-8 p-3 bg-white/5 hover:bg-amber-600 rounded-full transition-all group">
            <X className="w-8 h-8 text-white group-hover:scale-110" />
          </button>
          <div className="relative max-w-7xl w-full max-h-full" onClick={e => e.stopPropagation()}>
            <img src={expandedImage} className="w-full h-full object-contain shadow-2xl rounded-lg border border-white/10" />
            <button onClick={() => downloadImage(expandedImage, 'montage-asset')} className="absolute bottom-4 right-4 flex items-center gap-2 bg-amber-600 hover:bg-amber-500 px-6 py-3 rounded-full font-bold shadow-xl transition-all">
              <DownloadCloud className="w-5 h-5" /> 下載原始圖片
            </button>
          </div>
        </div>
      )}

      <aside className="w-64 border-r border-white/5 flex flex-col bg-black/40 p-6">
        <div className="flex items-center gap-3 mb-12">
          <div className="bg-amber-600 p-2 rounded-lg shadow-[0_0_15px_rgba(217,119,6,0.3)]"><Film className="w-6 h-6 text-white" /></div>
          <h1 className="text-lg font-serif font-bold tracking-widest text-white/90">電影蒙太奇</h1>
        </div>
        <nav className="flex-1 space-y-2">
          {Object.entries(PHASE_METADATA).map(([key, meta], idx) => {
            const phaseKey = key as ProductionPhase;
            const isActive = activeStep === phaseKey;
            const isAccessible = Object.values(ProductionPhase).indexOf(phaseKey) <= Object.values(ProductionPhase).indexOf(project.currentPhase);
            return (
              <button key={key} disabled={!isAccessible} onClick={() => setActiveStep(phaseKey)} className={`w-full relative flex items-center gap-4 p-3 rounded-lg transition-all text-left group ${isActive ? 'bg-amber-600/20 text-amber-500 ring-1 ring-amber-600/30' : 'text-neutral-600 hover:text-neutral-400'} ${!isAccessible ? 'opacity-30 grayscale cursor-not-allowed' : 'cursor-pointer'}`}>
                {isActive && <div className="absolute left-0 w-1 h-6 bg-amber-600 rounded-full" />}
                <span className="text-xl">{meta.icon}</span>
                <div className="flex flex-col"><span className="text-[9px] uppercase tracking-tighter opacity-50">Step 0{idx+1}</span><span className="text-sm font-bold">{meta.title}</span></div>
              </button>
            );
          })}
        </nav>
        <div className="mt-8 space-y-2 border-t border-white/5 pt-6">
          <button onClick={saveProject} className="w-full flex items-center gap-3 px-3 py-2 text-xs text-neutral-400 hover:text-white transition-colors group"><Download className="w-4 h-4 text-amber-600" /> <span>匯出專案</span></button>
          <button onClick={() => fileInputRef.current?.click()} className="w-full flex items-center gap-3 px-3 py-2 text-xs text-neutral-400 hover:text-white transition-colors group"><Upload className="w-4 h-4 text-amber-600" /> <span>匯入專案</span></button>
          <input type="file" ref={fileInputRef} onChange={loadProject} className="hidden" accept=".json" />
        </div>
      </aside>

      <main className="flex-1 flex flex-col relative overflow-hidden">
        <header className="h-16 px-8 border-b border-white/5 flex items-center justify-between z-10 bg-black/50 backdrop-blur-md">
          <div className="flex items-center gap-2"><Terminal className="w-4 h-4 text-amber-600" /><span className="text-[10px] text-neutral-500 uppercase tracking-[0.2em]">TERMINAL</span><ChevronRight className="w-3 h-3 text-neutral-600" /><span className="text-sm font-bold text-amber-500 uppercase">{PHASE_METADATA[activeStep]?.title}</span></div>
          <div className="flex items-center gap-4">
            {activeStep === ProductionPhase.PRODUCTION_PLAN && (
              <button onClick={confirmProductionPlan} disabled={isLoading} className="bg-amber-600 hover:bg-amber-500 px-6 py-2 rounded-full text-[11px] font-bold flex items-center gap-2 shadow-lg transition-all">
                {isLoading ? <Loader2 className="w-3.5 h-3.5 animate-spin" /> : <CheckCircle2 className="w-3.5 h-3.5" />} 確認方案並塑造舞台
              </button>
            )}
            {activeStep === ProductionPhase.VISUAL_DEV && (
              <button onClick={() => setActiveStep(ProductionPhase.CHARACTER_DEV)} className="bg-amber-600 hover:bg-amber-500 px-6 py-2 rounded-full text-[11px] font-bold flex items-center gap-2 shadow-lg transition-all">
                <UserPlus className="w-3.5 h-3.5" /> 進行角色塑造
              </button>
            )}
          </div>
        </header>

        <section className="flex-1 flex flex-col items-center justify-start p-8 max-w-5xl mx-auto w-full overflow-y-auto">
          {activeStep === ProductionPhase.INSPIRATION && (
            <InspirationPhase input={input} setInput={setInput} isLoading={isLoading} isElaborating={isElaborating} suggestions={project.suggestions} onSubmit={handleSubmitIdea} onSuggestionClick={handleSuggestionClick} guideText={PHASE_METADATA[activeStep]?.guide} />
          )}
          {activeStep === ProductionPhase.PRODUCTION_PLAN && (
            <ProductionPlanPhase dna={tempDNA} setDna={setTempDNA} />
          )}
          {activeStep === ProductionPhase.VISUAL_DEV && (
            <VisualDevPhase project={project} isAnalyzing={isAnalyzing} isLoading={isLoading} onUpdateStage={updateStage} onRenderGrid={handleRenderStageGrid} guideText={PHASE_METADATA[activeStep]?.guide} />
          )}
          {activeStep === ProductionPhase.CHARACTER_DEV && (
            <CharacterDevPhase project={project} isAnalyzing={isAnalyzing} isLoading={isLoading} onUpdateCharacter={updateCharacter} onPolishCharacter={handlePolishCharacter} onRenderGrid={handleRenderCharacterGrid} guideText={PHASE_METADATA[activeStep]?.guide} />
          )}
        </section>
      </main>

      <aside className="w-80 border-l border-white/5 bg-black/40 p-6 flex flex-col gap-8 overflow-y-auto">
        <h3 className="text-[10px] font-bold text-neutral-500 uppercase tracking-widest border-b border-white/5 pb-2">視覺檔案 (Asset)</h3>

        {/* 核心視覺 */}
        <div className="space-y-4">
          <span className="text-[10px] text-amber-500/70 font-mono uppercase tracking-widest block">CORE_VISUAL</span>
          {project.coreSceneImage ? (
            <div className="aspect-video rounded-2xl overflow-hidden border border-white/10 shadow-lg cursor-zoom-in" onClick={() => setExpandedImage(project.coreSceneImage!)}>
              <img src={project.coreSceneImage} className="w-full h-full object-cover" alt="Core Visual" />
            </div>
          ) : (
            <div className="py-12 border border-dashed border-white/10 rounded-2xl text-center opacity-30">
              <ImageIcon className="w-6 h-6 mx-auto mb-2 text-neutral-700" />
              <p className="text-[8px] uppercase tracking-widest">等待核心視覺</p>
            </div>
          )}
        </div>

        {/* 舞台九宮格列表 */}
        {project.proposedStages.some(s => s.gridImage) && (
          <div className="space-y-6 pt-6 border-t border-white/5">
            <span className="text-[10px] text-amber-500/70 font-mono uppercase tracking-widest block">STAGE_GRIDS</span>
            {project.proposedStages.filter(s => s.gridImage).map((stage, i) => (
              <div key={i} className="space-y-2 group">
                <div className="flex items-center justify-between">
                  <span className="text-[9px] font-bold text-neutral-400 truncate block">{stage.name}</span>
                  <Download className="w-3 h-3 text-neutral-600 hover:text-amber-500 cursor-pointer" onClick={() => downloadImage(stage.gridImage!, `Stage-${stage.name}`)} />
                </div>
                <div className="aspect-square rounded-xl overflow-hidden border border-white/5 cursor-zoom-in" onClick={() => setExpandedImage(stage.gridImage!)}>
                  <img src={stage.gridImage} className="w-full h-full object-cover grayscale hover:grayscale-0 transition-all duration-500" alt={stage.name} />
                </div>
              </div>
            ))}
          </div>
        )}

        {/* 角色九宮格列表 */}
        {project.proposedCharacters.some(c => c.gridImage) && (
          <div className="space-y-6 pt-6 border-t border-white/5">
            <span className="text-[10px] text-amber-500/70 font-mono uppercase tracking-widest block">CHARACTER_GRIDS</span>
            {project.proposedCharacters.filter(c => c.gridImage).map((char, i) => (
              <div key={i} className="space-y-2 group">
                <div className="flex items-center justify-between">
                  <span className="text-[9px] font-bold text-neutral-400 truncate block">{char.name}</span>
                  <Download className="w-3 h-3 text-neutral-600 hover:text-amber-500 cursor-pointer" onClick={() => downloadImage(char.gridImage!, `Character-${char.name}`)} />
                </div>
                <div className="aspect-square rounded-xl overflow-hidden border border-white/5 cursor-zoom-in" onClick={() => setExpandedImage(char.gridImage!)}>
                  <img src={char.gridImage} className="w-full h-full object-cover" alt={char.name} />
                </div>
              </div>
            ))}
          </div>
        )}
      </aside>
    </div>
  );
};

export default App;

import React from 'react';
import { Target, Users, MapPin, BookOpen, ImageIcon, Loader2 } from 'lucide-react';
import { ProjectDNA } from '../types';

interface ProductionPlanPhaseProps {
  dna: ProjectDNA;
  setDna: (dna: ProjectDNA) => void;
  onRenderCoreVisual: () => void;
  isLoading: boolean;
}

export const ProductionPlanPhase: React.FC<ProductionPlanPhaseProps> = ({ dna, setDna, onRenderCoreVisual, isLoading }) => {
  const updateField = (field: keyof ProjectDNA, value: string) => {
    setDna({ ...dna, [field]: value });
  };

  return (
    <div className="w-full space-y-12 pb-20 animate-in fade-in duration-700">
      <div className="text-center space-y-4">
        <h2 className="text-3xl font-serif text-neutral-100">優化拍攝 DNA</h2>
        <p className="text-sm text-neutral-500">確立影片風格、核心敘事與劇本細節。這將作為後續舞台與角色生成的基石。</p>
      </div>
      <div className="grid grid-cols-1 lg:grid-cols-2 gap-12">
        <div className="space-y-8">
          {[
            { id: 'coreNarrative', label: '核心敘事', icon: <Target className="w-3 h-3" /> },
            { id: 'socialBackground', label: '社會背景', icon: <Users className="w-3 h-3" /> },
            { id: 'environment', label: '地理環境', icon: <MapPin className="w-3 h-3" /> }
          ].map(f => (
            <div key={f.id} className="group relative">
              <label className="text-[10px] font-bold text-neutral-500 uppercase tracking-widest flex items-center gap-2 mb-3">
                {f.icon} {f.label}
              </label>
              <textarea 
                value={dna[f.id as keyof ProjectDNA] || ''} 
                onChange={(e) => updateField(f.id as keyof ProjectDNA, e.target.value)} 
                rows={6} 
                className="w-full bg-white/5 border border-white/10 rounded-xl p-4 text-sm text-neutral-300 outline-none focus:ring-1 focus:ring-amber-500 leading-relaxed transition-all" 
              />
            </div>
          ))}
        </div>
        <div className="flex flex-col space-y-3 group">
          <label className="text-[10px] font-bold text-neutral-500 uppercase tracking-widest flex items-center gap-2">
            <BookOpen className="w-3.5 h-3.5" /> 劇本摘要
          </label>
          <textarea 
            value={dna.story || ''} 
            onChange={(e) => updateField('story', e.target.value)} 
            rows={20} 
            className="w-full bg-white/5 border border-white/10 rounded-2xl p-6 text-sm focus:ring-1 focus:ring-amber-500 outline-none leading-relaxed font-serif text-neutral-300 transition-all flex-1" 
          />
          <button 
            onClick={onRenderCoreVisual}
            disabled={isLoading}
            className="w-full py-4 bg-amber-600/10 hover:bg-amber-600 text-amber-500 hover:text-white rounded-xl text-xs font-bold flex items-center justify-center gap-3 transition-all shadow-lg group/btn"
          >
            {isLoading ? <Loader2 className="w-4 h-4 animate-spin" /> : <ImageIcon className="w-4 h-4 group-hover/btn:scale-110 transition-transform" />}
            渲染核心視覺定位圖 (Core Visual DNA)
          </button>
        </div>
      </div>
    </div>
  );
};

import React, { useState, useEffect, useRef } from 'react';
import { ProductionPhase, Suggestion, ProjectState, ProjectDNA, StageDesign, CharacterDesign } from './types';
import { PHASE_METADATA } from './constants';
import { GeminiService } from './services/geminiService';
import { ApiKeySelector } from './components/ApiKeySelector';
import { InspirationPhase } from './components/InspirationPhase';
import { ProductionPlanPhase } from './components/ProductionPlanPhase';
import { VisualDevPhase } from './components/VisualDevPhase';
import { CharacterDevPhase } from './components/CharacterDevPhase';
import { 
  Film, Loader2, ArrowRight, 
  ChevronRight, Download, Upload,
  X, CheckCircle2, Terminal, MapPin, Users, Target,
  Grid, Image as ImageIcon, Maximize2, DownloadCloud, UserPlus
} from 'lucide-react';

const App: React.FC = () => {
  const [hasKey, setHasKey] = useState(false);
  const [isLoading, setIsLoading] = useState(false);
  const [isAnalyzing, setIsAnalyzing] = useState(false);
  const [isElaborating, setIsElaborating] = useState(false);
  const [input, setInput] = useState('');
  const [activeStep, setActiveStep] = useState<ProductionPhase>(ProductionPhase.INSPIRATION);
  const [expandedImage, setExpandedImage] = useState<string | null>(null);

  const [project, setProject] = useState<ProjectState>({
    currentPhase: ProductionPhase.INSPIRATION,
    initialInput: '',
    dna: { format: '電影', style: '寫實電影感 (Realistic Cinematic)', story: '', ratio: '16:9', environment: '', socialBackground: '', coreNarrative: '' },
    suggestions: [], proposedStages: [], proposedCharacters: [], history: [], generatedVideos: [], sceneGrid: []
  });

  const [tempDNA, setTempDNA] = useState<ProjectDNA>(project.dna);
  const fileInputRef = useRef<HTMLInputElement>(null);
  const geminiRef = useRef<GeminiService | null>(null);

  useEffect(() => {
    const checkKey = async () => {
      // @ts-ignore
      const exists = await window.aistudio.hasSelectedApiKey();
      if (exists) {
        setHasKey(true);
        geminiRef.current = new GeminiService(process.env.API_KEY || '');
      }
    };
    checkKey();
  }, []);

  useEffect(() => {
    if (activeStep === ProductionPhase.INSPIRATION && project.initialInput) {
      setInput(project.initialInput);
    }
  }, [project.initialInput, activeStep]);

  useEffect(() => {
    if (activeStep === ProductionPhase.VISUAL_DEV && project.proposedStages.length === 0 && !isAnalyzing && geminiRef.current) {
      handleIdentifyStages();
    }
    if (activeStep === ProductionPhase.CHARACTER_DEV && project.proposedCharacters.length === 0 && !isAnalyzing && geminiRef.current) {
      handleAutoAnalyzeCharacters();
    }
  }, [activeStep, project.proposedStages.length, project.proposedCharacters.length]);

  const handleIdentifyStages = async () => {
    if (!geminiRef.current || isAnalyzing) return;
    setIsAnalyzing(true);
    try {
      const stages = await geminiRef.current.identifyCoreStages(project.dna);
      setProject(prev => ({ ...prev, proposedStages: stages }));
    } catch (err) { console.error(err); } finally { setIsAnalyzing(false); }
  };

  const handleAutoAnalyzeCharacters = async () => {
    if (!geminiRef.current || isAnalyzing) return;
    setIsAnalyzing(true);
    try {
      const chars = await geminiRef.current.analyzeCharacters(project.dna);
      setProject(prev => ({ ...prev, proposedCharacters: chars }));
    } catch (err) { console.error(err); } finally { setIsAnalyzing(false); }
  };

  const handleSubmitIdea = async (e?: React.FormEvent) => {
    if (e) e.preventDefault();
    if (!input.trim() || isLoading || !geminiRef.current) return;
    setIsLoading(true);
    try {
      const results = await geminiRef.current.generateSuggestions(input, activeStep, JSON.stringify(project.dna));
      setProject(prev => ({ 
        ...prev, 
        suggestions: results || [], 
        initialInput: activeStep === ProductionPhase.INSPIRATION ? input : prev.initialInput
      }));
    } finally { setIsLoading(false); }
  };

  const handleSuggestionClick = async (s: Suggestion) => {
    if (!geminiRef.current) return;
    setIsElaborating(true);
    try {
      const detailedDNA = await geminiRef.current.elaboratePlan(s);
      setTempDNA(detailedDNA);
      setProject(prev => ({
        ...prev, dna: detailedDNA, currentPhase: ProductionPhase.PRODUCTION_PLAN, suggestions: []
      }));
      setActiveStep(ProductionPhase.PRODUCTION_PLAN);
    } finally { setIsElaborating(false); }
  };

  const handleRenderCoreVisualOnly = async () => {
    if (!geminiRef.current) return;
    setIsLoading(true);
    try {
      const coreImage = await geminiRef.current.generateCoreStyleVisual(tempDNA) || undefined;
      setProject(prev => ({ ...prev, coreSceneImage: coreImage }));
    } finally { setIsLoading(false); }
  };

  const confirmProductionPlan = async () => {
    if (!geminiRef.current) return;
    setIsLoading(true);
    try {
      // 如果還沒生成核心視覺，則生成一個
      let coreImage = project.coreSceneImage;
      if (!coreImage) {
        coreImage = await geminiRef.current.generateCoreStyleVisual(tempDNA) || undefined;
      }
      setProject(prev => ({
        ...prev, currentPhase: ProductionPhase.VISUAL_DEV, dna: { ...tempDNA }, coreSceneImage: coreImage,
        proposedStages: [], proposedCharacters: []
      }));
      setActiveStep(ProductionPhase.VISUAL_DEV);
    } finally { setIsLoading(false); }
  };

  const saveProject = () => {
    const dataToSave = { ...project, initialInput: input };
    const data = JSON.stringify(dataToSave, null, 2);
    const blob = new Blob([data], { type: 'application/json' });
    const url = URL.createObjectURL(blob);
    const link = document.createElement('a');
    link.href = url;
    link.download = `montage-project-${new Date().toISOString().slice(0, 10)}.json`;
    link.click();
  };

  const loadProject = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;
    const reader = new FileReader();
    reader.onload = (event) => {
      try {
        const data = JSON.parse(event.target?.result as string) as ProjectState;
        if (data.currentPhase && data.dna) {
          setProject(data);
          setActiveStep(data.currentPhase);
          setTempDNA(data.dna);
          if (data.initialInput) setInput(data.initialInput);
        }
      } catch (err) { alert('檔案格式錯誤。'); }
    };
    reader.readAsText(file);
    if (fileInputRef.current) fileInputRef.current.value = '';
  };

  const handleRenderStageGrid = async (idx: number) => {
    if (!geminiRef.current) return;
    setIsLoading(true);
    setProject(prev => ({ ...prev, selectedStageIndex: idx }));
    try {
      const gridResult = await geminiRef.current.generateSceneGrid(project.dna, project.proposedStages[idx]);
      if (gridResult) {
        setProject(prev => {
          const newStages = [...prev.proposedStages];
          newStages[idx] = { ...newStages[idx], gridImage: gridResult };
          return { ...prev, proposedStages: newStages };
        });
      }
    } finally { setIsLoading(false); }
  };

  const handleRenderCharacterGrid = async (idx: number) => {
    if (!geminiRef.current) return;
    setIsLoading(true);
    setProject(prev => ({ ...prev, selectedCharacterIndex: idx }));
    try {
      const gridResult = await geminiRef.current.generateCharacterGrid(project.dna, project.proposedCharacters[idx]);
      if (gridResult) {
        setProject(prev => {
          const newChars = [...prev.proposedCharacters];
          newChars[idx] = { ...newChars[idx], gridImage: gridResult };
          return { ...prev, proposedCharacters: newChars };
        });
      }
    } finally { setIsLoading(false); }
  };

  const updateStage = (idx: number, field: keyof StageDesign, value: string) => {
    setProject(prev => {
      const newStages = [...prev.proposedStages];
      newStages[idx] = { ...newStages[idx], [field]: value };
      return { ...prev, proposedStages: newStages };
    });
  };

  const updateCharacter = (idx: number, field: keyof CharacterDesign, value: string) => {
    setProject(prev => {
      const newChars = [...prev.proposedCharacters];
      newChars[idx] = { ...newChars[idx], [field]: value };
      return { ...prev, proposedCharacters: newChars };
    });
  };

  const handlePolishCharacter = async (idx: number, field: keyof CharacterDesign, label: string) => {
    if (!geminiRef.current || isLoading) return;
    setIsLoading(true);
    try {
      const char = project.proposedCharacters[idx];
      const polished = await geminiRef.current.polishText(char[field] as string, `角色塑造之${label}`);
      updateCharacter(idx, field, polished);
    } finally { setIsLoading(false); }
  };

  const downloadImage = (base64: string, name: string) => {
    const link = document.createElement('a');
    link.href = base64;
    link.download = `${name}.png`;
    link.click();
  };

  if (!hasKey) return <ApiKeySelector onSelected={() => setHasKey(true)} />;

  return (
    <div className="flex h-screen bg-[#050505] text-white overflow-hidden font-sans">
      {expandedImage && (
        <div className="fixed inset-0 bg-black/95 z-[100] flex flex-col items-center justify-center p-8 animate-in fade-in duration-300" onClick={() => setExpandedImage(null)}>
          <button className="absolute top-8 right-8 p-3 bg-white/5 hover:bg-amber-600 rounded-full transition-all group">
            <X className="w-8 h-8 text-white group-hover:scale-110" />
          </button>
          <div className="relative max-w-7xl w-full max-h-full" onClick={e => e.stopPropagation()}>
            <img src={expandedImage} className="w-full h-full object-contain shadow-2xl rounded-lg border border-white/10" />
            <button onClick={() => downloadImage(expandedImage, 'montage-asset')} className="absolute bottom-4 right-4 flex items-center gap-2 bg-amber-600 hover:bg-amber-500 px-6 py-3 rounded-full font-bold shadow-xl transition-all">
              <DownloadCloud className="w-5 h-5" /> 下載原始圖片
            </button>
          </div>
        </div>
      )}

      <aside className="w-64 border-r border-white/5 flex flex-col bg-black/40 p-6">
        <div className="flex items-center gap-3 mb-12">
          <div className="bg-amber-600 p-2 rounded-lg shadow-[0_0_15px_rgba(217,119,6,0.3)]"><Film className="w-6 h-6 text-white" /></div>
          <h1 className="text-lg font-serif font-bold tracking-widest text-white/90">電影蒙太奇</h1>
        </div>
        <nav className="flex-1 space-y-2">
          {Object.entries(PHASE_METADATA).map(([key, meta], idx) => {
            const phaseKey = key as ProductionPhase;
            const isActive = activeStep === phaseKey;
            const isAccessible = Object.values(ProductionPhase).indexOf(phaseKey) <= Object.values(ProductionPhase).indexOf(project.currentPhase);
            return (
              <button key={key} disabled={!isAccessible} onClick={() => setActiveStep(phaseKey)} className={`w-full relative flex items-center gap-4 p-3 rounded-lg transition-all text-left group ${isActive ? 'bg-amber-600/20 text-amber-500 ring-1 ring-amber-600/30' : 'text-neutral-600 hover:text-neutral-400'} ${!isAccessible ? 'opacity-30 grayscale cursor-not-allowed' : 'cursor-pointer'}`}>
                {isActive && <div className="absolute left-0 w-1 h-6 bg-amber-600 rounded-full" />}
                <span className="text-xl">{meta.icon}</span>
                <div className="flex flex-col"><span className="text-[9px] uppercase tracking-tighter opacity-50">Step 0{idx+1}</span><span className="text-sm font-bold">{meta.title}</span></div>
              </button>
            );
          })}
        </nav>
        <div className="mt-8 space-y-2 border-t border-white/5 pt-6">
          <button onClick={saveProject} className="w-full flex items-center gap-3 px-3 py-2 text-xs text-neutral-400 hover:text-white transition-colors group"><Download className="w-4 h-4 text-amber-600" /> <span>匯出專案</span></button>
          <button onClick={() => fileInputRef.current?.click()} className="w-full flex items-center gap-3 px-3 py-2 text-xs text-neutral-400 hover:text-white transition-colors group"><Upload className="w-4 h-4 text-amber-600" /> <span>匯入專案</span></button>
          <input type="file" ref={fileInputRef} onChange={loadProject} className="hidden" accept=".json" />
        </div>
      </aside>

      <main className="flex-1 flex flex-col relative overflow-hidden">
        <header className="h-16 px-8 border-b border-white/5 flex items-center justify-between z-10 bg-black/50 backdrop-blur-md">
          <div className="flex items-center gap-2"><Terminal className="w-4 h-4 text-amber-600" /><span className="text-[10px] text-neutral-500 uppercase tracking-[0.2em]">TERMINAL</span><ChevronRight className="w-3 h-3 text-neutral-600" /><span className="text-sm font-bold text-amber-500 uppercase">{PHASE_METADATA[activeStep]?.title}</span></div>
          <div className="flex items-center gap-4">
            {activeStep === ProductionPhase.PRODUCTION_PLAN && (
              <button onClick={confirmProductionPlan} disabled={isLoading} className="bg-amber-600 hover:bg-amber-500 px-6 py-2 rounded-full text-[11px] font-bold flex items-center gap-2 shadow-lg transition-all">
                {isLoading ? <Loader2 className="w-3.5 h-3.5 animate-spin" /> : <CheckCircle2 className="w-3.5 h-3.5" />} 確認方案並塑造舞台
              </button>
            )}
            {activeStep === ProductionPhase.VISUAL_DEV && (
              <button onClick={() => setActiveStep(ProductionPhase.CHARACTER_DEV)} className="bg-amber-600 hover:bg-amber-500 px-6 py-2 rounded-full text-[11px] font-bold flex items-center gap-2 shadow-lg transition-all">
                <UserPlus className="w-3.5 h-3.5" /> 進行角色塑造
              </button>
            )}
          </div>
        </header>

        <section className="flex-1 flex flex-col items-center justify-start p-8 max-w-5xl mx-auto w-full overflow-y-auto">
          {activeStep === ProductionPhase.INSPIRATION && (
            <InspirationPhase input={input} setInput={setInput} isLoading={isLoading} isElaborating={isElaborating} suggestions={project.suggestions} onSubmit={handleSubmitIdea} onSuggestionClick={handleSuggestionClick} guideText={PHASE_METADATA[activeStep]?.guide} />
          )}
          {activeStep === ProductionPhase.PRODUCTION_PLAN && (
            <ProductionPlanPhase dna={tempDNA} setDna={setTempDNA} onRenderCoreVisual={handleRenderCoreVisualOnly} isLoading={isLoading} />
          )}
          {activeStep === ProductionPhase.VISUAL_DEV && (
            <VisualDevPhase project={project} isAnalyzing={isAnalyzing} isLoading={isLoading} onUpdateStage={updateStage} onRenderGrid={handleRenderStageGrid} guideText={PHASE_METADATA[activeStep]?.guide} />
          )}
          {activeStep === ProductionPhase.CHARACTER_DEV && (
            <CharacterDevPhase project={project} isAnalyzing={isAnalyzing} isLoading={isLoading} onUpdateCharacter={updateCharacter} onPolishCharacter={handlePolishCharacter} onRenderGrid={handleRenderCharacterGrid} guideText={PHASE_METADATA[activeStep]?.guide} />
          )}
        </section>
      </main>

      <aside className="w-80 border-l border-white/5 bg-black/40 p-6 flex flex-col gap-8 overflow-y-auto">
        <h3 className="text-[10px] font-bold text-neutral-500 uppercase tracking-widest border-b border-white/5 pb-2">視覺檔案 (Asset)</h3>

        {/* 核心視覺 */}
        <div className="space-y-4">
          <span className="text-[10px] text-amber-500/70 font-mono uppercase tracking-widest block">CORE_VISUAL</span>
          {project.coreSceneImage ? (
            <div className="aspect-video rounded-2xl overflow-hidden border border-white/10 shadow-lg cursor-zoom-in" onClick={() => setExpandedImage(project.coreSceneImage!)}>
              <img src={project.coreSceneImage} className="w-full h-full object-cover" alt="Core Visual" />
            </div>
          ) : (
            <div className="py-12 border border-dashed border-white/10 rounded-2xl text-center opacity-30">
              <ImageIcon className="w-6 h-6 mx-auto mb-2 text-neutral-700" />
              <p className="text-[8px] uppercase tracking-widest">等待核心視覺</p>
            </div>
          )}
        </div>

        {/* 舞台九宮格列表 */}
        {project.proposedStages.some(s => s.gridImage) && (
          <div className="space-y-6 pt-6 border-t border-white/5">
            <span className="text-[10px] text-amber-500/70 font-mono uppercase tracking-widest block">STAGE_GRIDS</span>
            {project.proposedStages.filter(s => s.gridImage).map((stage, i) => (
              <div key={i} className="space-y-2 group">
                <div className="flex items-center justify-between">
                  <span className="text-[9px] font-bold text-neutral-400 truncate block">{stage.name}</span>
                  <Download className="w-3 h-3 text-neutral-600 hover:text-amber-500 cursor-pointer" onClick={() => downloadImage(stage.gridImage!, `Stage-${stage.name}`)} />
                </div>
                <div className="aspect-square rounded-xl overflow-hidden border border-white/5 cursor-zoom-in" onClick={() => setExpandedImage(stage.gridImage!)}>
                  <img src={stage.gridImage} className="w-full h-full object-cover grayscale hover:grayscale-0 transition-all duration-500" alt={stage.name} />
                </div>
              </div>
            ))}
          </div>
        )}

        {/* 角色九宮格列表 */}
        {project.proposedCharacters.some(c => c.gridImage) && (
          <div className="space-y-6 pt-6 border-t border-white/5">
            <span className="text-[10px] text-amber-500/70 font-mono uppercase tracking-widest block">CHARACTER_GRIDS</span>
            {project.proposedCharacters.filter(c => c.gridImage).map((char, i) => (
              <div key={i} className="space-y-2 group">
                <div className="flex items-center justify-between">
                  <span className="text-[9px] font-bold text-neutral-400 truncate block">{char.name}</span>
                  <Download className="w-3 h-3 text-neutral-600 hover:text-amber-500 cursor-pointer" onClick={() => downloadImage(char.gridImage!, `Character-${char.name}`)} />
                </div>
                <div className="aspect-square rounded-xl overflow-hidden border border-white/5 cursor-zoom-in" onClick={() => setExpandedImage(char.gridImage!)}>
                  <img src={char.gridImage} className="w-full h-full object-cover" alt={char.name} />
                </div>
              </div>
            ))}
          </div>
        )}
      </aside>
    </div>
  );
};

export default App;

import React from 'react';
import { Loader2, Sparkles, Monitor, Palette, Layout } from 'lucide-react';
import { Suggestion, ProjectDNA } from '../types';

interface InspirationPhaseProps {
  input: string;
  setInput: (val: string) => void;
  isLoading: boolean;
  isElaborating: boolean;
  suggestions: Suggestion[];
  onSubmit: (e: React.FormEvent) => void;
  onSuggestionClick: (s: Suggestion) => void;
  guideText: string;
  dna: ProjectDNA;
  onUpdateDNA: (field: keyof ProjectDNA, value: string) => void;
}

export const InspirationPhase: React.FC<InspirationPhaseProps> = ({
  input, setInput, isLoading, isElaborating, suggestions, onSubmit, onSuggestionClick, guideText, dna, onUpdateDNA
}) => {
  return (
    <div className="w-full max-w-3xl mt-12 mb-12 animate-in fade-in slide-in-from-top-4 duration-700">
      <h2 className="text-xl md:text-2xl font-serif text-center mb-8 text-neutral-100">{guideText}</h2>

      {/* 核心設定列 */}
      <div className="grid grid-cols-1 md:grid-cols-3 gap-4 mb-8">
        <div className="space-y-2">
          <label className="text-[10px] font-bold text-neutral-500 uppercase tracking-widest flex items-center gap-2">
            <Layout className="w-3 h-3 text-amber-600" /> 製作形式
          </label>
          <select 
            value={dna.format} 
            onChange={(e) => onUpdateDNA('format', e.target.value)}
            className="w-full bg-white/5 border border-white/10 rounded-xl px-4 py-2.5 text-xs text-neutral-300 outline-none focus:ring-1 focus:ring-amber-500 transition-all appearance-none"
          >
            {['電影', '動畫', '商業廣告', '紀錄片', '音樂錄影帶 (MV)'].map(f => <option key={f} value={f} className="bg-neutral-900">{f}</option>)}
          </select>
        </div>

        <div className="space-y-2">
          <label className="text-[10px] font-bold text-neutral-500 uppercase tracking-widest flex items-center gap-2">
            <Palette className="w-3 h-3 text-amber-600" /> 視覺風格
          </label>
          <input 
            type="text"
            value={dna.style}
            onChange={(e) => onUpdateDNA('style', e.target.value)}
            placeholder="例如：寫實電影感、賽博龐克..."
            className="w-full bg-white/5 border border-white/10 rounded-xl px-4 py-2.5 text-xs text-neutral-300 outline-none focus:ring-1 focus:ring-amber-500 transition-all"
          />
        </div>

        <div className="space-y-2">
          <label className="text-[10px] font-bold text-neutral-500 uppercase tracking-widest flex items-center gap-2">
            <Monitor className="w-3 h-3 text-amber-600" /> 畫面比例
          </label>
          <select 
            value={dna.ratio} 
            onChange={(e) => onUpdateDNA('ratio', e.target.value)}
            className="w-full bg-white/5 border border-white/10 rounded-xl px-4 py-2.5 text-xs text-neutral-300 outline-none focus:ring-1 focus:ring-amber-500 transition-all appearance-none"
          >
            {['16:9', '9:16', '2.39:1 (寬螢幕)', '4:3', '1:1'].map(r => <option key={r} value={r} className="bg-neutral-900">{r}</option>)}
          </select>
        </div>
      </div>

      <form onSubmit={onSubmit} className="relative group mb-12">
        <textarea 
          value={input} 
          onChange={(e) => setInput(e.target.value)} 
          placeholder="在此輸入您的創意指令或靈感碎片..." 
          rows={4} 
          className="w-full bg-white/5 border border-white/10 p-5 rounded-2xl text-lg focus:outline-none focus:ring-2 focus:ring-amber-600/50 resize-none shadow-2xl transition-all" 
        />
        <button 
          type="submit" 
          disabled={isLoading || !input.trim()} 
          className="absolute right-3 bottom-3 bg-amber-600 hover:bg-amber-500 p-4 rounded-xl shadow-lg transition-all group/btn"
        >
          {isLoading ? <Loader2 className="w-6 h-6 animate-spin" /> : <Sparkles className="w-6 h-6 group-hover/btn:scale-110 transition-transform" />}
        </button>
      </form>

      {!isElaborating && suggestions?.length > 0 && (
        <div className="w-full grid grid-cols-1 md:grid-cols-3 gap-6 mt-16 animate-in slide-in-from-bottom-8 duration-700">
          {suggestions.map((s, i) => (
            <button 
              key={i} 
              onClick={() => onSuggestionClick(s)} 
              className="glass p-8 rounded-2xl text-center border-white/5 hover:border-amber-600 group transition-all flex flex-col items-center"
            >
              <h3 className="text-lg font-serif font-bold mb-4 line-clamp-2 h-14 flex items-center justify-center text-neutral-200">{s.title}</h3>
              <div className="flex flex-wrap justify-center gap-1.5 mt-auto">
                {s.tags?.map(t => <span key={t} className="text-[9px] bg-amber-900/30 px-2 py-0.5 rounded text-amber-200/60 border border-amber-600/10">#{t}</span>)}
              </div>
            </button>
          ))}
        </div>
      )}

      {isElaborating && (
        <div className="w-full flex flex-col items-center gap-4 mt-20 animate-pulse">
          <Loader2 className="w-8 h-8 text-amber-600 animate-spin" />
          <p className="text-xs font-bold text-amber-500 uppercase tracking-widest">正在擴充拍攝方案 DNA...</p>
        </div>
      )}
    </div>
  );
};

import React, { useState, useEffect, useRef } from 'react';
import { ProductionPhase, Suggestion, ProjectState, ProjectDNA, StageDesign, CharacterDesign } from './types';
import { PHASE_METADATA } from './constants';
import { GeminiService } from './services/geminiService';
import { ApiKeySelector } from './components/ApiKeySelector';
import { InspirationPhase } from './components/InspirationPhase';
import { ProductionPlanPhase } from './components/ProductionPlanPhase';
import { VisualDevPhase } from './components/VisualDevPhase';
import { CharacterDevPhase } from './components/CharacterDevPhase';
import { 
  Film, Loader2, ArrowRight, 
  ChevronRight, Download, Upload,
  X, CheckCircle2, Terminal, MapPin, Users, Target,
  Grid, Image as ImageIcon, Maximize2, DownloadCloud, UserPlus
} from 'lucide-react';

const App: React.FC = () => {
  const [hasKey, setHasKey] = useState(false);
  const [isLoading, setIsLoading] = useState(false);
  const [isAnalyzing, setIsAnalyzing] = useState(false);
  const [isElaborating, setIsElaborating] = useState(false);
  const [input, setInput] = useState('');
  const [activeStep, setActiveStep] = useState<ProductionPhase>(ProductionPhase.INSPIRATION);
  const [expandedImage, setExpandedImage] = useState<string | null>(null);

  const [project, setProject] = useState<ProjectState>({
    currentPhase: ProductionPhase.INSPIRATION,
    initialInput: '',
    dna: { format: '電影', style: '寫實電影感 (Realistic Cinematic)', story: '', ratio: '16:9', environment: '', socialBackground: '', coreNarrative: '' },
    suggestions: [], proposedStages: [], proposedCharacters: [], history: [], generatedVideos: [], sceneGrid: []
  });

  const [tempDNA, setTempDNA] = useState<ProjectDNA>(project.dna);
  const fileInputRef = useRef<HTMLInputElement>(null);
  const geminiRef = useRef<GeminiService | null>(null);

  useEffect(() => {
    const checkKey = async () => {
      // @ts-ignore
      const exists = await window.aistudio.hasSelectedApiKey();
      if (exists) {
        setHasKey(true);
        geminiRef.current = new GeminiService(process.env.API_KEY || '');
      }
    };
    checkKey();
  }, []);

  useEffect(() => {
    if (activeStep === ProductionPhase.INSPIRATION && project.initialInput) {
      setInput(project.initialInput);
    }
  }, [project.initialInput, activeStep]);

  useEffect(() => {
    if (activeStep === ProductionPhase.VISUAL_DEV && project.proposedStages.length === 0 && !isAnalyzing && geminiRef.current) {
      handleIdentifyStages();
    }
    if (activeStep === ProductionPhase.CHARACTER_DEV && project.proposedCharacters.length === 0 && !isAnalyzing && geminiRef.current) {
      handleAutoAnalyzeCharacters();
    }
  }, [activeStep, project.proposedStages.length, project.proposedCharacters.length]);

  const handleIdentifyStages = async () => {
    if (!geminiRef.current || isAnalyzing) return;
    setIsAnalyzing(true);
    try {
      const stages = await geminiRef.current.identifyCoreStages(project.dna);
      setProject(prev => ({ ...prev, proposedStages: stages }));
    } catch (err) { console.error(err); } finally { setIsAnalyzing(false); }
  };

  const handleAutoAnalyzeCharacters = async () => {
    if (!geminiRef.current || isAnalyzing) return;
    setIsAnalyzing(true);
    try {
      const chars = await geminiRef.current.analyzeCharacters(project.dna);
      setProject(prev => ({ ...prev, proposedCharacters: chars }));
    } catch (err) { console.error(err); } finally { setIsAnalyzing(false); }
  };

  const updateDNAField = (field: keyof ProjectDNA, value: string) => {
    setProject(prev => ({
      ...prev,
      dna: { ...prev.dna, [field]: value }
    }));
    setTempDNA(prev => ({ ...prev, [field]: value }));
  };

  const handleSubmitIdea = async (e?: React.FormEvent) => {
    if (e) e.preventDefault();
    if (!input.trim() || isLoading || !geminiRef.current) return;
    setIsLoading(true);
    try {
      const results = await geminiRef.current.generateSuggestions(input, activeStep, JSON.stringify(project.dna));
      setProject(prev => ({ 
        ...prev, 
        suggestions: results || [], 
        initialInput: activeStep === ProductionPhase.INSPIRATION ? input : prev.initialInput
      }));
    } finally { setIsLoading(false); }
  };

  const handleSuggestionClick = async (s: Suggestion) => {
    if (!geminiRef.current) return;
    setIsElaborating(true);
    try {
      const detailedDNA = await geminiRef.current.elaboratePlan(s, project.dna);
      setTempDNA(detailedDNA);
      setProject(prev => ({
        ...prev, dna: detailedDNA, currentPhase: ProductionPhase.PRODUCTION_PLAN, suggestions: []
      }));
      setActiveStep(ProductionPhase.PRODUCTION_PLAN);
    } finally { setIsElaborating(false); }
  };

  const handleRenderCoreVisualOnly = async () => {
    if (!geminiRef.current) return;
    setIsLoading(true);
    try {
      const coreImage = await geminiRef.current.generateCoreStyleVisual(tempDNA) || undefined;
      setProject(prev => ({ ...prev, coreSceneImage: coreImage }));
    } finally { setIsLoading(false); }
  };

  const confirmProductionPlan = async () => {
    if (!geminiRef.current) return;
    setIsLoading(true);
    try {
      let coreImage = project.coreSceneImage;
      if (!coreImage) {
        coreImage = await geminiRef.current.generateCoreStyleVisual(tempDNA) || undefined;
      }
      setProject(prev => ({
        ...prev, currentPhase: ProductionPhase.VISUAL_DEV, dna: { ...tempDNA }, coreSceneImage: coreImage,
        proposedStages: [], proposedCharacters: []
      }));
      setActiveStep(ProductionPhase.VISUAL_DEV);
    } finally { setIsLoading(false); }
  };

  const saveProject = () => {
    const dataToSave = { ...project, initialInput: input };
    const data = JSON.stringify(dataToSave, null, 2);
    const blob = new Blob([data], { type: 'application/json' });
    const url = URL.createObjectURL(blob);
    const link = document.createElement('a');
    link.href = url;
    link.download = `montage-project-${new Date().toISOString().slice(0, 10)}.json`;
    link.click();
  };

  const loadProject = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;
    const reader = new FileReader();
    reader.onload = (event) => {
      try {
        const data = JSON.parse(event.target?.result as string) as ProjectState;
        if (data.currentPhase && data.dna) {
          setProject(data);
          setActiveStep(data.currentPhase);
          setTempDNA(data.dna);
          if (data.initialInput) setInput(data.initialInput);
        }
      } catch (err) { alert('檔案格式錯誤。'); }
    };
    reader.readAsText(file);
    if (fileInputRef.current) fileInputRef.current.value = '';
  };

  const handleRenderStageGrid = async (idx: number) => {
    if (!geminiRef.current) return;
    setIsLoading(true);
    setProject(prev => ({ ...prev, selectedStageIndex: idx }));
    try {
      const gridResult = await geminiRef.current.generateSceneGrid(project.dna, project.proposedStages[idx]);
      if (gridResult) {
        setProject(prev => {
          const newStages = [...prev.proposedStages];
          newStages[idx] = { ...newStages[idx], gridImage: gridResult };
          return { ...prev, proposedStages: newStages };
        });
      }
    } finally { setIsLoading(false); }
  };

  const handleRenderCharacterGrid = async (idx: number) => {
    if (!geminiRef.current) return;
    setIsLoading(true);
    setProject(prev => ({ ...prev, selectedCharacterIndex: idx }));
    try {
      const gridResult = await geminiRef.current.generateCharacterGrid(project.dna, project.proposedCharacters[idx]);
      if (gridResult) {
        setProject(prev => {
          const newChars = [...prev.proposedCharacters];
          newChars[idx] = { ...newChars[idx], gridImage: gridResult };
          return { ...prev, proposedCharacters: newChars };
        });
      }
    } finally { setIsLoading(false); }
  };

  const updateStage = (idx: number, field: keyof StageDesign, value: string) => {
    setProject(prev => {
      const newStages = [...prev.proposedStages];
      newStages[idx] = { ...newStages[idx], [field]: value };
      return { ...prev, proposedStages: newStages };
    });
  };

  const updateCharacter = (idx: number, field: keyof CharacterDesign, value: string) => {
    setProject(prev => {
      const newChars = [...prev.proposedCharacters];
      newChars[idx] = { ...newChars[idx], [field]: value };
      return { ...prev, proposedCharacters: newChars };
    });
  };

  const handlePolishCharacter = async (idx: number, field: keyof CharacterDesign, label: string) => {
    if (!geminiRef.current || isLoading) return;
    setIsLoading(true);
    try {
      const char = project.proposedCharacters[idx];
      const polished = await geminiRef.current.polishText(char[field] as string, `角色塑造之${label}`);
      updateCharacter(idx, field, polished);
    } finally { setIsLoading(false); }
  };

  const downloadImage = (base64: string, name: string) => {
    const link = document.createElement('a');
    link.href = base64;
    link.download = `${name}.png`;
    link.click();
  };

  if (!hasKey) return <ApiKeySelector onSelected={() => setHasKey(true)} />;

  return (
    <div className="flex h-screen bg-[#050505] text-white overflow-hidden font-sans">
      {expandedImage && (
        <div className="fixed inset-0 bg-black/95 z-[100] flex flex-col items-center justify-center p-8 animate-in fade-in duration-300" onClick={() => setExpandedImage(null)}>
          <button className="absolute top-8 right-8 p-3 bg-white/5 hover:bg-amber-600 rounded-full transition-all group">
            <X className="w-8 h-8 text-white group-hover:scale-110" />
          </button>
          <div className="relative max-w-7xl w-full max-h-full" onClick={e => e.stopPropagation()}>
            <img src={expandedImage} className="w-full h-full object-contain shadow-2xl rounded-lg border border-white/10" />
            <button onClick={() => downloadImage(expandedImage, 'montage-asset')} className="absolute bottom-4 right-4 flex items-center gap-2 bg-amber-600 hover:bg-amber-500 px-6 py-3 rounded-full font-bold shadow-xl transition-all">
              <DownloadCloud className="w-5 h-5" /> 下載原始圖片
            </button>
          </div>
        </div>
      )}

      <aside className="w-64 border-r border-white/5 flex flex-col bg-black/40 p-6">
        <div className="flex items-center gap-3 mb-12">
          <div className="bg-amber-600 p-2 rounded-lg shadow-[0_0_15px_rgba(217,119,6,0.3)]"><Film className="w-6 h-6 text-white" /></div>
          <h1 className="text-lg font-serif font-bold tracking-widest text-white/90">電影蒙太奇</h1>
        </div>
        <nav className="flex-1 space-y-2">
          {Object.entries(PHASE_METADATA).map(([key, meta], idx) => {
            const phaseKey = key as ProductionPhase;
            const isActive = activeStep === phaseKey;
            const isAccessible = Object.values(ProductionPhase).indexOf(phaseKey) <= Object.values(ProductionPhase).indexOf(project.currentPhase);
            return (
              <button key={key} disabled={!isAccessible} onClick={() => setActiveStep(phaseKey)} className={`w-full relative flex items-center gap-4 p-3 rounded-lg transition-all text-left group ${isActive ? 'bg-amber-600/20 text-amber-500 ring-1 ring-amber-600/30' : 'text-neutral-600 hover:text-neutral-400'} ${!isAccessible ? 'opacity-30 grayscale cursor-not-allowed' : 'cursor-pointer'}`}>
                {isActive && <div className="absolute left-0 w-1 h-6 bg-amber-600 rounded-full" />}
                <span className="text-xl">{meta.icon}</span>
                <div className="flex flex-col"><span className="text-[9px] uppercase tracking-tighter opacity-50">Step 0{idx+1}</span><span className="text-sm font-bold">{meta.title}</span></div>
              </button>
            );
          })}
        </nav>
        <div className="mt-8 space-y-2 border-t border-white/5 pt-6">
          <button onClick={saveProject} className="w-full flex items-center gap-3 px-3 py-2 text-xs text-neutral-400 hover:text-white transition-colors group"><Download className="w-4 h-4 text-amber-600" /> <span>匯出專案</span></button>
          <button onClick={() => fileInputRef.current?.click()} className="w-full flex items-center gap-3 px-3 py-2 text-xs text-neutral-400 hover:text-white transition-colors group"><Upload className="w-4 h-4 text-amber-600" /> <span>匯入專案</span></button>
          <input type="file" ref={fileInputRef} onChange={loadProject} className="hidden" accept=".json" />
        </div>
      </aside>

      <main className="flex-1 flex flex-col relative overflow-hidden">
        <header className="h-16 px-8 border-b border-white/5 flex items-center justify-between z-10 bg-black/50 backdrop-blur-md">
          <div className="flex items-center gap-2"><Terminal className="w-4 h-4 text-amber-600" /><span className="text-[10px] text-neutral-500 uppercase tracking-[0.2em]">TERMINAL</span><ChevronRight className="w-3 h-3 text-neutral-600" /><span className="text-sm font-bold text-amber-500 uppercase">{PHASE_METADATA[activeStep]?.title}</span></div>
          <div className="flex items-center gap-4">
            {activeStep === ProductionPhase.PRODUCTION_PLAN && (
              <button onClick={confirmProductionPlan} disabled={isLoading} className="bg-amber-600 hover:bg-amber-500 px-6 py-2 rounded-full text-[11px] font-bold flex items-center gap-2 shadow-lg transition-all">
                {isLoading ? <Loader2 className="w-3.5 h-3.5 animate-spin" /> : <CheckCircle2 className="w-3.5 h-3.5" />} 確認方案並塑造舞台
              </button>
            )}
            {activeStep === ProductionPhase.VISUAL_DEV && (
              <button onClick={() => setActiveStep(ProductionPhase.CHARACTER_DEV)} className="bg-amber-600 hover:bg-amber-500 px-6 py-2 rounded-full text-[11px] font-bold flex items-center gap-2 shadow-lg transition-all">
                <UserPlus className="w-3.5 h-3.5" /> 進行角色塑造
              </button>
            )}
          </div>
        </header>

        <section className="flex-1 flex flex-col items-center justify-start p-8 max-w-5xl mx-auto w-full overflow-y-auto">
          {activeStep === ProductionPhase.INSPIRATION && (
            <InspirationPhase 
              input={input} 
              setInput={setInput} 
              isLoading={isLoading} 
              isElaborating={isElaborating} 
              suggestions={project.suggestions} 
              onSubmit={handleSubmitIdea} 
              onSuggestionClick={handleSuggestionClick} 
              guideText={PHASE_METADATA[activeStep]?.guide}
              dna={project.dna}
              onUpdateDNA={updateDNAField}
            />
          )}
          {activeStep === ProductionPhase.PRODUCTION_PLAN && (
            <ProductionPlanPhase dna={tempDNA} setDna={setTempDNA} onRenderCoreVisual={handleRenderCoreVisualOnly} isLoading={isLoading} />
          )}
          {activeStep === ProductionPhase.VISUAL_DEV && (
            <VisualDevPhase project={project} isAnalyzing={isAnalyzing} isLoading={isLoading} onUpdateStage={updateStage} onRenderGrid={handleRenderStageGrid} guideText={PHASE_METADATA[activeStep]?.guide} />
          )}
          {activeStep === ProductionPhase.CHARACTER_DEV && (
            <CharacterDevPhase project={project} isAnalyzing={isAnalyzing} isLoading={isLoading} onUpdateCharacter={updateCharacter} onPolishCharacter={handlePolishCharacter} onRenderGrid={handleRenderCharacterGrid} guideText={PHASE_METADATA[activeStep]?.guide} />
          )}
        </section>
      </main>

      <aside className="w-80 border-l border-white/5 bg-black/40 p-6 flex flex-col gap-8 overflow-y-auto">
        <h3 className="text-[10px] font-bold text-neutral-500 uppercase tracking-widest border-b border-white/5 pb-2">視覺檔案 (Asset)</h3>

        {/* 核心視覺 */}
        <div className="space-y-4">
          <span className="text-[10px] text-amber-500/70 font-mono uppercase tracking-widest block">CORE_VISUAL</span>
          {project.coreSceneImage ? (
            <div className="aspect-video rounded-2xl overflow-hidden border border-white/10 shadow-lg cursor-zoom-in" onClick={() => setExpandedImage(project.coreSceneImage!)}>
              <img src={project.coreSceneImage} className="w-full h-full object-cover" alt="Core Visual" />
            </div>
          ) : (
            <div className="py-12 border border-dashed border-white/10 rounded-2xl text-center opacity-30">
              <ImageIcon className="w-6 h-6 mx-auto mb-2 text-neutral-700" />
              <p className="text-[8px] uppercase tracking-widest">等待核心視覺</p>
            </div>
          )}
        </div>

        {/* 舞台九宮格列表 */}
        {project.proposedStages.some(s => s.gridImage) && (
          <div className="space-y-6 pt-6 border-t border-white/5">
            <span className="text-[10px] text-amber-500/70 font-mono uppercase tracking-widest block">STAGE_GRIDS</span>
            {project.proposedStages.filter(s => s.gridImage).map((stage, i) => (
              <div key={i} className="space-y-2 group">
                <div className="flex items-center justify-between">
                  <span className="text-[9px] font-bold text-neutral-400 truncate block">{stage.name}</span>
                  <Download className="w-3 h-3 text-neutral-600 hover:text-amber-500 cursor-pointer" onClick={() => downloadImage(stage.gridImage!, `Stage-${stage.name}`)} />
                </div>
                <div className="aspect-square rounded-xl overflow-hidden border border-white/5 cursor-zoom-in" onClick={() => setExpandedImage(stage.gridImage!)}>
                  <img src={stage.gridImage} className="w-full h-full object-cover grayscale hover:grayscale-0 transition-all duration-500" alt={stage.name} />
                </div>
              </div>
            ))}
          </div>
        )}

        {/* 角色九宮格列表 */}
        {project.proposedCharacters.some(c => c.gridImage) && (
          <div className="space-y-6 pt-6 border-t border-white/5">
            <span className="text-[10px] text-amber-500/70 font-mono uppercase tracking-widest block">CHARACTER_GRIDS</span>
            {project.proposedCharacters.filter(c => c.gridImage).map((char, i) => (
              <div key={i} className="space-y-2 group">
                <div className="flex items-center justify-between">
                  <span className="text-[9px] font-bold text-neutral-400 truncate block">{char.name}</span>
                  <Download className="w-3 h-3 text-neutral-600 hover:text-amber-500 cursor-pointer" onClick={() => downloadImage(char.gridImage!, `Character-${char.name}`)} />
                </div>
                <div className="aspect-square rounded-xl overflow-hidden border border-white/5 cursor-zoom-in" onClick={() => setExpandedImage(char.gridImage!)}>
                  <img src={char.gridImage} className="w-full h-full object-cover" alt={char.name} />
                </div>
              </div>
            ))}
          </div>
        )}
      </aside>
    </div>
  );
};

export default App;

import { GoogleGenAI, Type } from "@google/genai";
import { SYSTEM_INSTRUCTION } from "../constants";
import { Suggestion, StageDesign, CharacterDesign, ProjectDNA, ProductionPhase } from "../types";

export class GeminiService {
  constructor(apiKey: string) { }

  async generateSuggestions(input: string, phase: ProductionPhase, context: string): Promise<Suggestion[]> {
    const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
    const currentDNA = JSON.parse(context) as ProjectDNA;

    const prompt = `
    目前的製作設定：
    - 形式：${currentDNA.format}
    - 預想風格：${currentDNA.style}
    - 畫面比例：${currentDNA.ratio}

    核心靈感/指令： "${input}"

    請根據上述設定與指令，提供三個具體的創意導向（頂尖導演層次提案）。
    如果是 INSPIRATION 階段，請發揮聯想力，自動推論出初步的：
    1. 地理環境 (environment)
    2. 社會背景 (socialBackground)
    3. 核心敘事 (coreNarrative)

    請回傳 JSON 陣列，包含 title, description, tags, environment, socialBackground, coreNarrative。`;

    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: [{ role: 'user', parts: [{ text: prompt }] }],
      config: {
        systemInstruction: SYSTEM_INSTRUCTION,
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.ARRAY,
          items: {
            type: Type.OBJECT,
            properties: {
              title: { type: Type.STRING },
              description: { type: Type.STRING },
              tags: { type: Type.ARRAY, items: { type: Type.STRING } },
              environment: { type: Type.STRING },
              socialBackground: { type: Type.STRING },
              coreNarrative: { type: Type.STRING }
            },
            required: ["title", "description", "tags"]
          }
        }
      }
    });
    return JSON.parse(response.text || "[]");
  }

  async elaboratePlan(suggestion: Suggestion, baseDNA: ProjectDNA): Promise<ProjectDNA> {
    const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
    const prompt = `
    請將以下提案擴充為完整的電影拍攝 DNA：
    提案標題：${suggestion.title}

    核心設定參考（必須以此為基底進行擴展）：
    - 形式：${baseDNA.format}
    - 視覺風格：${baseDNA.style}
    - 畫面比例：${baseDNA.ratio}

    擴充內容需包含：地理環境、社會背景、核心敘事與一份專業的劇本摘要。
    劇本摘要應聚焦於視覺張力與空間敘事。
    `;

    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: [{ role: 'user', parts: [{ text: prompt }] }],
      config: {
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.OBJECT,
          properties: {
            format: { type: Type.STRING },
            style: { type: Type.STRING },
            story: { type: Type.STRING },
            ratio: { type: Type.STRING },
            environment: { type: Type.STRING },
            socialBackground: { type: Type.STRING },
            coreNarrative: { type: Type.STRING }
          },
          required: ["format", "style", "story", "environment", "socialBackground", "coreNarrative"]
        }
      }
    });
    const result = JSON.parse(response.text || "{}");
    // 確保預設值不被覆蓋（除非 AI 有更優建議，但通常保留用戶預設）
    return {
      ...result,
      format: baseDNA.format,
      ratio: baseDNA.ratio,
      style: result.style || baseDNA.style
    };
  }

  async identifyCoreStages(dna: ProjectDNA): Promise<StageDesign[]> {
    const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
    const prompt = `你是一位頂尖電影美術指導與空間設計師。請針對提供的劇本內容進行核心舞台 (Core Stage) 的識別與視覺設計。

    劇本摘要：${dna.story}
    視覺風格：${dna.style} (形式：${dna.format})
    環境背景：${dna.environment}

    請回傳 JSON 陣列，包含 name 與詳盡的 description。`;

    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: [{ role: 'user', parts: [{ text: prompt }] }],
      config: {
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.ARRAY,
          items: {
            type: Type.OBJECT,
            properties: {
              name: { type: Type.STRING },
              description: { type: Type.STRING }
            },
            required: ["name", "description"]
          }
        }
      }
    });
    return JSON.parse(response.text || "[]");
  }

  async analyzeCharacters(dna: ProjectDNA): Promise<CharacterDesign[]> {
    const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
    const prompt = `你是一位頂尖電影選角指導。請設計角色視覺原型。
    劇本摘要：${dna.story}
    視覺風格：${dna.style} (形式：${dna.format})

    請回傳 JSON 陣列。`;

    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: [{ role: 'user', parts: [{ text: prompt }] }],
      config: {
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.ARRAY,
          items: {
            type: Type.OBJECT,
            properties: {
              name: { type: Type.STRING },
              role: { type: Type.STRING },
              physicalTraits: { type: Type.STRING },
              visualTone: { type: Type.STRING },
              motivation: { type: Type.STRING }
            },
            required: ["name", "role", "physicalTraits", "visualTone", "motivation"]
          }
        }
      }
    });
    return JSON.parse(response.text || "[]");
  }

  async polishText(text: string, type: string): Promise<string> {
    const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: `你是專業電影視覺指導。請進行場景化潤色，強調視覺細節與專業術語。類型：${type}。內容：${text}`,
    });
    return response.text || text;
  }

  async generateCoreStyleVisual(dna: ProjectDNA): Promise<string | null> {
    const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
    const prompt = `
      A professional cinematic mood board / style guide collage for the project: "${dna.coreNarrative}".
      Format: ${dna.format}. Style: ${dna.style}.
      STRICT LAYOUT REQUIREMENT: ONE single image that is a composite (split-screen/grid) showing 4-5 distinct cinematic perspectives:
      1. An Epic Wide Shot establishing the ${dna.environment}.
      2. A dramatic medium shot showcasing lighting.
      3. Close-up of symbolic prop.

      Unified color grading, 8k, cinematic.
    `;
    try {
      const response = await ai.models.generateContent({
        model: 'gemini-3-pro-image-preview',
        contents: { parts: [{ text: prompt }] },
        config: { imageConfig: { aspectRatio: dna.ratio.includes('9:16') ? "9:16" : "16:9", imageSize: "1K" } }
      });
      for (const part of response.candidates?.[0]?.content?.parts || []) {
        if (part.inlineData) return `data:image/png;base64,${part.inlineData.data}`;
      }
      return null;
    } catch (error) { return null; }
  }

  async generateSceneGrid(dna: ProjectDNA, stage: StageDesign): Promise<string> {
    const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
    const gridPrompt = `
      Professional 3x3 cinematic concept art storyboard for stage: "${stage.name}".
      Spatial Context: ${stage.description}. Style: ${dna.style}. Format: ${dna.format}.
      STRICT LAYOUT: 3x3 grid with EXACTLY NINE equal panels. 
    `;
    try {
      const response = await ai.models.generateContent({
        model: 'gemini-3-pro-image-preview',
        contents: { parts: [{ text: gridPrompt }] },
        config: { imageConfig: { aspectRatio: "1:1", imageSize: "1K" } }
      });
      for (const part of response.candidates?.[0]?.content?.parts || []) {
        if (part.inlineData) return `data:image/png;base64,${part.inlineData.data}`;
      }
    } catch (error) { console.error(error); }
    return "";
  }

  async generateCharacterGrid(dna: ProjectDNA, character: CharacterDesign): Promise<string> {
    const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
    const gridPrompt = `
      Professional 3x3 character concept art for: "${character.name}" (${character.role}).
      Traits: ${character.physicalTraits}. Style: ${dna.style}. Format: ${dna.format}.
      STRICT LAYOUT: 3x3 grid with EXACTLY NINE panels.
    `;
    try {
      const response = await ai.models.generateContent({
        model: 'gemini-3-pro-image-preview',
        contents: { parts: [{ text: gridPrompt }] },
        config: { imageConfig: { aspectRatio: "1:1", imageSize: "1K" } }
      });
      for (const part of response.candidates?.[0]?.content?.parts || []) {
        if (part.inlineData) return `data:image/png;base64,${part.inlineData.data}`;
      }
    } catch (error) { console.error(error); }
    return "";
  }
}

