import React, { useState, useEffect, useRef } from 'react';
import { ProductionPhase, Suggestion, ProjectState, ProjectDNA, StageDesign, CharacterDesign } from './types';
import { PHASE_METADATA } from './constants';
import { GeminiService } from './services/geminiService';
import { ApiKeySelector } from './components/ApiKeySelector';
import { InspirationPhase } from './components/InspirationPhase';
import { ProductionPlanPhase } from './components/ProductionPlanPhase';
import { VisualDevPhase } from './components/VisualDevPhase';
import { CharacterDevPhase } from './components/CharacterDevPhase';
import { 
  Film, Loader2, ArrowRight, 
  ChevronRight, Download, Upload,
  X, CheckCircle2, Terminal, MapPin, Users, Target,
  Grid, Image as ImageIcon, Maximize2, DownloadCloud, UserPlus
} from 'lucide-react';

const App: React.FC = () => {
  const [hasKey, setHasKey] = useState(false);
  const [isLoading, setIsLoading] = useState(false);
  const [isAnalyzing, setIsAnalyzing] = useState(false);
  const [isElaborating, setIsElaborating] = useState(false);
  const [input, setInput] = useState('');
  const [activeStep, setActiveStep] = useState<ProductionPhase>(ProductionPhase.INSPIRATION);
  const [expandedImage, setExpandedImage] = useState<string | null>(null);

  const [project, setProject] = useState<ProjectState>({
    currentPhase: ProductionPhase.INSPIRATION,
    initialInput: '',
    dna: { format: '電影', style: '寫實電影感', story: '', ratio: '16:9', environment: '', socialBackground: '', coreNarrative: '', directorVision: '' },
    suggestions: [], proposedStages: [], proposedCharacters: [], history: [], generatedVideos: [],
    coreStageImage: undefined 
  });

  const [tempDNA, setTempDNA] = useState<ProjectDNA>(project.dna);
  const fileInputRef = useRef<HTMLInputElement>(null);
  const geminiRef = useRef<GeminiService | null>(null);

  useEffect(() => {
    const checkKey = async () => {
      // @ts-ignore
      const exists = await window.aistudio.hasSelectedApiKey();
      if (exists) {
        setHasKey(true);
        geminiRef.current = new GeminiService(process.env.API_KEY || '');
      }
    };
    checkKey();
  }, []);

  useEffect(() => {
    if (activeStep === ProductionPhase.INSPIRATION && project.initialInput) {
      setInput(project.initialInput);
    }
  }, [project.initialInput, activeStep]);

  useEffect(() => {
    if (activeStep === ProductionPhase.VISUAL_DEV && project.proposedStages.length === 0 && !isAnalyzing && geminiRef.current) {
      handleIdentifyStages();
    }
    if (activeStep === ProductionPhase.CHARACTER_DEV && project.proposedCharacters.length === 0 && !isAnalyzing && geminiRef.current) {
      handleAutoAnalyzeCharacters();
    }
  }, [activeStep]);

  const handleIdentifyStages = async () => {
    if (!geminiRef.current || isAnalyzing) return;
    setIsAnalyzing(true);
    try {
      const stages = await geminiRef.current.identifyCoreStages(project.dna);
      setProject(prev => ({ ...prev, proposedStages: stages }));
    } catch (err) { console.error(err); } finally { setIsAnalyzing(false); }
  };

  const handleAutoAnalyzeCharacters = async () => {
    if (!geminiRef.current || isAnalyzing) return;
    setIsAnalyzing(true);
    try {
      const chars = await geminiRef.current.analyzeCharacters(project.dna);
      setProject(prev => ({ ...prev, proposedCharacters: chars }));
    } catch (err) { console.error(err); } finally { setIsAnalyzing(false); }
  };

  const updateDNAField = (field: keyof ProjectDNA, value: string) => {
    const updatedDNA = { ...project.dna, [field]: value };
    setProject(prev => ({ ...prev, dna: updatedDNA }));
    setTempDNA(updatedDNA);
  };

  const handleSubmitIdea = async (e?: React.FormEvent) => {
    if (e) e.preventDefault();
    if (!input.trim() || isLoading || !geminiRef.current) return;
    setIsLoading(true);
    try {
      const results = await geminiRef.current.generateSuggestions(input, activeStep, JSON.stringify(project.dna));
      setProject(prev => ({ 
        ...prev, 
        suggestions: results || [], 
        initialInput: activeStep === ProductionPhase.INSPIRATION ? input : prev.initialInput
      }));
    } finally { setIsLoading(false); }
  };

  const handleSuggestionClick = async (s: Suggestion) => {
    if (!geminiRef.current) return;
    setIsElaborating(true);
    try {
      const detailedDNA = await geminiRef.current.elaboratePlan(s, project.dna);
      setTempDNA(detailedDNA);
      setProject(prev => ({
        ...prev, 
        dna: detailedDNA, 
        currentPhase: ProductionPhase.PRODUCTION_PLAN, 
        suggestions: []
      }));
      setActiveStep(ProductionPhase.PRODUCTION_PLAN);
    } finally { setIsElaborating(false); }
  };

  const handleRenderCoreStageOnly = async () => {
    if (!geminiRef.current) return;
    setIsLoading(true);
    try {
      const coreImage = await geminiRef.current.generateCoreStyleVisual(tempDNA) || undefined;
      setProject(prev => ({ ...prev, coreStageImage: coreImage }));
    } finally { setIsLoading(false); }
  };

  const confirmProductionPlan = async () => {
    if (!geminiRef.current) return;
    setIsLoading(true);
    try {
      let coreImage = project.coreStageImage;
      if (!coreImage) {
        coreImage = await geminiRef.current.generateCoreStyleVisual(tempDNA) || undefined;
      }
      setProject(prev => ({
        ...prev, 
        currentPhase: ProductionPhase.VISUAL_DEV, 
        dna: { ...tempDNA }, 
        coreStageImage: coreImage,
        proposedStages: [], 
        proposedCharacters: []
      }));
      setActiveStep(ProductionPhase.VISUAL_DEV);
    } finally { setIsLoading(false); }
  };

  const handleProceedToCharacterDev = () => {
    setProject(prev => ({ ...prev, currentPhase: ProductionPhase.CHARACTER_DEV }));
    setActiveStep(ProductionPhase.CHARACTER_DEV);
  };

  const saveProject = () => {
    // 確保 initialInput 同步
    const stateToSave: ProjectState = { 
      ...project, 
      initialInput: input 
    };
    const data = JSON.stringify(stateToSave, null, 2);
    const blob = new Blob([data], { type: 'application/json' });
    const url = URL.createObjectURL(blob);
    const link = document.createElement('a');
    link.href = url;
    link.download = `montage-project-${new Date().toISOString().slice(0, 10)}.json`;
    link.click();
  };

  const loadProject = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;
    const reader = new FileReader();
    reader.onload = (event) => {
      try {
        const data = JSON.parse(event.target?.result as string) as ProjectState;
        if (data.currentPhase && data.dna) {
          setProject(data);
          setActiveStep(data.currentPhase);
          setTempDNA(data.dna);
          if (data.initialInput) setInput(data.initialInput);
        }
      } catch (err) { alert('檔案格式錯誤。'); }
    };
    reader.readAsText(file);
    if (fileInputRef.current) fileInputRef.current.value = '';
  };

  const handleRenderStageGrid = async (idx: number) => {
    if (!geminiRef.current) return;
    setIsLoading(true);
    setProject(prev => ({ ...prev, selectedStageIndex: idx }));
    try {
      const gridResult = await geminiRef.current.generateStageGrid(project.dna, project.proposedStages[idx]);
      if (gridResult) {
        setProject(prev => {
          const newStages = [...prev.proposedStages];
          newStages[idx] = { ...newStages[idx], gridImage: gridResult };
          return { ...prev, proposedStages: newStages };
        });
      }
    } finally { setIsLoading(false); }
  };

  const handleRenderCharacterGrid = async (idx: number) => {
    if (!geminiRef.current) return;
    setIsLoading(true);
    setProject(prev => ({ ...prev, selectedCharacterIndex: idx }));
    try {
      const gridResult = await geminiRef.current.generateCharacterGrid(project.dna, project.proposedCharacters[idx]);
      if (gridResult) {
        setProject(prev => {
          const newChars = [...prev.proposedCharacters];
          newChars[idx] = { ...newChars[idx], gridImage: gridResult };
          return { ...prev, proposedCharacters: newChars };
        });
      }
    } finally { setIsLoading(false); }
  };

  const updateStage = (idx: number, field: keyof StageDesign, value: string) => {
    setProject(prev => {
      const newStages = [...prev.proposedStages];
      newStages[idx] = { ...newStages[idx], [field]: value };
      return { ...prev, proposedStages: newStages };
    });
  };

  const updateCharacter = (idx: number, field: keyof CharacterDesign, value: string) => {
    setProject(prev => {
      const newChars = [...prev.proposedCharacters];
      newChars[idx] = { ...newChars[idx], [field]: value };
      return { ...prev, proposedCharacters: newChars };
    });
  };

  const handlePolishCharacter = async (idx: number, field: keyof CharacterDesign, label: string) => {
    if (!geminiRef.current || isLoading) return;
    setIsLoading(true);
    try {
      const char = project.proposedCharacters[idx];
      const polished = await geminiRef.current.polishText(char[field] as string, `角色塑造之${label}`);
      updateCharacter(idx, field, polished);
    } finally { setIsLoading(false); }
  };

  const downloadImage = (base64: string, name: string) => {
    const link = document.createElement('a');
    link.href = base64;
    link.download = `${name}.png`;
    link.click();
  };

  const getPhaseIndex = (phase: ProductionPhase) => {
    return Object.values(ProductionPhase).indexOf(phase);
  };

  if (!hasKey) return <ApiKeySelector onSelected={() => setHasKey(true)} />;

  return (
    <div className="flex h-screen bg-[#050505] text-white overflow-hidden font-sans">
      {expandedImage && (
        <div className="fixed inset-0 bg-black/95 z-[100] flex flex-col items-center justify-center p-8 animate-in fade-in duration-300" onClick={() => setExpandedImage(null)}>
          <button className="absolute top-8 right-8 p-3 bg-white/5 hover:bg-amber-600 rounded-full transition-all group">
            <X className="w-8 h-8 text-white group-hover:scale-110" />
          </button>
          <div className="relative max-w-7xl w-full max-h-full" onClick={e => e.stopPropagation()}>
            <img src={expandedImage} className="w-full h-full object-contain shadow-2xl rounded-lg border border-white/10" />
            <button onClick={() => downloadImage(expandedImage, 'montage-asset')} className="absolute bottom-4 right-4 flex items-center gap-2 bg-amber-600 hover:bg-amber-500 px-6 py-3 rounded-full font-bold shadow-xl transition-all">
              <DownloadCloud className="w-5 h-5" /> 下載原始圖片
            </button>
          </div>
        </div>
      )}

      <aside className="w-64 border-r border-white/5 flex flex-col bg-black/40 p-6">
        <div className="flex items-center gap-3 mb-12">
          <div className="bg-amber-600 p-2 rounded-lg shadow-[0_0_15px_rgba(217,119,6,0.3)]"><Film className="w-6 h-6 text-white" /></div>
          <h1 className="text-lg font-serif font-bold tracking-widest text-white/90 uppercase">Montage AI</h1>
        </div>
        <nav className="flex-1 space-y-2">
          {Object.entries(PHASE_METADATA).map(([key, meta], idx) => {
            const phaseKey = key as ProductionPhase;
            const isActive = activeStep === phaseKey;
            const isAccessible = getPhaseIndex(phaseKey) <= getPhaseIndex(project.currentPhase);
            return (
              <button 
                key={key} 
                disabled={!isAccessible} 
                onClick={() => setActiveStep(phaseKey)} 
                className={`w-full relative flex items-center gap-4 p-3 rounded-lg transition-all text-left group ${isActive ? 'bg-amber-600/20 text-amber-500 ring-1 ring-amber-600/30' : 'text-neutral-600 hover:text-neutral-400'} ${!isAccessible ? 'opacity-30 grayscale cursor-not-allowed' : 'cursor-pointer'}`}
              >
                {isActive && <div className="absolute left-0 w-1 h-6 bg-amber-600 rounded-full" />}
                <span className="text-xl">{meta.icon}</span>
                <div className="flex flex-col">
                  <span className="text-[9px] uppercase tracking-tighter opacity-50">Step 0{idx+1}</span>
                  <span className="text-sm font-bold">{meta.title}</span>
                </div>
              </button>
            );
          })}
        </nav>
        <div className="mt-8 space-y-2 border-t border-white/5 pt-6">
          <button onClick={saveProject} className="w-full flex items-center gap-3 px-3 py-2 text-xs text-neutral-400 hover:text-white transition-colors group"><Download className="w-4 h-4 text-amber-600" /> <span>匯出專案</span></button>
          <button onClick={() => fileInputRef.current?.click()} className="w-full flex items-center gap-3 px-3 py-2 text-xs text-neutral-400 hover:text-white transition-colors group"><Upload className="w-4 h-4 text-amber-600" /> <span>匯入專案</span></button>
          <input type="file" ref={fileInputRef} onChange={loadProject} className="hidden" accept=".json" />
        </div>
      </aside>

      <main className="flex-1 flex flex-col relative overflow-hidden">
        <header className="h-16 px-8 border-b border-white/5 flex items-center justify-between z-10 bg-black/50 backdrop-blur-md">
          <div className="flex items-center gap-2"><Terminal className="w-4 h-4 text-amber-600" /><span className="text-[10px] text-neutral-500 uppercase tracking-[0.2em]">TERMINAL</span><ChevronRight className="w-3 h-3 text-neutral-600" /><span className="text-sm font-bold text-amber-500 uppercase">{PHASE_METADATA[activeStep]?.title}</span></div>
          <div className="flex items-center gap-4">
            {activeStep === ProductionPhase.PRODUCTION_PLAN && (
              <button onClick={confirmProductionPlan} disabled={isLoading} className="bg-amber-600 hover:bg-amber-500 px-6 py-2 rounded-full text-[11px] font-bold flex items-center gap-2 shadow-lg transition-all">
                {isLoading ? <Loader2 className="w-3.5 h-3.5 animate-spin" /> : <CheckCircle2 className="w-3.5 h-3.5" />} 確認方案並塑造舞台
              </button>
            )}
            {activeStep === ProductionPhase.VISUAL_DEV && (
              <button onClick={handleProceedToCharacterDev} className="bg-amber-600 hover:bg-amber-500 px-6 py-2 rounded-full text-[11px] font-bold flex items-center gap-2 shadow-lg transition-all">
                <UserPlus className="w-3.5 h-3.5" /> 進行角色塑造
              </button>
            )}
          </div>
        </header>

        <section className="flex-1 flex flex-col items-center justify-start p-8 max-w-5xl mx-auto w-full overflow-y-auto">
          {activeStep === ProductionPhase.INSPIRATION && (
            <InspirationPhase 
              input={input} 
              setInput={setInput} 
              isLoading={isLoading} 
              isElaborating={isElaborating} 
              suggestions={project.suggestions} 
              onSubmit={handleSubmitIdea} 
              onSuggestionClick={handleSuggestionClick} 
              guideText={PHASE_METADATA[activeStep]?.guide}
              dna={project.dna}
              onUpdateDNA={updateDNAField}
            />
          )}
          {activeStep === ProductionPhase.PRODUCTION_PLAN && (
            <ProductionPlanPhase dna={tempDNA} setDna={setTempDNA} onRenderCoreVisual={handleRenderCoreStageOnly} isLoading={isLoading} />
          )}
          {activeStep === ProductionPhase.VISUAL_DEV && (
            <VisualDevPhase project={project} isAnalyzing={isAnalyzing} isLoading={isLoading} onUpdateStage={updateStage} onRenderGrid={handleRenderStageGrid} guideText={PHASE_METADATA[activeStep]?.guide} />
          )}
          {activeStep === ProductionPhase.CHARACTER_DEV && (
            <CharacterDevPhase project={project} isAnalyzing={isAnalyzing} isLoading={isLoading} onUpdateCharacter={updateCharacter} onPolishCharacter={handlePolishCharacter} onRenderGrid={handleRenderCharacterGrid} guideText={PHASE_METADATA[activeStep]?.guide} />
          )}
        </section>
      </main>

      <aside className="w-80 border-l border-white/5 bg-black/40 p-6 flex flex-col gap-8 overflow-y-auto">
        <h3 className="text-[10px] font-bold text-neutral-500 uppercase tracking-widest border-b border-white/5 pb-2">視覺檔案 (Asset)</h3>

        {/* 核心舞台視覺 */}
        <div className="space-y-4">
          <span className="text-[10px] text-amber-500/70 font-mono uppercase tracking-widest block">CORE_STAGE_VISUAL</span>
          {project.coreStageImage ? (
            <div className="aspect-video rounded-2xl overflow-hidden border border-white/10 shadow-lg cursor-zoom-in" onClick={() => setExpandedImage(project.coreStageImage!)}>
              <img src={project.coreStageImage} className="w-full h-full object-cover" alt="Core Stage Visual" />
            </div>
          ) : (
            <div className="py-12 border border-dashed border-white/10 rounded-2xl text-center opacity-30">
              <ImageIcon className="w-6 h-6 mx-auto mb-2 text-neutral-700" />
              <p className="text-[8px] uppercase tracking-widest">等待核心舞台視覺</p>
            </div>
          )}
        </div>

        {/* 舞台九宮格列表 */}
        {project.proposedStages.some(s => s.gridImage) && (
          <div className="space-y-6 pt-6 border-t border-white/5">
            <span className="text-[10px] text-amber-500/70 font-mono uppercase tracking-widest block">STAGE_GRIDS</span>
            {project.proposedStages.filter(s => s.gridImage).map((stage, i) => (
              <div key={i} className="space-y-2 group">
                <div className="flex items-center justify-between">
                  <span className="text-[9px] font-bold text-neutral-400 truncate block">{stage.name}</span>
                  <Download className="w-3 h-3 text-neutral-600 hover:text-amber-500 cursor-pointer" onClick={() => downloadImage(stage.gridImage!, `Stage-${stage.name}`)} />
                </div>
                <div className="aspect-square rounded-xl overflow-hidden border border-white/5 cursor-zoom-in" onClick={() => setExpandedImage(stage.gridImage!)}>
                  <img src={stage.gridImage} className="w-full h-full object-cover grayscale hover:grayscale-0 transition-all duration-500" alt={stage.name} />
                </div>
              </div>
            ))}
          </div>
        )}

        {/* 角色九宮格列表 */}
        {project.proposedCharacters.some(c => c.gridImage) && (
          <div className="space-y-6 pt-6 border-t border-white/5">
            <span className="text-[10px] text-amber-500/70 font-mono uppercase tracking-widest block">CHARACTER_GRIDS</span>
            {project.proposedCharacters.filter(c => c.gridImage).map((char, i) => (
              <div key={i} className="space-y-2 group">
                <div className="flex items-center justify-between">
                  <span className="text-[9px] font-bold text-neutral-400 truncate block">{char.name}</span>
                  <Download className="w-3 h-3 text-neutral-600 hover:text-amber-500 cursor-pointer" onClick={() => downloadImage(char.gridImage!, `Character-${char.name}`)} />
                </div>
                <div className="aspect-square rounded-xl overflow-hidden border border-white/5 cursor-zoom-in" onClick={() => setExpandedImage(char.gridImage!)}>
                  <img src={char.gridImage} className="w-full h-full object-cover" alt={char.name} />
                </div>
              </div>
            ))}
          </div>
        )}
      </aside>
    </div>
  );
};

export default App;

export { };

export enum ProductionPhase {
  INSPIRATION = 'INSPIRATION',
  PRODUCTION_PLAN = 'PRODUCTION_PLAN',
  VISUAL_DEV = 'VISUAL_DEV',
  CHARACTER_DEV = 'CHARACTER_DEV',
  STORY_ARCH = 'STORY_ARCH',
  STORYBOARD = 'STORYBOARD',
  VIDEO_PROMPTING = 'VIDEO_PROMPTING'
}

export interface Suggestion {
  title: string;
  description: string;
  tags: string[];
  environment?: string;
  socialBackground?: string;
  coreNarrative?: string;
}

export interface StageDesign {
  name: string;
  description: string;
  gridImage?: string;
}

export interface CharacterDesign {
  name: string;
  role: string;
  physicalTraits: string; 
  visualTone: string;    
  motivation: string;    
  gridImage?: string;    
}

export interface ProjectDNA {
  format: string;
  style: string;
  story: string;
  ratio: string;
  environment: string;
  socialBackground: string;
  coreNarrative: string;
  directorVision?: string;
}

export interface ProjectState {
  currentPhase: ProductionPhase;
  initialInput: string;
  dna: ProjectDNA;
  proposedStages: StageDesign[];
  proposedCharacters: CharacterDesign[]; 
  selectedStageIndex?: number;
  selectedCharacterIndex?: number;      
  coreStageImage?: string; 
}

import { GoogleGenAI, Type } from "@google/genai";
import { SYSTEM_INSTRUCTION } from "../constants";
import { Suggestion, StageDesign, CharacterDesign, ProjectDNA, ProductionPhase } from "../types";

export class GeminiService {
  constructor(apiKey: string) { }

  async generateSuggestions(input: string, phase: ProductionPhase, context: string): Promise<Suggestion[]> {
    const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
    const currentDNA = JSON.parse(context) as ProjectDNA;

    const prompt = `
    目前的製作設定：
    - 形式：${currentDNA.format}
    - 預想視覺風格：${currentDNA.style}
    - 畫面比例：${currentDNA.ratio}

    核心靈感/指令： "${input}"。

    請根據目前的製作階段 [${phase}]，提供三個具體的創意導向（頂尖導演提案）。
    這些提案必須在視覺張力與敘事節奏上符合上述的「製作設定」。

    【關鍵任務】如果是 INSPIRATION 階段，請發揮頂尖導演聯想力，自動推論出初步的：
    1. 地理環境 (environment)
    2. 社會背景 (socialBackground)
    3. 核心敘事 (coreNarrative)

    請回傳 JSON 陣列，包含 title, description, tags, environment, socialBackground, coreNarrative。`;

    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: [{ role: 'user', parts: [{ text: prompt }] }],
      config: {
        systemInstruction: SYSTEM_INSTRUCTION,
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.ARRAY,
          items: {
            type: Type.OBJECT,
            properties: {
              title: { type: Type.STRING },
              description: { type: Type.STRING },
              tags: { type: Type.ARRAY, items: { type: Type.STRING } },
              environment: { type: Type.STRING },
              socialBackground: { type: Type.STRING },
              coreNarrative: { type: Type.STRING }
            },
            required: ["title", "description", "tags"]
          }
        }
      }
    });
    return JSON.parse(response.text || "[]");
  }

  async elaboratePlan(suggestion: Suggestion, baseDNA: ProjectDNA): Promise<ProjectDNA> {
    const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
    const prompt = `
    請將以下提案擴充為完整的電影拍攝 DNA：
    提案標題：${suggestion.title}

    【核心約束】你必須嚴格遵循用戶設定的基底 DNA：
    - 製作形式：${baseDNA.format}
    - 預選視覺風格：${baseDNA.style}
    - 畫面比例：${baseDNA.ratio}

    內容需包含：符合該風格的地理環境、社會背景、核心敘事與一份細緻的劇本摘要。
    此外，請作為 AI 頂尖導演，提出一份「拍攝方案建議方向 (directorVision)」，包含建議的運鏡方式、色彩校正方向、以及聲音設計重點。
    `;

    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: [{ role: 'user', parts: [{ text: prompt }] }],
      config: {
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.OBJECT,
          properties: {
            format: { type: Type.STRING },
            style: { type: Type.STRING },
            story: { type: Type.STRING },
            ratio: { type: Type.STRING },
            environment: { type: Type.STRING },
            socialBackground: { type: Type.STRING },
            coreNarrative: { type: Type.STRING },
            directorVision: { type: Type.STRING }
          },
          required: ["format", "style", "story", "environment", "socialBackground", "coreNarrative", "directorVision"]
        }
      }
    });
    const result = JSON.parse(response.text || "{}");

    return {
      ...result,
      format: baseDNA.format, 
      ratio: baseDNA.ratio,   
      style: result.style || baseDNA.style 
    };
  }

  async identifyCoreStages(dna: ProjectDNA): Promise<StageDesign[]> {
    const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
    const prompt = `你是一位頂尖電影美術指導與空間設計師。請針對提供的劇本內容進行核心舞台 (Core Stage) 的識別與視覺設計。

【執行步驟】
1. 歸納主要地點：從「劇本摘要」中找出最具代表性的核心舞台。
2. 詳細空間設計：內容必須包含：場地大小、位置方位、關鍵物件陳設、光影質調、色調材質細節。

劇本摘要：${dna.story}
視覺風格定義：${dna.style} (形式：${dna.format})
環境背景：${dna.environment}

請回傳 JSON 陣列，包含 name 與詳盡的 description。`;

    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: [{ role: 'user', parts: [{ text: prompt }] }],
      config: {
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.ARRAY,
          items: {
            type: Type.OBJECT,
            properties: {
              name: { type: Type.STRING },
              description: { type: Type.STRING }
            },
            required: ["name", "description"]
          }
        }
      }
    });
    return JSON.parse(response.text || "[]");
  }

  async analyzeCharacters(dna: ProjectDNA): Promise<CharacterDesign[]> {
    const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
    const prompt = `你是一位頂尖電影選角指導與角色造型設計師。請針對劇本內容識別出核心角色並設計視覺原型。

    劇本摘要：${dna.story}
    視覺風格：${dna.style} (形式：${dna.format})

    請回傳 JSON 陣列。`;

    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: [{ role: 'user', parts: [{ text: prompt }] }],
      config: {
        systemInstruction: SYSTEM_INSTRUCTION,
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.ARRAY,
          items: {
            type: Type.OBJECT,
            properties: {
              name: { type: Type.STRING },
              role: { type: Type.STRING },
              physicalTraits: { type: Type.STRING },
              visualTone: { type: Type.STRING },
              motivation: { type: Type.STRING }
            },
            required: ["name", "role", "physicalTraits", "visualTone", "motivation"]
          }
        }
      }
    });
    return JSON.parse(response.text || "[]");
  }

  async polishText(text: string, type: string): Promise<string> {
    const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: `你是專業電影視覺指導。請進行場景化潤色，強調視覺細節與專業術語。類型：${type}。內容：${text}`,
    });
    return response.text || text;
  }

  async generateCoreStyleVisual(dna: ProjectDNA): Promise<string | null> {
    const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
    const prompt = `
      A professional cinematic mood board / style guide collage for the project: "${dna.coreNarrative}".
      Format: ${dna.format}. Style: ${dna.style}.
      STRICT LAYOUT REQUIREMENT: ONE single image that is a composite (split-screen/grid) showing 4-5 distinct cinematic perspectives:
      1. An Epic Wide Shot establishing the ${dna.environment}.
      2. A dramatic medium shot showcasing lighting and texture.
      3. Close-up of symbolic prop.

      Unified color grading, 8k, cinematic.
    `;
    try {
      const response = await ai.models.generateContent({
        model: 'gemini-3-pro-image-preview',
        contents: { parts: [{ text: prompt }] },
        config: { imageConfig: { aspectRatio: dna.ratio === '9:16' ? "9:16" : "16:9", imageSize: "1K" } }
      });
      for (const part of response.candidates?.[0]?.content?.parts || []) {
        if (part.inlineData) return `data:image/png;base64,${part.inlineData.data}`;
      }
      return null;
    } catch (error) { return null; }
  }

  async generateStageGrid(dna: ProjectDNA, stage: StageDesign): Promise<string> {
    const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
    const gridPrompt = `
      Professional 3x3 Stage Concept Design Sheet for: "${stage.name}".
      Context: ${stage.description}. Style: ${dna.style}. Format: ${dna.format}.

      STRICT LAYOUT: You MUST generate a 3x3 grid with EXACTLY NINE equal panels, each showing:
      Panel 1: Overhead Wide / Bird's Eye View (全景俯瞰)
      Panel 2: Frontal Wide View (正面全景)
      Panel 3: Side Wide View (側面全景)
      Panel 4: Entrance Perspective (入口視角)
      Panel 5: Core Area Close-up (核心區域特寫)
      Panel 6: Atmospheric Detail A (氛圍細節A)
      Panel 7: Atmospheric Detail B (氛圍細節B)
      Panel 8: Key Prop Close-up (關鍵道具特寫)
      Panel 9: Character Perspective POV (角色視角POV)

      Unified aesthetic, consistent spatial logic, 8k cinematic quality.
    `;
    try {
      const response = await ai.models.generateContent({
        model: 'gemini-3-pro-image-preview',
        contents: { parts: [{ text: gridPrompt }] },
        config: { imageConfig: { aspectRatio: "1:1", imageSize: "1K" } }
      });
      for (const part of response.candidates?.[0]?.content?.parts || []) {
        if (part.inlineData) return `data:image/png;base64,${part.inlineData.data}`;
      }
    } catch (error) { console.error(error); }
    return "";
  }

  async generateCharacterGrid(dna: ProjectDNA, character: CharacterDesign): Promise<string> {
    const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
    const gridPrompt = `
      Professional 3x3 Universal Character Design Concept Sheet for: "${character.name}" (${character.role}).
      Traits: ${character.physicalTraits}. Tone: ${character.visualTone}. 
      Style: ${dna.style}. Format: ${dna.format}.

      STRICT LAYOUT: You MUST generate a 3x3 grid with EXACTLY NINE equal panels, demonstrating the anatomical structure and aesthetic essence of the character (applicable to humans, birds, or creatures):
      Panel 1: Frontal Hero View (正面全貌) - Basic proportions and silhouette.
      Panel 2: Lateral Profile (側面輪廓) - Posture and anatomical depth.
      Panel 3: Dorsal/Rear Structure (背面與表面結構) - Focus on spine, wings, or back patterns.
      Panel 4: Head & Sensory Close-up (頭部/感官特寫) - Focus on eyes and facial features.
      Panel 5: Extremity Detail (末端肢體細節) - Close-up of hands, claws, paws, or talons.
      Panel 6: Surface Texture Macro (材質與紋理特寫) - Focus on feathers, skin, scales, or clothing fiber.
      Panel 7: Dynamic Action Pose (動態姿態) - The character in motion, showing energy flow.
      Panel 8: Signature Expression (特徵神態) - The character's typical reaction or emotional state.
      Panel 9: Scale & Atmosphere (比例參照與氛圍) - The character in environment or silhouette.

      Maintain absolute consistency across all nine panels. High-fidelity concept art style.
    `;
    try {
      const response = await ai.models.generateContent({
        model: 'gemini-3-pro-image-preview',
        contents: { parts: [{ text: gridPrompt }] },
        config: { imageConfig: { aspectRatio: "1:1", imageSize: "1K" } }
      });
      for (const part of response.candidates?.[0]?.content?.parts || []) {
        if (part.inlineData) return `data:image/png;base64,${part.inlineData.data}`;
      }
    } catch (error) { console.error(error); }
    return "";
  }
}

import React, { useState, useEffect, useRef } from 'react';
import { ProductionPhase, Suggestion, ProjectState, ProjectDNA, StageDesign, CharacterDesign } from './types';
import { PHASE_METADATA } from './constants';
import { GeminiService } from './services/geminiService';
import { ApiKeySelector } from './components/ApiKeySelector';
import { InspirationPhase } from './components/InspirationPhase';
import { ProductionPlanPhase } from './components/ProductionPlanPhase';
import { VisualDevPhase } from './components/VisualDevPhase';
import { CharacterDevPhase } from './components/CharacterDevPhase';
import { 
  Film, Loader2, ArrowRight, 
  ChevronRight, Download, Upload,
  X, CheckCircle2, Terminal, MapPin, Users, Target,
  Grid, Image as ImageIcon, Maximize2, DownloadCloud, UserPlus
} from 'lucide-react';

const App: React.FC = () => {
  const [hasKey, setHasKey] = useState(false);
  const [isLoading, setIsLoading] = useState(false);
  const [isAnalyzing, setIsAnalyzing] = useState(false);
  const [isElaborating, setIsElaborating] = useState(false);
  const [input, setInput] = useState('');
  const [activeStep, setActiveStep] = useState<ProductionPhase>(ProductionPhase.INSPIRATION);
  const [expandedImage, setExpandedImage] = useState<string | null>(null);

  // Ephemeral UI State - 不會被存入 JSON
  const [suggestions, setSuggestions] = useState<Suggestion[]>([]);

  // Persistent Project State - 核心存檔狀態
  const [project, setProject] = useState<ProjectState>({
    currentPhase: ProductionPhase.INSPIRATION,
    initialInput: '',
    dna: { format: '電影', style: '寫實電影感', story: '', ratio: '16:9', environment: '', socialBackground: '', coreNarrative: '', directorVision: '' },
    proposedStages: [], 
    proposedCharacters: [], 
    coreStageImage: undefined 
  });

  const [tempDNA, setTempDNA] = useState<ProjectDNA>(project.dna);
  const fileInputRef = useRef<HTMLInputElement>(null);
  const geminiRef = useRef<GeminiService | null>(null);

  useEffect(() => {
    const checkKey = async () => {
      // @ts-ignore
      const exists = await window.aistudio.hasSelectedApiKey();
      if (exists) {
        setHasKey(true);
        geminiRef.current = new GeminiService(process.env.API_KEY || '');
      }
    };
    checkKey();
  }, []);

  useEffect(() => {
    if (activeStep === ProductionPhase.INSPIRATION && project.initialInput) {
      setInput(project.initialInput);
    }
  }, [project.initialInput, activeStep]);

  useEffect(() => {
    if (activeStep === ProductionPhase.VISUAL_DEV && project.proposedStages.length === 0 && !isAnalyzing && geminiRef.current) {
      handleIdentifyStages();
    }
    if (activeStep === ProductionPhase.CHARACTER_DEV && project.proposedCharacters.length === 0 && !isAnalyzing && geminiRef.current) {
      handleAutoAnalyzeCharacters();
    }
  }, [activeStep]);

  const handleIdentifyStages = async () => {
    if (!geminiRef.current || isAnalyzing) return;
    setIsAnalyzing(true);
    try {
      const stages = await geminiRef.current.identifyCoreStages(project.dna);
      setProject(prev => ({ ...prev, proposedStages: stages }));
    } catch (err) { console.error(err); } finally { setIsAnalyzing(false); }
  };

  const handleAutoAnalyzeCharacters = async () => {
    if (!geminiRef.current || isAnalyzing) return;
    setIsAnalyzing(true);
    try {
      const chars = await geminiRef.current.analyzeCharacters(project.dna);
      setProject(prev => ({ ...prev, proposedCharacters: chars }));
    } catch (err) { console.error(err); } finally { setIsAnalyzing(false); }
  };

  const updateDNAField = (field: keyof ProjectDNA, value: string) => {
    const updatedDNA = { ...project.dna, [field]: value };
    setProject(prev => ({ ...prev, dna: updatedDNA }));
    setTempDNA(updatedDNA);
  };

  const handleSubmitIdea = async (e?: React.FormEvent) => {
    if (e) e.preventDefault();
    if (!input.trim() || isLoading || !geminiRef.current) return;
    setIsLoading(true);
    try {
      const results = await geminiRef.current.generateSuggestions(input, activeStep, JSON.stringify(project.dna));
      setSuggestions(results || []);
      setProject(prev => ({ 
        ...prev, 
        initialInput: activeStep === ProductionPhase.INSPIRATION ? input : prev.initialInput
      }));
    } finally { setIsLoading(false); }
  };

  const handleSuggestionClick = async (s: Suggestion) => {
    if (!geminiRef.current) return;
    setIsElaborating(true);
    try {
      const detailedDNA = await geminiRef.current.elaboratePlan(s, project.dna);
      setTempDNA(detailedDNA);
      setSuggestions([]); // 選擇後清空暫存提案
      setProject(prev => ({
        ...prev, 
        dna: detailedDNA, 
        currentPhase: ProductionPhase.PRODUCTION_PLAN
      }));
      setActiveStep(ProductionPhase.PRODUCTION_PLAN);
    } finally { setIsElaborating(false); }
  };

  const handleRenderCoreStageOnly = async () => {
    if (!geminiRef.current) return;
    setIsLoading(true);
    try {
      const coreImage = await geminiRef.current.generateCoreStyleVisual(tempDNA) || undefined;
      setProject(prev => ({ ...prev, coreStageImage: coreImage }));
    } finally { setIsLoading(false); }
  };

  const confirmProductionPlan = async () => {
    if (!geminiRef.current) return;
    setIsLoading(true);
    try {
      let coreImage = project.coreStageImage;
      if (!coreImage) {
        coreImage = await geminiRef.current.generateCoreStyleVisual(tempDNA) || undefined;
      }
      setProject(prev => ({
        ...prev, 
        currentPhase: ProductionPhase.VISUAL_DEV, 
        dna: { ...tempDNA }, 
        coreStageImage: coreImage,
        proposedStages: [], 
        proposedCharacters: []
      }));
      setActiveStep(ProductionPhase.VISUAL_DEV);
    } finally { setIsLoading(false); }
  };

  const handleProceedToCharacterDev = () => {
    setProject(prev => ({ ...prev, currentPhase: ProductionPhase.CHARACTER_DEV }));
    setActiveStep(ProductionPhase.CHARACTER_DEV);
  };

  const saveProject = () => {
    const stateToSave: ProjectState = { 
      ...project, 
      initialInput: input 
    };
    const data = JSON.stringify(stateToSave, null, 2);
    const blob = new Blob([data], { type: 'application/json' });
    const url = URL.createObjectURL(blob);
    const link = document.createElement('a');
    link.href = url;
    link.download = `montage-project-${new Date().toISOString().slice(0, 10)}.json`;
    link.click();
  };

  const loadProject = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;
    const reader = new FileReader();
    reader.onload = (event) => {
      try {
        const data = JSON.parse(event.target?.result as string) as ProjectState;
        if (data.currentPhase && data.dna) {
          setProject(data);
          setActiveStep(data.currentPhase);
          setTempDNA(data.dna);
          if (data.initialInput) setInput(data.initialInput);
        }
      } catch (err) { alert('檔案格式錯誤。'); }
    };
    reader.readAsText(file);
    if (fileInputRef.current) fileInputRef.current.value = '';
  };

  const handleRenderStageGrid = async (idx: number) => {
    if (!geminiRef.current) return;
    setIsLoading(true);
    setProject(prev => ({ ...prev, selectedStageIndex: idx }));
    try {
      const gridResult = await geminiRef.current.generateStageGrid(project.dna, project.proposedStages[idx]);
      if (gridResult) {
        setProject(prev => {
          const newStages = [...prev.proposedStages];
          newStages[idx] = { ...newStages[idx], gridImage: gridResult };
          return { ...prev, proposedStages: newStages };
        });
      }
    } finally { setIsLoading(false); }
  };

  const handleRenderCharacterGrid = async (idx: number) => {
    if (!geminiRef.current) return;
    setIsLoading(true);
    setProject(prev => ({ ...prev, selectedCharacterIndex: idx }));
    try {
      const gridResult = await geminiRef.current.generateCharacterGrid(project.dna, project.proposedCharacters[idx]);
      if (gridResult) {
        setProject(prev => {
          const newChars = [...prev.proposedCharacters];
          newChars[idx] = { ...newChars[idx], gridImage: gridResult };
          return { ...prev, proposedCharacters: newChars };
        });
      }
    } finally { setIsLoading(false); }
  };

  const updateStage = (idx: number, field: keyof StageDesign, value: string) => {
    setProject(prev => {
      const newStages = [...prev.proposedStages];
      newStages[idx] = { ...newStages[idx], [field]: value };
      return { ...prev, proposedStages: newStages };
    });
  };

  const updateCharacter = (idx: number, field: keyof CharacterDesign, value: string) => {
    setProject(prev => {
      const newChars = [...prev.proposedCharacters];
      newChars[idx] = { ...newChars[idx], [field]: value };
      return { ...prev, proposedCharacters: newChars };
    });
  };

  const handlePolishCharacter = async (idx: number, field: keyof CharacterDesign, label: string) => {
    if (!geminiRef.current || isLoading) return;
    setIsLoading(true);
    try {
      const char = project.proposedCharacters[idx];
      const polished = await geminiRef.current.polishText(char[field] as string, `角色塑造之${label}`);
      updateCharacter(idx, field, polished);
    } finally { setIsLoading(false); }
  };

  const downloadImage = (base64: string, name: string) => {
    const link = document.createElement('a');
    link.href = base64;
    link.download = `${name}.png`;
    link.click();
  };

  const getPhaseIndex = (phase: ProductionPhase) => {
    return Object.values(ProductionPhase).indexOf(phase);
  };

  if (!hasKey) return <ApiKeySelector onSelected={() => setHasKey(true)} />;

  return (
    <div className="flex h-screen bg-[#050505] text-white overflow-hidden font-sans">
      {expandedImage && (
        <div className="fixed inset-0 bg-black/95 z-[100] flex flex-col items-center justify-center p-8 animate-in fade-in duration-300" onClick={() => setExpandedImage(null)}>
          <button className="absolute top-8 right-8 p-3 bg-white/5 hover:bg-amber-600 rounded-full transition-all group">
            <X className="w-8 h-8 text-white group-hover:scale-110" />
          </button>
          <div className="relative max-w-7xl w-full max-h-full" onClick={e => e.stopPropagation()}>
            <img src={expandedImage} className="w-full h-full object-contain shadow-2xl rounded-lg border border-white/10" />
            <button onClick={() => downloadImage(expandedImage, 'montage-asset')} className="absolute bottom-4 right-4 flex items-center gap-2 bg-amber-600 hover:bg-amber-500 px-6 py-3 rounded-full font-bold shadow-xl transition-all">
              <DownloadCloud className="w-5 h-5" /> 下載原始圖片
            </button>
          </div>
        </div>
      )}

      <aside className="w-64 border-r border-white/5 flex flex-col bg-black/40 p-6">
        <div className="flex items-center gap-3 mb-12">
          <div className="bg-amber-600 p-2 rounded-lg shadow-[0_0_15px_rgba(217,119,6,0.3)]"><Film className="w-6 h-6 text-white" /></div>
          <h1 className="text-lg font-serif font-bold tracking-widest text-white/90 uppercase">Montage AI</h1>
        </div>
        <nav className="flex-1 space-y-2">
          {Object.entries(PHASE_METADATA).map(([key, meta], idx) => {
            const phaseKey = key as ProductionPhase;
            const isActive = activeStep === phaseKey;
            const isAccessible = getPhaseIndex(phaseKey) <= getPhaseIndex(project.currentPhase);
            return (
              <button 
                key={key} 
                disabled={!isAccessible} 
                onClick={() => setActiveStep(phaseKey)} 
                className={`w-full relative flex items-center gap-4 p-3 rounded-lg transition-all text-left group ${isActive ? 'bg-amber-600/20 text-amber-500 ring-1 ring-amber-600/30' : 'text-neutral-600 hover:text-neutral-400'} ${!isAccessible ? 'opacity-30 grayscale cursor-not-allowed' : 'cursor-pointer'}`}
              >
                {isActive && <div className="absolute left-0 w-1 h-6 bg-amber-600 rounded-full" />}
                <span className="text-xl">{meta.icon}</span>
                <div className="flex flex-col">
                  <span className="text-[9px] uppercase tracking-tighter opacity-50">Step 0{idx+1}</span>
                  <span className="text-sm font-bold">{meta.title}</span>
                </div>
              </button>
            );
          })}
        </nav>
        <div className="mt-8 space-y-2 border-t border-white/5 pt-6">
          <button onClick={saveProject} className="w-full flex items-center gap-3 px-3 py-2 text-xs text-neutral-400 hover:text-white transition-colors group"><Download className="w-4 h-4 text-amber-600" /> <span>匯出專案</span></button>
          <button onClick={() => fileInputRef.current?.click()} className="w-full flex items-center gap-3 px-3 py-2 text-xs text-neutral-400 hover:text-white transition-colors group"><Upload className="w-4 h-4 text-amber-600" /> <span>匯入專案</span></button>
          <input type="file" ref={fileInputRef} onChange={loadProject} className="hidden" accept=".json" />
        </div>
      </aside>

      <main className="flex-1 flex flex-col relative overflow-hidden">
        <header className="h-16 px-8 border-b border-white/5 flex items-center justify-between z-10 bg-black/50 backdrop-blur-md">
          <div className="flex items-center gap-2"><Terminal className="w-4 h-4 text-amber-600" /><span className="text-[10px] text-neutral-500 uppercase tracking-[0.2em]">TERMINAL</span><ChevronRight className="w-3 h-3 text-neutral-600" /><span className="text-sm font-bold text-amber-500 uppercase">{PHASE_METADATA[activeStep]?.title}</span></div>
          <div className="flex items-center gap-4">
            {activeStep === ProductionPhase.PRODUCTION_PLAN && (
              <button onClick={confirmProductionPlan} disabled={isLoading} className="bg-amber-600 hover:bg-amber-500 px-6 py-2 rounded-full text-[11px] font-bold flex items-center gap-2 shadow-lg transition-all">
                {isLoading ? <Loader2 className="w-3.5 h-3.5 animate-spin" /> : <CheckCircle2 className="w-3.5 h-3.5" />} 確認方案並塑造舞台
              </button>
            )}
            {activeStep === ProductionPhase.VISUAL_DEV && (
              <button onClick={handleProceedToCharacterDev} className="bg-amber-600 hover:bg-amber-500 px-6 py-2 rounded-full text-[11px] font-bold flex items-center gap-2 shadow-lg transition-all">
                <UserPlus className="w-3.5 h-3.5" /> 進行角色塑造
              </button>
            )}
          </div>
        </header>

        <section className="flex-1 flex flex-col items-center justify-start p-8 max-w-5xl mx-auto w-full overflow-y-auto">
          {activeStep === ProductionPhase.INSPIRATION && (
            <InspirationPhase 
              input={input} 
              setInput={setInput} 
              isLoading={isLoading} 
              isElaborating={isElaborating} 
              suggestions={suggestions} 
              onSubmit={handleSubmitIdea} 
              onSuggestionClick={handleSuggestionClick} 
              guideText={PHASE_METADATA[activeStep]?.guide}
              dna={project.dna}
              onUpdateDNA={updateDNAField}
            />
          )}
          {activeStep === ProductionPhase.PRODUCTION_PLAN && (
            <ProductionPlanPhase dna={tempDNA} setDna={setTempDNA} onRenderCoreVisual={handleRenderCoreStageOnly} isLoading={isLoading} />
          )}
          {activeStep === ProductionPhase.VISUAL_DEV && (
            <VisualDevPhase project={project} isAnalyzing={isAnalyzing} isLoading={isLoading} onUpdateStage={updateStage} onRenderGrid={handleRenderStageGrid} guideText={PHASE_METADATA[activeStep]?.guide} />
          )}
          {activeStep === ProductionPhase.CHARACTER_DEV && (
            <CharacterDevPhase project={project} isAnalyzing={isAnalyzing} isLoading={isLoading} onUpdateCharacter={updateCharacter} onPolishCharacter={handlePolishCharacter} onRenderGrid={handleRenderCharacterGrid} guideText={PHASE_METADATA[activeStep]?.guide} />
          )}
        </section>
      </main>

      <aside className="w-80 border-l border-white/5 bg-black/40 p-6 flex flex-col gap-8 overflow-y-auto">
        <h3 className="text-[10px] font-bold text-neutral-500 uppercase tracking-widest border-b border-white/5 pb-2">視覺檔案 (Asset)</h3>

        <div className="space-y-4">
          <span className="text-[10px] text-amber-500/70 font-mono uppercase tracking-widest block">CORE_STAGE_VISUAL</span>
          {project.coreStageImage ? (
            <div className="aspect-video rounded-2xl overflow-hidden border border-white/10 shadow-lg cursor-zoom-in" onClick={() => setExpandedImage(project.coreStageImage!)}>
              <img src={project.coreStageImage} className="w-full h-full object-cover" alt="Core Stage Visual" />
            </div>
          ) : (
            <div className="py-12 border border-dashed border-white/10 rounded-2xl text-center opacity-30">
              <ImageIcon className="w-6 h-6 mx-auto mb-2 text-neutral-700" />
              <p className="text-[8px] uppercase tracking-widest">等待核心舞台視覺</p>
            </div>
          )}
        </div>

        {project.proposedStages.some(s => s.gridImage) && (
          <div className="space-y-6 pt-6 border-t border-white/5">
            <span className="text-[10px] text-amber-500/70 font-mono uppercase tracking-widest block">STAGE_GRIDS</span>
            {project.proposedStages.filter(s => s.gridImage).map((stage, i) => (
              <div key={i} className="space-y-2 group">
                <div className="flex items-center justify-between">
                  <span className="text-[9px] font-bold text-neutral-400 truncate block">{stage.name}</span>
                  <Download className="w-3 h-3 text-neutral-600 hover:text-amber-500 cursor-pointer" onClick={() => downloadImage(stage.gridImage!, `Stage-${stage.name}`)} />
                </div>
                <div className="aspect-square rounded-xl overflow-hidden border border-white/5 cursor-zoom-in" onClick={() => setExpandedImage(stage.gridImage!)}>
                  <img src={stage.gridImage} className="w-full h-full object-cover grayscale hover:grayscale-0 transition-all duration-500" alt={stage.name} />
                </div>
              </div>
            ))}
          </div>
        )}

        {project.proposedCharacters.some(c => c.gridImage) && (
          <div className="space-y-6 pt-6 border-t border-white/5">
            <span className="text-[10px] text-amber-500/70 font-mono uppercase tracking-widest block">CHARACTER_GRIDS</span>
            {project.proposedCharacters.filter(c => c.gridImage).map((char, i) => (
              <div key={i} className="space-y-2 group">
                <div className="flex items-center justify-between">
                  <span className="text-[9px] font-bold text-neutral-400 truncate block">{char.name}</span>
                  <Download className="w-3 h-3 text-neutral-600 hover:text-amber-500 cursor-pointer" onClick={() => downloadImage(char.gridImage!, `Character-${char.name}`)} />
                </div>
                <div className="aspect-square rounded-xl overflow-hidden border border-white/5 cursor-zoom-in" onClick={() => setExpandedImage(char.gridImage!)}>
                  <img src={char.gridImage} className="w-full h-full object-cover" alt={char.name} />
                </div>
              </div>
            ))}
          </div>
        )}
      </aside>
    </div>
  );
};

export default App;

export { };

export enum ProductionPhase {
  INSPIRATION = 'INSPIRATION',
  PRODUCTION_PLAN = 'PRODUCTION_PLAN',
  VISUAL_DEV = 'VISUAL_DEV',
  CHARACTER_DEV = 'CHARACTER_DEV',
  STORY_ARCH = 'STORY_ARCH',
  STORYBOARD = 'STORYBOARD',
  VIDEO_PROMPTING = 'VIDEO_PROMPTING'
}

// Fixed missing Message interface used in ChatInterface.tsx
export interface Message {
  role: 'user' | 'assistant';
  content: string;
  videoUrl?: string;
  images?: string[];
}

export interface Suggestion {
  title: string;
  description: string;
  tags: string[];
  environment?: string;
  socialBackground?: string;
  coreNarrative?: string;
}

export interface StageDesign {
  name: string;
  description: string;
  gridImage?: string;
}

export interface CharacterDesign {
  name: string;
  role: string;
  physicalTraits: string; 
  visualTone: string;    
  motivation: string;    
  gridImage?: string;    
}

export interface ProjectDNA {
  format: string;
  style: string;
  story: string;
  ratio: string;
  environment: string;
  socialBackground: string;
  coreNarrative: string;
  directorVision?: string;
}

export interface ProjectState {
  currentPhase: ProductionPhase;
  initialInput: string;
  dna: ProjectDNA;
  proposedStages: StageDesign[];
  proposedCharacters: CharacterDesign[]; 
  selectedStageIndex?: number;
  selectedCharacterIndex?: number;      
  coreStageImage?: string; 
}

import { ProductionPhase } from './types';

export const SYSTEM_INSTRUCTION = `你是一位頂尖的「電影美術指導」與「敘事空間架構師」。你專精於將文字劇本轉化為具備戲劇張力的「核心舞台 (Core Stage)」。

你的任務是根據通用的「空間敘事架構」進行舞台識別與設計：

【角色—路徑—交匯點 (Actor-Path-Nexus) 架構】
1. 角色基點 (Actor Base)：識別主角的核心活動區域與情感定錨點（例如：居住地、避難所、工作場域）。
2. 行動路徑 (Action Path)：分析主角在故事中的移動線條、視線投射或追求/逃避的路徑。
3. 敘事交匯點 (Narrative Nexus)：識別主角與其他角色、或與關鍵目標物產生互動、目擊、衝突或情感轉折的地理集群。

舞台定義：一個「核心舞台」必須是一個完整的地理空間集群，它能容納角色的行動並反映其敘事功能，而不僅僅是單一背景。

根據目前的製作階段，你的提案重點應如下：
1. 靈感來源：提案不同的敘事方向。
2. 拍攝方案：深化地理環境、社會背景與核心敘事。
3. 舞台塑造：識別劇本中的核心舞台，分析其角色路徑與交匯邏輯。
4. 角色塑造：提案角色的視覺特徵與性格張力。
5. 敘事結構：提案劇本蒙太奇處理。
6. 技術分鏡：提案具體的分鏡鏡位策略。
7. 影片生成：提案最優化的 AI 影片提示詞。

請務必以 JSON 格式回傳提案。`;

export const PHASE_METADATA = {
  [ProductionPhase.INSPIRATION]: { 
    title: '靈感來源', 
    icon: '✨',
    guide: '輸入靈感碎片，為您提案三種敘事方向。'
  },
  [ProductionPhase.PRODUCTION_PLAN]: { 
    title: '拍攝方案', 
    icon: '📋',
    guide: '優化您的拍攝細節與核心敘事內核。'
  },
  [ProductionPhase.VISUAL_DEV]: { 
    title: '舞台塑造', 
    icon: '🌄',
    guide: '分析角色路徑，塑造核心敘事舞台。'
  },
  [ProductionPhase.CHARACTER_DEV]: { 
    title: '角色塑造', 
    icon: '👤',
    guide: '提取劇情線索，塑造角色形象。'
  },
  [ProductionPhase.STORY_ARCH]: { 
    title: '敘事結構', 
    icon: '📖',
    guide: '描述劇情關鍵，提案三種蒙太奇敘事節奏。'
  },
  [ProductionPhase.STORYBOARD]: { 
    title: '技術分鏡', 
    icon: '🎞️',
    guide: '描述動作場景，提案三種分鏡鏡位策略。'
  },
  [ProductionPhase.VIDEO_PROMPTING]: { 
    title: '影片生成', 
    icon: '⚡',
    guide: '輸入拍攝願景，提案三種專業影片提示詞。'
  },
};

import React, { useState, useEffect, useRef } from 'react';
import { ProductionPhase, Suggestion, ProjectState, ProjectDNA, StageDesign, CharacterDesign } from './types';
import { PHASE_METADATA } from './constants';
import { GeminiService } from './services/geminiService';
import { ApiKeySelector } from './components/ApiKeySelector';
import { InspirationPhase } from './components/InspirationPhase';
import { ProductionPlanPhase } from './components/ProductionPlanPhase';
import { VisualDevPhase } from './components/VisualDevPhase';
import { CharacterDevPhase } from './components/CharacterDevPhase';
import { 
  Film, Loader2, ArrowRight, 
  ChevronRight, Download, Upload,
  X, CheckCircle2, Terminal, MapPin, Users, Target,
  Grid, Image as ImageIcon, Maximize2, DownloadCloud, UserPlus,
  BookOpen
} from 'lucide-react';

const App: React.FC = () => {
  const [hasKey, setHasKey] = useState(false);
  const [isLoading, setIsLoading] = useState(false);
  const [isAnalyzing, setIsAnalyzing] = useState(false);
  const [isElaborating, setIsElaborating] = useState(false);
  const [input, setInput] = useState('');
  const [activeStep, setActiveStep] = useState<ProductionPhase>(ProductionPhase.INSPIRATION);
  const [expandedImage, setExpandedImage] = useState<string | null>(null);

  // Ephemeral UI State
  const [suggestions, setSuggestions] = useState<Suggestion[]>([]);

  // Persistent Project State
  const [project, setProject] = useState<ProjectState>({
    currentPhase: ProductionPhase.INSPIRATION,
    initialInput: '',
    dna: { format: '電影', style: '寫實電影感', story: '', ratio: '16:9', environment: '', socialBackground: '', coreNarrative: '', directorVision: '' },
    proposedStages: [], 
    proposedCharacters: [], 
    coreStageImage: undefined 
  });

  const [tempDNA, setTempDNA] = useState<ProjectDNA>(project.dna);
  const fileInputRef = useRef<HTMLInputElement>(null);
  const geminiRef = useRef<GeminiService | null>(null);

  useEffect(() => {
    const checkKey = async () => {
      // @ts-ignore
      const exists = await window.aistudio.hasSelectedApiKey();
      if (exists) {
        setHasKey(true);
        geminiRef.current = new GeminiService(process.env.API_KEY || '');
      }
    };
    checkKey();
  }, []);

  useEffect(() => {
    if (activeStep === ProductionPhase.INSPIRATION && project.initialInput) {
      setInput(project.initialInput);
    }
  }, [project.initialInput, activeStep]);

  useEffect(() => {
    if (activeStep === ProductionPhase.VISUAL_DEV && project.proposedStages.length === 0 && !isAnalyzing && geminiRef.current) {
      handleIdentifyStages();
    }
    if (activeStep === ProductionPhase.CHARACTER_DEV && project.proposedCharacters.length === 0 && !isAnalyzing && geminiRef.current) {
      handleAutoAnalyzeCharacters();
    }
  }, [activeStep]);

  const handleIdentifyStages = async () => {
    if (!geminiRef.current || isAnalyzing) return;
    setIsAnalyzing(true);
    try {
      const stages = await geminiRef.current.identifyCoreStages(project.dna);
      setProject(prev => ({ ...prev, proposedStages: stages }));
    } catch (err) { console.error(err); } finally { setIsAnalyzing(false); }
  };

  const handleAutoAnalyzeCharacters = async () => {
    if (!geminiRef.current || isAnalyzing) return;
    setIsAnalyzing(true);
    try {
      const chars = await geminiRef.current.analyzeCharacters(project.dna);
      setProject(prev => ({ ...prev, proposedCharacters: chars }));
    } catch (err) { console.error(err); } finally { setIsAnalyzing(false); }
  };

  const updateDNAField = (field: keyof ProjectDNA, value: string) => {
    const updatedDNA = { ...project.dna, [field]: value };
    setProject(prev => ({ ...prev, dna: updatedDNA }));
    setTempDNA(updatedDNA);
  };

  const handleSubmitIdea = async (e?: React.FormEvent) => {
    if (e) e.preventDefault();
    if (!input.trim() || isLoading || !geminiRef.current) return;
    setIsLoading(true);
    try {
      const results = await geminiRef.current.generateSuggestions(input, activeStep, JSON.stringify(project.dna));
      setSuggestions(results || []);
      setProject(prev => ({ 
        ...prev, 
        initialInput: activeStep === ProductionPhase.INSPIRATION ? input : prev.initialInput
      }));
    } finally { setIsLoading(false); }
  };

  const handleSuggestionClick = async (s: Suggestion) => {
    if (!geminiRef.current) return;
    setIsElaborating(true);
    try {
      const detailedDNA = await geminiRef.current.elaboratePlan(s, project.dna);
      setTempDNA(detailedDNA);
      setSuggestions([]);
      setProject(prev => ({
        ...prev, 
        dna: detailedDNA, 
        currentPhase: ProductionPhase.PRODUCTION_PLAN
      }));
      setActiveStep(ProductionPhase.PRODUCTION_PLAN);
    } finally { setIsElaborating(false); }
  };

  const handleRenderCoreStageOnly = async () => {
    if (!geminiRef.current) return;
    setIsLoading(true);
    try {
      const coreImage = await geminiRef.current.generateCoreStyleVisual(tempDNA) || undefined;
      setProject(prev => ({ ...prev, coreStageImage: coreImage }));
    } finally { setIsLoading(false); }
  };

  const confirmProductionPlan = async () => {
    if (!geminiRef.current) return;
    setIsLoading(true);
    try {
      let coreImage = project.coreStageImage;
      if (!coreImage) {
        coreImage = await geminiRef.current.generateCoreStyleVisual(tempDNA) || undefined;
      }
      setProject(prev => ({
        ...prev, 
        currentPhase: ProductionPhase.VISUAL_DEV, 
        dna: { ...tempDNA }, 
        coreStageImage: coreImage,
        proposedStages: [], 
        proposedCharacters: []
      }));
      setActiveStep(ProductionPhase.VISUAL_DEV);
    } finally { setIsLoading(false); }
  };

  const handleProceedToCharacterDev = () => {
    setProject(prev => ({ ...prev, currentPhase: ProductionPhase.CHARACTER_DEV }));
    setActiveStep(ProductionPhase.CHARACTER_DEV);
  };

  const handleProceedToStoryArch = () => {
    setProject(prev => ({ ...prev, currentPhase: ProductionPhase.STORY_ARCH }));
    setActiveStep(ProductionPhase.STORY_ARCH);
  };

  const saveProject = () => {
    const stateToSave: ProjectState = { 
      ...project, 
      initialInput: input 
    };
    const data = JSON.stringify(stateToSave, null, 2);
    const blob = new Blob([data], { type: 'application/json' });
    const url = URL.createObjectURL(blob);
    const link = document.createElement('a');
    link.href = url;
    link.download = `montage-project-${new Date().toISOString().slice(0, 10)}.json`;
    link.click();
  };

  const loadProject = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;
    const reader = new FileReader();
    reader.onload = (event) => {
      try {
        const data = JSON.parse(event.target?.result as string) as ProjectState;
        if (data.currentPhase && data.dna) {
          setProject(data);
          setActiveStep(data.currentPhase);
          setTempDNA(data.dna);
          if (data.initialInput) setInput(data.initialInput);
        }
      } catch (err) { alert('檔案格式錯誤。'); }
    };
    reader.readAsText(file);
    if (fileInputRef.current) fileInputRef.current.value = '';
  };

  const handleRenderStageGrid = async (idx: number) => {
    if (!geminiRef.current) return;
    setIsLoading(true);
    setProject(prev => ({ ...prev, selectedStageIndex: idx }));
    try {
      const gridResult = await geminiRef.current.generateStageGrid(project.dna, project.proposedStages[idx]);
      if (gridResult) {
        setProject(prev => {
          const newStages = [...prev.proposedStages];
          newStages[idx] = { ...newStages[idx], gridImage: gridResult };
          return { ...prev, proposedStages: newStages };
        });
      }
    } finally { setIsLoading(false); }
  };

  const handleRenderCharacterGrid = async (idx: number) => {
    if (!geminiRef.current) return;
    setIsLoading(true);
    setProject(prev => ({ ...prev, selectedCharacterIndex: idx }));
    try {
      const gridResult = await geminiRef.current.generateCharacterGrid(project.dna, project.proposedCharacters[idx]);
      if (gridResult) {
        setProject(prev => {
          const newChars = [...prev.proposedCharacters];
          newChars[idx] = { ...newChars[idx], gridImage: gridResult };
          return { ...prev, proposedCharacters: newChars };
        });
      }
    } finally { setIsLoading(false); }
  };

  const updateStage = (idx: number, field: keyof StageDesign, value: string) => {
    setProject(prev => {
      const newStages = [...prev.proposedStages];
      newStages[idx] = { ...newStages[idx], [field]: value };
      return { ...prev, proposedStages: newStages };
    });
  };

  const updateCharacter = (idx: number, field: keyof CharacterDesign, value: string) => {
    setProject(prev => {
      const newChars = [...prev.proposedCharacters];
      newChars[idx] = { ...newChars[idx], [field]: value };
      return { ...prev, proposedCharacters: newChars };
    });
  };

  const handlePolishCharacter = async (idx: number, field: keyof CharacterDesign, label: string) => {
    if (!geminiRef.current || isLoading) return;
    setIsLoading(true);
    try {
      const char = project.proposedCharacters[idx];
      const polished = await geminiRef.current.polishText(char[field] as string, `角色塑造之${label}`);
      updateCharacter(idx, field, polished);
    } finally { setIsLoading(false); }
  };

  const downloadImage = (base64: string, name: string) => {
    const link = document.createElement('a');
    link.href = base64;
    link.download = `${name}.png`;
    link.click();
  };

  const getPhaseIndex = (phase: ProductionPhase) => {
    return Object.values(ProductionPhase).indexOf(phase);
  };

  const allCharactersReady = project.proposedCharacters.length > 0 && 
                             project.proposedCharacters.every(c => c.gridImage);

  if (!hasKey) return <ApiKeySelector onSelected={() => setHasKey(true)} />;

  return (
    <div className="flex h-screen bg-[#050505] text-white overflow-hidden font-sans">
      {expandedImage && (
        <div className="fixed inset-0 bg-black/95 z-[100] flex flex-col items-center justify-center p-8 animate-in fade-in duration-300" onClick={() => setExpandedImage(null)}>
          <button className="absolute top-8 right-8 p-3 bg-white/5 hover:bg-amber-600 rounded-full transition-all group">
            <X className="w-8 h-8 text-white group-hover:scale-110" />
          </button>
          <div className="relative max-w-7xl w-full max-h-full" onClick={e => e.stopPropagation()}>
            <img src={expandedImage} className="w-full h-full object-contain shadow-2xl rounded-lg border border-white/10" />
            <button onClick={() => downloadImage(expandedImage, 'montage-asset')} className="absolute bottom-4 right-4 flex items-center gap-2 bg-amber-600 hover:bg-amber-500 px-6 py-3 rounded-full font-bold shadow-xl transition-all">
              <DownloadCloud className="w-5 h-5" /> 下載原始圖片
            </button>
          </div>
        </div>
      )}

      <aside className="w-64 border-r border-white/5 flex flex-col bg-black/40 p-6">
        <div className="flex items-center gap-3 mb-12">
          <div className="bg-amber-600 p-2 rounded-lg shadow-[0_0_15px_rgba(217,119,6,0.3)]"><Film className="w-6 h-6 text-white" /></div>
          <h1 className="text-lg font-serif font-bold tracking-widest text-white/90 uppercase">Montage AI</h1>
        </div>
        <nav className="flex-1 space-y-2">
          {Object.entries(PHASE_METADATA).map(([key, meta], idx) => {
            const phaseKey = key as ProductionPhase;
            const isActive = activeStep === phaseKey;
            const isAccessible = getPhaseIndex(phaseKey) <= getPhaseIndex(project.currentPhase);
            return (
              <button 
                key={key} 
                disabled={!isAccessible} 
                onClick={() => setActiveStep(phaseKey)} 
                className={`w-full relative flex items-center gap-4 p-3 rounded-lg transition-all text-left group ${isActive ? 'bg-amber-600/20 text-amber-500 ring-1 ring-amber-600/30' : 'text-neutral-600 hover:text-neutral-400'} ${!isAccessible ? 'opacity-30 grayscale cursor-not-allowed' : 'cursor-pointer'}`}
              >
                {isActive && <div className="absolute left-0 w-1 h-6 bg-amber-600 rounded-full" />}
                <span className="text-xl">{meta.icon}</span>
                <div className="flex flex-col">
                  <span className="text-[9px] uppercase tracking-tighter opacity-50">Step 0{idx+1}</span>
                  <span className="text-sm font-bold">{meta.title}</span>
                </div>
              </button>
            );
          })}
        </nav>
        <div className="mt-8 space-y-2 border-t border-white/5 pt-6">
          <button onClick={saveProject} className="w-full flex items-center gap-3 px-3 py-2 text-xs text-neutral-400 hover:text-white transition-colors group"><Download className="w-4 h-4 text-amber-600" /> <span>匯出專案</span></button>
          <button onClick={() => fileInputRef.current?.click()} className="w-full flex items-center gap-3 px-3 py-2 text-xs text-neutral-400 hover:text-white transition-colors group"><Upload className="w-4 h-4 text-amber-600" /> <span>匯入專案</span></button>
          <input type="file" ref={fileInputRef} onChange={loadProject} className="hidden" accept=".json" />
        </div>
      </aside>

      <main className="flex-1 flex flex-col relative overflow-hidden">
        <header className="h-16 px-8 border-b border-white/5 flex items-center justify-between z-10 bg-black/50 backdrop-blur-md">
          <div className="flex items-center gap-2"><Terminal className="w-4 h-4 text-amber-600" /><span className="text-[10px] text-neutral-500 uppercase tracking-[0.2em]">TERMINAL</span><ChevronRight className="w-3 h-3 text-neutral-600" /><span className="text-sm font-bold text-amber-500 uppercase">{PHASE_METADATA[activeStep]?.title}</span></div>
          <div className="flex items-center gap-4">
            {activeStep === ProductionPhase.PRODUCTION_PLAN && (
              <button onClick={confirmProductionPlan} disabled={isLoading} className="bg-amber-600 hover:bg-amber-500 px-6 py-2 rounded-full text-[11px] font-bold flex items-center gap-2 shadow-lg transition-all">
                {isLoading ? <Loader2 className="w-3.5 h-3.5 animate-spin" /> : <CheckCircle2 className="w-3.5 h-3.5" />} 確認方案並塑造舞台
              </button>
            )}
            {activeStep === ProductionPhase.VISUAL_DEV && (
              <button onClick={handleProceedToCharacterDev} className="bg-amber-600 hover:bg-amber-500 px-6 py-2 rounded-full text-[11px] font-bold flex items-center gap-2 shadow-lg transition-all">
                <UserPlus className="w-3.5 h-3.5" /> 進行角色塑造
              </button>
            )}
            {activeStep === ProductionPhase.CHARACTER_DEV && (
              <button 
                onClick={handleProceedToStoryArch} 
                disabled={!allCharactersReady}
                className={`px-6 py-2 rounded-full text-[11px] font-bold flex items-center gap-2 shadow-lg transition-all ${allCharactersReady ? 'bg-amber-600 hover:bg-amber-500 text-white' : 'bg-neutral-800 text-neutral-500 cursor-not-allowed opacity-50'}`}
              >
                <BookOpen className="w-3.5 h-3.5" /> 鋪陳敘事結構
              </button>
            )}
          </div>
        </header>

        <section className="flex-1 flex flex-col items-center justify-start p-8 max-w-5xl mx-auto w-full overflow-y-auto">
          {activeStep === ProductionPhase.INSPIRATION && (
            <InspirationPhase 
              input={input} 
              setInput={setInput} 
              isLoading={isLoading} 
              isElaborating={isElaborating} 
              suggestions={suggestions} 
              onSubmit={handleSubmitIdea} 
              onSuggestionClick={handleSuggestionClick} 
              guideText={PHASE_METADATA[activeStep]?.guide}
              dna={project.dna}
              onUpdateDNA={updateDNAField}
            />
          )}
          {activeStep === ProductionPhase.PRODUCTION_PLAN && (
            <ProductionPlanPhase dna={tempDNA} setDna={setTempDNA} onRenderCoreVisual={handleRenderCoreStageOnly} isLoading={isLoading} />
          )}
          {activeStep === ProductionPhase.VISUAL_DEV && (
            <VisualDevPhase project={project} isAnalyzing={isAnalyzing} isLoading={isLoading} onUpdateStage={updateStage} onRenderGrid={handleRenderStageGrid} guideText={PHASE_METADATA[activeStep]?.guide} />
          )}
          {activeStep === ProductionPhase.CHARACTER_DEV && (
            <CharacterDevPhase project={project} isAnalyzing={isAnalyzing} isLoading={isLoading} onUpdateCharacter={updateCharacter} onPolishCharacter={handlePolishCharacter} onRenderGrid={handleRenderCharacterGrid} guideText={PHASE_METADATA[activeStep]?.guide} />
          )}
        </section>
      </main>

      <aside className="w-80 border-l border-white/5 bg-black/40 p-6 flex flex-col gap-8 overflow-y-auto">
        <h3 className="text-[10px] font-bold text-neutral-500 uppercase tracking-widest border-b border-white/5 pb-2">視覺檔案 (Asset)</h3>

        <div className="space-y-4">
          <span className="text-[10px] text-amber-500/70 font-mono uppercase tracking-widest block">CORE_STAGE_VISUAL</span>
          {project.coreStageImage ? (
            <div className="aspect-video rounded-2xl overflow-hidden border border-white/10 shadow-lg cursor-zoom-in" onClick={() => setExpandedImage(project.coreStageImage!)}>
              <img src={project.coreStageImage} className="w-full h-full object-cover" alt="Core Stage Visual" />
            </div>
          ) : (
            <div className="py-12 border border-dashed border-white/10 rounded-2xl text-center opacity-30">
              <ImageIcon className="w-6 h-6 mx-auto mb-2 text-neutral-700" />
              <p className="text-[8px] uppercase tracking-widest">等待核心舞台視覺</p>
            </div>
          )}
        </div>

        {project.proposedStages.some(s => s.gridImage) && (
          <div className="space-y-6 pt-6 border-t border-white/5">
            <span className="text-[10px] text-amber-500/70 font-mono uppercase tracking-widest block">STAGE_GRIDS</span>
            {project.proposedStages.filter(s => s.gridImage).map((stage, i) => (
              <div key={i} className="space-y-2 group">
                <div className="flex items-center justify-between">
                  <span className="text-[9px] font-bold text-neutral-400 truncate block">{stage.name}</span>
                  <Download className="w-3 h-3 text-neutral-600 hover:text-amber-500 cursor-pointer" onClick={() => downloadImage(stage.gridImage!, `Stage-${stage.name}`)} />
                </div>
                <div className="aspect-square rounded-xl overflow-hidden border border-white/5 cursor-zoom-in" onClick={() => setExpandedImage(stage.gridImage!)}>
                  <img src={stage.gridImage} className="w-full h-full object-cover grayscale hover:grayscale-0 transition-all duration-500" alt={stage.name} />
                </div>
              </div>
            ))}
          </div>
        )}

        {project.proposedCharacters.some(c => c.gridImage) && (
          <div className="space-y-6 pt-6 border-t border-white/5">
            <span className="text-[10px] text-amber-500/70 font-mono uppercase tracking-widest block">CHARACTER_GRIDS</span>
            {project.proposedCharacters.filter(c => c.gridImage).map((char, i) => (
              <div key={i} className="space-y-2 group">
                <div className="flex items-center justify-between">
                  <span className="text-[9px] font-bold text-neutral-400 truncate block">{char.name}</span>
                  <Download className="w-3 h-3 text-neutral-600 hover:text-amber-500 cursor-pointer" onClick={() => downloadImage(char.gridImage!, `Character-${char.name}`)} />
                </div>
                <div className="aspect-square rounded-xl overflow-hidden border border-white/5 cursor-zoom-in" onClick={() => setExpandedImage(char.gridImage!)}>
                  <img src={char.gridImage} className="w-full h-full object-cover" alt={char.name} />
                </div>
              </div>
            ))}
          </div>
        )}
      </aside>
    </div>
  );
};

export default App;

export { };

export enum ProductionPhase {
  INSPIRATION = 'INSPIRATION',
  PRODUCTION_PLAN = 'PRODUCTION_PLAN',
  VISUAL_DEV = 'VISUAL_DEV',
  CHARACTER_DEV = 'CHARACTER_DEV',
  STORY_ARCH = 'STORY_ARCH',
  STORYBOARD = 'STORYBOARD',
  VIDEO_PROMPTING = 'VIDEO_PROMPTING'
}

export interface Message {
  role: 'user' | 'assistant';
  content: string;
  videoUrl?: string;
  images?: string[];
}

export interface Suggestion {
  title: string;
  description: string;
  tags: string[];
  environment?: string;
  socialBackground?: string;
  coreNarrative?: string;
}

export interface StageDesign {
  name: string;
  description: string;
  gridImage?: string;
}

export interface CharacterDesign {
  name: string;
  role: string;
  physicalTraits: string; 
  visualTone: string;    
  motivation: string;    
  gridImage?: string;    
}

export interface Chapter {
  title: string;
  emotionalTone: string;
