        contents: { parts: [{ text: gridPrompt }] },
        config: { imageConfig: { aspectRatio: "1:1", imageSize: "1K" } }
      });
      for (const part of response.candidates?.[0]?.content?.parts || []) {
        if (part.inlineData) return `data:image/png;base64,${part.inlineData.data}`;
      }
    } catch (error) { console.error(error); }
    return "";
  }

  async generateCharacterGrid(dna: ProjectDNA, character: CharacterDesign): Promise<string> {
    const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
    const gridPrompt = `
      Professional 3x3 "Deconstructive Visual Language" Character Sheet for: "${character.name}" (${character.role}).
      Style: ${dna.style}. Format: ${dna.format}.

      STRICT 3x3 GRID LAYOUT:
      1. Center: Full body dynamic pose.
      2. Surrounding Panels: Close-up of facial emotions, macro-texture of skin/surface/suit, symbolic accessories, material breakdown, and profile silhouette.
      Ensure high-fidelity concept art style, consistent lighting and color palette across all nine panels.
    `;
    try {
      const response = await ai.models.generateContent({
        model: 'gemini-3-pro-image-preview',
        contents: { parts: [{ text: gridPrompt }] },
        config: { imageConfig: { aspectRatio: "1:1", imageSize: "1K" } }
      });
      for (const part of response.candidates?.[0]?.content?.parts || []) {
        if (part.inlineData) return `data:image/png;base64,${part.inlineData.data}`;
      }
    } catch (error) { console.error(error); }
    return "";
  }
}

import React from 'react';
import { Loader2, Clapperboard, Video, Music, Info, Camera, Clock, Plus, Trash2 } from 'lucide-react';
import { ProjectState, Storyboard, StoryboardEntry } from '../types';

interface StoryboardPhaseProps {
  project: ProjectState;
  isLoading: boolean;
  onUpdateStoryboard: (sb: Storyboard) => void;
  guideText: string;
}

export const StoryboardPhase: React.FC<StoryboardPhaseProps> = ({
  project, isLoading, onUpdateStoryboard, guideText
}) => {
  const sb = project.storyboard;

  if (isLoading && !sb) {
    return (
      <div className="py-20 flex flex-col items-center gap-6 animate-pulse">
        <Loader2 className="w-12 h-12 text-amber-600 animate-spin" />
        <p className="text-amber-500 text-xs font-bold uppercase tracking-[0.3em]">AI 正在編寫技術分鏡腳本...</p>
      </div>
    );
  }

  if (!sb) return null;

  const handleUpdateEntry = (idx: number, field: keyof StoryboardEntry, val: string) => {
    const newEntries = [...sb.entries];
    newEntries[idx] = { ...newEntries[idx], [field]: val };

    // Contiguous timeline logic
    if (field === 'endTime' && idx < newEntries.length - 1) {
      newEntries[idx + 1] = { ...newEntries[idx + 1], startTime: val };
    }
    if (field === 'startTime' && idx > 0) {
      newEntries[idx - 1] = { ...newEntries[idx - 1], endTime: val };
    }

    onUpdateStoryboard({ entries: newEntries });
  };

  const handleAddEntry = (idx: number) => {
    const newEntries = [...sb.entries];
    const prevEntry = newEntries[idx];
    const startTime = prevEntry ? prevEntry.endTime : "00:00:00";

    // Auto-calculate dummy end time (+5s)
    const [h, m, s] = startTime.split(':').map(Number);
    const date = new Date();
    date.setHours(h, m, s + 5);
    const endTime = date.toTimeString().split(' ')[0];

    const newEntry: StoryboardEntry = {
      startTime,
      endTime,
      shotType: "MCU",
      movement: "STATIC",
      action: "新分鏡動作描述...",
      audio: "環境音...",
      directingNote: "技術指導..."
    };

    newEntries.splice(idx + 1, 0, newEntry);

    // Fix subsequent start times
    for (let i = idx + 1; i < newEntries.length - 1; i++) {
        newEntries[i+1].startTime = newEntries[i].endTime;
    }

    onUpdateStoryboard({ entries: newEntries });
  };

  const handleRemoveEntry = (idx: number) => {
    if (sb.entries.length <= 1) return;
    const newEntries = [...sb.entries];
    newEntries.splice(idx, 1);

    // Heal the timeline gap
    if (idx > 0 && idx < newEntries.length) {
        newEntries[idx].startTime = newEntries[idx - 1].endTime;
    } else if (idx === 0 && newEntries.length > 0) {
        newEntries[0].startTime = "00:00:00";
    }

    onUpdateStoryboard({ entries: newEntries });
  };

  return (
    <div className="w-full space-y-12 pb-20 animate-in fade-in duration-1000">
      <div className="text-center space-y-4">
        <h2 className="text-3xl font-serif text-neutral-100">{guideText}</h2>
        <p className="text-sm text-neutral-500 max-w-xl mx-auto">技術分鏡腳本已生成。修改時間戳會自動連動前後鏡頭，確保時間軸連續性。</p>
      </div>

      <div className="glass rounded-3xl border-white/5 overflow-hidden shadow-2xl">
        <div className="overflow-x-auto">
          <table className="w-full text-left border-collapse min-w-[1200px]">
            <thead>
              <tr className="bg-white/5 border-b border-white/10">
                <th className="px-4 py-4 text-[10px] font-bold text-neutral-500 uppercase tracking-widest w-28">Time Range</th>
                <th className="px-4 py-4 text-[10px] font-bold text-neutral-500 uppercase tracking-widest w-40">Shot Type</th>
                <th className="px-4 py-4 text-[10px] font-bold text-neutral-500 uppercase tracking-widest w-40">Movement</th>
                <th className="px-4 py-4 text-[10px] font-bold text-neutral-500 uppercase tracking-widest">Visual Action</th>
                <th className="px-4 py-4 text-[10px] font-bold text-neutral-500 uppercase tracking-widest w-48">Audio / SFX</th>
                <th className="px-4 py-4 text-[10px] font-bold text-neutral-500 uppercase tracking-widest w-48 text-amber-500/70">Directing Note</th>
                <th className="px-4 py-4 text-[10px] font-bold text-neutral-500 uppercase tracking-widest w-16 text-center">Actions</th>
              </tr>
            </thead>
            <tbody className="divide-y divide-white/5">
              {sb.entries.map((entry, idx) => (
                <tr key={idx} className="hover:bg-amber-600/5 transition-colors group border-b border-white/5">
                  {/* TIME RANGE COLUMN */}
                  <td className="px-3 py-4 align-top space-y-2 border-r border-white/5">
                    <div className="flex flex-col gap-2">
                        <div className="flex items-center gap-1.5 px-2 py-1 bg-black/40 rounded border border-white/10 group-focus-within:border-amber-500/50 transition-colors">
                            <span className="text-[8px] text-neutral-600 font-bold">IN</span>
                            <input
                                className="bg-transparent border-none text-[11px] font-mono font-bold text-amber-600 w-full p-0 focus:ring-0"
                                value={entry.startTime}
                                readOnly={idx === 0}
                                onChange={(e) => handleUpdateEntry(idx, 'startTime', e.target.value)}
                            />
                        </div>
                        <div className="flex items-center gap-1.5 px-2 py-1 bg-black/40 rounded border border-white/10 group-focus-within:border-amber-500/50 transition-colors">
                            <span className="text-[8px] text-neutral-600 font-bold">OUT</span>
                            <input
                                className="bg-transparent border-none text-[11px] font-mono font-bold text-amber-500 w-full p-0 focus:ring-0"
                                value={entry.endTime}
                                onChange={(e) => handleUpdateEntry(idx, 'endTime', e.target.value)}
                            />
                        </div>
                    </div>
                  </td>

                  {/* SHOT TYPE */}
                  <td className="px-3 py-4 align-top border-r border-white/5">
                    <div className="flex flex-col gap-1">
                      <div className="flex items-center gap-1 text-[8px] font-bold text-neutral-600 uppercase mb-1">
                        <Camera className="w-2.5 h-2.5" /> Lens Strategy
                      </div>
                      <textarea
                        className="w-full bg-transparent border-none text-[10px] font-bold text-blue-400 uppercase leading-snug resize-none p-0 focus:ring-0"
                        rows={2}
                        value={entry.shotType}
                        onChange={(e) => handleUpdateEntry(idx, 'shotType', e.target.value)}
                      />
                    </div>
                  </td>

                  {/* MOVEMENT */}
                  <td className="px-3 py-4 align-top border-r border-white/5">
                    <div className="flex flex-col gap-1">
                      <div className="flex items-center gap-1 text-[8px] font-bold text-neutral-600 uppercase mb-1">
                        <Video className="w-2.5 h-2.5" /> Camera Kinematics
                      </div>
                      <textarea
                        className="w-full bg-transparent border-none text-[10px] font-bold text-purple-400 uppercase leading-snug resize-none p-0 focus:ring-0"
                        rows={2}
                        value={entry.movement}
                        onChange={(e) => handleUpdateEntry(idx, 'movement', e.target.value)}
                      />
                    </div>
                  </td>

                  {/* VISUAL ACTION */}
                  <td className="px-4 py-4 align-top border-r border-white/5">
                    <div className="text-[8px] font-bold text-neutral-600 uppercase mb-1">Visual Dynamics</div>
                    <textarea
                      className="w-full bg-transparent border-none text-[11px] text-neutral-200 leading-relaxed resize-none p-0 focus:ring-0"
                      rows={2}
                      value={entry.action}
                      onChange={(e) => handleUpdateEntry(idx, 'action', e.target.value)}
                      onInput={(e) => {
                        const target = e.target as HTMLTextAreaElement;
                        target.style.height = 'auto';
                        target.style.height = target.scrollHeight + 'px';
                      }}
                    />
                  </td>

                  {/* AUDIO */}
                  <td className="px-4 py-4 align-top border-r border-white/5">
                    <div className="flex items-center gap-1.5 text-[8px] font-bold text-neutral-600 uppercase mb-1">
                      <Music className="w-2.5 h-2.5" /> Soundscape
                    </div>
                    <textarea
                        className="w-full bg-transparent border-none text-[10px] text-neutral-400 italic leading-relaxed resize-none p-0 focus:ring-0"
                        rows={2}
                        value={entry.audio}
                        onChange={(e) => handleUpdateEntry(idx, 'audio', e.target.value)}
                    />
                  </td>

                  {/* DIRECTING NOTE */}
                  <td className="px-4 py-4 align-top border-r border-white/5">
                    <div className="flex items-center gap-1.5 text-[8px] font-bold text-amber-500/50 uppercase mb-1">
                      <Info className="w-2.5 h-2.5" /> Director's Blocking
                    </div>
                    <textarea
                        className="w-full bg-transparent border-none text-[10px] text-neutral-500 leading-relaxed resize-none p-0 focus:ring-0"
                        rows={2}
                        value={entry.directingNote}
                        onChange={(e) => handleUpdateEntry(idx, 'directingNote', e.target.value)}
                    />
                  </td>

                  {/* ACTIONS */}
                  <td className="px-3 py-4 align-top">
                    <div className="flex flex-col gap-2 items-center opacity-0 group-hover:opacity-100 transition-opacity">
                      <button 
                        onClick={() => handleAddEntry(idx)}
                        className="p-1.5 bg-amber-600/10 hover:bg-amber-600 text-amber-500 hover:text-white rounded-md transition-all"
                        title="插入下一個鏡頭"
                      >
                        <Plus className="w-3.5 h-3.5" />
                      </button>
                      <button 
                        onClick={() => handleRemoveEntry(idx)}
                        className="p-1.5 bg-red-500/10 hover:bg-red-500 text-neutral-600 hover:text-white rounded-md transition-all"
                        title="移除此鏡頭"
                      >
                        <Trash2 className="w-3.5 h-3.5" />
                      </button>
                    </div>
                  </td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>
      </div>

      <div className="flex justify-center pt-8">
        <div className="inline-flex items-center gap-4 px-8 py-4 bg-amber-600/5 rounded-full border border-amber-600/20 shadow-xl group hover:border-amber-600/40 transition-all">
          <Clapperboard className="w-6 h-6 text-amber-600 group-hover:scale-110 transition-transform" />
          <p className="text-xs font-bold text-neutral-400 uppercase tracking-[0.2em]">技術藍圖定稿 • 準備進入影像生成</p>
        </div>
      </div>
    </div>
  );
};

import { GoogleGenAI, Type } from "@google/genai";
import { SYSTEM_INSTRUCTION } from "../constants";
import { Suggestion, StageDesign, CharacterDesign, ProjectDNA, ProductionPhase, StoryArchitecture, Storyboard } from "../types";

export class GeminiService {
  constructor(apiKey: string) { }

  async generateSuggestions(input: string, phase: ProductionPhase, context: string): Promise<Suggestion[]> {
    const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
    const currentDNA = JSON.parse(context) as ProjectDNA;

    const prompt = `
    目前的製作設定：
    - 形式：${currentDNA.format}
    - 預想視覺風格：${currentDNA.style}
    - 畫面比例：${currentDNA.ratio}

    核心靈感/指令： "${input}"。

    請根據目前的製作階段 [${phase}]，提供三個具體的創意導向（頂尖導演提案）。
    這些提案必須在視覺張力與敘事節奏上符合上述的「製作設定」。

    【關鍵任務】如果是 INSPIRATION 階段，請發揮頂尖導演聯想力，自動推論出初步的：
    1. 地理環境 (environment)
    2. 社會背景 (socialBackground)
    3. 核心敘事 (coreNarrative)

    請回傳 JSON 陣列，包含 title, description, tags, environment, socialBackground, coreNarrative。`;

    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: [{ role: 'user', parts: [{ text: prompt }] }],
      config: {
        systemInstruction: SYSTEM_INSTRUCTION,
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.ARRAY,
          items: {
            type: Type.OBJECT,
            properties: {
              title: { type: Type.STRING },
              description: { type: Type.STRING },
              tags: { type: Type.ARRAY, items: { type: Type.STRING } },
              environment: { type: Type.STRING },
              socialBackground: { type: Type.STRING },
              coreNarrative: { type: Type.STRING }
            },
            required: ["title", "description", "tags"]
          }
        }
      }
    });
    return JSON.parse(response.text || "[]");
  }

  async elaboratePlan(suggestion: Suggestion, baseDNA: ProjectDNA): Promise<ProjectDNA> {
    const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
    const prompt = `
    請將以下提案擴充為完整的電影拍攝 DNA：
    提案標題：${suggestion.title}

    【核心約束】你必須嚴格遵循用戶設定的基底 DNA：
    - 製作形式：${baseDNA.format}
    - 預選視覺風格：${baseDNA.style}
    - 畫面比例：${baseDNA.ratio}

    內容需包含：符合該風格的地理環境、社會背景、核心敘事與一份細緻的劇本摘要。
    此外，請作為 AI 頂尖導演，提出一份「拍攝方案建議方向 (directorVision)」，包含建議的運鏡方式、色彩校正方向、以及聲音設計重點。
    `;

    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: [{ role: 'user', parts: [{ text: prompt }] }],
      config: {
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.OBJECT,
          properties: {
            format: { type: Type.STRING },
            style: { type: Type.STRING },
            story: { type: Type.STRING },
            ratio: { type: Type.STRING },
            environment: { type: Type.STRING },
            socialBackground: { type: Type.STRING },
            coreNarrative: { type: Type.STRING },
            directorVision: { type: Type.STRING }
          },
          required: ["format", "style", "story", "environment", "socialBackground", "coreNarrative", "directorVision"]
        }
      }
    });
