import React from 'react';
import { Loader2, Clapperboard, Video, Music, Info, Camera, Clock, Plus, Trash2 } from 'lucide-react';
import { ProjectState, Storyboard, StoryboardEntry } from '../types';

interface StoryboardPhaseProps {
  project: ProjectState;
  isLoading: boolean;
  onUpdateStoryboard: (sb: Storyboard) => void;
  guideText: string;
}

export const StoryboardPhase: React.FC<StoryboardPhaseProps> = ({
  project, isLoading, onUpdateStoryboard, guideText
}) => {
  const sb = project.storyboard;

  if (isLoading && !sb) {
    return (
      <div className="py-20 flex flex-col items-center gap-6 animate-pulse">
        <Loader2 className="w-12 h-12 text-amber-600 animate-spin" />
        <p className="text-amber-500 text-xs font-bold uppercase tracking-[0.3em]">AI 正在編寫技術分鏡腳本...</p>
      </div>
    );
  }

  if (!sb) return null;

  const handleUpdateEntry = (idx: number, field: keyof StoryboardEntry, val: string) => {
    const newEntries = [...sb.entries];
    newEntries[idx] = { ...newEntries[idx], [field]: val };

    // 連續時間軸自動平移功能
    if (field === 'endTime') {
      // 修改目前鏡頭的結束時間，連動下一個鏡頭的開始時間
      if (idx < newEntries.length - 1) {
        newEntries[idx + 1] = { ...newEntries[idx + 1], startTime: val };
      }
    } else if (field === 'startTime') {
      // 修改目前鏡頭的開始時間，連動上一個鏡頭的結束時間
      if (idx > 0) {
        newEntries[idx - 1] = { ...newEntries[idx - 1], endTime: val };
      }
    }

    onUpdateStoryboard({ entries: newEntries });
  };

  const handleAddEntry = (idx: number) => {
    const newEntries = [...sb.entries];
    const currentEntry = newEntries[idx];
    const startTime = currentEntry.endTime;

    // 自動預填 5 秒長度
    const [h, m, s] = startTime.split(':').map(Number);
    const date = new Date();
    date.setHours(h, m, s + 5);
    const endTime = date.toTimeString().split(' ')[0];

    const newEntry: StoryboardEntry = {
      startTime,
      endTime,
      shotType: "MCU",
      movement: "STATIC",
      action: "新場景視覺動態描述...",
      audio: "同步環境聲...",
      directingNote: "導演技術細節指導..."
    };

    newEntries.splice(idx + 1, 0, newEntry);

    // 重新校準後續所有鏡頭的起始時間，保持連續性
    for (let i = idx + 1; i < newEntries.length - 1; i++) {
        newEntries[i+1].startTime = newEntries[i].endTime;
    }

    onUpdateStoryboard({ entries: newEntries });
  };

  const handleRemoveEntry = (idx: number) => {
    if (sb.entries.length <= 1) return;
    const newEntries = [...sb.entries];
    newEntries.splice(idx, 1);

    // 縫合時間軸斷裂處
    if (idx > 0 && idx < newEntries.length) {
        newEntries[idx].startTime = newEntries[idx - 1].endTime;
    } else if (idx === 0 && newEntries.length > 0) {
        newEntries[0].startTime = "00:00:00";
    }

    onUpdateStoryboard({ entries: newEntries });
  };

  return (
    <div className="w-full space-y-8 pb-20 animate-in fade-in duration-1000 overflow-hidden">
      <div className="text-center space-y-3">
        <h2 className="text-2xl font-serif text-neutral-100">{guideText}</h2>
        <p className="text-[11px] text-neutral-500 max-w-xl mx-auto">分鏡已對齊 AI 規劃。修改時間會自動連動前後鏡頭，確保無重疊或斷裂。</p>
      </div>

      <div className="glass rounded-2xl border-white/5 overflow-hidden shadow-2xl max-w-full">
        <div className="overflow-x-auto">
          <table className="w-full text-left border-collapse table-fixed min-w-[900px]">
            <thead className="bg-white/5">
              <tr className="border-b border-white/10">
                <th className="px-3 py-3 text-[9px] font-bold text-neutral-500 uppercase tracking-widest w-20">Time</th>
                <th className="px-3 py-3 text-[9px] font-bold text-neutral-500 uppercase tracking-widest w-24">Shot Type</th>
                <th className="px-3 py-3 text-[9px] font-bold text-neutral-500 uppercase tracking-widest w-24">Movement</th>
                <th className="px-3 py-3 text-[9px] font-bold text-neutral-500 uppercase tracking-widest">Visual Action</th>
                <th className="px-3 py-3 text-[9px] font-bold text-neutral-500 uppercase tracking-widest w-36">Audio / SFX</th>
                <th className="px-3 py-3 text-[9px] font-bold text-neutral-500 uppercase tracking-widest w-36 text-amber-500/70">Director's Note</th>
                <th className="px-2 py-3 text-[9px] font-bold text-neutral-500 uppercase tracking-widest w-12 text-center">Ops</th>
              </tr>
            </thead>
            <tbody className="divide-y divide-white/5">
              {sb.entries.map((entry, idx) => (
                <tr key={idx} className="hover:bg-amber-600/5 transition-colors group">
                  {/* 起迄時間列 */}
                  <td className="px-2 py-3 align-top border-r border-white/5">
                    <div className="flex flex-col gap-1.5">
                        <div className="flex items-center gap-1 px-1.5 py-0.5 bg-black/40 rounded border border-white/5 focus-within:border-amber-500/30">
                            <span className="text-[7px] text-neutral-600 font-bold w-4">IN</span>
                            <input
                                className="bg-transparent border-none text-[10px] font-mono font-bold text-amber-600 w-full p-0 focus:ring-0"
                                value={entry.startTime}
                                readOnly={idx === 0}
                                onChange={(e) => handleUpdateEntry(idx, 'startTime', e.target.value)}
                            />
                        </div>
                        <div className="flex items-center gap-1 px-1.5 py-0.5 bg-black/40 rounded border border-white/5 focus-within:border-amber-500/30">
                            <span className="text-[7px] text-neutral-600 font-bold w-4">OUT</span>
                            <input
                                className="bg-transparent border-none text-[10px] font-mono font-bold text-amber-500 w-full p-0 focus:ring-0"
                                value={entry.endTime}
                                onChange={(e) => handleUpdateEntry(idx, 'endTime', e.target.value)}
                            />
                        </div>
                    </div>
                  </td>

                  {/* 鏡頭類型 */}
                  <td className="px-2 py-3 align-top border-r border-white/5">
                    <textarea
                      className="w-full bg-transparent border-none text-[10px] font-bold text-blue-400 uppercase leading-snug resize-none p-0 focus:ring-0"
                      rows={2}
                      value={entry.shotType}
                      onChange={(e) => handleUpdateEntry(idx, 'shotType', e.target.value)}
                    />
                  </td>

                  {/* 運鏡描述 */}
                  <td className="px-2 py-3 align-top border-r border-white/5">
                    <textarea
                      className="w-full bg-transparent border-none text-[10px] font-bold text-purple-400 uppercase leading-snug resize-none p-0 focus:ring-0"
                      rows={2}
                      value={entry.movement}
                      onChange={(e) => handleUpdateEntry(idx, 'movement', e.target.value)}
                    />
                  </td>

                  {/* 畫面動作 */}
                  <td className="px-3 py-3 align-top border-r border-white/5">
                    <textarea
                      className="w-full bg-transparent border-none text-[10px] text-neutral-200 leading-normal resize-none p-0 focus:ring-0 h-auto"
                      rows={2}
                      value={entry.action}
                      onChange={(e) => handleUpdateEntry(idx, 'action', e.target.value)}
                      onInput={(e) => {
                        const target = e.target as HTMLTextAreaElement;
                        target.style.height = 'auto';
                        target.style.height = target.scrollHeight + 'px';
                      }}
                    />
                  </td>

                  {/* 音效音樂 */}
                  <td className="px-3 py-3 align-top border-r border-white/5">
                    <textarea
                        className="w-full bg-transparent border-none text-[9px] text-neutral-400 italic leading-normal resize-none p-0 focus:ring-0"
                        rows={2}
                        value={entry.audio}
                        onChange={(e) => handleUpdateEntry(idx, 'audio', e.target.value)}
                    />
                  </td>

                  {/* 導戲備註 */}
                  <td className="px-3 py-3 align-top border-r border-white/5">
                    <textarea
                        className="w-full bg-transparent border-none text-[9px] text-neutral-500 leading-normal resize-none p-0 focus:ring-0"
                        rows={2}
                        value={entry.directingNote}
                        onChange={(e) => handleUpdateEntry(idx, 'directingNote', e.target.value)}
                    />
                  </td>

                  {/* 操作按鈕 */}
                  <td className="px-1 py-3 align-top">
                    <div className="flex flex-col gap-1.5 items-center opacity-0 group-hover:opacity-100 transition-opacity">
                      <button 
                        onClick={() => handleAddEntry(idx)}
                        className="p-1 bg-amber-600/10 hover:bg-amber-600 text-amber-500 hover:text-white rounded transition-all"
                        title="插入下個鏡頭"
                      >
                        <Plus className="w-3 h-3" />
                      </button>
                      <button 
                        onClick={() => handleRemoveEntry(idx)}
                        className="p-1 bg-red-500/10 hover:bg-red-500 text-neutral-600 hover:text-white rounded transition-all"
                        title="移除此鏡頭"
                      >
                        <Trash2 className="w-3 h-3" />
                      </button>
                    </div>
                  </td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>
      </div>

      <div className="flex justify-center pt-4">
        <div className="inline-flex items-center gap-3 px-6 py-3 bg-amber-600/5 rounded-full border border-amber-600/20 shadow-xl group hover:border-amber-600/40 transition-all cursor-default">
          <Clapperboard className="w-5 h-5 text-amber-600 group-hover:scale-110 transition-transform" />
          <p className="text-[10px] font-bold text-neutral-400 uppercase tracking-[0.2em]">分鏡技術規劃完成 • 定稿準備生成</p>
        </div>
      </div>
    </div>
  );
};

