  async generateStoryArchitecture(dna: ProjectDNA): Promise<StoryArchitecture> {
    const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
    const prompt = `你是一位資深編劇。請根據拍攝 DNA，構想並鋪陳具備蒙太奇節奏的敘事結構。

    【任務細節】
    1. 確立結構點：激勵事件 (Inciting Incident)、中點轉折 (Midpoint)、全片高潮 (Climax)、最終結局 (Resolution)。
    2. 章節劃分：將故事分為 3-5 個章節。
    3. 每章設計：
       - 章節標題 (title)。
       - 情緒基調 (emotionalTone)：如「壓抑與疏離」、「爆發性衝突」、「哀傷的釋放」。
       - 摘要內容 (summary)。
       - 場景變換 (scenes)：描述 2-4 個場景的視覺變遷。

    劇本摘要：${dna.story}
    核心敘事：${dna.coreNarrative}
    視覺風格：${dna.style}

    請回傳 JSON。`;

    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: [{ role: 'user', parts: [{ text: prompt }] }],
      config: {
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.OBJECT,
          properties: {
            incitingIncident: { type: Type.STRING },
            midpoint: { type: Type.STRING },
