  async generateCoreStyleVisual(dna: ProjectDNA): Promise<string | null> {
    const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
    const prompt = `
      A professional cinematic mood board / style guide collage for the project: "${dna.coreNarrative}".
      Format: ${dna.format}. Style: ${dna.style}.
      STRICT LAYOUT REQUIREMENT: ONE single image that is a composite showing 4-5 distinct cinematic perspectives:
      1. An Epic Wide Shot establishing the ${dna.environment}.
      2. A dramatic medium shot showcasing lighting and texture.
      3. Close-up of symbolic prop.
      Unified color grading, 8k, cinematic.
    `;
    try {
      const response = await ai.models.generateContent({
        model: 'gemini-3-pro-image-preview',
        contents: { parts: [{ text: prompt }] },
        config: { imageConfig: { aspectRatio: dna.ratio === '9:16' ? "9:16" : "16:9", imageSize: "1K" } }
      });
      for (const part of response.candidates?.[0]?.content?.parts || []) {
        if (part.inlineData) return `data:image/png;base64,${part.inlineData.data}`;
      }
      return null;
    } catch (error) { return null; }
  }

  async generateStageGrid(dna: ProjectDNA, stage: StageDesign): Promise<string> {
    const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
