import React, { useEffect } from 'react';
import { Loader2, Clapperboard, Plus, Trash2 } from 'lucide-react';
import { ProjectState, Storyboard, StoryboardEntry } from '../types';

interface StoryboardPhaseProps {
  project: ProjectState;
  isLoading: boolean;
  onUpdateStoryboard: (sb: Storyboard) => void;
  guideText: string;
}

export const StoryboardPhase: React.FC<StoryboardPhaseProps> = ({
  project, isLoading, onUpdateStoryboard, guideText
}) => {
  const sb = project.storyboard;

  // 智慧剖析：如果 AI 傳回的字串是範圍 (例如 "00:00 - 00:05")，自動拆分
  useEffect(() => {
    if (sb && sb.entries.length > 0) {
      let needsFix = false;
      const fixedEntries = sb.entries.map(entry => {
        let { startTime, endTime } = entry;

        // 剖析 startTime 是否包含範圍
        if (startTime && startTime.includes('-')) {
          const parts = startTime.split('-').map(p => p.trim());
          startTime = parts[0];
          endTime = parts[1] || endTime;
          needsFix = true;
        }

        // 剖析 endTime 是否包含範圍 (有時 AI 會重複填寫在兩欄)
        if (endTime && endTime.includes('-')) {
          const parts = endTime.split('-').map(p => p.trim());
          endTime = parts[1] || parts[0];
          needsFix = true;
        }

        return { ...entry, startTime, endTime };
      });

      if (needsFix) {
        onUpdateStoryboard({ entries: fixedEntries });
      }
    }
  }, [sb?.entries.length]); // 僅在長度改變時（剛生成完）進行一次校準

  if (isLoading && !sb) {
    return (
      <div className="py-20 flex flex-col items-center gap-6 animate-pulse">
        <Loader2 className="w-12 h-12 text-amber-600 animate-spin" />
        <p className="text-amber-500 text-xs font-bold uppercase tracking-[0.3em]">AI 正在編寫技術分鏡腳本...</p>
      </div>
    );
  }

  if (!sb) return null;

  const addSeconds = (timeStr: string, secondsToAdd: number) => {
    const parts = (timeStr || "00:00").split(':');
    let m = 0, s = 0;
    if (parts.length === 3) {
      m = parseInt(parts[1]) || 0;
      s = parseInt(parts[2]) || 0;
    } else {
      m = parseInt(parts[0]) || 0;
      s = parseInt(parts[1]) || 0;
    }

    let totalSeconds = m * 60 + s + secondsToAdd;
    if (totalSeconds < 0) totalSeconds = 0;
    const nextM = Math.floor(totalSeconds / 60);
    const nextS = totalSeconds % 60;
    return `${String(nextM).padStart(2, '0')}:${String(nextS).padStart(2, '0')}`;
  };

  const handleUpdateEntry = (idx: number, field: keyof StoryboardEntry, val: string) => {
    const newEntries = [...sb.entries];
    newEntries[idx] = { ...newEntries[idx], [field]: val };

    if (field === 'endTime') {
      if (idx < newEntries.length - 1) {
        newEntries[idx + 1] = { ...newEntries[idx + 1], startTime: addSeconds(val, 1) };
      }
    } else if (field === 'startTime') {
      if (idx > 0) {
        newEntries[idx - 1] = { ...newEntries[idx - 1], endTime: addSeconds(val, -1) };
      }
    }

    onUpdateStoryboard({ entries: newEntries });
  };

  const handleAddEntry = (idx: number) => {
    const newEntries = [...sb.entries];
    const currentEntry = newEntries[idx];
    const startTime = addSeconds(currentEntry.endTime || "00:00", 1);
    const endTime = addSeconds(startTime, 5);

    const newEntry: StoryboardEntry = {
      startTime,
      endTime,
      shotType: "MCU",
      movement: "STATIC",
      action: "新場景視覺動態...",
      audio: "環境音效..."
    };

    newEntries.splice(idx + 1, 0, newEntry);
    onUpdateStoryboard({ entries: newEntries });
  };

  const handleRemoveEntry = (idx: number) => {
    if (sb.entries.length <= 1) return;
    const newEntries = [...sb.entries];
    newEntries.splice(idx, 1);
    onUpdateStoryboard({ entries: newEntries });
  };

  const formatDisplayTime = (time: string) => {
    if (!time) return "00:00";
    const parts = time.split(':');
    if (parts.length === 3) return `${parts[1]}:${parts[2]}`;
    return time;
  };

  return (
    <div className="w-full space-y-4 pb-20 animate-in fade-in duration-1000">
      <div className="text-center space-y-1">
        <h2 className="text-2xl font-serif text-neutral-100">{guideText}</h2>
        <p className="text-[9px] text-neutral-500 uppercase tracking-widest">規則：次鏡頭起始時間為前鏡頭結束時間 + 1s</p>
      </div>

      <div className="border border-white/10 shadow-2xl bg-black/40 relative overflow-hidden flex flex-col h-[600px]">
        {/* 表格標題 */}
        <div className="w-full bg-white/5 border-b border-white/10 flex h-8 items-center shrink-0">
          <div className="w-[10%] px-2 text-[9px] font-bold text-neutral-500 uppercase tracking-widest">Time (mm:ss)</div>
          <div className="w-[12%] px-2 text-[9px] font-bold text-neutral-500 uppercase tracking-widest">Shot</div>
          <div className="w-[12%] px-2 text-[9px] font-bold text-neutral-500 uppercase tracking-widest">Motion</div>
          <div className="w-[41%] px-3 text-[9px] font-bold text-neutral-500 uppercase tracking-widest">Visual Action</div>
          <div className="w-[20%] px-3 text-[9px] font-bold text-neutral-500 uppercase tracking-widest">Audio</div>
          <div className="w-[5%] px-1 text-[9px] font-bold text-neutral-500 uppercase tracking-widest text-center">Ops</div>
        </div>

        {/* 捲動內容區塊 */}
        <div className="flex-1 overflow-y-auto overflow-x-hidden divide-y divide-white/5">
          {sb.entries.map((entry, idx) => (
            <div key={idx} className="flex hover:bg-amber-600/5 transition-colors group border-b border-white/5 last:border-b-0 min-h-[64px]">
              {/* 時間欄位：移除間隙緊密堆疊 */}
              <div className="w-[10%] px-1.5 py-2 flex flex-col border-r border-white/5 justify-center">
                <div className="bg-black/60 border border-white/10 border-b-0">
                  <input
                    className="bg-transparent border-none text-[10px] font-mono font-bold text-amber-600 w-full p-1 focus:ring-0 text-center leading-none"
                    value={formatDisplayTime(entry.startTime)}
                    readOnly={idx === 0}
                    onChange={(e) => handleUpdateEntry(idx, 'startTime', e.target.value)}
                  />
                </div>
                <div className="bg-black/60 border border-white/10">
                  <input
                    className="bg-transparent border-none text-[10px] font-mono font-bold text-amber-500 w-full p-1 focus:ring-0 text-center leading-none"
                    value={formatDisplayTime(entry.endTime)}
                    onChange={(e) => handleUpdateEntry(idx, 'endTime', e.target.value)}
                  />
                </div>
              </div>

              {/* 鏡頭 */}
              <div className="w-[12%] px-2 py-2 border-r border-white/5">
                <textarea
                  className="w-full bg-transparent border-none text-[10px] font-bold text-blue-400 uppercase leading-snug resize-none p-0 focus:ring-0"
                  rows={2}
                  value={entry.shotType}
                  onChange={(e) => handleUpdateEntry(idx, 'shotType', e.target.value)}
                />
              </div>

              {/* 運鏡 */}
              <div className="w-[12%] px-2 py-2 border-r border-white/5">
                <textarea
                  className="w-full bg-transparent border-none text-[10px] font-bold text-purple-400 uppercase leading-snug resize-none p-0 focus:ring-0"
                  rows={2}
                  value={entry.movement}
                  onChange={(e) => handleUpdateEntry(idx, 'movement', e.target.value)}
                />
              </div>

              {/* 畫面動作 */}
              <div className="w-[41%] px-3 py-2 border-r border-white/5">
                <textarea
                  className="w-full bg-transparent border-none text-[10px] text-neutral-200 leading-normal resize-none p-0 focus:ring-0"
                  rows={2}
                  value={entry.action}
                  onChange={(e) => handleUpdateEntry(idx, 'action', e.target.value)}
                />
              </div>

              {/* 音效 */}
              <div className="w-[20%] px-3 py-2 border-r border-white/5">
                <textarea
                  className="w-full bg-transparent border-none text-[9px] text-neutral-400 italic leading-normal resize-none p-0 focus:ring-0"
                  rows={2}
                  value={entry.audio}
                  onChange={(e) => handleUpdateEntry(idx, 'audio', e.target.value)}
                />
              </div>

              {/* 操作 */}
              <div className="w-[5%] px-1 py-2 flex flex-col gap-1 items-center justify-center opacity-0 group-hover:opacity-100 transition-opacity">
                <button onClick={() => handleAddEntry(idx)} className="p-1 bg-amber-600/10 hover:bg-amber-600 text-amber-500 hover:text-white transition-all">
                  <Plus className="w-2.5 h-2.5" />
                </button>
                <button onClick={() => handleRemoveEntry(idx)} className="p-1 bg-red-500/10 hover:bg-red-500 text-neutral-600 hover:text-white transition-all">
                  <Trash2 className="w-2.5 h-2.5" />
                </button>
              </div>
            </div>
          ))}
        </div>
      </div>

      <div className="flex justify-center pt-2">
        <div className="inline-flex items-center gap-3 px-6 py-2.5 bg-amber-600/5 rounded-full border border-amber-600/20 shadow-xl group hover:border-amber-600/40 transition-all cursor-default">
          <Clapperboard className="w-4 h-4 text-amber-600 group-hover:scale-110 transition-transform" />
          <p className="text-[9px] font-bold text-neutral-400 uppercase tracking-[0.2em]">分鏡規劃完成 • 定稿準備生成</p>
        </div>
      </div>
    </div>
  );
};

import React, { useState, useEffect, useRef } from 'react';
import { ProductionPhase, Suggestion, ProjectState, ProjectDNA, StageDesign, CharacterDesign, StoryArchitecture, Storyboard } from './types';
import { PHASE_METADATA } from './constants';
import { GeminiService } from './services/geminiService';
import { ApiKeySelector } from './components/ApiKeySelector';
import { InspirationPhase } from './components/InspirationPhase';
import { ProductionPlanPhase } from './components/ProductionPlanPhase';
import { VisualDevPhase } from './components/VisualDevPhase';
import { CharacterDevPhase } from './components/CharacterDevPhase';
import { StoryArchPhase } from './components/StoryArchPhase';
import { StoryboardPhase } from './components/StoryboardPhase';
import { 
  Film, Loader2, ArrowRight, 
  ChevronRight, Download, Upload,
  X, CheckCircle2, Terminal, MapPin, Users, Target,
  Grid, Image as ImageIcon, Maximize2, DownloadCloud, UserPlus,
  BookOpen, Layout, Zap
} from 'lucide-react';

const App: React.FC = () => {
  const [hasKey, setHasKey] = useState(false);
  const [isLoading, setIsLoading] = useState(false);
  const [isAnalyzing, setIsAnalyzing] = useState(false);
  const [isElaborating, setIsElaborating] = useState(false);
  const [input, setInput] = useState('');
  const [activeStep, setActiveStep] = useState<ProductionPhase>(ProductionPhase.INSPIRATION);
  const [expandedImage, setExpandedImage] = useState<string | null>(null);

  const [suggestions, setSuggestions] = useState<Suggestion[]>([]);

  const [project, setProject] = useState<ProjectState>({
    currentPhase: ProductionPhase.INSPIRATION,
    initialInput: '',
    dna: { format: '電影', style: '寫實電影感', story: '', ratio: '16:9', environment: '', socialBackground: '', coreNarrative: '', directorVision: '' },
    proposedStages: [], 
    proposedCharacters: [], 
    coreStageImage: undefined 
  });

  const [tempDNA, setTempDNA] = useState<ProjectDNA>(project.dna);
  const fileInputRef = useRef<HTMLInputElement>(null);
  const geminiRef = useRef<GeminiService | null>(null);

  const handleApiError = (err: any) => {
    console.error(err);
    if (err && typeof err === 'object' && 'message' in err && typeof err.message === 'string' && err.message.includes("Requested entity was not found.")) {
      setHasKey(false);
      geminiRef.current = null;
    }
  };

  useEffect(() => {
    const checkKey = async () => {
      // @ts-ignore
      const exists = await window.aistudio.hasSelectedApiKey();
      if (exists) {
        setHasKey(true);
        geminiRef.current = new GeminiService(process.env.API_KEY || '');
      }
    };
    checkKey();
  }, []);

  useEffect(() => {
    if (activeStep === ProductionPhase.INSPIRATION && project.initialInput) {
      setInput(project.initialInput);
    }
  }, [project.initialInput, activeStep]);

  useEffect(() => {
    if (activeStep === ProductionPhase.VISUAL_DEV && project.proposedStages.length === 0 && !isAnalyzing && geminiRef.current) {
      handleIdentifyStages();
    }
    if (activeStep === ProductionPhase.CHARACTER_DEV && project.proposedCharacters.length === 0 && !isAnalyzing && geminiRef.current) {
      handleAutoAnalyzeCharacters();
    }
    if (activeStep === ProductionPhase.STORY_ARCH && !project.storyArchitecture && !isLoading && geminiRef.current) {
      handleAutoGenerateStoryArch();
    }
    if (activeStep === ProductionPhase.STORYBOARD && !project.storyboard && !isLoading && geminiRef.current) {
      handleAutoGenerateStoryboard();
    }
  }, [activeStep, project.proposedStages.length, project.proposedCharacters.length, project.storyArchitecture, project.storyboard]);

  const handleIdentifyStages = async () => {
    if (!geminiRef.current || isAnalyzing) return;
    setIsAnalyzing(true);
    try {
      const stages = await geminiRef.current.identifyCoreStages(project.dna);
      setProject(prev => ({ ...prev, proposedStages: stages }));
    } catch (err) { handleApiError(err); } finally { setIsAnalyzing(false); }
  };

  const handleAutoAnalyzeCharacters = async () => {
    if (!geminiRef.current || isAnalyzing) return;
    setIsAnalyzing(true);
    try {
      const chars = await geminiRef.current.analyzeCharacters(project.dna);
      setProject(prev => ({ ...prev, proposedCharacters: chars }));
    } catch (err) { handleApiError(err); } finally { setIsAnalyzing(false); }
  };

  const handleAutoGenerateStoryArch = async () => {
    if (!geminiRef.current || isLoading) return;
    setIsLoading(true);
    try {
      const arch = await geminiRef.current.generateStoryArchitecture(project.dna);
      setProject(prev => ({ ...prev, storyArchitecture: arch }));
    } catch (err) { handleApiError(err); } finally { setIsLoading(false); }
  };

  const handleAutoGenerateStoryboard = async () => {
    if (!geminiRef.current || isLoading || !project.storyArchitecture) return;
    setIsLoading(true);
    try {
      const sb = await geminiRef.current.generateStoryboard(project.dna, project.storyArchitecture);
      setProject(prev => ({ ...prev, storyboard: sb }));
    } catch (err) { handleApiError(err); } finally { setIsLoading(false); }
  };

  const updateDNAField = (field: keyof ProjectDNA, value: string) => {
    const updatedDNA = { ...project.dna, [field]: value };
    setProject(prev => ({ ...prev, dna: updatedDNA }));
    setTempDNA(updatedDNA);
  };

  const handleSubmitIdea = async (e?: React.FormEvent) => {
    if (e) e.preventDefault();
    if (!input.trim() || isLoading || !geminiRef.current) return;
    setIsLoading(true);
    try {
      const results = await geminiRef.current.generateSuggestions(input, activeStep, JSON.stringify(project.dna));
      setSuggestions(results || []);
      setProject(prev => ({ 
        ...prev, 
        initialInput: activeStep === ProductionPhase.INSPIRATION ? input : prev.initialInput
      }));
    } catch (err) { handleApiError(err); } finally { setIsLoading(false); }
  };

  const handleSuggestionClick = async (s: Suggestion) => {
    if (!geminiRef.current) return;
    setIsElaborating(true);
    try {
      const detailedDNA = await geminiRef.current.elaboratePlan(s, project.dna);
      setTempDNA(detailedDNA);
      setSuggestions([]);
      setProject(prev => ({
        ...prev, 
        dna: detailedDNA, 
        currentPhase: ProductionPhase.PRODUCTION_PLAN
      }));
      setActiveStep(ProductionPhase.PRODUCTION_PLAN);
    } catch (err) { handleApiError(err); } finally { setIsElaborating(false); }
  };

  const handleRenderCoreStageOnly = async () => {
    if (!geminiRef.current) return;
    setIsLoading(true);
    try {
      const coreImage = await geminiRef.current.generateCoreStyleVisual(tempDNA) || undefined;
      setProject(prev => ({ ...prev, coreStageImage: coreImage }));
    } catch (err) { handleApiError(err); } finally { setIsLoading(false); }
  };

  const confirmProductionPlan = async () => {
    if (!geminiRef.current) return;
    setIsLoading(true);
    try {
      let coreImage = project.coreStageImage;
      if (!coreImage) {
        coreImage = await geminiRef.current.generateCoreStyleVisual(tempDNA) || undefined;
      }
      setProject(prev => ({
        ...prev, 
        currentPhase: ProductionPhase.VISUAL_DEV, 
        dna: { ...tempDNA }, 
        coreStageImage: coreImage,
        proposedStages: [], 
        proposedCharacters: []
      }));
      setActiveStep(ProductionPhase.VISUAL_DEV);
    } finally { setIsLoading(false); }
  };

  const handleProceedToCharacterDev = () => {
    setProject(prev => ({ 
      ...prev, 
      currentPhase: ProductionPhase.CHARACTER_DEV,
      proposedCharacters: [] // 重設資料以觸發重新生成
    }));
    setActiveStep(ProductionPhase.CHARACTER_DEV);
  };

  const handleProceedToStoryArch = () => {
    setProject(prev => ({ 
      ...prev, 
      currentPhase: ProductionPhase.STORY_ARCH,
      storyArchitecture: undefined // 重設資料以觸發重新生成
    }));
    setActiveStep(ProductionPhase.STORY_ARCH);
  };

  const handleProceedToStoryboard = () => {
    setProject(prev => ({ 
      ...prev, 
      currentPhase: ProductionPhase.STORYBOARD,
      storyboard: undefined // 重設資料以觸發重新生成
    }));
    setActiveStep(ProductionPhase.STORYBOARD);
  };

  const handleProceedToVideoPrompting = () => {
    setProject(prev => ({ ...prev, currentPhase: ProductionPhase.VIDEO_PROMPTING }));
    setActiveStep(ProductionPhase.VIDEO_PROMPTING);
  };

  const saveProject = () => {
    const stateToSave: ProjectState = { 
      ...project, 
      initialInput: input 
    };
    const data = JSON.stringify(stateToSave, null, 2);
    const blob = new Blob([data], { type: 'application/json' });
    const url = URL.createObjectURL(blob);
    const link = document.createElement('a');
    link.href = url;
    link.download = `montage-project-${new Date().toISOString().slice(0, 10)}.json`;
    link.click();
  };

  const loadProject = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;
    const reader = new FileReader();
    reader.onload = (event) => {
      try {
        const data = JSON.parse(event.target?.result as string) as ProjectState;
        if (data.currentPhase && data.dna) {
          setProject(data);
          setActiveStep(data.currentPhase);
          setTempDNA(data.dna);
          if (data.initialInput) setInput(data.initialInput);
        }
      } catch (err) { alert('檔案格式錯誤。'); }
    };
    reader.readAsText(file);
    if (fileInputRef.current) fileInputRef.current.value = '';
  };

  const handleRenderStageGrid = async (idx: number) => {
    if (!geminiRef.current) return;
    setIsLoading(true);
    setProject(prev => ({ ...prev, selectedStageIndex: idx }));
    try {
      const gridResult = await geminiRef.current.generateStageGrid(project.dna, project.proposedStages[idx]);
      if (gridResult) {
        setProject(prev => {
          const newStages = [...prev.proposedStages];
          newStages[idx] = { ...newStages[idx], gridImage: gridResult };
          return { ...prev, proposedStages: newStages };
        });
      }
    } catch (err) { handleApiError(err); } finally { setIsLoading(false); }
  };

  const handleRenderCharacterGrid = async (idx: number) => {
    if (!geminiRef.current) return;
    setIsLoading(true);
    setProject(prev => ({ ...prev, selectedCharacterIndex: idx }));
    try {
      const gridResult = await geminiRef.current.generateCharacterGrid(project.dna, project.proposedCharacters[idx]);
      if (gridResult) {
        setProject(prev => {
          const newChars = [...prev.proposedCharacters];
          newChars[idx] = { ...newChars[idx], gridImage: gridResult };
          return { ...prev, proposedCharacters: newChars };
        });
      }
    } catch (err) { handleApiError(err); } finally { setIsLoading(false); }
  };

  const updateStage = (idx: number, field: keyof StageDesign, value: string) => {
    setProject(prev => {
      const newStages = [...prev.proposedStages];
      newStages[idx] = { ...newStages[idx], [field]: value };
      return { ...prev, proposedStages: newStages };
    });
  };

  const updateCharacter = (idx: number, field: keyof CharacterDesign, value: string) => {
    setProject(prev => {
      const newChars = [...prev.proposedCharacters];
      newChars[idx] = { ...newChars[idx], [field]: value };
      return { ...prev, proposedCharacters: newChars };
    });
  };

  const updateStoryArch = (arch: StoryArchitecture) => {
    setProject(prev => ({ ...prev, storyArchitecture: arch }));
  };

  const updateStoryboard = (sb: Storyboard) => {
    setProject(prev => ({ ...prev, storyboard: sb }));
  };

  const handlePolishCharacter = async (idx: number, field: keyof CharacterDesign, label: string) => {
    if (!geminiRef.current || isLoading) return;
    setIsLoading(true);
    try {
      const char = project.proposedCharacters[idx];
      const polished = await geminiRef.current.polishText(char[field] as string, `角色塑造之${label}`);
      updateCharacter(idx, field, polished);
    } catch (err) { handleApiError(err); } finally { setIsLoading(false); }
  };

  const downloadImage = (base64: string, name: string) => {
    const link = document.createElement('a');
    link.href = base64;
    link.download = `${name}.png`;
    link.click();
  };

  const getPhaseIndex = (phase: ProductionPhase) => {
    return Object.values(ProductionPhase).indexOf(phase);
  };

  const allCharactersReady = project.proposedCharacters.length > 0 && 
                             project.proposedCharacters.every(c => c.gridImage);

  if (!hasKey) return <ApiKeySelector onSelected={() => {
    setHasKey(true);
    if (!geminiRef.current) {
      geminiRef.current = new GeminiService(process.env.API_KEY || '');
    }
  }} />;

  return (
    <div className="flex h-screen bg-[#050505] text-white overflow-hidden font-sans">
      {expandedImage && (
        <div className="fixed inset-0 bg-black/95 z-[100] flex flex-col items-center justify-center p-8 animate-in fade-in duration-300" onClick={() => setExpandedImage(null)}>
          <button className="absolute top-8 right-8 p-3 bg-white/5 hover:bg-amber-600 rounded-full transition-all group">
            <X className="w-8 h-8 text-white group-hover:scale-110" />
          </button>
          <div className="relative max-w-7xl w-full max-h-full" onClick={e => e.stopPropagation()}>
            <img src={expandedImage} className="w-full h-full object-contain shadow-2xl rounded-lg border border-white/10" />
            <button onClick={() => downloadImage(expandedImage, 'montage-asset')} className="absolute bottom-4 right-4 flex items-center gap-2 bg-amber-600 hover:bg-amber-500 px-6 py-3 rounded-full font-bold shadow-xl transition-all">
              <DownloadCloud className="w-5 h-5" /> 下載原始圖片
            </button>
          </div>
        </div>
      )}

      <aside className="w-64 border-r border-white/5 flex flex-col bg-black/40 p-6">
        <div className="flex items-center gap-3 mb-12">
          <div className="bg-amber-600 p-2 rounded-lg shadow-[0_0_15px_rgba(217,119,6,0.3)]"><Film className="w-6 h-6 text-white" /></div>
          <h1 className="text-lg font-serif font-bold tracking-widest text-white/90 uppercase">Montage AI</h1>
        </div>
        <nav className="flex-1 space-y-2">
          {Object.entries(PHASE_METADATA).map(([key, meta], idx) => {
            const phaseKey = key as ProductionPhase;
            const isActive = activeStep === phaseKey;
            const isAccessible = getPhaseIndex(phaseKey) <= getPhaseIndex(project.currentPhase);
            return (
              <button 
                key={key} 
                disabled={!isAccessible} 
                onClick={() => setActiveStep(phaseKey)} 
                className={`w-full relative flex items-center gap-4 p-3 rounded-lg transition-all text-left group ${isActive ? 'bg-amber-600/20 text-amber-500 ring-1 ring-amber-600/30' : 'text-neutral-600 hover:text-neutral-400'} ${!isAccessible ? 'opacity-30 grayscale cursor-not-allowed' : 'cursor-pointer'}`}
              >
                {isActive && <div className="absolute left-0 w-1 h-6 bg-amber-600 rounded-full" />}
                <span className="text-xl">{meta.icon}</span>
                <div className="flex flex-col">
                  <span className="text-[9px] uppercase tracking-tighter opacity-50">Step 0{idx+1}</span>
                  <span className="text-sm font-bold">{meta.title}</span>
                </div>
              </button>
            );
          })}
        </nav>
        <div className="mt-8 space-y-2 border-t border-white/5 pt-6">
          <button onClick={saveProject} className="w-full flex items-center gap-3 px-3 py-2 text-xs text-neutral-400 hover:text-white transition-colors group"><Download className="w-4 h-4 text-amber-600" /> <span>匯出專案</span></button>
          <button onClick={() => fileInputRef.current?.click()} className="w-full flex items-center gap-3 px-3 py-2 text-xs text-neutral-400 hover:text-white transition-colors group"><Upload className="w-4 h-4 text-amber-600" /> <span>匯入專案</span></button>
          <input type="file" ref={fileInputRef} onChange={loadProject} className="hidden" accept=".json" />
        </div>
      </aside>

      <main className="flex-1 flex flex-col relative overflow-hidden">
        <header className="h-16 px-8 border-b border-white/5 flex items-center justify-between z-10 bg-black/50 backdrop-blur-md">
          <div className="flex items-center gap-2"><Terminal className="w-4 h-4 text-amber-600" /><span className="text-[10px] text-neutral-500 uppercase tracking-[0.2em]">TERMINAL</span><ChevronRight className="w-3 h-3 text-neutral-600" /><span className="text-sm font-bold text-amber-500 uppercase">{PHASE_METADATA[activeStep]?.title}</span></div>
          <div className="flex items-center gap-4">
            {activeStep === ProductionPhase.PRODUCTION_PLAN && (
              <button onClick={confirmProductionPlan} disabled={isLoading} className="bg-amber-600 hover:bg-amber-500 px-6 py-2 rounded-full text-[11px] font-bold flex items-center gap-2 shadow-lg transition-all">
                {isLoading ? <Loader2 className="w-3.5 h-3.5 animate-spin" /> : <CheckCircle2 className="w-3.5 h-3.5" />} 確認方案並塑造舞台
              </button>
            )}
            {activeStep === ProductionPhase.VISUAL_DEV && (
              <button onClick={handleProceedToCharacterDev} className="bg-amber-600 hover:bg-amber-500 px-6 py-2 rounded-full text-[11px] font-bold flex items-center gap-2 shadow-lg transition-all">
                <UserPlus className="w-3.5 h-3.5" /> 進行角色塑造
              </button>
            )}
            {activeStep === ProductionPhase.CHARACTER_DEV && (
              <button 
                onClick={handleProceedToStoryArch} 
                disabled={!allCharactersReady}
                className={`px-6 py-2 rounded-full text-[11px] font-bold flex items-center gap-2 shadow-lg transition-all ${allCharactersReady ? 'bg-amber-600 hover:bg-amber-500 text-white' : 'bg-neutral-800 text-neutral-500 cursor-not-allowed opacity-50'}`}
              >
                <BookOpen className="w-3.5 h-3.5" /> 鋪陳敘事結構
              </button>
            )}
            {activeStep === ProductionPhase.STORY_ARCH && (
              <button 
                onClick={handleProceedToStoryboard} 
                className="bg-amber-600 hover:bg-amber-500 px-6 py-2 rounded-full text-[11px] font-bold flex items-center gap-2 shadow-lg transition-all"
              >
                <Layout className="w-3.5 h-3.5" /> 進行分鏡規劃
              </button>
            )}
            {activeStep === ProductionPhase.STORYBOARD && (
              <button 
                onClick={handleProceedToVideoPrompting} 
                className="bg-amber-600 hover:bg-amber-500 px-6 py-2 rounded-full text-[11px] font-bold flex items-center gap-2 shadow-lg transition-all"
              >
                <Zap className="w-3.5 h-3.5" /> 生成 AI 影片提示詞
              </button>
            )}
          </div>
        </header>

        <section className="flex-1 flex flex-col items-center justify-start p-8 max-w-5xl mx-auto w-full overflow-y-auto">
          {activeStep === ProductionPhase.INSPIRATION && (
            <InspirationPhase 
              input={input} 
              setInput={setInput} 
              isLoading={isLoading} 
              isElaborating={isElaborating} 
              suggestions={suggestions} 
              onSubmit={handleSubmitIdea} 
              onSuggestionClick={handleSuggestionClick} 
              guideText={PHASE_METADATA[activeStep]?.guide}
              dna={project.dna}
              onUpdateDNA={updateDNAField}
            />
          )}
          {activeStep === ProductionPhase.PRODUCTION_PLAN && (
            <ProductionPlanPhase dna={tempDNA} setDna={setTempDNA} onRenderCoreVisual={handleRenderCoreStageOnly} isLoading={isLoading} />
          )}
          {activeStep === ProductionPhase.VISUAL_DEV && (
            <VisualDevPhase project={project} isAnalyzing={isAnalyzing} isLoading={isLoading} onUpdateStage={updateStage} onRenderGrid={handleRenderStageGrid} guideText={PHASE_METADATA[activeStep]?.guide} />
          )}
          {activeStep === ProductionPhase.CHARACTER_DEV && (
            <CharacterDevPhase project={project} isAnalyzing={isAnalyzing} isLoading={isLoading} onUpdateCharacter={updateCharacter} onPolishCharacter={handlePolishCharacter} onRenderGrid={handleRenderCharacterGrid} guideText={PHASE_METADATA[activeStep]?.guide} />
          )}
          {activeStep === ProductionPhase.STORY_ARCH && (
            <StoryArchPhase project={project} isLoading={isLoading} onUpdateArch={updateStoryArch} guideText={PHASE_METADATA[activeStep]?.guide} />
          )}
          {activeStep === ProductionPhase.STORYBOARD && (
            <StoryboardPhase project={project} isLoading={isLoading} onUpdateStoryboard={updateStoryboard} guideText={PHASE_METADATA[activeStep]?.guide} />
          )}
        </section>
      </main>

      <aside className="w-80 border-l border-white/5 bg-black/40 p-6 flex flex-col gap-8 overflow-y-auto">
        <h3 className="text-[10px] font-bold text-neutral-500 uppercase tracking-widest border-b border-white/5 pb-2">視覺檔案 (Asset)</h3>

        <div className="space-y-4">
          <span className="text-[10px] text-amber-500/70 font-mono uppercase tracking-widest block">CORE_STAGE_VISUAL</span>
          {project.coreStageImage ? (
            <div className="aspect-video rounded-2xl overflow-hidden border border-white/10 shadow-lg cursor-zoom-in" onClick={() => setExpandedImage(project.coreStageImage!)}>
              <img src={project.coreStageImage} className="w-full h-full object-cover" alt="Core Stage Visual" />
            </div>
          ) : (
            <div className="py-12 border border-dashed border-white/10 rounded-2xl text-center opacity-30">
              <ImageIcon className="w-6 h-6 mx-auto mb-2 text-neutral-700" />
              <p className="text-[8px] uppercase tracking-widest">等待核心舞台視覺</p>
            </div>
          )}
        </div>

        {project.proposedStages.some(s => s.gridImage) && (
          <div className="space-y-6 pt-6 border-t border-white/5">
            <span className="text-[10px] text-amber-500/70 font-mono uppercase tracking-widest block">STAGE_GRIDS</span>
