import React, { useEffect } from 'react';
import { Loader2, Clapperboard, Plus, Trash2 } from 'lucide-react';
import { ProjectState, Storyboard, StoryboardEntry } from '../types';

interface StoryboardPhaseProps {
  project: ProjectState;
  isLoading: boolean;
  onUpdateStoryboard: (sb: Storyboard) => void;
  guideText: string;
}

export const StoryboardPhase: React.FC<StoryboardPhaseProps> = ({
  project, isLoading, onUpdateStoryboard, guideText
}) => {
  const sb = project.storyboard;

  // 智慧剖析：如果 AI 傳回的字串是範圍 (例如 "00:00 - 00:05")，自動拆分
  useEffect(() => {
    if (sb && sb.entries.length > 0) {
      let needsFix = false;
      const fixedEntries = sb.entries.map(entry => {
        let { startTime, endTime } = entry;

        // 剖析 startTime 是否包含範圍
        if (startTime && startTime.includes('-')) {
          const parts = startTime.split('-').map(p => p.trim());
          startTime = parts[0];
          endTime = parts[1] || endTime;
          needsFix = true;
        }

        // 剖析 endTime 是否包含範圍
        if (endTime && endTime.includes('-')) {
          const parts = endTime.split('-').map(p => p.trim());
          endTime = parts[1] || parts[0];
          needsFix = true;
        }

        return { ...entry, startTime, endTime };
      });

      if (needsFix) {
        onUpdateStoryboard({ entries: fixedEntries });
      }
    }
  }, [sb?.entries.length]); 

  if (isLoading && !sb) {
    return (
      <div className="py-20 flex flex-col items-center gap-6 animate-pulse">
        <Loader2 className="w-12 h-12 text-amber-600 animate-spin" />
        <p className="text-amber-500 text-xs font-bold uppercase tracking-[0.3em]">AI 正在編寫技術分鏡腳本...</p>
      </div>
    );
  }

  if (!sb) return null;

  const addSeconds = (timeStr: string, secondsToAdd: number) => {
    const parts = (timeStr || "00:00").split(':');
    let m = 0, s = 0;
    if (parts.length === 3) {
      m = parseInt(parts[1]) || 0;
      s = parseInt(parts[2]) || 0;
    } else {
      m = parseInt(parts[0]) || 0;
      s = parseInt(parts[1]) || 0;
    }

    let totalSeconds = m * 60 + s + secondsToAdd;
    if (totalSeconds < 0) totalSeconds = 0;
    const nextM = Math.floor(totalSeconds / 60);
    const nextS = totalSeconds % 60;
    return `${String(nextM).padStart(2, '0')}:${String(nextS).padStart(2, '0')}`;
  };

  const handleUpdateEntry = (idx: number, field: keyof StoryboardEntry, val: string) => {
    const newEntries = [...sb.entries];
    newEntries[idx] = { ...newEntries[idx], [field]: val };

    if (field === 'endTime') {
      if (idx < newEntries.length - 1) {
        newEntries[idx + 1] = { ...newEntries[idx + 1], startTime: addSeconds(val, 1) };
      }
    } else if (field === 'startTime') {
      if (idx > 0) {
        newEntries[idx - 1] = { ...newEntries[idx - 1], endTime: addSeconds(val, -1) };
      }
    }

    onUpdateStoryboard({ entries: newEntries });
  };

  const handleAddEntry = (idx: number) => {
    const newEntries = [...sb.entries];
    const currentEntry = newEntries[idx];
    const startTime = addSeconds(currentEntry.endTime || "00:00", 1);
    const endTime = addSeconds(startTime, 5);

    const newEntry: StoryboardEntry = {
      startTime,
      endTime,
      shotType: "MCU",
      movement: "STATIC",
      action: "新場景視覺動態...",
      audio: "環境音效..."
    };

    newEntries.splice(idx + 1, 0, newEntry);
    onUpdateStoryboard({ entries: newEntries });
  };

  const handleRemoveEntry = (idx: number) => {
    if (sb.entries.length <= 1) return;
    const newEntries = [...sb.entries];
    newEntries.splice(idx, 1);
    onUpdateStoryboard({ entries: newEntries });
  };

  const formatDisplayTime = (time: string) => {
    if (!time) return "00:00";
    const parts = time.split(':');
    if (parts.length === 3) return `${parts[1]}:${parts[2]}`;
    return time;
  };

  return (
    <div className="w-full space-y-4 pb-20 animate-in fade-in duration-1000">
      <div className="text-center space-y-1">
        <h2 className="text-2xl font-serif text-neutral-100">{guideText}</h2>
        <p className="text-[9px] text-neutral-500 uppercase tracking-widest">規則：次鏡頭起始時間為前鏡頭結束時間 + 1s</p>
      </div>

      <div className="border border-white/10 shadow-2xl bg-black/40 relative overflow-hidden flex flex-col h-[600px]">
        {/* 表格標題 */}
        <div className="w-full bg-white/5 border-b border-white/10 flex h-8 items-center shrink-0">
          <div className="w-[10%] text-[9px] font-bold text-neutral-500 uppercase tracking-widest text-center border-r border-white/5">Time</div>
          <div className="w-[12%] px-2 text-[9px] font-bold text-neutral-500 uppercase tracking-widest border-r border-white/5">Shot</div>
          <div className="w-[12%] px-2 text-[9px] font-bold text-neutral-500 uppercase tracking-widest border-r border-white/5">Motion</div>
          <div className="w-[41%] px-3 text-[9px] font-bold text-neutral-500 uppercase tracking-widest border-r border-white/5">Visual Action</div>
          <div className="w-[20%] px-3 text-[9px] font-bold text-neutral-500 uppercase tracking-widest border-r border-white/5">Audio</div>
          <div className="w-[5%] px-1 text-[9px] font-bold text-neutral-500 uppercase tracking-widest text-center">Ops</div>
        </div>

        {/* 捲動內容區塊 */}
        <div className="flex-1 overflow-y-auto overflow-x-hidden divide-y divide-white/5">
          {sb.entries.map((entry, idx) => (
            <div key={idx} className="flex hover:bg-amber-600/5 transition-colors group border-b border-white/5 last:border-b-0 min-h-[64px]">

              {/* 時間欄位：徹底移除外圍間距，高度均分 */}
              <div className="w-[10%] flex flex-col border-r border-white/5">
                <div className="h-1/2 flex items-center bg-black/60 border-b border-white/10">
                  <input
                    className="bg-transparent border-none text-[10px] font-mono font-bold text-amber-600 w-full h-full p-0 focus:ring-0 text-center leading-none"
                    value={formatDisplayTime(entry.startTime)}
                    readOnly={idx === 0}
                    onChange={(e) => handleUpdateEntry(idx, 'startTime', e.target.value)}
                  />
                </div>
                <div className="h-1/2 flex items-center bg-black/60">
                  <input
                    className="bg-transparent border-none text-[10px] font-mono font-bold text-amber-500 w-full h-full p-0 focus:ring-0 text-center leading-none"
                    value={formatDisplayTime(entry.endTime)}
                    onChange={(e) => handleUpdateEntry(idx, 'endTime', e.target.value)}
                  />
                </div>
              </div>

              {/* 鏡頭 */}
              <div className="w-[12%] px-2 py-2 border-r border-white/5">
                <textarea
                  className="w-full bg-transparent border-none text-[10px] font-bold text-blue-400 uppercase leading-snug resize-none p-0 focus:ring-0"
                  rows={2}
                  value={entry.shotType}
                  onChange={(e) => handleUpdateEntry(idx, 'shotType', e.target.value)}
                />
              </div>

              {/* 運鏡 */}
              <div className="w-[12%] px-2 py-2 border-r border-white/5">
                <textarea
                  className="w-full bg-transparent border-none text-[10px] font-bold text-purple-400 uppercase leading-snug resize-none p-0 focus:ring-0"
                  rows={2}
                  value={entry.movement}
                  onChange={(e) => handleUpdateEntry(idx, 'movement', e.target.value)}
                />
              </div>

              {/* 畫面動作 */}
              <div className="w-[41%] px-3 py-2 border-r border-white/5">
                <textarea
                  className="w-full bg-transparent border-none text-[10px] text-neutral-200 leading-normal resize-none p-0 focus:ring-0"
                  rows={2}
                  value={entry.action}
                  onChange={(e) => handleUpdateEntry(idx, 'action', e.target.value)}
                />
              </div>

              {/* 音效 */}
              <div className="w-[20%] px-3 py-2 border-r border-white/5">
                <textarea
                  className="w-full bg-transparent border-none text-[9px] text-neutral-400 italic leading-normal resize-none p-0 focus:ring-0"
                  rows={2}
                  value={entry.audio}
                  onChange={(e) => handleUpdateEntry(idx, 'audio', e.target.value)}
                />
              </div>

              {/* 操作 */}
              <div className="w-[5%] px-1 py-2 flex flex-col gap-1 items-center justify-center opacity-0 group-hover:opacity-100 transition-opacity">
                <button onClick={() => handleAddEntry(idx)} className="p-1 bg-amber-600/10 hover:bg-amber-600 text-amber-500 hover:text-white transition-all">
                  <Plus className="w-2.5 h-2.5" />
                </button>
                <button onClick={() => handleRemoveEntry(idx)} className="p-1 bg-red-500/10 hover:bg-red-500 text-neutral-600 hover:text-white transition-all">
                  <Trash2 className="w-2.5 h-2.5" />
                </button>
              </div>
            </div>
          ))}
        </div>
      </div>

      <div className="flex justify-center pt-2">
        <div className="inline-flex items-center gap-3 px-6 py-2.5 bg-amber-600/5 rounded-full border border-amber-600/20 shadow-xl group hover:border-amber-600/40 transition-all cursor-default">
          <Clapperboard className="w-4 h-4 text-amber-600 group-hover:scale-110 transition-transform" />
          <p className="text-[9px] font-bold text-neutral-400 uppercase tracking-[0.2em]">分鏡規劃完成 • 定稿準備生成</p>
        </div>
      </div>
    </div>
  );
};

import { GoogleGenAI, Type } from "@google/genai";
import { SYSTEM_INSTRUCTION } from "../constants";
import { Suggestion, StageDesign, CharacterDesign, ProjectDNA, ProductionPhase, StoryArchitecture, Storyboard } from "../types";

export class GeminiService {
  constructor(apiKey: string) { }

  async generateSuggestions(input: string, phase: ProductionPhase, context: string): Promise<Suggestion[]> {
    const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
    const currentDNA = JSON.parse(context) as ProjectDNA;

    const prompt = `
    目前的製作設定：
    - 形式：${currentDNA.format}
    - 預想視覺風格：${currentDNA.style}
    - 畫面比例：${currentDNA.ratio}

    核心靈感/指令： "${input}"。

    請根據目前的製作階段 [${phase}]，提供三個具體的創意導向（頂尖導演提案）。
    這些提案必須在視覺張力與敘事節奏上符合上述的「製作設定」。

    【關鍵任務】如果是 INSPIRATION 階段，請發揮頂尖導演聯想力，自動推論出初步的：
    1. 地理環境 (environment)
    2. 社會背景 (socialBackground)
    3. 核心敘事 (coreNarrative)

    請回傳 JSON 陣列，包含 title, description, tags, environment, socialBackground, coreNarrative。`;

    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: [{ role: 'user', parts: [{ text: prompt }] }],
      config: {
        systemInstruction: SYSTEM_INSTRUCTION,
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.ARRAY,
          items: {
            type: Type.OBJECT,
            properties: {
              title: { type: Type.STRING },
              description: { type: Type.STRING },
              tags: { type: Type.ARRAY, items: { type: Type.STRING } },
              environment: { type: Type.STRING },
              socialBackground: { type: Type.STRING },
              coreNarrative: { type: Type.STRING }
            },
            required: ["title", "description", "tags"]
          }
        }
      }
    });
    return JSON.parse(response.text || "[]");
  }

  async elaboratePlan(suggestion: Suggestion, baseDNA: ProjectDNA): Promise<ProjectDNA> {
    const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
    const prompt = `
    請將以下提案擴充為完整的電影拍攝 DNA：
    提案標題：${suggestion.title}

    【核心約束】你必須嚴格遵循用戶設定的基底 DNA：
    - 製作形式：${baseDNA.format}
    - 預選視覺風格：${baseDNA.style}
    - 畫面比例：${baseDNA.ratio}

    內容需包含：符合該風格的地理環境、社會背景、核心敘事與一份細緻的劇本摘要。
    此外，請作為 AI 頂尖導演，提出一份「拍攝方案建議方向 (directorVision)」，包含建議的運鏡方式、色彩校正方向、以及聲音設計重點。
    `;

    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: [{ role: 'user', parts: [{ text: prompt }] }],
      config: {
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.OBJECT,
          properties: {
            format: { type: Type.STRING },
            style: { type: Type.STRING },
            story: { type: Type.STRING },
            ratio: { type: Type.STRING },
            environment: { type: Type.STRING },
            socialBackground: { type: Type.STRING },
            coreNarrative: { type: Type.STRING },
            directorVision: { type: Type.STRING }
          },
          required: ["format", "style", "story", "environment", "socialBackground", "coreNarrative", "directorVision"]
        }
      }
    });
    const result = JSON.parse(response.text || "{}");

    return {
      ...result,
      format: baseDNA.format, 
      ratio: baseDNA.ratio,   
      style: result.style || baseDNA.style 
    };
  }

  async identifyCoreStages(dna: ProjectDNA): Promise<StageDesign[]> {
    const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
    const prompt = `你是一位頂尖電影美術指導與空間敘事分析師。請針對提供的劇本內容進行「核心舞台 (Core Stage)」的識別與視覺設計。

【識別與篩選原則】
1. 從「劇本摘要」中找出故事的主要發生地點，並將其歸納為 1-3 個核心舞台。
2. 舞台識別必須以「宏觀角度」審視，請嚴格自我詢問：
   - 該空間是否為角色核心活動/生活的區域？
   - 該空間是否為角色之間產生關鍵互動、衝突或情感轉折的必經之地？
   - 若兩者皆為「否」，請剔除該地點，重新考量其他具備敘事權重的地理集群。

【輸出內容需求】
請回傳 JSON 陣列，每個舞台物件必須包含：
- name: 舞台名稱。
- description: 詳盡描述舞台的外觀視覺要素，必須嚴格包含以下項目：
  1. 場地大小 (Scale)
  2. 位置與方位 (Location & Direction)
  3. 主要物件與關鍵道具 (Key Props)
  4. 光影色調與色彩策略 (Lighting & Palette)
  5. 核心敘事氛圍 (Atmosphere)

劇本摘要：${dna.story}
視覺風格定義：${dna.style} (形式：${dna.format})
環境背景：${dna.environment}`;

    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: [{ role: 'user', parts: [{ text: prompt }] }],
      config: {
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.ARRAY,
          items: {
            type: Type.OBJECT,
            properties: {
              name: { type: Type.STRING },
              description: { type: Type.STRING }
            },
            required: ["name", "description"]
          }
        }
      }
    });
    return JSON.parse(response.text || "[]");
  }

  async analyzeCharacters(dna: ProjectDNA): Promise<CharacterDesign[]> {
    const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
    const prompt = `你是一位頂尖電影選角指導。請從劇本中「提取劇情線索」，塑造具備視覺特徵的角色。

    劇本摘要：${dna.story}
    視覺風格：${dna.style}

    【塑造任務】
    - 識別核心角色姓名與角色 (role)。
    - 設計獨特的外貌特徵 (physicalTraits)。
    - 定義外觀材質色調 (visualTone)，反映其性格或處境。
    - 挖掘內在動機 (motivation)。

    請回傳 JSON 陣列。`;

    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: [{ role: 'user', parts: [{ text: prompt }] }],
      config: {
        systemInstruction: SYSTEM_INSTRUCTION,
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.ARRAY,
          items: {
            type: Type.OBJECT,
            properties: {
              name: { type: Type.STRING },
              role: { type: Type.STRING },
              physicalTraits: { type: Type.STRING },
              visualTone: { type: Type.STRING },
              motivation: { type: Type.STRING }
            },
            required: ["name", "role", "physicalTraits", "visualTone", "motivation"]
          }
        }
      }
    });
    return JSON.parse(response.text || "[]");
  }

  async generateStoryArchitecture(dna: ProjectDNA): Promise<StoryArchitecture> {
    const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
    const prompt = `你是一位資深編劇。請根據拍攝 DNA，構想並鋪陳具備蒙太奇節奏的敘事結構。

    【任務細節】
    1. 確立結構點：激勵事件 (Inciting Incident)、中點轉折 (Midpoint)、全片高潮 (Climax)、最終結局 (Resolution)。
    2. 章節劃分：將故事分為 3-5 個章節。
    3. 每章設計：
       - 章節標題 (title)。
       - 情緒基調 (emotionalTone)：如「壓抑與疏離」、「爆發性衝突」、「哀傷的釋放」。
       - 摘要內容 (summary)。
       - 場景變換 (scenes)：描述 2-4 個場景的視覺變遷。

    劇本摘要：${dna.story}
    核心敘事：${dna.coreNarrative}
    視覺風格：${dna.style}

    請回傳 JSON。`;

    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: [{ role: 'user', parts: [{ text: prompt }] }],
      config: {
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.OBJECT,
          properties: {
            incitingIncident: { type: Type.STRING },
            midpoint: { type: Type.STRING },
            climax: { type: Type.STRING },
            resolution: { type: Type.STRING },
            chapters: {
              type: Type.ARRAY,
              items: {
                type: Type.OBJECT,
                properties: {
                  title: { type: Type.STRING },
                  emotionalTone: { type: Type.STRING },
                  summary: { type: Type.STRING },
                  scenes: { type: Type.ARRAY, items: { type: Type.STRING } }
                },
                required: ["title", "emotionalTone", "summary", "scenes"]
              }
            }
          },
          required: ["incitingIncident", "midpoint", "climax", "resolution", "chapters"]
        }
      }
    });
    return JSON.parse(response.text || "{}");
  }

  async generateStoryboard(dna: ProjectDNA, arch: StoryArchitecture): Promise<Storyboard> {
    const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
    const prompt = `你是一位資深電影導演與攝影指導 (DP)。請將提供的「敘事結構與場景序列」轉化為精確的「技術分鏡腳本 (Technical Storyboard)」。

    【腳本撰寫要求】
    1. 密度：將每個章節內的場景序列細化為 2-4 個具體鏡頭。
    2. 時間規則：請嚴格分開填寫 startTime 與 endTime 兩個欄位。格式必須為 mm:ss。
       - 首鏡頭 startTime 必須為 00:00。
       - 下一個鏡頭的 startTime 為上一個鏡頭 endTime 加 1 秒。
    3. 鏡頭語言 (shotType)：使用專業術語。
    4. 運鏡 (movement)：描述攝影機運動。
    5. 動作 (action)：視覺動態與角色行為。**請務必使用「繁體中文」填寫。**
    6. 音效 (audio)：環境聲、SFX 或 BGM。**請務必使用「繁體中文」填寫。**

    專案 DNA：${JSON.stringify(dna)}
    敘事結構：${JSON.stringify(arch)}

    請回傳 JSON 格式的 entries 陣列。`;

    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: [{ role: 'user', parts: [{ text: prompt }] }],
      config: {
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.OBJECT,
          properties: {
            entries: {
              type: Type.ARRAY,
              items: {
                type: Type.OBJECT,
                properties: {
                  startTime: { type: Type.STRING },
                  endTime: { type: Type.STRING },
                  shotType: { type: Type.STRING },
                  movement: { type: Type.STRING },
                  action: { type: Type.STRING },
                  audio: { type: Type.STRING }
                },
                required: ["startTime", "endTime", "shotType", "movement", "action", "audio"]
              }
            }
          },
          required: ["entries"]
        }
      }
    });
    return JSON.parse(response.text || "{ entries: [] }");
  }

  async polishText(text: string, type: string): Promise<string> {
    const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: `你是專業電影視覺指導。請進行場景化潤色，強調視覺細節與專業術語。類型：${type}。內容：${text}`,
    });
    return response.text || text;
  }

  async generateCoreStyleVisual(dna: ProjectDNA): Promise<string | null> {
    const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
    const prompt = `
      A professional cinematic mood board / style guide collage for the project: "${dna.coreNarrative}".
      Format: ${dna.format}. Style: ${dna.style}.
      STRICT LAYOUT REQUIREMENT: ONE single image that is a composite showing 4-5 distinct cinematic perspectives:
      1. An Epic Wide Shot establishing the ${dna.environment}.
      2. A dramatic medium shot showcasing lighting and texture.
      3. Close-up of symbolic prop.
      Unified color grading, 8k, cinematic.
    `;
    try {
      const response = await ai.models.generateContent({
        model: 'gemini-3-pro-image-preview',
        contents: { parts: [{ text: prompt }] },
        config: { imageConfig: { aspectRatio: dna.ratio === '9:16' ? "9:16" : "16:9", imageSize: "1K" } }
      });
      for (const part of response.candidates?.[0]?.content?.parts || []) {
        if (part.inlineData) return `data:image/png;base64,${part.inlineData.data}`;
      }
      return null;
    } catch (error) { return null; }
  }

  async generateStageGrid(dna: ProjectDNA, stage: StageDesign): Promise<string> {
    const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
    const gridPrompt = `
      Professional 3x3 Stage Concept Design Sheet for: "${stage.name}".
      Context: ${stage.description}. Style: ${dna.style}. Format: ${dna.format}.

      STRICT LAYOUT: A 3x3 grid with EXACTLY NINE equal panels showing established spatial views:
      - Rows 1 & 2: Wide establishing shots and internal spatial logic.
      - Row 3: Close-ups of textures, specific lighting clusters, and environmental details.
