    `;
    try {
      const response = await ai.models.generateContent({
        model: 'gemini-3-pro-image-preview',
        contents: { parts: [{ text: gridPrompt }] },
        config: { imageConfig: { aspectRatio: "1:1", imageSize: "1K" } }
      });
      for (const part of response.candidates?.[0]?.content?.parts || []) {
        if (part.inlineData) return `data:image/png;base64,${part.inlineData.data}`;
      }
    } catch (error) { console.error(error); }
    return "";
  }

  async generateCharacterGrid(dna: ProjectDNA, character: CharacterDesign): Promise<string> {
    const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
    const gridPrompt = `
      Professional 3x3 "Deconstructive Visual Language" Character Sheet for: "${character.name}" (${character.role}).
      Style: ${dna.style}. Format: ${dna.format}.

      STRICT 3x3 GRID LAYOUT:
      1. Center: Full body dynamic pose.
      2. Surrounding Panels: Close-up of facial emotions, macro-texture of skin/surface/suit, symbolic accessories, material breakdown, and profile silhouette.
      Ensure high-fidelity concept art style, consistent lighting and color palette across all nine panels.
