import React, { useEffect } from 'react';
import { Loader2, Clapperboard, Plus, Trash2 } from 'lucide-react';
import { ProjectState, Storyboard, StoryboardEntry } from '../types';

interface StoryboardPhaseProps {
  project: ProjectState;
  isLoading: boolean;
  onUpdateStoryboard: (sb: Storyboard) => void;
  guideText: string;
}

export const StoryboardPhase: React.FC<StoryboardPhaseProps> = ({
  project, isLoading, onUpdateStoryboard, guideText
}) => {
  const sb = project.storyboard;

  // 智慧剖析：如果 AI 傳回的字串是範圍 (例如 "00:00 - 00:05")，自動拆分
  useEffect(() => {
    if (sb && sb.entries.length > 0) {
      let needsFix = false;
      const fixedEntries = sb.entries.map(entry => {
        let { startTime, endTime } = entry;

        // 剖析 startTime 是否包含範圍
        if (startTime && startTime.includes('-')) {
          const parts = startTime.split('-').map(p => p.trim());
          startTime = parts[0];
          endTime = parts[1] || endTime;
          needsFix = true;
        }

        // 剖析 endTime 是否包含範圍
        if (endTime && endTime.includes('-')) {
          const parts = endTime.split('-').map(p => p.trim());
          endTime = parts[1] || parts[0];
          needsFix = true;
        }

        return { ...entry, startTime, endTime };
      });

      if (needsFix) {
        onUpdateStoryboard({ entries: fixedEntries });
      }
    }
  }, [sb?.entries.length]); 

  if (isLoading && !sb) {
    return (
      <div className="py-20 flex flex-col items-center gap-6 animate-pulse">
        <Loader2 className="w-12 h-12 text-amber-600 animate-spin" />
        <p className="text-amber-500 text-xs font-bold uppercase tracking-[0.3em]">AI 正在編寫技術分鏡腳本...</p>
      </div>
    );
  }

  if (!sb) return null;

  const addSeconds = (timeStr: string, secondsToAdd: number) => {
    const parts = (timeStr || "00:00").split(':');
    let m = 0, s = 0;
    if (parts.length === 3) {
      m = parseInt(parts[1]) || 0;
      s = parseInt(parts[2]) || 0;
    } else {
      m = parseInt(parts[0]) || 0;
      s = parseInt(parts[1]) || 0;
    }

    let totalSeconds = m * 60 + s + secondsToAdd;
    if (totalSeconds < 0) totalSeconds = 0;
    const nextM = Math.floor(totalSeconds / 60);
    const nextS = totalSeconds % 60;
    return `${String(nextM).padStart(2, '0')}:${String(nextS).padStart(2, '0')}`;
  };

  const handleUpdateEntry = (idx: number, field: keyof StoryboardEntry, val: string) => {
    const newEntries = [...sb.entries];
    newEntries[idx] = { ...newEntries[idx], [field]: val };

    if (field === 'endTime') {
      if (idx < newEntries.length - 1) {
        newEntries[idx + 1] = { ...newEntries[idx + 1], startTime: addSeconds(val, 1) };
      }
    } else if (field === 'startTime') {
      if (idx > 0) {
        newEntries[idx - 1] = { ...newEntries[idx - 1], endTime: addSeconds(val, -1) };
      }
    }

    onUpdateStoryboard({ entries: newEntries });
  };

  const handleAddEntry = (idx: number) => {
    const newEntries = [...sb.entries];
    const currentEntry = newEntries[idx];
    const startTime = addSeconds(currentEntry.endTime || "00:00", 1);
    const endTime = addSeconds(startTime, 5);

    const newEntry: StoryboardEntry = {
      startTime,
      endTime,
      shotType: "MCU",
      movement: "STATIC",
      action: "新場景視覺動態...",
      audio: "環境音效..."
    };

    newEntries.splice(idx + 1, 0, newEntry);
    onUpdateStoryboard({ entries: newEntries });
  };

  const handleRemoveEntry = (idx: number) => {
    if (sb.entries.length <= 1) return;
    const newEntries = [...sb.entries];
    newEntries.splice(idx, 1);
    onUpdateStoryboard({ entries: newEntries });
  };

  const formatDisplayTime = (time: string) => {
    if (!time) return "00:00";
    const parts = time.split(':');
    if (parts.length === 3) return `${parts[1]}:${parts[2]}`;
    return time;
  };

  return (
    <div className="w-full space-y-4 pb-20 animate-in fade-in duration-1000">
      <div className="text-center space-y-1">
        <h2 className="text-2xl font-serif text-neutral-100">{guideText}</h2>
        <p className="text-[9px] text-neutral-500 uppercase tracking-widest">規則：次鏡頭起始時間為前鏡頭結束時間 + 1s</p>
      </div>

      <div className="border border-white/10 shadow-2xl bg-black/40 relative overflow-hidden flex flex-col h-[600px]">
        {/* 表格標題 */}
        <div className="w-full bg-white/5 border-b border-white/10 flex h-8 items-center shrink-0">
          <div className="w-[10%] text-[9px] font-bold text-neutral-500 uppercase tracking-widest text-center border-r border-white/5">Time</div>
          <div className="w-[12%] px-2 text-[9px] font-bold text-neutral-500 uppercase tracking-widest border-r border-white/5">Shot</div>
          <div className="w-[12%] px-2 text-[9px] font-bold text-neutral-500 uppercase tracking-widest border-r border-white/5">Motion</div>
          <div className="w-[41%] px-3 text-[9px] font-bold text-neutral-500 uppercase tracking-widest border-r border-white/5">Visual Action</div>
          <div className="w-[20%] px-3 text-[9px] font-bold text-neutral-500 uppercase tracking-widest border-r border-white/5">Audio</div>
          <div className="w-[5%] px-1 text-[9px] font-bold text-neutral-500 uppercase tracking-widest text-center">Ops</div>
        </div>

        {/* 捲動內容區塊 */}
        <div className="flex-1 overflow-y-auto overflow-x-hidden divide-y divide-white/5">
          {sb.entries.map((entry, idx) => (
            <div key={idx} className="flex hover:bg-amber-600/5 transition-colors group border-b border-white/5 last:border-b-0 min-h-[48px]">

              {/* 時間欄位：進一步縮減字體與高度 */}
              <div className="w-[10%] flex flex-col border-r border-white/5 bg-black/40">
                <div className="h-1/2 flex items-center border-b border-white/5">
                  <input
                    className="bg-transparent border-none text-[9px] font-mono font-bold text-amber-600 w-full h-full p-0 focus:ring-0 text-center leading-none"
                    value={formatDisplayTime(entry.startTime)}
                    readOnly={idx === 0}
                    onChange={(e) => handleUpdateEntry(idx, 'startTime', e.target.value)}
                  />
                </div>
                <div className="h-1/2 flex items-center">
                  <input
                    className="bg-transparent border-none text-[9px] font-mono font-bold text-amber-500 w-full h-full p-0 focus:ring-0 text-center leading-none"
                    value={formatDisplayTime(entry.endTime)}
                    onChange={(e) => handleUpdateEntry(idx, 'endTime', e.target.value)}
                  />
                </div>
              </div>

              {/* 鏡頭 */}
              <div className="w-[12%] px-2 py-2 border-r border-white/5">
                <textarea
                  className="w-full bg-transparent border-none text-[10px] font-bold text-blue-400 uppercase leading-snug resize-none p-0 focus:ring-0"
                  rows={2}
                  value={entry.shotType}
                  onChange={(e) => handleUpdateEntry(idx, 'shotType', e.target.value)}
                />
              </div>

              {/* 運鏡 */}
              <div className="w-[12%] px-2 py-2 border-r border-white/5">
                <textarea
                  className="w-full bg-transparent border-none text-[10px] font-bold text-purple-400 uppercase leading-snug resize-none p-0 focus:ring-0"
                  rows={2}
                  value={entry.movement}
                  onChange={(e) => handleUpdateEntry(idx, 'movement', e.target.value)}
                />
              </div>

              {/* 畫面動作 */}
              <div className="w-[41%] px-3 py-2 border-r border-white/5">
                <textarea
                  className="w-full bg-transparent border-none text-[10px] text-neutral-200 leading-normal resize-none p-0 focus:ring-0"
                  rows={2}
                  value={entry.action}
                  onChange={(e) => handleUpdateEntry(idx, 'action', e.target.value)}
                />
              </div>

              {/* 音效 */}
              <div className="w-[20%] px-3 py-2 border-r border-white/5">
                <textarea
                  className="w-full bg-transparent border-none text-[9px] text-neutral-400 italic leading-normal resize-none p-0 focus:ring-0"
                  rows={2}
                  value={entry.audio}
                  onChange={(e) => handleUpdateEntry(idx, 'audio', e.target.value)}
                />
              </div>

              {/* 操作 */}
              <div className="w-[5%] px-1 py-2 flex flex-col gap-1 items-center justify-center opacity-0 group-hover:opacity-100 transition-opacity">
                <button onClick={() => handleAddEntry(idx)} className="p-1 bg-amber-600/10 hover:bg-amber-600 text-amber-500 hover:text-white transition-all">
                  <Plus className="w-2.5 h-2.5" />
                </button>
                <button onClick={() => handleRemoveEntry(idx)} className="p-1 bg-red-500/10 hover:bg-red-500 text-neutral-600 hover:text-white transition-all">
                  <Trash2 className="w-2.5 h-2.5" />
                </button>
              </div>
            </div>
          ))}
        </div>
      </div>

      <div className="flex justify-center pt-2">
        <div className="inline-flex items-center gap-3 px-6 py-2.5 bg-amber-600/5 rounded-full border border-amber-600/20 shadow-xl group hover:border-amber-600/40 transition-all cursor-default">
          <Clapperboard className="w-4 h-4 text-amber-600 group-hover:scale-110 transition-transform" />
          <p className="text-[9px] font-bold text-neutral-400 uppercase tracking-[0.2em]">分鏡規劃完成 • 定稿準備生成</p>
        </div>
      </div>
    </div>
  );
};

