import { GoogleGenAI, Type } from "@google/genai";
import { SYSTEM_INSTRUCTION } from "../constants";
import { Suggestion, StageDesign, CharacterDesign, ProjectDNA, ProductionPhase, StoryArchitecture, Storyboard } from "../types";

export class GeminiService {
  constructor(apiKey: string) { }

  async generateSuggestions(input: string, phase: ProductionPhase, context: string): Promise<Suggestion[]> {
    const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
    const currentDNA = JSON.parse(context) as ProjectDNA;

    const prompt = `
    目前的製作設定：
    - 形式：${currentDNA.format}
    - 預想視覺風格：${currentDNA.style}
    - 畫面比例：${currentDNA.ratio}

    核心靈感/指令： "${input}"。

    請根據目前的製作階段 [${phase}]，提供三個具體的創意導向（頂尖導演提案）。
    這些提案必須在視覺張力與敘事節奏上符合上述的「製作設定」。

    【關鍵任務】如果是 INSPIRATION 階段，請發揮頂尖導演聯想力，自動推論出初步的：
    1. 地理環境 (environment)
    2. 社會背景 (socialBackground)
    3. 核心敘事 (coreNarrative)

    請回傳 JSON 陣列，包含 title, description, tags, environment, socialBackground, coreNarrative。`;

    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: [{ role: 'user', parts: [{ text: prompt }] }],
      config: {
        systemInstruction: SYSTEM_INSTRUCTION,
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.ARRAY,
          items: {
            type: Type.OBJECT,
            properties: {
              title: { type: Type.STRING },
              description: { type: Type.STRING },
              tags: { type: Type.ARRAY, items: { type: Type.STRING } },
              environment: { type: Type.STRING },
              socialBackground: { type: Type.STRING },
              coreNarrative: { type: Type.STRING }
            },
            required: ["title", "description", "tags"]
          }
        }
      }
    });
    return JSON.parse(response.text || "[]");
  }

  async elaboratePlan(suggestion: Suggestion, baseDNA: ProjectDNA): Promise<ProjectDNA> {
    const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
    const prompt = `
    請將以下提案擴充為完整的電影拍攝 DNA：
    提案標題：${suggestion.title}

    【核心約束】你必須嚴格遵循用戶設定的基底 DNA：
    - 製作形式：${baseDNA.format}
    - 預選視覺風格：${baseDNA.style}
    - 畫面比例：${baseDNA.ratio}

    內容需包含：符合該風格的地理環境、社會背景、核心敘事與一份細緻的劇本摘要。
    此外，請作為 AI 頂尖導演，提出一份「拍攝方案建議方向 (directorVision)」，包含建議的運鏡方式、色彩校正方向、以及聲音設計重點。
    `;

    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: [{ role: 'user', parts: [{ text: prompt }] }],
      config: {
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.OBJECT,
          properties: {
            format: { type: Type.STRING },
            style: { type: Type.STRING },
            story: { type: Type.STRING },
            ratio: { type: Type.STRING },
            environment: { type: Type.STRING },
            socialBackground: { type: Type.STRING },
            coreNarrative: { type: Type.STRING },
            directorVision: { type: Type.STRING }
          },
          required: ["format", "style", "story", "environment", "socialBackground", "coreNarrative", "directorVision"]
        }
      }
    });
    const result = JSON.parse(response.text || "{}");

    return {
      ...result,
      format: baseDNA.format, 
      ratio: baseDNA.ratio,   
      style: result.style || baseDNA.style 
    };
  }

  async identifyCoreStages(dna: ProjectDNA): Promise<StageDesign[]> {
    const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
    const prompt = `你是一位頂尖電影美術指導與空間敘事分析師。請針對提供的劇本內容進行「核心舞台 (Core Stage)」的識別與視覺設計。
    請為每個舞台命名為簡短的識別名詞 (2-4 個繁體中文字)。

【識別與篩選原則】
1. 從「劇本摘要」中找出故事的主要發生地點，並將其歸納為 1-3 個核心舞台。
2. 舞台識別必須以「宏觀角度」審視，請嚴格自我詢問：
   - 該空間是否為角色核心活動/生活的區域？
   - 該空間是否為角色之間產生關鍵互動、衝突或情感轉折的必經之地？
   - 若兩者皆為「否」，請剔除該地點，重新考量其他具備敘事權重的地理集群。

【輸出內容需求】
請回傳 JSON 陣列，每個舞台物件必須包含：
- name: 舞台名稱。
- description: 詳盡描述舞台的外觀視覺要素，必須嚴格包含以下項目：
  1. 場地大小 (Scale)
  2. 位置與方位 (Location & Direction)
  3. 主要物件與關鍵道具 (Key Props)
  4. 光影色調與色彩策略 (Lighting & Palette)
  5. 核心敘事氛圍 (Atmosphere)

劇本摘要：${dna.story}
視覺風格定義：${dna.style} (形式：${dna.format})
環境背景：${dna.environment}`;

    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: [{ role: 'user', parts: [{ text: prompt }] }],
      config: {
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.ARRAY,
          items: {
            type: Type.OBJECT,
            properties: {
              name: { type: Type.STRING },
              description: { type: Type.STRING }
            },
            required: ["name", "description"]
          }
        }
      }
    });
    return JSON.parse(response.text || "[]");
  }

  async analyzeCharacters(dna: ProjectDNA): Promise<CharacterDesign[]> {
    const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
    const prompt = `你是一位頂尖電影選角指導。請從劇本中「提取劇情線索」，塑造具備視覺特徵的角色。
    請為每個角色命名為簡短的識別名詞 (2-4 個繁體中文字)。

    劇本摘要：${dna.story}
    視覺風格：${dna.style}

    【塑造任務】
    - 識別核心角色姓名與角色 (role)。
    - 設計獨特的外貌特徵 (physicalTraits)。
    - 定義外觀材質色調 (visualTone)，反映其性格或處境。
    - 挖掘內在動機 (motivation)。

    請回傳 JSON 陣列。`;

    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: [{ role: 'user', parts: [{ text: prompt }] }],
      config: {
        systemInstruction: SYSTEM_INSTRUCTION,
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.ARRAY,
          items: {
            type: Type.OBJECT,
            properties: {
              name: { type: Type.STRING },
              role: { type: Type.STRING },
              physicalTraits: { type: Type.STRING },
              visualTone: { type: Type.STRING },
              motivation: { type: Type.STRING }
            },
            required: ["name", "role", "physicalTraits", "visualTone", "motivation"]
          }
        }
      }
    });
    return JSON.parse(response.text || "[]");
  }

  async generateStoryArchitecture(dna: ProjectDNA): Promise<StoryArchitecture> {
    const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
    const prompt = `你是一位資深編劇。請根據拍攝 DNA，構想並鋪陳具備蒙太奇節奏的敘事結構。

    【任務細節】
    1. 確立結構點：激勵事件 (Inciting Incident)、中點轉折 (Midpoint)、全片高潮 (Climax)、最終結局 (Resolution)。
    2. 章節劃分：將故事分為 3-5 個章節。
    3. 每章設計：
       - 章節標題 (title)。
       - 情緒基調 (emotionalTone)：如「壓抑與疏離」、「爆發性衝突」、「哀傷的釋放」。
       - 摘要內容 (summary)。
       - 場景變換 (scenes)：描述 2-4 個場景的視覺變遷。

    劇本摘要：${dna.story}
    核心敘事：${dna.coreNarrative}
    視覺風格：${dna.style}

    請回傳 JSON。`;

    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: [{ role: 'user', parts: [{ text: prompt }] }],
      config: {
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.OBJECT,
          properties: {
            incitingIncident: { type: Type.STRING },
            midpoint: { type: Type.STRING },
            climax: { type: Type.STRING },
            resolution: { type: Type.STRING },
            chapters: {
              type: Type.ARRAY,
              items: {
                type: Type.OBJECT,
                properties: {
                  title: { type: Type.STRING },
                  emotionalTone: { type: Type.STRING },
                  summary: { type: Type.STRING },
                  scenes: { type: Type.ARRAY, items: { type: Type.STRING } }
                },
                required: ["title", "emotionalTone", "summary", "scenes"]
              }
            }
          },
          required: ["incitingIncident", "midpoint", "climax", "resolution", "chapters"]
        }
      }
    });
    return JSON.parse(response.text || "{}");
  }

  async generateStoryboard(dna: ProjectDNA, arch: StoryArchitecture, stageNames: string[], characterNames: string[]): Promise<Storyboard> {
    const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
    const prompt = `你是一位資深電影導演與攝影指導 (DP)。請將提供的「敘事結構與場景序列」轉化為精確的「技術分鏡腳本 (Technical Storyboard)」。

    【關鍵關聯約束】
    1. 舞台 (stage)：請從提供的舞台清單中挑選最符合場景的地點：[${stageNames.join(', ')}]。
    2. 角色 (character)：請從提供的角色清單中挑選在此鏡頭出現的角色：[${characterNames.join(', ')}]。

    【腳本撰寫要求】
    1. 密度：將每個章節內的場景序列細化為 2-4 個具體鏡頭。
    2. 時間規則：請嚴格分開填寫 startTime 與 endTime 兩個欄位。格式必須為 mm:ss。
       - 首鏡頭 startTime 必須為 00:00。
       - 下一個鏡頭的 startTime 為上一個鏡頭 endTime 加 1 秒。
    3. 鏡頭語言 (shotType)：使用專業術語（如 WS, MCU, CU, OTS）。
    4. 運鏡 (movement)：描述攝影機運動（如 STATIC, PAN, TILT, DOLLY）。
    5. 動作 (action)：視覺動態與角色行為。**請務必使用「繁體中文」填寫。**
    6. 音效 (audio)：環境聲、SFX 或 BGM。**請務必使用「繁體中文」填寫。**

    專案 DNA：${JSON.stringify(dna)}
    敘事結構：${JSON.stringify(arch)}

    請回傳 JSON 格式。`;

    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: [{ role: 'user', parts: [{ text: prompt }] }],
      config: {
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.OBJECT,
          properties: {
            entries: {
              type: Type.ARRAY,
              items: {
                type: Type.OBJECT,
                properties: {
                  startTime: { type: Type.STRING },
                  endTime: { type: Type.STRING },
                  stage: { type: Type.STRING },
                  character: { type: Type.STRING },
                  shotType: { type: Type.STRING },
                  movement: { type: Type.STRING },
                  action: { type: Type.STRING },
                  audio: { type: Type.STRING }
                },
                required: ["startTime", "endTime", "stage", "character", "shotType", "movement", "action", "audio"]
              }
            }
          },
          required: ["entries"]
        }
      }
    });
    return JSON.parse(response.text || "{ entries: [] }");
  }

  async polishText(text: string, type: string): Promise<string> {
    const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: `你是專業電影視覺指導。請進行場景化潤色，強調視覺細節與專業術語。類型：${type}。內容：${text}`,
    });
    return response.text || text;
  }

  async generateCoreStyleVisual(dna: ProjectDNA): Promise<string | null> {
    const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
    const prompt = `
      A professional cinematic mood board / style guide collage for the project: "${dna.coreNarrative}".
      Format: ${dna.format}. Style: ${dna.style}.
      STRICT LAYOUT REQUIREMENT: ONE single image that is a composite showing 4-5 distinct cinematic perspectives:
      1. An Epic Wide Shot establishing the ${dna.environment}.
      2. A dramatic medium shot showcasing lighting and texture.
      3. Close-up of symbolic prop.
      Unified color grading, 8k, cinematic.
    `;
    try {
      const response = await ai.models.generateContent({
        model: 'gemini-3-pro-image-preview',
        contents: { parts: [{ text: prompt }] },
        config: { imageConfig: { aspectRatio: dna.ratio === '9:16' ? "9:16" : "16:9", imageSize: "1K" } }
      });
      for (const part of response.candidates?.[0]?.content?.parts || []) {
        if (part.inlineData) return `data:image/png;base64,${part.inlineData.data}`;
      }
      return null;
    } catch (error) { return null; }
  }

  async generateStageGrid(dna: ProjectDNA, stage: StageDesign): Promise<string> {
    const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
    const gridPrompt = `
      Professional 3x3 Stage Concept Design Sheet for: "${stage.name}".
      Context: ${stage.description}. Style: ${dna.style}. Format: ${dna.format}.

      STRICT LAYOUT: A 3x3 grid with EXACTLY NINE equal panels showing established spatial views:
      - Rows 1 & 2: Wide establishing shots and internal spatial logic.
      - Row 3: Close-ups of textures, specific lighting clusters, and environmental details.
      Unified aesthetic, 8k cinematic quality.
    `;
    try {
      const response = await ai.models.generateContent({
        model: 'gemini-3-pro-image-preview',
        contents: { parts: [{ text: gridPrompt }] },
        config: { imageConfig: { aspectRatio: "1:1", imageSize: "1K" } }
      });
      for (const part of response.candidates?.[0]?.content?.parts || []) {
        if (part.inlineData) return `data:image/png;base64,${part.inlineData.data}`;
      }
    } catch (error) { console.error(error); }
    return "";
  }

  async generateCharacterGrid(dna: ProjectDNA, character: CharacterDesign): Promise<string> {
    const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
    const gridPrompt = `
      Professional 3x3 "Deconstructive Visual Language" Character Sheet for: "${character.name}" (${character.role}).
      Style: ${dna.style}. Format: ${dna.format}.

      STRICT 3x3 GRID LAYOUT:
      1. Center: Full body dynamic pose.
      2. Surrounding Panels: Close-up of facial emotions, macro-texture of skin/surface/suit, symbolic accessories, material breakdown, and profile silhouette.
      Ensure high-fidelity concept art style, consistent lighting and color palette across all nine panels.
    `;
    try {
      const response = await ai.models.generateContent({
        model: 'gemini-3-pro-image-preview',
        contents: { parts: [{ text: gridPrompt }] },
        config: { imageConfig: { aspectRatio: "1:1", imageSize: "1K" } }
      });
      for (const part of response.candidates?.[0]?.content?.parts || []) {
        if (part.inlineData) return `data:image/png;base64,${part.inlineData.data}`;
      }
    } catch (error) { console.error(error); }
    return "";
  }
}

import React, { useState, useEffect, useRef } from 'react';
import { ProductionPhase, Suggestion, ProjectState, ProjectDNA, StageDesign, CharacterDesign, StoryArchitecture, Storyboard } from './types';
import { PHASE_METADATA } from './constants';
import { GeminiService } from './services/geminiService';
import { ApiKeySelector } from './components/ApiKeySelector';
import { InspirationPhase } from './components/InspirationPhase';
import { ProductionPlanPhase } from './components/ProductionPlanPhase';
import { VisualDevPhase } from './components/VisualDevPhase';
import { CharacterDevPhase } from './components/CharacterDevPhase';
import { StoryArchPhase } from './components/StoryArchPhase';
import { StoryboardPhase } from './components/StoryboardPhase';
import { 
  Film, Loader2, ArrowRight, 
  ChevronRight, Download, Upload,
  X, CheckCircle2, Terminal, MapPin, Users, Target,
  Grid, Image as ImageIcon, Maximize2, DownloadCloud, UserPlus,
  BookOpen, Layout, Zap
} from 'lucide-react';

const App: React.FC = () => {
  const [hasKey, setHasKey] = useState(false);
  const [isLoading, setIsLoading] = useState(false);
  const [isAnalyzing, setIsAnalyzing] = useState(false);
  const [isElaborating, setIsElaborating] = useState(false);
  const [input, setInput] = useState('');
  const [activeStep, setActiveStep] = useState<ProductionPhase>(ProductionPhase.INSPIRATION);
  const [expandedImage, setExpandedImage] = useState<string | null>(null);

  const [suggestions, setSuggestions] = useState<Suggestion[]>([]);

  const [project, setProject] = useState<ProjectState>({
    currentPhase: ProductionPhase.INSPIRATION,
    initialInput: '',
    dna: { format: '電影', style: '寫實電影感', story: '', ratio: '16:9', environment: '', socialBackground: '', coreNarrative: '', directorVision: '' },
    proposedStages: [], 
    proposedCharacters: [], 
    coreStageImage: undefined 
  });

  const [tempDNA, setTempDNA] = useState<ProjectDNA>(project.dna);
  const fileInputRef = useRef<HTMLInputElement>(null);
  const geminiRef = useRef<GeminiService | null>(null);

  const handleApiError = (err: any) => {
    console.error(err);
    if (err && typeof err === 'object' && 'message' in err && typeof err.message === 'string' && err.message.includes("Requested entity was not found.")) {
      setHasKey(false);
      geminiRef.current = null;
    }
  };

  useEffect(() => {
    const checkKey = async () => {
      // @ts-ignore
      const exists = await window.aistudio.hasSelectedApiKey();
      if (exists) {
        setHasKey(true);
        geminiRef.current = new GeminiService(process.env.API_KEY || '');
      }
    };
    checkKey();
  }, []);

  useEffect(() => {
    if (activeStep === ProductionPhase.INSPIRATION && project.initialInput) {
      setInput(project.initialInput);
    }
  }, [project.initialInput, activeStep]);

  useEffect(() => {
    if (activeStep === ProductionPhase.VISUAL_DEV && project.proposedStages.length === 0 && !isAnalyzing && geminiRef.current) {
      handleIdentifyStages();
    }
    if (activeStep === ProductionPhase.CHARACTER_DEV && project.proposedCharacters.length === 0 && !isAnalyzing && geminiRef.current) {
      handleAutoAnalyzeCharacters();
    }
    if (activeStep === ProductionPhase.STORY_ARCH && !project.storyArchitecture && !isLoading && geminiRef.current) {
      handleAutoGenerateStoryArch();
    }
    if (activeStep === ProductionPhase.STORYBOARD && !project.storyboard && !isLoading && geminiRef.current) {
      handleAutoGenerateStoryboard();
    }
  }, [activeStep, project.proposedStages.length, project.proposedCharacters.length, project.storyArchitecture, project.storyboard]);

  const handleIdentifyStages = async () => {
    if (!geminiRef.current || isAnalyzing) return;
    setIsAnalyzing(true);
    try {
      const stages = await geminiRef.current.identifyCoreStages(project.dna);
      setProject(prev => ({ ...prev, proposedStages: stages }));
    } catch (err) { handleApiError(err); } finally { setIsAnalyzing(false); }
  };

  const handleAutoAnalyzeCharacters = async () => {
    if (!geminiRef.current || isAnalyzing) return;
    setIsAnalyzing(true);
    try {
      const chars = await geminiRef.current.analyzeCharacters(project.dna);
      setProject(prev => ({ ...prev, proposedCharacters: chars }));
    } catch (err) { handleApiError(err); } finally { setIsAnalyzing(false); }
  };

  const handleAutoGenerateStoryArch = async () => {
    if (!geminiRef.current || isLoading) return;
    setIsLoading(true);
    try {
      const arch = await geminiRef.current.generateStoryArchitecture(project.dna);
      setProject(prev => ({ ...prev, storyArchitecture: arch }));
    } catch (err) { handleApiError(err); } finally { setIsLoading(false); }
  };

  const handleAutoGenerateStoryboard = async () => {
    if (!geminiRef.current || isLoading || !project.storyArchitecture) return;
    setIsLoading(true);
    try {
      const stageNames = project.proposedStages.map(s => s.name);
      const charNames = project.proposedCharacters.map(c => c.name);
      const sb = await geminiRef.current.generateStoryboard(project.dna, project.storyArchitecture, stageNames, charNames);
      setProject(prev => ({ ...prev, storyboard: sb }));
    } catch (err) { handleApiError(err); } finally { setIsLoading(false); }
  };

  const updateDNAField = (field: keyof ProjectDNA, value: string) => {
    const updatedDNA = { ...project.dna, [field]: value };
    setProject(prev => ({ ...prev, dna: updatedDNA }));
    setTempDNA(updatedDNA);
  };

  const handleSubmitIdea = async (e?: React.FormEvent) => {
    if (e) e.preventDefault();
    if (!input.trim() || isLoading || !geminiRef.current) return;
    setIsLoading(true);
    try {
      const results = await geminiRef.current.generateSuggestions(input, activeStep, JSON.stringify(project.dna));
      setSuggestions(results || []);
      setProject(prev => ({ 
        ...prev, 
        initialInput: activeStep === ProductionPhase.INSPIRATION ? input : prev.initialInput
      }));
    } catch (err) { handleApiError(err); } finally { setIsLoading(false); }
  };

  const handleSuggestionClick = async (s: Suggestion) => {
    if (!geminiRef.current) return;
    setIsElaborating(true);
    try {
      const detailedDNA = await geminiRef.current.elaboratePlan(s, project.dna);
      setTempDNA(detailedDNA);
      setSuggestions([]);
      setProject(prev => ({
        ...prev, 
        dna: detailedDNA, 
        currentPhase: ProductionPhase.PRODUCTION_PLAN
      }));
      setActiveStep(ProductionPhase.PRODUCTION_PLAN);
    } catch (err) { handleApiError(err); } finally { setIsElaborating(false); }
  };

  const handleRenderCoreStageOnly = async () => {
    if (!geminiRef.current) return;
    setIsLoading(true);
    try {
      const coreImage = await geminiRef.current.generateCoreStyleVisual(tempDNA) || undefined;
      setProject(prev => ({ ...prev, coreStageImage: coreImage }));
    } catch (err) { handleApiError(err); } finally { setIsLoading(false); }
  };

  const confirmProductionPlan = async () => {
    if (!geminiRef.current) return;
    setIsLoading(true);
    try {
      let coreImage = project.coreStageImage;
      if (!coreImage) {
        coreImage = await geminiRef.current.generateCoreStyleVisual(tempDNA) || undefined;
      }
      setProject(prev => ({
        ...prev, 
        currentPhase: ProductionPhase.VISUAL_DEV, 
        dna: { ...tempDNA }, 
        coreStageImage: coreImage,
        proposedStages: [], 
        proposedCharacters: []
      }));
      setActiveStep(ProductionPhase.VISUAL_DEV);
    } finally { setIsLoading(false); }
  };

  const handleProceedToCharacterDev = () => {
    setProject(prev => ({ 
      ...prev, 
      currentPhase: ProductionPhase.CHARACTER_DEV,
      proposedCharacters: [] 
    }));
    setActiveStep(ProductionPhase.CHARACTER_DEV);
  };

  const handleProceedToStoryArch = () => {
    setProject(prev => ({ 
      ...prev, 
      currentPhase: ProductionPhase.STORY_ARCH,
      storyArchitecture: undefined 
    }));
    setActiveStep(ProductionPhase.STORY_ARCH);
  };

  const handleProceedToStoryboard = () => {
    setProject(prev => ({ 
      ...prev, 
      currentPhase: ProductionPhase.STORYBOARD,
      storyboard: undefined 
    }));
    setActiveStep(ProductionPhase.STORYBOARD);
  };

  const handleProceedToVideoPrompting = () => {
    setProject(prev => ({ ...prev, currentPhase: ProductionPhase.VIDEO_PROMPTING }));
    setActiveStep(ProductionPhase.VIDEO_PROMPTING);
  };

  const saveProject = () => {
    const stateToSave: ProjectState = { 
      ...project, 
      initialInput: input 
    };
    const data = JSON.stringify(stateToSave, null, 2);
    const blob = new Blob([data], { type: 'application/json' });
    const url = URL.createObjectURL(blob);
    const link = document.createElement('a');
    link.href = url;
    link.download = `montage-project-${new Date().toISOString().slice(0, 10)}.json`;
    link.click();
  };

  const loadProject = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;
    const reader = new FileReader();
    reader.onload = (event) => {
      try {
        const data = JSON.parse(event.target?.result as string) as ProjectState;
        if (data.currentPhase && data.dna) {
          setProject(data);
          setActiveStep(data.currentPhase);
          setTempDNA(data.dna);
          if (data.initialInput) setInput(data.initialInput);
        }
      } catch (err) { alert('檔案格式錯誤。'); }
    };
    reader.readAsText(file);
    if (fileInputRef.current) fileInputRef.current.value = '';
  };

  const handleRenderStageGrid = async (idx: number) => {
    if (!geminiRef.current) return;
    setIsLoading(true);
    setProject(prev => ({ ...prev, selectedStageIndex: idx }));
    try {
      const gridResult = await geminiRef.current.generateStageGrid(project.dna, project.proposedStages[idx]);
      if (gridResult) {
        setProject(prev => {
          const newStages = [...prev.proposedStages];
          newStages[idx] = { ...newStages[idx], gridImage: gridResult };
          return { ...prev, proposedStages: newStages };
        });
      }
    } catch (err) { handleApiError(err); } finally { setIsLoading(false); }
  };

  const handleRenderCharacterGrid = async (idx: number) => {
    if (!geminiRef.current) return;
    setIsLoading(true);
    setProject(prev => ({ ...prev, selectedCharacterIndex: idx }));
    try {
      const gridResult = await geminiRef.current.generateCharacterGrid(project.dna, project.proposedCharacters[idx]);
      if (gridResult) {
        setProject(prev => {
          const newChars = [...prev.proposedCharacters];
          newChars[idx] = { ...newChars[idx], gridImage: gridResult };
          return { ...prev, proposedCharacters: newChars };
        });
      }
    } catch (err) { handleApiError(err); } finally { setIsLoading(false); }
  };

  const updateStage = (idx: number, field: keyof StageDesign, value: string) => {
    setProject(prev => {
      const newStages = [...prev.proposedStages];
      newStages[idx] = { ...newStages[idx], [field]: value };
      return { ...prev, proposedStages: newStages };
    });
  };

  const updateCharacter = (idx: number, field: keyof CharacterDesign, value: string) => {
    setProject(prev => {
      const newChars = [...prev.proposedCharacters];
      newChars[idx] = { ...newChars[idx], [field]: value };
      return { ...prev, proposedCharacters: newChars };
    });
  };

  const updateStoryArch = (arch: StoryArchitecture) => {
    setProject(prev => ({ ...prev, storyArchitecture: arch }));
  };

  const updateStoryboard = (sb: Storyboard) => {
    setProject(prev => ({ ...prev, storyboard: sb }));
  };

  const handlePolishCharacter = async (idx: number, field: keyof CharacterDesign, label: string) => {
    if (!geminiRef.current || isLoading) return;
    setIsLoading(true);
    try {
      const char = project.proposedCharacters[idx];
      const polished = await geminiRef.current.polishText(char[field] as string, `角色塑造之${label}`);
      updateCharacter(idx, field, polished);
    } catch (err) { handleApiError(err); } finally { setIsLoading(false); }
  };

  const downloadImage = (base64: string, name: string) => {
    const link = document.createElement('a');
    link.href = base64;
    link.download = `${name}.png`;
    link.click();
  };

  const getPhaseIndex = (phase: ProductionPhase) => {
    return Object.values(ProductionPhase).indexOf(phase);
  };

  const allCharactersReady = project.proposedCharacters.length > 0 && 
                             project.proposedCharacters.every(c => c.gridImage);

  if (!hasKey) return <ApiKeySelector onSelected={() => {
    setHasKey(true);
    if (!geminiRef.current) {
      geminiRef.current = new GeminiService(process.env.API_KEY || '');
    }
  }} />;

  return (
    <div className="flex h-screen bg-[#050505] text-white overflow-hidden font-sans">
      {expandedImage && (
        <div className="fixed inset-0 bg-black/95 z-[100] flex flex-col items-center justify-center p-8 animate-in fade-in duration-300" onClick={() => setExpandedImage(null)}>
          <button className="absolute top-8 right-8 p-3 bg-white/5 hover:bg-amber-600 rounded-full transition-all group">
            <X className="w-8 h-8 text-white group-hover:scale-110" />
          </button>
          <div className="relative max-w-7xl w-full max-h-full" onClick={e => e.stopPropagation()}>
            <img src={expandedImage} className="w-full h-full object-contain shadow-2xl rounded-lg border border-white/10" />
            <button onClick={() => downloadImage(expandedImage, 'montage-asset')} className="absolute bottom-4 right-4 flex items-center gap-2 bg-amber-600 hover:bg-amber-500 px-6 py-3 rounded-full font-bold shadow-xl transition-all">
              <DownloadCloud className="w-5 h-5" /> 下載原始圖片
            </button>
          </div>
        </div>
      )}

      <aside className="w-64 border-r border-white/5 flex flex-col bg-black/40 p-6">
        <div className="flex items-center gap-3 mb-12">
          <div className="bg-amber-600 p-2 rounded-lg shadow-[0_0_15px_rgba(217,119,6,0.3)]"><Film className="w-6 h-6 text-white" /></div>
          <h1 className="text-lg font-serif font-bold tracking-widest text-white/90 uppercase">Montage AI</h1>
        </div>
        <nav className="flex-1 space-y-2">
          {Object.entries(PHASE_METADATA).map(([key, meta], idx) => {
            const phaseKey = key as ProductionPhase;
