import { GoogleGenAI, Type } from "@google/genai";
import { SYSTEM_INSTRUCTION } from "../constants";
import { Suggestion, StageDesign, CharacterDesign, ProjectDNA, ProductionPhase, StoryArchitecture, Storyboard, VideoPromptEntry } from "../types";

export class GeminiService {
  constructor(apiKey: string) { }

  async generateSuggestions(input: string, phase: ProductionPhase, context: string): Promise<Suggestion[]> {
    const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
    const currentDNA = JSON.parse(context) as ProjectDNA;

    const prompt = `
    目前的製作設定：
    - 形式：${currentDNA.format}
    - 預想視覺風格：${currentDNA.style}
    - 畫面比例：${currentDNA.ratio}

    核心靈感/指令： "${input}"。

    請根據目前的製作階段 [${phase}]，提供三個具體的創意導向（頂尖導演提案）。
    這些提案必須在視覺張力與敘事節奏上符合上述的「製作設定」。

    【關鍵任務】如果是 INSPIRATION 階段，請發揮頂尖導演聯想力，自動推論出初步的：
    1. 地理環境 (environment)
    2. 社會背景 (socialBackground)
    3. 核心敘事 (coreNarrative)

    請回傳 JSON 陣列，包含 title, description, tags, environment, socialBackground, coreNarrative。`;

    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: [{ role: 'user', parts: [{ text: prompt }] }],
      config: {
        systemInstruction: SYSTEM_INSTRUCTION,
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.ARRAY,
          items: {
            type: Type.OBJECT,
            properties: {
              title: { type: Type.STRING },
              description: { type: Type.STRING },
              tags: { type: Type.ARRAY, items: { type: Type.STRING } },
              environment: { type: Type.STRING },
              socialBackground: { type: Type.STRING },
              coreNarrative: { type: Type.STRING }
            },
            required: ["title", "description", "tags"]
          }
        }
      }
    });
    return JSON.parse(response.text || "[]");
  }

  async elaboratePlan(suggestion: Suggestion, baseDNA: ProjectDNA): Promise<ProjectDNA> {
    const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
    const prompt = `
    請將以下提案擴充為完整的電影拍攝 DNA：
    提案標題：${suggestion.title}

    【核心約束】你必須嚴格遵循用戶設定的基底 DNA：
    - 製作形式：${baseDNA.format}
    - 預選視覺風格：${baseDNA.style}
    - 畫面比例：${baseDNA.ratio}

    內容需包含：符合該風格的地理環境、社會背景、核心敘事與一份細緻的劇本摘要。
    此外，請作為 AI 頂尖導演，提出一份「拍攝方案建議方向 (directorVision)」，包含建議的運鏡方式、色彩校正方向、以及聲音設計重點。
    `;

    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: [{ role: 'user', parts: [{ text: prompt }] }],
      config: {
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.OBJECT,
          properties: {
            format: { type: Type.STRING },
            style: { type: Type.STRING },
            story: { type: Type.STRING },
            ratio: { type: Type.STRING },
            environment: { type: Type.STRING },
            socialBackground: { type: Type.STRING },
            coreNarrative: { type: Type.STRING },
            directorVision: { type: Type.STRING }
          },
          required: ["format", "style", "story", "environment", "socialBackground", "coreNarrative", "directorVision"]
        }
      }
    });
    const result = JSON.parse(response.text || "{}");

    return {
      ...result,
      format: baseDNA.format, 
      ratio: baseDNA.ratio,   
      style: result.style || baseDNA.style 
    };
  }

  async identifyCoreStages(dna: ProjectDNA): Promise<StageDesign[]> {
    const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
    const prompt = `你是一位頂尖電影美術指導與空間敘事分析師。請針對提供的劇本內容進行「核心舞台 (Core Stage)」的識別與視覺設計。
    請為每個舞台命名為簡短的識別名詞 (2-4 個繁體中文字)。

【識別與篩選原則】
1. 從「劇本摘要」中找出故事的主要發生地點，並將其歸納為 1-3 個核心舞台。
2. 舞台識別必須以「宏觀角度」審視。

【輸出內容需求】
請回傳 JSON 陣列，每個舞台物件必須包含：
- name: 舞台名稱。
- description: 詳盡描述舞台的外觀視覺要素。

劇本摘要：${dna.story}
視覺風格定義：${dna.style} (形式：${dna.format})
環境背景：${dna.environment}`;

    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: [{ role: 'user', parts: [{ text: prompt }] }],
      config: {
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.ARRAY,
          items: {
