  async generateStoryboard(dna: ProjectDNA, arch: StoryArchitecture, stageNames: string[], characterNames: string[]): Promise<Storyboard> {
    const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
    const prompt = `你是一位資深電影導演與攝影指導 (DP)。請將提供的「敘事結構與場景序列」轉化為精確的「技術分鏡腳本 (Technical Storyboard)」。

    【關鍵關聯約束】
    1. 舞台 (stage)：請從提供的舞台清單中挑選：[${stageNames.join(', ')}]。
    2. 角色 (character)：請從提供的角色清單中挑選：[${characterNames.join(', ')}]。

    專案 DNA：${JSON.stringify(dna)}
    敘事結構：${JSON.stringify(arch)}

    請回傳 JSON 格式。`;

    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: [{ role: 'user', parts: [{ text: prompt }] }],
      config: {
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.OBJECT,
          properties: {
            entries: {
              type: Type.ARRAY,
              items: {
                type: Type.OBJECT,
                properties: {
                  startTime: { type: Type.STRING },
