  async generateVideoPrompts(dna: ProjectDNA, storyboard: Storyboard, stages: StageDesign[], characters: CharacterDesign[]): Promise<VideoPromptEntry[]> {
    const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
    const stageNames = stages.map((s, i) => `STAGE_0${i+1}: ${s.name}`).join('; ');
    const charNames = characters.map((c, i) => `CHAR_0${i+1}: ${c.name}`).join('; ');

    const prompt = `你是一位頂尖 AI 影片生成提示詞專家 (Prompt Engineer)。

    【任務目標】
    將「技術分鏡表」轉化為專業的 AI 影片生成指令。

    【核心約束：5秒原則】
    1. 每個提示詞描述的影片長度不得超過 5 秒。
    2. 如果分鏡鏡位時長超過 5 秒，你必須將其拆分為多個「連續性 (Continuous)」的提示詞。
    3. 拆分時需確保描述的動作是連貫的。

    【核心約束：資產一致性】
    1. 必須在提示詞中使用對應的資產代號：
       - 舞台參照：使用 [STAGE_01], [STAGE_02] 等標記。
       - 角色參照：使用 [CHAR_01], [CHAR_02] 等標記。
    2. 提示詞應描述角色在該舞台九宮格中所定義的視覺特徵與空間光影。

    【資產清單】
    舞台：${stageNames}
    角色：${charNames}

    【分鏡資料】
    ${JSON.stringify(storyboard.entries)}

    請回傳 JSON 陣列，包含 shotIdx (分鏡編號), timeRange (如 00:00-00:05), prompt (英文提示詞), isContinuous (是否為續接鏡頭), stageRef (舞台代號), charRef (角色代號)。
    提示詞應包含：Cinematic shot, lighting style, camera movement, character action, texture details.`;

    const response = await ai.models.generateContent({
      model: 'gemini-3-pro-preview', // 使用 Pro 模型以獲得更高質量的提示詞
      contents: [{ role: 'user', parts: [{ text: prompt }] }],
      config: {
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.ARRAY,
          items: {
            type: Type.OBJECT,
            properties: {
              shotIdx: { type: Type.INTEGER },
              timeRange: { type: Type.STRING },
              prompt: { type: Type.STRING },
              isContinuous: { type: Type.BOOLEAN },
              stageRef: { type: Type.STRING },
              charRef: { type: Type.STRING }
            },
            required: ["shotIdx", "timeRange", "prompt", "isContinuous", "stageRef", "charRef"]
          }
        }
      }
    });
    return JSON.parse(response.text || "[]");
  }

  async polishText(text: string, type: string): Promise<string> {
    const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: `你是專業電影視覺指導。內容：${text}`,
    });
    return response.text || text;
  }

  async generateCoreStyleVisual(dna: ProjectDNA): Promise<string | null> {
    const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
    const prompt = `A professional cinematic mood board collage for: "${dna.coreNarrative}". Style: ${dna.style}.`;
    try {
      const response = await ai.models.generateContent({
        model: 'gemini-3-pro-image-preview',
        contents: { parts: [{ text: prompt }] },
        config: { imageConfig: { aspectRatio: dna.ratio === '9:16' ? "9:16" : "16:9", imageSize: "1K" } }
      });
      for (const part of response.candidates?.[0]?.content?.parts || []) {
        if (part.inlineData) return `data:image/png;base64,${part.inlineData.data}`;
      }
      return null;
    } catch (error) { return null; }
  }

  async generateStageGrid(dna: ProjectDNA, stage: StageDesign): Promise<string> {
    const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
    const gridPrompt = `Professional 3x3 Stage Concept Sheet for: "${stage.name}". Context: ${stage.description}.`;
    try {
      const response = await ai.models.generateContent({
        model: 'gemini-3-pro-image-preview',
        contents: { parts: [{ text: gridPrompt }] },
        config: { imageConfig: { aspectRatio: "1:1", imageSize: "1K" } }
      });
      for (const part of response.candidates?.[0]?.content?.parts || []) {
        if (part.inlineData) return `data:image/png;base64,${part.inlineData.data}`;
      }
    } catch (error) { console.error(error); }
    return "";
  }

  async generateCharacterGrid(dna: ProjectDNA, character: CharacterDesign): Promise<string> {
