import { GoogleGenAI, Type } from "@google/genai";
import { SYSTEM_INSTRUCTION } from "../constants";
import { Suggestion, StageDesign, CharacterDesign, ProjectDNA, ProductionPhase, StoryArchitecture, Storyboard, VideoPromptEntry } from "../types";

export class GeminiService {
  constructor(apiKey: string) { }

  async generateSuggestions(input: string, phase: ProductionPhase, context: string): Promise<Suggestion[]> {
    const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
    const currentDNA = JSON.parse(context) as ProjectDNA;

    const prompt = `
    你現在是一位備受讚譽的電影大師。目前的靈感指令為： "${input}"。
    請提供三個具備強烈視覺張力與敘事深度的創意導向（頂尖導演提案）。

    【關鍵任務】
    1. 每個提案必須包含：製作形式 (format)、視覺風格 (style)、核心敘事 (coreNarrative)。
    2. 自動推論出該提案適合的：地理環境 (environment)、社會背景 (socialBackground)。
    3. 敘事應包含具體的衝突點與時代氣息。

    請嚴格回傳符合 Schema 的 JSON 陣列。`;

    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: [{ role: 'user', parts: [{ text: prompt }] }],
      config: {
        systemInstruction: SYSTEM_INSTRUCTION,
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.ARRAY,
          items: {
            type: Type.OBJECT,
            properties: {
              title: { type: Type.STRING },
              description: { type: Type.STRING },
              tags: { type: Type.ARRAY, items: { type: Type.STRING } },
              format: { type: Type.STRING },
              style: { type: Type.STRING },
              environment: { type: Type.STRING },
              socialBackground: { type: Type.STRING },
              coreNarrative: { type: Type.STRING }
            },
            required: ["title", "description", "tags", "format", "style", "environment", "socialBackground", "coreNarrative"]
          }
        }
      }
    });
    return JSON.parse(response.text || "[]");
  }

  async elaboratePlan(suggestion: Suggestion, baseDNA: ProjectDNA): Promise<ProjectDNA> {
    const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
    // 使用 Gemini 3 Pro 進行深度敘事與視覺規劃
    const prompt = `
    你現在是一位備受國際影壇推崇的視覺大師與資深編劇。請根據以下提案細節，將其擴充為極其詳盡且具備高度藝術執行力的「影片製作 DNA」：

    【提案參考內容】
    - 標題：${suggestion.title}
    - 描述：${suggestion.description}
    - 標籤：${suggestion.tags?.join(', ')}
    - 製作形式：${suggestion.format}
    - 視覺風格：${suggestion.style}
    - 地理環境：${suggestion.environment}
    - 社會背景：${suggestion.socialBackground}
    - 核心敘事：${suggestion.coreNarrative}

    【擴充任務：導演製作清單】
    請針對以下四個維度進行深度創作與描述：
    1. 空間幾何：詳述在「${suggestion.style}」風格下，建築或自然空間的比例分配、構圖幾何原則（如：對稱、極簡、壓迫感、超現實比例）。
    2. 色彩美學：定義核心色彩計畫（Color Palette），包含主色、輔色與點綴色。詳述光影質感（如：硬調光、瀰漫光、膠捲質感、數位冷冽感）。
    3. 衝突本質：深入挖掘主角在「${suggestion.socialBackground}」背景下，面對「${suggestion.coreNarrative}」時所產生的內在情感衝突與外在生存/環境衝突。
    4. 劇本摘要：編寫一份至少 800 字、充滿強烈鏡頭感、動作細節與感官細節（聽覺、觸覺、視覺）的文字劇本。描述應包含關鍵轉折與對白意象。

    請嚴格回傳符合 Schema 的 JSON 物件。
    `;

    const response = await ai.models.generateContent({
      model: 'gemini-3-pro-preview',
      contents: [{ role: 'user', parts: [{ text: prompt }] }],
      config: {
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.OBJECT,
          properties: {
            format: { type: Type.STRING },
            style: { type: Type.STRING },
            story: { type: Type.STRING },
            ratio: { type: Type.STRING },
            environment: { type: Type.STRING },
            socialBackground: { type: Type.STRING },
            coreNarrative: { type: Type.STRING },
            directorVision: { type: Type.STRING }
          },
          required: ["format", "style", "story", "environment", "socialBackground", "coreNarrative", "directorVision"]
        }
      }
    });
    const result = JSON.parse(response.text || "{}");
    // 根據您的要求，點擊提案時即時修改製作形式與視覺風格，畫面比例預設為 16:9
    return { 
      ...result, 
      format: suggestion.format || result.format || baseDNA.format, 
      style: suggestion.style || result.style || baseDNA.style,
      ratio: "16:9" 
    };
  }

  async identifyCoreStages(dna: ProjectDNA): Promise<StageDesign[]> {
    const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
    const prompt = `作為美術指導，請從以下劇本中識別並設計三個「核心舞台」。
    劇本脈絡：${dna.story}

    請運用 Actor-Path-Nexus 架構，確保每個舞台都具備獨特的敘事功能與空間語彙。`;

    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: [{ role: 'user', parts: [{ text: prompt }] }],
      config: {
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.ARRAY,
          items: {
            type: Type.OBJECT,
            properties: {
              name: { type: Type.STRING },
              description: { type: Type.STRING }
            },
            required: ["name", "description"]
          }
        }
      }
    });
    return JSON.parse(response.text || "[]");
  }

