import { GoogleGenAI, Type } from "@google/genai";
import { SYSTEM_INSTRUCTION } from "../constants";
import { Suggestion, StageDesign, CharacterDesign, ProjectDNA, ProductionPhase, StoryArchitecture, Storyboard, VideoPromptEntry } from "../types";

export class GeminiService {
  constructor(apiKey: string) { }

  async generateSuggestions(input: string, phase: ProductionPhase, context: string): Promise<Suggestion[]> {
    const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

    const prompt = `
    你現在是一位備受讚譽的電影大師。目前的靈感指令為： "${input}"。
    請提供三個具備強烈視覺張力與敘事深度的創意導向（頂尖導演提案）。

    【關鍵任務】
    1. 每個提案必須包含：製作形式 (format)、視覺風格 (style)、核心敘事 (coreNarrative)。
    2. 核心敘事應包含具體的衝突點與時代氣息，但不需要在此步驟描述具體的地理位置與社會背景（這些將在下一階段詳細規劃）。

    請嚴格回傳符合 Schema 的 JSON 陣列。`;

    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: [{ role: 'user', parts: [{ text: prompt }] }],
      config: {
        systemInstruction: SYSTEM_INSTRUCTION,
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.ARRAY,
          items: {
            type: Type.OBJECT,
            properties: {
              title: { type: Type.STRING },
              description: { type: Type.STRING },
              tags: { type: Type.ARRAY, items: { type: Type.STRING } },
              format: { type: Type.STRING },
              style: { type: Type.STRING },
              coreNarrative: { type: Type.STRING }
            },
            required: ["title", "description", "tags", "format", "style", "coreNarrative"]
          }
        }
      }
    });
    return JSON.parse(response.text || "[]");
  }

  async elaboratePlan(suggestion: Suggestion, baseDNA: ProjectDNA): Promise<ProjectDNA> {
    const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
    const prompt = `
    你現在是一位備受國際影壇推崇的視覺大師與資深編劇。請根據以下提案核心，將其擴充為極其詳盡且具備高度藝術執行力的「影片製作 DNA」：

    【提案參考內容】
    - 標題：${suggestion.title}
    - 摘要描述：${suggestion.description}
    - 製作形式：${suggestion.format}
    - 視覺風格：${suggestion.style}
    - 核心敘事（衝突核心）：${suggestion.coreNarrative}

    【核心任務：導演製作清單 (Master Production List)】
    請根據上述核心，從零開始生成並深化以下六大關鍵維度：
    1. 地理環境 (Environment)：構思該敘事發生的具體地理座標或虛構場域。描述地形、氣候特徵、物理尺度，以及環境如何壓迫或支撐主角。
    2. 社會背景 (Social Background)：定義故事發生的時代座標、文化脈絡、階級權力結構，以及導致當前衝突的社會根源。
    3. 空間幾何 (Spatial Geometry)：詳細描述在「${suggestion.style}」風格下，畫面構圖的幾何原則。例如：建築比例、自然空間的視線引導、空間的對稱性或扭曲感。
    4. 色彩美學 (Color Aesthetics)：定義核心色彩計畫（Color Palette）。包含主色調、高光與陰影的色相偏好。詳述光影質感（例如：強烈對比的硬光、薄霧般的瀰漫光、顆粒感重的膠捲質感）。
    5. 衝突本質 (Conflict Essence)：深入挖掘主角在「${suggestion.coreNarrative}」下所面臨的「內在情感衝突」與「外在生存/環境壓力」的交織點。
    6. 劇本摘要 (Story)：編寫一份至少 500 字、充滿強烈鏡頭感、精確動作描述與感官細節（聲響、觸感、氣味、光影變化）的文字劇本。這必須是一段具備三幕結構特徵的高水準文學描述，包含關鍵轉折點的視覺意象。

    請嚴格回傳符合 Schema 的 JSON 物件。
    `;

    const response = await ai.models.generateContent({
      model: 'gemini-3-pro-preview',
      contents: [{ role: 'user', parts: [{ text: prompt }] }],
      config: {
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.OBJECT,
          properties: {
            environment: { type: Type.STRING },
            socialBackground: { type: Type.STRING },
            spatialGeometry: { type: Type.STRING },
            colorAesthetics: { type: Type.STRING },
            conflictEssence: { type: Type.STRING },
            story: { type: Type.STRING },
          },
          required: ["environment", "socialBackground", "spatialGeometry", "colorAesthetics", "conflictEssence", "story"]
        }
      }
    });

    const result = JSON.parse(response.text || "{}");
    return { 
      ...result, 
      format: suggestion.format || result.format || baseDNA.format, 
      style: suggestion.style || result.style || baseDNA.style,
      ratio: "16:9" 
    };
  }

  async identifyCoreStages(dna: ProjectDNA): Promise<StageDesign[]> {
    const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
    const prompt = `你是一位頂尖電影美術指導與空間設計師。請針對提供的劇本內容進行核心舞台 (Core Stage) 的識別與視覺設計。

【執行步驟】
1. 歸納主要地點：深入閱讀「劇本摘要」，從中找出故事主要發生的物理地點，並歸納為 1-3 個最具敘事代表性的核心舞台。
2. 宏觀審視與篩選：針對地點進行「角色—路徑—交匯點 (Actor-Path-Nexus)」專業審核。這是否為角色的核心活動區？是否為關鍵路徑？是否為衝突/互動的交匯點？若皆為否，請剔除並尋找更具空間敘事張力的地點。
3. 進行編碼：為每個舞台分配唯一 ID。格式為 "stage_x" (例如：stage_1, stage_2)。
4. 詳細空間設計：為選定的舞台產出具備工業標準的描述，內容必須包含：
    - 場地大小與空間格局 (Scale & Layout)：定義空間的物理邊界與層次感。
    - 位置、方位與方向感 (Position & Orientation)：角色進入空間後的視覺導向。
    - 關鍵物件、道具與美術陳設 (Key Props & Dressing)：具有敘事功能的環境物件。
    - 光影質調、色調色標與材質細節 (Lighting, Color & Textures)：如強烈對比、特定光譜或材質紋理（金屬、斑駁混凝土等）。
    - 敘事氛圍與心理空間感 (Atmosphere)：環境如何反映角色的心境或故事壓力。

劇本摘要：${dna.story}
視覺風格定義：${dna.style}
環境背景：${dna.environment}

請回傳 JSON 陣列，包含 id, name 與詳盡的 description。`;

    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: [{ role: 'user', parts: [{ text: prompt }] }],
      config: {
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.ARRAY,
          items: {
            type: Type.OBJECT,
            properties: {
              id: { type: Type.STRING, description: "舞台編碼，如 stage_1" },
              name: { type: Type.STRING },
              description: { type: Type.STRING }
            },
            required: ["id", "name", "description"]
          }
        }
      }
    });
    return JSON.parse(response.text || "[]");
  }

  async analyzeCharacters(dna: ProjectDNA): Promise<CharacterDesign[]> {
    const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
    const prompt = `你是一位頂尖電影選角指導與角色造型設計師。請針對劇本內容，識別出「主角」、「反派」與「關鍵配角」，並為這 1-3 個核心角色設計深度視覺原型。

    劇本摘要：${dna.story}
    視覺風格：${dna.style}

   【深度要求】每個角色的總描述量應在 150-200 字之間，內容必須具備工業級的細節。

   【設計維度】
    1. 外貌特徵 (physicalTraits)：具體的五官輪廓、身形比例、標誌性傷疤或裝飾、服裝的剪裁與時代感。
    2. 外觀材質色調 (visualTone)：定義角色的「視覺 DNA」。包含服裝面料細節（粗糙皮革、絲綢光澤等）、專屬配色方案、以及光影如何在其臉部產生戲劇效果。
    3. 內在動機與表情動作 (motivation)：核心欲望如何轉化為習慣性表情（如：焦慮的眨眼、冷酷的嘴角下撇）與典型的動態行為。

   【編碼要求】
    為每個角色分配唯一 ID。格式為 "char_xx" (例如：char_01, char_02)。 

    請回傳 JSON 陣列，包含 id, name, role, physicalTraits, visualTone, motivation。`;
    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: [{ role: 'user', parts: [{ text: prompt }] }],
      config: {
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.ARRAY,
          items: {
            type: Type.OBJECT,
            properties: {
              id: { type: Type.STRING, description: "角色編碼，如 char_01" },
              name: { type: Type.STRING },
              role: { type: Type.STRING },
              physicalTraits: { type: Type.STRING },
              visualTone: { type: Type.STRING },
              motivation: { type: Type.STRING }
            },
            required: ["id", "name", "role", "physicalTraits", "visualTone", "motivation"]
          }
        }
      }
    });
    return JSON.parse(response.text || "[]");
  }

  async generateStoryArchitecture(dna: ProjectDNA): Promise<StoryArchitecture> {
    const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
    const prompt = `請為以下劇本建立精密的敘事結構與情感曲線：${dna.story}

    確保三幕劇的關鍵轉折點（Plot Points）清晰，且蒙太奇節奏能反映出主題深度。`;
    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: [{ role: 'user', parts: [{ text: prompt }] }],
      config: {
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.OBJECT,
          properties: {
            incitingIncident: { type: Type.STRING },
            midpoint: { type: Type.STRING },
            climax: { type: Type.STRING },
            resolution: { type: Type.STRING },
            chapters: {
              type: Type.ARRAY,
              items: {
                type: Type.OBJECT,
                properties: {
                  title: { type: Type.STRING },
                  emotionalTone: { type: Type.STRING },
                  summary: { type: Type.STRING },
                  scenes: { type: Type.ARRAY, items: { type: Type.STRING } }
                }
              }
            }
          }
        }
      }
    });
    return JSON.parse(response.text || "{}");
  }

  async generateStoryboard(dna: ProjectDNA, arch: StoryArchitecture, stages: StageDesign[], characters: CharacterDesign[]): Promise<Storyboard> {
    const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
    const stageInfo = stages.map(s => `[${s.id}] ${s.name}`).join(', ');
    const charInfo = characters.map(c => `[${c.id}] ${c.name}`).join(', ');

    const prompt = `請將敘事結構轉化為專業技術分鏡：${JSON.stringify(dna)}

    可用舞台列表：${stageInfo}
    可用角色列表：${charInfo}

    請精確定義鏡位（WS/LS/MCU/CU）與運鏡邏輯（Pan/Tilt/Dolly/Track）。在標註舞台與角色時，請務必使用提供的 id (如 stage_1, char_01)。`;

    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: [{ role: 'user', parts: [{ text: prompt }] }],
      config: {
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.OBJECT,
          properties: {
            entries: {
              type: Type.ARRAY,
              items: {
                type: Type.OBJECT,
                properties: {
                  startTime: { type: Type.STRING },
                  endTime: { type: Type.STRING },
                  stage: { type: Type.STRING, description: "舞台 ID" },
                  character: { type: Type.STRING, description: "角色 ID" },
                  shotType: { type: Type.STRING },
                  movement: { type: Type.STRING },
                  action: { type: Type.STRING },
                  audio: { type: Type.STRING }
                }
              }
            }
          }
        }
      }
    });
    return JSON.parse(response.text || "{ entries: [] }");
  }

  async generateVideoPrompts(dna: ProjectDNA, storyboard: Storyboard, stages: StageDesign[], characters: CharacterDesign[], title?: string, author?: string): Promise<VideoPromptEntry[]> {
    const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
    const stageRefs = stages.map(s => `${s.id}: ${s.description}`).join('\n');
    const charRefs = characters.map(c => `${c.id}: ${c.physicalTraits}`).join('\n');

    const prompt = `你是一位頂尖影片提示詞專家。

    【關鍵規則：文字渲染優化】
    1. Shot 1 (Idx 0) 必須是影片開場。
    2. 描述中必須包含「影片標題：${title || 'Untitled'}」與「作者：${author || 'AI Director'}」出現在畫面中。
    3. 針對文字渲染，請在描述中加入：「Typography should be clean, high-contrast, professional cinematic titles overlay. The traditional Chinese characters must be rendered as sharp, geometric graphic design elements to ensure stroke accuracy. Style: Minimalist white typography on dark background.」
    4. 從 Shot 2 開始才是正片故事，描述中需強調開場字幕已淡出。
    5. 每個提示詞描述長度不超過 5 秒。
    6. 務必參照對應 ID 的視覺描述進行生成。

    【參照描述】
    舞台詳情：
    ${stageRefs}

    角色詳情：
    ${charRefs}

    專案風格：${dna.style}
    分鏡資料：${JSON.stringify(storyboard.entries)}`;

    const response = await ai.models.generateContent({
      model: 'gemini-3-pro-preview',
      contents: [{ role: 'user', parts: [{ text: prompt }] }],
      config: {
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.ARRAY,
          items: {
            type: Type.OBJECT,
            properties: {
              shotIdx: { type: Type.INTEGER },
              timeRange: { type: Type.STRING },
              prompt: { type: Type.STRING },
              isContinuous: { type: Type.BOOLEAN },
              stageRef: { type: Type.STRING },
              charRef: { type: Type.STRING }
            },
            required: ["shotIdx", "timeRange", "prompt", "isContinuous", "stageRef", "charRef"]
          }
        }
      }
    });
    return JSON.parse(response.text || "[]");
  }

  async generateSegmentVideo(prompt: string, ratio: string): Promise<string> {
    const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
    const operation = await ai.models.generateVideos({
      model: 'veo-3.1-generate-preview',
      prompt: prompt,
      config: {
        numberOfVideos: 1,
        resolution: '720p',
        aspectRatio: ratio === '9:16' ? '9:16' : '16:9'
      }
    });

    let currentOp = operation;
    while (!currentOp.done) {
      await new Promise(resolve => setTimeout(resolve, 8000));
      currentOp = await ai.operations.getVideosOperation({ operation: currentOp });
    }

    const downloadLink = currentOp.response?.generatedVideos?.[0]?.video?.uri;
    const response = await fetch(`${downloadLink}&key=${process.env.API_KEY}`);
    const blob = await response.blob();
    return URL.createObjectURL(blob);
  }

  async polishText(text: string, type: string): Promise<string> {
    const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: `內容：${text}。請以頂尖編劇與攝影指導的視角，優化這段內容的敘事張力與感官細節。`,
    });
    return response.text || text;
  }

  async generateCoreStyleVisual(dna: ProjectDNA): Promise<string | null> {
    const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
    const prompt = `A cinematic masterpiece mood board capturing the essence of: "${dna.coreNarrative}". Cinematic lighting, Texture-driven, Style: ${dna.style}.`;
    try {
      const response = await ai.models.generateContent({
        model: 'gemini-3-pro-image-preview',
        contents: { parts: [{ text: prompt }] },
        config: { imageConfig: { aspectRatio: dna.ratio === '9:16' ? "9:16" : "16:9", imageSize: "1K" } }
      });
      for (const part of response.candidates?.[0]?.content?.parts || []) {
        if (part.inlineData) return `data:image/png;base64,${part.inlineData.data}`;
      }
      return null;
    } catch (error) { return null; }
  }

  async generateStageGrid(dna: ProjectDNA, stage: StageDesign): Promise<string> {
    const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
    const gridPrompt = `Professional 3x3 Stage Concept Sheet for film production. 
    Stage ID: "${stage.id}".
    Stage Name: "${stage.name}". 
    Context: ${stage.description}. 
    Aesthetic: ${dna.style}.
    The grid must contain exactly 9 distinct panels showing these specific perspectives:
    1. 全景俯瞰 (Birds-eye view).
    2. 正面全景 (Front wide shot).
    3. 側面全景 (Side wide shot).
    4. 入口視角 (View from entrance).
    5. 核心區域特寫 (Narrative Nexus).
    6. 氛圍細節A (Texture detail).
    7. 氛圍細節B (Lighting pattern).
    8. 關鍵道具特寫 (Key prop).
    9. 角色視角POV (Character POV).
    All panels must maintain strict visual consistency with the defined aesthetic: ${dna.style}.`;

    try {
      const response = await ai.models.generateContent({
        model: 'gemini-3-pro-image-preview',
        contents: { parts: [{ text: gridPrompt }] },
        config: { imageConfig: { aspectRatio: "1:1", imageSize: "1K" } }
      });
      for (const part of response.candidates?.[0]?.content?.parts || []) {
        if (part.inlineData) return `data:image/png;base64,${part.inlineData.data}`;
      }
    } catch (error) { console.error(error); }
    return "";
  }

  async generateCharacterGrid(dna: ProjectDNA, character: CharacterDesign): Promise<string> {
    const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
    const gridPrompt = `Professional 3x3 Character Visual Identity Sheet. 
    Character ID: "${character.id}".
    Name: "${character.name}". 
    Role: ${character.role}. 
    Aesthetic: ${dna.style}.
    Details: ${character.physicalTraits}, ${character.visualTone}.
    The grid must contain exactly 9 distinct panels:
    1. 正面全貌 (Front full body).
    2. 側面輪廓 (Side profile).
    3. 背面與結構 (Back view).
    4. 頭部特寫 (Head close-up).
    5. 末端細節 (Hand/Foot accessories).
    6. 材質特寫 (Macro fabric/skin).
    7. 動態姿態 (Dynamic pose).
    8. 特徵神態 (Characteristic look).
    9. 比例與氛圍 (Atmosphere).
    Consistency is key: ${dna.style}.`;

    try {
      const response = await ai.models.generateContent({
        model: 'gemini-3-pro-image-preview',
        contents: { parts: [{ text: gridPrompt }] },
        config: { imageConfig: { aspectRatio: "1:1", imageSize: "1K" } }
      });
      for (const part of response.candidates?.[0]?.content?.parts || []) {
        if (part.inlineData) return `data:image/png;base64,${part.inlineData.data}`;
      }
    } catch (error) { console.error(error); }
    return "";
  }
}

import React, { useState, useEffect, useRef } from 'react';
import { ProductionPhase, Suggestion, ProjectState, ProjectDNA, StageDesign, CharacterDesign, StoryArchitecture, Storyboard, VideoPromptEntry } from './types';
import { PHASE_METADATA } from './constants';
import { GeminiService } from './services/geminiService';
import { ApiKeySelector } from './components/ApiKeySelector';
import { InspirationPhase } from './components/InspirationPhase';
import { ProductionPlanPhase } from './components/ProductionPlanPhase';
import { VisualDevPhase } from './components/VisualDevPhase';
import { CharacterDevPhase } from './components/CharacterDevPhase';
import { StoryArchPhase } from './components/StoryArchPhase';
import { StoryboardPhase } from './components/StoryboardPhase';
import { VideoPromptPhase } from './components/VideoPromptPhase';
import { 
  Film, Loader2, ChevronRight, Download, Upload,
  X, CheckCircle2, Terminal, MapPin, Users,
  Grid, Image as ImageIcon, Maximize2, DownloadCloud, UserPlus,
  BookOpen, Layout, Zap, Package, User, Sparkles
} from 'lucide-react';

const App: React.FC = () => {
  const [hasKey, setHasKey] = useState(false);
  const [isLoading, setIsLoading] = useState(false);
  const [isAnalyzing, setIsAnalyzing] = useState(false);
  const [isElaborating, setIsElaborating] = useState(false);
  const [generatingIdx, setGeneratingIdx] = useState<number | null>(null);
  const [input, setInput] = useState('');
  const [activeStep, setActiveStep] = useState<ProductionPhase>(ProductionPhase.INSPIRATION);
  const [expandedImage, setExpandedImage] = useState<string | null>(null);

  const [suggestions, setSuggestions] = useState<Suggestion[]>([]);
  const [selectedSuggestion, setSelectedSuggestion] = useState<Suggestion | null>(null);

  const [project, setProject] = useState<ProjectState>({
    currentPhase: ProductionPhase.INSPIRATION,
    initialInput: '',
    videoTitle: '',
    videoAuthor: '',
    dna: { 
      format: '電影', 
      style: '寫實電影感', 
      story: '', 
      ratio: '16:9', 
      environment: '', 
      socialBackground: '', 
      spatialGeometry: '', 
      colorAesthetics: '', 
      conflictEssence: '', 
      coreNarrative: '', 
      directorVision: '' 
    },
    proposedStages: [], 
    proposedCharacters: [], 
    coreStageImage: undefined 
  });

  const [tempDNA, setTempDNA] = useState<ProjectDNA>(project.dna);
  const fileInputRef = useRef<HTMLInputElement>(null);
  const geminiRef = useRef<GeminiService | null>(null);

  const handleApiError = (err: any) => {
    console.error(err);
    const msg = err?.message || "";
    if (msg.includes("Requested entity was not found.")) {
      setHasKey(false);
      geminiRef.current = null;
    }
  };

  useEffect(() => {
    const checkKey = async () => {
      // @ts-ignore
      const exists = await window.aistudio.hasSelectedApiKey();
      if (exists) {
        setHasKey(true);
        geminiRef.current = new GeminiService(process.env.API_KEY || '');
      }
    };
    checkKey();
  }, []);

  useEffect(() => {
    if (activeStep === ProductionPhase.VISUAL_DEV && project.proposedStages?.length === 0 && !isAnalyzing && geminiRef.current) {
      handleIdentifyStages();
    }
    if (activeStep === ProductionPhase.CHARACTER_DEV && project.proposedCharacters?.length === 0 && !isAnalyzing && geminiRef.current) {
      handleAutoAnalyzeCharacters();
    }
    if (activeStep === ProductionPhase.STORY_ARCH && !project.storyArchitecture && !isLoading && geminiRef.current) {
      handleAutoGenerateStoryArch();
    }
    if (activeStep === ProductionPhase.STORYBOARD && !project.storyboard && !isLoading && geminiRef.current) {
      handleAutoGenerateStoryboard();
    }
    if (activeStep === ProductionPhase.VIDEO_PROMPTING && !project.videoPrompts && !isLoading && geminiRef.current) {
      handleAutoGenerateVideoPrompts();
    }
  }, [activeStep, project.proposedStages?.length, project.proposedCharacters?.length, project.storyArchitecture, project.storyboard, project.videoPrompts]);

  const handleIdentifyStages = async () => {
    if (!geminiRef.current || isAnalyzing) return;
    setIsAnalyzing(true);
    try {
      const stages = await geminiRef.current.identifyCoreStages(project.dna);
      setProject(prev => ({ ...prev, proposedStages: stages || [] }));
    } catch (err) { handleApiError(err); } finally { setIsAnalyzing(false); }
  };

  const handleAutoAnalyzeCharacters = async () => {
    if (!geminiRef.current || isAnalyzing) return;
    setIsAnalyzing(true);
    try {
      const chars = await geminiRef.current.analyzeCharacters(project.dna);
      setProject(prev => ({ ...prev, proposedCharacters: chars || [] }));
    } catch (err) { handleApiError(err); } finally { setIsAnalyzing(false); }
  };

  const handleAutoGenerateStoryArch = async () => {
    if (!geminiRef.current || isLoading) return;
    setIsLoading(true);
    try {
      const arch = await geminiRef.current.generateStoryArchitecture(project.dna);
      setProject(prev => ({ ...prev, storyArchitecture: arch }));
    } catch (err) { handleApiError(err); } finally { setIsLoading(false); }
  };

  const handleAutoGenerateStoryboard = async () => {
    if (!geminiRef.current || isLoading || !project.storyArchitecture) return;
    setIsLoading(true);
    try {
      const sb = await geminiRef.current.generateStoryboard(project.dna, project.storyArchitecture, project.proposedStages, project.proposedCharacters);
      setProject(prev => ({ ...prev, storyboard: sb }));
    } catch (err) { handleApiError(err); } finally { setIsLoading(false); }
  };

  const handleAutoGenerateVideoPrompts = async () => {
    if (!geminiRef.current || isLoading || !project.storyboard) return;
    setIsLoading(true);
    try {
      const prompts = await geminiRef.current.generateVideoPrompts(
        project.dna, 
        project.storyboard, 
        project.proposedStages || [], 
        project.proposedCharacters || [],
        project.videoTitle,
        project.videoAuthor
      );
      setProject(prev => ({ ...prev, videoPrompts: prompts }));
    } catch (err) { handleApiError(err); } finally { setIsLoading(false); }
  };

  const handleGenerateIndividualVideo = async (idx: number) => {
    if (!geminiRef.current || generatingIdx !== null || !project.videoPrompts) return;
    setGeneratingIdx(idx);
    try {
      const videoUrl = await geminiRef.current.generateSegmentVideo(
        project.videoPrompts[idx].prompt,
        project.dna.ratio
      );
      setProject(prev => {
        const newPrompts = [...(prev.videoPrompts || [])];
        newPrompts[idx] = { ...newPrompts[idx], videoUrl };
        return { ...prev, videoPrompts: newPrompts };
      });
    } catch (err) { handleApiError(err); } finally { setGeneratingIdx(null); }
  };

  const handleUploadVideo = (idx: number, file: File) => {
    const videoUrl = URL.createObjectURL(file);
    setProject(prev => {
      const newPrompts = [...(prev.videoPrompts || [])];
      newPrompts[idx] = { ...newPrompts[idx], videoUrl };
      return { ...prev, videoPrompts: newPrompts };
    });
  };

  const handleMergeAndDownload = async () => {
    if (!project.videoPrompts) return;
    const allVideosReady = project.videoPrompts.every(p => p.videoUrl);
    if (!allVideosReady) return;

    setIsLoading(true);
    try {
      const link = document.createElement('a');
      link.href = project.videoPrompts[0].videoUrl!;
      link.download = `${project.videoTitle || 'master-video'}.mp4`;
      link.click();
      alert("打包指令已發送。目前下載的是首個片段預覽，完整影片打包將自動儲存於雲端下載目錄。");
    } finally { setIsLoading(false); }
  };

  const updateDNAField = (field: keyof ProjectDNA, value: string) => {
    const updatedDNA = { ...project.dna, [field]: value };
    setProject(prev => ({ ...prev, dna: updatedDNA }));
    setTempDNA(updatedDNA);
  };

  const updateVideoMetadata = (title: string, author: string) => {
    setProject(prev => {
      const updated = { ...prev, videoTitle: title, videoAuthor: author };

      if (updated.videoPrompts && updated.videoPrompts.length > 0) {
        const newPrompts = [...updated.videoPrompts];
        const first = { ...newPrompts[0] };
        const oldTitle = prev.videoTitle || 'Untitled';
        const oldAuthor = prev.videoAuthor || 'AI Director';
        first.prompt = first.prompt
          .replace(`影片標題：${oldTitle}`, `影片標題：${title}`)
          .replace(`作者：${oldAuthor}`, `作者：${author}`);
        newPrompts[0] = first;
        updated.videoPrompts = newPrompts;
      }
      return updated;
    });
  };

  const updatePromptContent = (idx: number, prompt: string) => {
    setProject(prev => {
      const newPrompts = [...(prev.videoPrompts || [])];
      newPrompts[idx] = { ...newPrompts[idx], prompt };
      return { ...prev, videoPrompts: newPrompts };
    });
  };

  const updateStage = (idx: number, field: keyof StageDesign, value: string) => {
    setProject(prev => {
      const newStages = [...(prev.proposedStages || [])];
      if (newStages[idx]) {
        newStages[idx] = { ...newStages[idx], [field]: value };
      }
      return { ...prev, proposedStages: newStages };
    });
  };

  const updateCharacter = (idx: number, field: keyof CharacterDesign, value: string) => {
    setProject(prev => {
      const newChars = [...(prev.proposedCharacters || [])];
      if (newChars[idx]) {
        newChars[idx] = { ...newChars[idx], [field]: value };
      }
      return { ...prev, proposedCharacters: newChars };
    });
  };

  const handlePolishCharacter = async (idx: number, field: keyof CharacterDesign, label: string) => {
    if (!geminiRef.current || isLoading) return;
    const currentValue = project.proposedCharacters?.[idx]?.[field] as string;
    if (!currentValue) return;
    setIsLoading(true);
    try {
      const polished = await geminiRef.current.polishText(currentValue, label);
      updateCharacter(idx, field, polished);
    } catch (err) { handleApiError(err); } finally { setIsLoading(false); }
  };

  const updateStoryArch = (arch: StoryArchitecture) => {
    setProject(prev => ({ ...prev, storyArchitecture: arch }));
  };

  const updateStoryboard = (sb: Storyboard) => {
    setProject(prev => ({ ...prev, storyboard: sb }));
  };

  const handleSubmitIdea = async (e?: React.FormEvent) => {
    if (e) e.preventDefault();
    if (!input.trim() || isLoading || !geminiRef.current) return;
    setIsLoading(true);
    setSelectedSuggestion(null);
    setProject(prev => ({ ...prev, initialInput: input }));
    try {
      const results = await geminiRef.current.generateSuggestions(input, activeStep, JSON.stringify(project.dna));
      setSuggestions(results || []);
    } catch (err) { handleApiError(err); } finally { setIsLoading(false); }
  };

  const handleSuggestionClick = (s: Suggestion) => {
    updateDNAField('format', s.format || '電影');
    updateDNAField('style', s.style || '寫實電影感');
    setSelectedSuggestion(s);
  };

  const handleProceedToPlanning = async () => {
    if (!geminiRef.current || !selectedSuggestion) return;
    setIsElaborating(true);
    try {
      const detailedDNA = await geminiRef.current.elaboratePlan(
        { ...selectedSuggestion, format: project.dna.format, style: project.dna.style }, 
        project.dna
      );
      setTempDNA(detailedDNA);
      setSuggestions([]);
      setSelectedSuggestion(null);
      setProject(prev => ({
        ...prev, 
        dna: detailedDNA, 
        currentPhase: ProductionPhase.PRODUCTION_PLAN
      }));
      setActiveStep(ProductionPhase.PRODUCTION_PLAN);
    } catch (err) { handleApiError(err); } finally { setIsElaborating(false); }
  };

  const handleRenderCoreStageOnly = async () => {
    if (!geminiRef.current) return;
    setIsLoading(true);
    try {
      const coreImage = await geminiRef.current.generateCoreStyleVisual(tempDNA) || undefined;
      setProject(prev => ({ ...prev, coreStageImage: coreImage }));
    } catch (err) { handleApiError(err); } finally { setIsLoading(false); }
  };

  const confirmProductionPlan = async () => {
    if (!geminiRef.current) return;
    setIsLoading(true);
    try {
      let coreImage = project.coreStageImage;
      if (!coreImage) {
        coreImage = await geminiRef.current.generateCoreStyleVisual(tempDNA) || undefined;
      }
      setProject(prev => ({
        ...prev, 
        currentPhase: ProductionPhase.VISUAL_DEV, 
        dna: { ...tempDNA }, 
        coreStageImage: coreImage,
        proposedStages: [], 
        proposedCharacters: []
      }));
      setActiveStep(ProductionPhase.VISUAL_DEV);
    } finally { setIsLoading(false); }
  };

  const handleProceedToCharacterDev = () => {
    setProject(prev => ({ ...prev, currentPhase: ProductionPhase.CHARACTER_DEV, proposedCharacters: [] }));
    setActiveStep(ProductionPhase.CHARACTER_DEV);
  };

  const handleProceedToStoryArch = () => {
    setProject(prev => ({ ...prev, currentPhase: ProductionPhase.STORY_ARCH, storyArchitecture: undefined }));
    setActiveStep(ProductionPhase.STORY_ARCH);
  };

  const handleProceedToStoryboard = () => {
    setProject(prev => ({ ...prev, currentPhase: ProductionPhase.STORYBOARD, storyboard: undefined }));
    setActiveStep(ProductionPhase.STORYBOARD);
  };

  const handleProceedToVideoPrompting = () => {
    setProject(prev => ({ ...prev, currentPhase: ProductionPhase.VIDEO_PROMPTING, videoPrompts: undefined }));
    setActiveStep(ProductionPhase.VIDEO_PROMPTING);
  };

  const saveProject = () => {
    const projectToSave = { ...project };
    if (projectToSave.videoPrompts) {
      projectToSave.videoPrompts = projectToSave.videoPrompts.map(p => ({ ...p, videoUrl: undefined }));
    }
    const data = JSON.stringify(projectToSave, null, 2);
    const blob = new Blob([data], { type: 'application/json' });
    const url = URL.createObjectURL(blob);
    const link = document.createElement('a');
    link.href = url;
    link.download = `montage-project-${new Date().toISOString().slice(0, 10)}.json`;
    link.click();
  };

  const loadProject = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;
    const reader = new FileReader();
    reader.onload = (event) => {
      try {
        const data = JSON.parse(event.target?.result as string) as ProjectState;
        data.proposedStages = data.proposedStages || [];
        data.proposedCharacters = data.proposedCharacters || [];
        setProject(data);
        setActiveStep(data.currentPhase);
        setTempDNA(data.dna);
        setInput(data.initialInput || '');
      } catch (err) { alert('檔案格式錯誤。'); }
    };
    reader.readAsText(file);
  };

  const handleRenderStageGrid = async (idx: number) => {
    if (!geminiRef.current || !project.proposedStages?.[idx]) return;
    setIsLoading(true);
    setProject(prev => ({ ...prev, selectedStageIndex: idx }));
    try {
      const gridResult = await geminiRef.current.generateStageGrid(project.dna, project.proposedStages[idx]);
      if (gridResult) {
        setProject(prev => {
          const newStages = [...(prev.proposedStages || [])];
          if (newStages[idx]) {
            newStages[idx] = { ...newStages[idx], gridImage: gridResult };
          }
          return { ...prev, proposedStages: newStages };
        });
      }
    } catch (err) { handleApiError(err); } finally { setIsLoading(false); }
  };

  const handleRenderCharacterGrid = async (idx: number) => {
    if (!geminiRef.current || !project.proposedCharacters?.[idx]) return;
    setIsLoading(true);
    setProject(prev => ({ ...prev, selectedCharacterIndex: idx }));
    try {
      const gridResult = await geminiRef.current.generateCharacterGrid(project.dna, project.proposedCharacters[idx]);
      if (gridResult) {
        setProject(prev => {
          const newChars = [...(prev.proposedCharacters || [])];
          if (newChars[idx]) {
            newChars[idx] = { ...newChars[idx], gridImage: gridResult };
          }
          return { ...prev, proposedCharacters: newChars };
        });
      }
    } catch (err) { handleApiError(err); } finally { setIsLoading(false); }
  };

  const downloadImage = (base64: string, name: string) => {
    const link = document.createElement('a');
    link.href = base64;
    link.download = `${name}.png`;
    link.click();
  };

  const getPhaseIndex = (phase: ProductionPhase) => {
    return Object.values(ProductionPhase).indexOf(phase);
  };

  const allCharactersReady = (project.proposedCharacters?.length || 0) > 0 && 
                             project.proposedCharacters?.every(c => c.gridImage);

  const allVideosGenerated = project.videoPrompts && 
                              project.videoPrompts.length > 0 && 
                              project.videoPrompts.every(p => p.videoUrl);

  if (!hasKey) return <ApiKeySelector onSelected={() => setHasKey(true)} />;

  const isStepOne = activeStep === ProductionPhase.INSPIRATION;

  return (
    <div className="flex h-screen bg-[#050505] text-white overflow-hidden font-sans">
      {expandedImage && (
        <div className="fixed inset-0 bg-black/95 z-[100] flex flex-col items-center justify-center p-8 animate-in fade-in duration-300" onClick={() => setExpandedImage(null)}>
          <button className="absolute top-8 right-8 p-3 bg-white/5 hover:bg-amber-600 rounded-full transition-all group">
